CREATE OR REPLACE FUNCTION "private"."_blind_source_get_current_shift"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_shift RECORD;
  v_total_sales numeric := 0;
  v_cash_sales numeric := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('has_active_shift', false);
  END IF;

  SELECT * INTO v_shift
  FROM public.shifts
  WHERE lounge_id = p_lounge_id
    AND status = 'open'
    AND (cashier_id = auth.uid() OR staff_user_id = auth.uid())
  ORDER BY opened_at DESC
  LIMIT 1;

  IF v_shift.id IS NULL THEN
    RETURN jsonb_build_object('has_active_shift', false, 'lounge_id', p_lounge_id);
  END IF;

  SELECT
    COALESCE(SUM(amount), 0),
    COALESCE(SUM(CASE WHEN payment_method = 'cash' THEN amount ELSE 0 END), 0)
  INTO v_total_sales, v_cash_sales
  FROM public.shift_payments
  WHERE shift_id = v_shift.id;

  RETURN jsonb_build_object(
    'has_active_shift', true,
    'shift_id', v_shift.id,
    'lounge_id', v_shift.lounge_id,
    'cashier_id', v_shift.cashier_id,
    'staff_user_id', v_shift.staff_user_id,
    'opened_at', v_shift.opened_at,
    'starting_cash', v_shift.starting_cash,
    'current_cash_sales', v_cash_sales,
    'current_total_sales', v_total_sales,
    'current_expected_cash', COALESCE(v_shift.starting_cash, 0) + v_cash_sales
  );
END;
$$;


ALTER FUNCTION "private"."_blind_source_get_current_shift"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."_blind_source_get_lounge_live_shift_overview"("p_lounge_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_shift record;
  v_name text;
  v_cash numeric := 0;
  v_digital numeric := 0;
  v_expenses numeric := 0;
  v_cash_expenses numeric := 0;
BEGIN
  IF (SELECT auth.uid()) IS NULL
     OR (SELECT private.current_user_role()) = 'super_admin'
     OR NOT (SELECT private.is_lounge_member(p_lounge_id)) THEN
    RAISE EXCEPTION 'Not authorized for this lounge.';
  END IF;

  SELECT * INTO v_shift
  FROM public.shifts
  WHERE lounge_id = p_lounge_id
    AND status = 'open'
  ORDER BY opened_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'has_active_shift', false,
      'lounge_id', p_lounge_id,
      'total_sales', 0,
      'cash_sales', 0,
      'digital_sales', 0,
      'total_expenses', 0,
      'expected_cash', 0
    );
  END IF;

  SELECT full_name INTO v_name
  FROM public.profiles
  WHERE id = COALESCE(v_shift.cashier_id, v_shift.staff_user_id);

  SELECT
    COALESCE(SUM(CASE WHEN payment_method = 'cash' THEN amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN payment_method <> 'cash' THEN amount ELSE 0 END), 0)
  INTO v_cash, v_digital
  FROM public.shift_payments
  WHERE shift_id = v_shift.id;

  SELECT
    COALESCE(SUM(amount), 0),
    COALESCE(SUM(CASE WHEN expense_type IN ('cash_drop', 'expense', 'other') THEN amount ELSE 0 END), 0)
  INTO v_expenses, v_cash_expenses
  FROM public.shift_expenses
  WHERE shift_id = v_shift.id;

  RETURN json_build_object(
    'has_active_shift', true,
    'lounge_id', p_lounge_id,
    'shift_id', v_shift.id,
    'cashier_id', v_shift.cashier_id,
    'cashier_name', COALESCE(v_name, 'Cashier'),
    'opened_at', v_shift.opened_at,
    'starting_cash', COALESCE(v_shift.starting_cash, 0),
    'cash_sales', v_cash,
    'digital_sales', v_digital,
    'total_sales', v_cash + v_digital,
    'total_expenses', v_expenses,
    'expected_cash', COALESCE(v_shift.starting_cash, 0) + v_cash - v_cash_expenses,
    'payment_count', (SELECT COUNT(*) FROM public.shift_payments WHERE shift_id = v_shift.id),
    'expense_count', (SELECT COUNT(*) FROM public.shift_expenses WHERE shift_id = v_shift.id),
    'linked_booking_count', (SELECT COUNT(*) FROM public.bookings WHERE shift_id = v_shift.id)
  );
END;
$$;


ALTER FUNCTION "private"."_blind_source_get_lounge_live_shift_overview"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_cashier_cash_operation"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_lounge uuid;
BEGIN
  SELECT lounge_id INTO v_lounge FROM public.bookings WHERE id=(p_operation->>'booking_id')::uuid;
  IF NOT FOUND OR v_lounge IS DISTINCT FROM (p_operation->>'lounge_id')::uuid THEN
    RAISE EXCEPTION 'OFFLINE_BOOKING_SCOPE_MISMATCH' USING ERRCODE='42501';
  END IF;
  RETURN public.collect_booking_cash_partial((p_operation->>'booking_id')::uuid,
    (p_operation->>'shift_id')::uuid,(p_operation->'payload'->>'amount_minor')::numeric,
    (p_operation->>'id')::uuid);
END; $$;


ALTER FUNCTION "private"."apply_cashier_cash_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_cashier_close_operation"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_booking public.bookings%ROWTYPE;v_at timestamptz:=(p_operation->>'occurred_at')::timestamptz;v_final numeric;
BEGIN
  v_booking:=private.lock_offline_fixed_session(p_operation);
  IF v_booking.status<>'in_progress'::public.booking_status OR v_booking.actual_start_time IS NULL
    OR v_at<v_booking.actual_start_time OR v_booking.cashier_booking_timezone IS NULL THEN
    RAISE EXCEPTION 'OFFLINE_SESSION_NOT_READY_TO_CLOSE' USING ERRCODE='55000';
  END IF;
  UPDATE public.bookings SET status='completed',cashier_closed_at=v_at,updated_at=now() WHERE id=v_booking.id RETURNING total_price INTO v_final;
  IF v_final*100 IS DISTINCT FROM (p_operation->>'quoted_total_minor')::numeric THEN
    RAISE EXCEPTION 'OFFLINE_BOOKING_PRICE_CHANGED' USING ERRCODE='22023';
  END IF;
  UPDATE public.rooms r SET status='available',is_available=true,updated_at=now()
    WHERE r.id=v_booking.room_id AND r.status='occupied' AND r.is_active IS TRUE
      AND NOT EXISTS(SELECT 1 FROM public.bookings WHERE room_id=r.id AND id<>v_booking.id AND status='in_progress'::public.booking_status);
  RETURN private.offline_fixed_session_receipt(v_booking.id);
END; $$;


ALTER FUNCTION "private"."apply_cashier_close_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_cashier_fixed_operation"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_result jsonb;
BEGIN
  INSERT INTO private.cashier_sync_context VALUES(txid_current(),(p_operation->>'lounge_id')::uuid,
    auth.uid(),(p_operation->>'permit_id')::uuid);
  INSERT INTO private.cashier_booking_command_context VALUES(txid_current(),(p_operation->>'booking_id')::uuid,p_operation->>'kind');
  CASE p_operation->>'kind'
    WHEN 'reserve' THEN v_result:=private.apply_cashier_reservation_operation(p_operation);
    WHEN 'start' THEN v_result:=private.apply_cashier_start_operation(p_operation);
    WHEN 'close' THEN v_result:=private.apply_cashier_close_operation(p_operation);
    ELSE RAISE EXCEPTION 'OFFLINE_OPERATION_KIND_NOT_IMPLEMENTED' USING ERRCODE='0A000';
  END CASE;
  PERFORM private.validate_offline_session_snapshot(p_operation,v_result);
  DELETE FROM private.cashier_booking_command_context WHERE transaction_id=txid_current();
  DELETE FROM private.cashier_sync_context WHERE transaction_id=txid_current();
  RETURN v_result;
END; $$;


ALTER FUNCTION "private"."apply_cashier_fixed_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_cashier_order_operation"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_booking public.bookings%ROWTYPE;v_lines jsonb;v_total numeric;v_paid numeric;v_final numeric;v_status text;
BEGIN
  PERFORM private.validate_offline_order_lines(p_operation);
  v_booking:=private.lock_offline_order_booking(p_operation);
  v_paid:=private.cash_collection_paid_amount(v_booking.id,v_booking.lounge_id,v_booking.payment_status);
  v_lines:=private.price_offline_order_lines(p_operation);
  SELECT sum((value->>'total_price')::numeric) INTO v_total FROM jsonb_array_elements(v_lines);
  IF (v_booking.total_price+v_total)*100 IS DISTINCT FROM (p_operation->>'quoted_total_minor')::numeric THEN
    RAISE EXCEPTION 'OFFLINE_BOOKING_PRICE_CHANGED' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.canteen_orders(id,booking_id,lounge_id,user_id,shift_id,items,total_price,note,status,created_at)
    VALUES((p_operation->>'id')::uuid,v_booking.id,v_booking.lounge_id,v_booking.user_id,
      (p_operation->>'shift_id')::uuid,v_lines,v_total,p_operation->'payload'->>'note','pending',
      (p_operation->>'occurred_at')::timestamptz);
  PERFORM private.insert_offline_order_lines(p_operation,v_lines);
  v_status:=CASE WHEN v_paid=v_booking.total_price+v_total THEN 'paid' WHEN v_paid>0 THEN 'partial' ELSE 'unpaid' END;
  UPDATE public.bookings SET addons_price=coalesce(addons_price,0)+v_total,addons_total=coalesce(addons_price,0)+v_total,
    total_price=v_booking.total_price+v_total,payment_status=v_status,updated_at=now() WHERE id=v_booking.id
    RETURNING total_price INTO v_final;
  IF v_final*100 IS DISTINCT FROM (p_operation->>'quoted_total_minor')::numeric THEN
    RAISE EXCEPTION 'OFFLINE_BOOKING_PRICE_CHANGED' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('booking_id',v_booking.id,'order_id',(p_operation->>'id')::uuid,
    'lounge_id',v_booking.lounge_id,'items',v_lines,'order_total_minor',v_total*100,
    'total_minor',v_final*100,'paid_minor',v_paid*100,'due_minor',(v_final-v_paid)*100,'payment_status',v_status);
END; $$;


ALTER FUNCTION "private"."apply_cashier_order_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_cashier_reservation_operation"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_room public.rooms%ROWTYPE;v_interval jsonb;v_quote jsonb;v_booking public.bookings%ROWTYPE;
BEGIN
  v_interval:=private.offline_booking_interval(p_operation);
  IF NOT EXISTS(SELECT 1 FROM public.lounges WHERE id=(p_operation->>'lounge_id')::uuid AND allow_cash_payment IS TRUE) THEN
    RAISE EXCEPTION 'OFFLINE_CASH_BOOKING_DISABLED' USING ERRCODE='55000';
  END IF;
  v_room:=private.lock_offline_booking_room((p_operation->'payload'->>'room_id')::uuid,(p_operation->>'lounge_id')::uuid);
  PERFORM private.lock_cash_collection_shift((p_operation->>'shift_id')::uuid,v_room.lounge_id);
  IF EXISTS(SELECT 1 FROM public.tournament_matches WHERE room_id=v_room.id AND status<>'cancelled'
    AND scheduled_at IS NOT NULL AND scheduled_end_at IS NOT NULL
    AND tstzrange(scheduled_at,scheduled_end_at,'[)') && tstzrange(
      to_timestamp((p_operation->'payload'->>'start_ms')::double precision/1000),
      to_timestamp((p_operation->'payload'->>'end_ms')::double precision/1000),'[)')) THEN
    RAISE EXCEPTION 'OFFLINE_TOURNAMENT_ROOM_CONFLICT' USING ERRCODE='55000';
  END IF;
  v_quote:=private.quote_offline_fixed_booking(p_operation,v_interval);
  INSERT INTO public.bookings(id,user_id,lounge_id,room_id,date,start_time,end_time,start_at,end_at,room_price,total_price,
    status,user_name,user_phone,room_name,play_mode,duration_minutes,shift_id,payment_status,payment_method,created_at,cashier_booking_timezone)
    VALUES((p_operation->>'booking_id')::uuid,NULL,v_room.lounge_id,v_room.id,(v_interval->>'start')::timestamp::date,
      (v_interval->>'start')::timestamp::time,(v_interval->>'end')::timestamp::time,
      (v_interval->>'start')::timestamp::time,(v_interval->>'end')::timestamp::time,
      (v_quote->>'room_subtotal')::numeric,(v_quote->>'final_total')::numeric,'upcoming',
      btrim(p_operation->'payload'->>'customer_name'),p_operation->'payload'->>'customer_phone',v_room.name,
      p_operation->'payload'->>'play_mode',(v_interval->>'minutes')::integer,(p_operation->>'shift_id')::uuid,
      'unpaid','cash',(p_operation->>'occurred_at')::timestamptz,v_interval->>'timezone') RETURNING * INTO v_booking;
  IF v_booking.total_price*100 IS DISTINCT FROM (p_operation->>'quoted_total_minor')::numeric THEN
    RAISE EXCEPTION 'OFFLINE_BOOKING_PRICE_CHANGED' USING ERRCODE='22023';
  END IF;
  RETURN private.offline_fixed_session_receipt(v_booking.id);
END; $$;


ALTER FUNCTION "private"."apply_cashier_reservation_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_cashier_start_operation"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_booking public.bookings%ROWTYPE;v_timezone text;v_at timestamptz:=(p_operation->>'occurred_at')::timestamptz;v_final numeric;
BEGIN
  v_booking:=private.lock_offline_fixed_session(p_operation);
  PERFORM private.lock_offline_booking_room(v_booking.room_id,v_booking.lounge_id);
  SELECT timezone INTO v_timezone FROM public.lounges WHERE id=v_booking.lounge_id;
  IF v_timezone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=v_timezone)
    OR (v_booking.cashier_booking_timezone IS NOT NULL AND v_booking.cashier_booking_timezone<>v_timezone) THEN
    RAISE EXCEPTION 'INVALID_LOUNGE_TIMEZONE' USING ERRCODE='22023';
  END IF;
  IF v_booking.status<>'upcoming'::public.booking_status
    OR v_at<(v_booking.date+v_booking.start_time) AT TIME ZONE v_timezone
    OR v_at>=((v_booking.date+v_booking.end_time)+CASE WHEN v_booking.end_time<=v_booking.start_time THEN interval '1 day' ELSE interval '0' END)
      AT TIME ZONE v_timezone THEN RAISE EXCEPTION 'OFFLINE_SESSION_OUTSIDE_BOOKED_WINDOW' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT 1 FROM public.bookings WHERE room_id=v_booking.room_id AND id<>v_booking.id AND status='in_progress'::public.booking_status) THEN
    RAISE EXCEPTION 'OFFLINE_ROOM_STILL_OCCUPIED' USING ERRCODE='55000';
  END IF;
  UPDATE public.bookings SET status='in_progress',checked_in_at=v_at,actual_start_time=v_at,
    cashier_booking_timezone=v_timezone,updated_at=now() WHERE id=v_booking.id RETURNING total_price INTO v_final;
  IF v_final*100 IS DISTINCT FROM (p_operation->>'quoted_total_minor')::numeric THEN
    RAISE EXCEPTION 'OFFLINE_BOOKING_PRICE_CHANGED' USING ERRCODE='22023';
  END IF;
  UPDATE public.rooms SET status='occupied',is_available=false,updated_at=now() WHERE id=v_booking.room_id;
  RETURN private.offline_fixed_session_receipt(v_booking.id);
END; $$;


ALTER FUNCTION "private"."apply_cashier_start_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_partial_cash_collection"("p_booking_id" "uuid", "p_shift_id" "uuid", "p_amount_minor" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_amount numeric := p_amount_minor/100;
  v_paid numeric;
  v_rate numeric := private.platform_commission_rate();
  v_shift_payment uuid;
  v_final_total numeric;
BEGIN
  v_booking:=private.lock_cash_collection_booking(p_booking_id);
  PERFORM private.lock_cash_collection_shift(p_shift_id,v_booking.lounge_id);
  v_paid:=private.cash_collection_paid_amount(p_booking_id,v_booking.lounge_id,v_booking.payment_status);
  IF v_amount>v_booking.total_price-v_paid THEN
    RAISE EXCEPTION 'CASH_EXCEEDS_OUTSTANDING_BALANCE' USING ERRCODE='22023';
  END IF;
  IF v_rate IS NULL OR v_rate<0 OR v_rate>1 OR v_rate::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION 'INVALID_COMMISSION_POLICY' USING ERRCODE='55000';
  END IF;
  INSERT INTO private.cash_collection_context VALUES(txid_current(),p_booking_id) ON CONFLICT DO NOTHING;
  INSERT INTO public.payments(booking_id,user_id,lounge_id,amount,commission_rate,commission,
    net_to_lounge,payment_method,status,paid_at)
  VALUES(p_booking_id,v_booking.user_id,v_booking.lounge_id,v_paid+v_amount,v_rate,
    round((v_paid+v_amount)*v_rate,2),(v_paid+v_amount)-round((v_paid+v_amount)*v_rate,2),'cash','completed',now())
  ON CONFLICT(booking_id) DO UPDATE SET amount=EXCLUDED.amount,commission_rate=EXCLUDED.commission_rate,
    commission=EXCLUDED.commission,net_to_lounge=EXCLUDED.net_to_lounge,paid_at=EXCLUDED.paid_at;
  INSERT INTO public.shift_payments(shift_id,lounge_id,booking_id,payment_method,category,amount,paid_at)
  VALUES(p_shift_id,v_booking.lounge_id,p_booking_id,'cash','gaming_time',v_amount,now()) RETURNING id INTO v_shift_payment;
  UPDATE public.bookings SET payment_status=CASE WHEN v_paid+v_amount=total_price THEN 'paid' ELSE 'partial' END,
    payment_method='cash',updated_at=now() WHERE id=p_booking_id RETURNING total_price INTO v_final_total;
  IF v_final_total IS DISTINCT FROM v_booking.total_price THEN
    RAISE EXCEPTION 'BOOKING_PRICE_CHANGED_DURING_COLLECTION' USING ERRCODE='22023';
  END IF;
  DELETE FROM private.cash_collection_context WHERE transaction_id=txid_current() AND booking_id=p_booking_id;
  RETURN jsonb_build_object('booking_id',p_booking_id,'lounge_id',v_booking.lounge_id,
    'shift_id',p_shift_id,'shift_payment_id',v_shift_payment,'collected_minor',p_amount_minor,
    'paid_minor',(v_paid+v_amount)*100,'due_minor',(v_booking.total_price-v_paid-v_amount)*100,
    'payment_status',CASE WHEN v_paid+v_amount=v_booking.total_price THEN 'paid' ELSE 'partial' END);
END; $$;


ALTER FUNCTION "private"."apply_partial_cash_collection"("p_booking_id" "uuid", "p_shift_id" "uuid", "p_amount_minor" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_cash_collector"("p_actor" "uuid", "p_lounge" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id
    WHERE p.id=p_actor AND p.is_active IS TRUE AND p.is_banned IS FALSE FOR SHARE OF p,u;
  IF NOT FOUND THEN RAISE EXCEPTION 'ACCOUNT_NOT_ELIGIBLE' USING ERRCODE='42501'; END IF;
  IF public.is_super_admin() IS NOT TRUE
      AND public.has_lounge_permission(p_lounge,'billing_checkout') IS NOT TRUE THEN
    RAISE EXCEPTION 'CASH_COLLECTION_PERMISSION_DENIED' USING ERRCODE='42501';
  END IF;
  PERFORM 1 FROM public.lounges WHERE id=p_lounge AND is_active IS TRUE AND status='active' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'LOUNGE_NOT_APPROVED' USING ERRCODE='42501'; END IF;
END; $$;


ALTER FUNCTION "private"."assert_cash_collector"("p_actor" "uuid", "p_lounge" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_cashier_conflict_reviewer"("p_lounge_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
 PERFORM 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=auth.uid()
  AND p.is_active IS TRUE AND p.is_banned IS FALSE FOR SHARE OF p,u;
 IF NOT FOUND THEN RAISE EXCEPTION 'ACCOUNT_NOT_ELIGIBLE' USING ERRCODE='42501'; END IF;
 IF public.is_super_admin() IS NOT TRUE AND
  (private.permission_role(auth.uid(),p_lounge_id) NOT IN ('owner','manager')
   OR private.permission_role(auth.uid(),p_lounge_id) IS NULL
   OR public.has_lounge_permission(p_lounge_id,'sessions_control') IS NOT TRUE
   OR public.has_lounge_permission(p_lounge_id,'billing_checkout') IS NOT TRUE) THEN
  RAISE EXCEPTION 'CASHIER_CONFLICT_REVIEW_DENIED' USING ERRCODE='42501';
 END IF;
 PERFORM 1 FROM public.lounges WHERE id=p_lounge_id AND is_active IS TRUE AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'LOUNGE_NOT_APPROVED' USING ERRCODE='42501'; END IF;
END; $$;


ALTER FUNCTION "private"."assert_cashier_conflict_reviewer"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_lounge_operator"("p_lounge_id" "uuid", "p_allow_cashier" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_role text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT p.role INTO v_role
  FROM public.profiles AS p
  WHERE p.id = auth.uid() AND COALESCE(p.is_active, true);

  IF v_role = 'super_admin' THEN
    RAISE EXCEPTION 'Platform super admins are not allowed to perform lounge operations' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
       SELECT 1 FROM public.profiles AS p
       WHERE p.id = auth.uid() AND p.lounge_id = p_lounge_id
         AND COALESCE(p.is_active, true)
         AND p.role IN ('owner','lounge_admin','admin','manager')
     )
     AND NOT EXISTS (
       SELECT 1 FROM public.lounge_staff AS ls
       JOIN public.profiles AS p ON p.id = ls.user_id
       WHERE ls.user_id = auth.uid() AND ls.lounge_id = p_lounge_id
         AND COALESCE(p.is_active, true)
         AND ls.role IN ('lounge_owner','manager')
     )
     AND NOT (p_allow_cashier AND (
       EXISTS (
         SELECT 1 FROM public.profiles AS p
         WHERE p.id = auth.uid() AND p.lounge_id = p_lounge_id
           AND COALESCE(p.is_active, true)
           AND p.role IN ('cashier','staff')
       ) OR EXISTS (
         SELECT 1 FROM public.lounge_staff AS ls
         JOIN public.profiles AS p ON p.id = ls.user_id
         WHERE ls.user_id = auth.uid() AND ls.lounge_id = p_lounge_id
           AND COALESCE(p.is_active, true)
           AND ls.role IN ('cashier','staff')
       )
     )) THEN
    RAISE EXCEPTION 'User is not authorized for this lounge' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "private"."assert_lounge_operator"("p_lounge_id" "uuid", "p_allow_cashier" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_offline_cashier_permission"("p_operation" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_permission text:=CASE WHEN p_operation->>'kind'='reserve' THEN 'bookings.manage' ELSE 'sessions_control' END;
BEGIN
  IF p_operation->>'kind'='collectCash' THEN
    PERFORM private.assert_cash_collector(auth.uid(),(p_operation->>'lounge_id')::uuid);
    RETURN;
  END IF;
  PERFORM 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id
    WHERE p.id=auth.uid() AND p.is_active IS TRUE AND p.is_banned IS FALSE FOR SHARE OF p,u;
  IF NOT FOUND THEN RAISE EXCEPTION 'ACCOUNT_NOT_ELIGIBLE' USING ERRCODE='42501'; END IF;
  IF public.is_super_admin() IS NOT TRUE AND
    public.has_lounge_permission((p_operation->>'lounge_id')::uuid,v_permission) IS NOT TRUE THEN
    RAISE EXCEPTION 'OFFLINE_SESSION_PERMISSION_DENIED' USING ERRCODE='42501';
  END IF;
  PERFORM 1 FROM public.lounges WHERE id=(p_operation->>'lounge_id')::uuid AND is_active IS TRUE AND status='active' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'LOUNGE_NOT_APPROVED' USING ERRCODE='42501'; END IF;
END; $$;


ALTER FUNCTION "private"."assert_offline_cashier_permission"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."block_api_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_temp'
    AS $$
begin
  if current_user in ('anon', 'authenticated') then
    raise exception 'This table is read-only for API roles' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."block_api_writes"() OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."bookings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "room_id" "uuid",
    "lounge_id" "uuid",
    "date" "date" NOT NULL,
    "start_time" time without time zone NOT NULL,
    "end_time" time without time zone NOT NULL,
    "room_price" numeric(12,2) NOT NULL,
    "addons_price" numeric(12,2) DEFAULT 0,
    "total_price" numeric(12,2) NOT NULL,
    "status" "public"."booking_status" DEFAULT 'pending'::"public"."booking_status",
    "qr_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "user_name" "text",
    "user_phone" "text",
    "room_name" "text",
    "booking_period" "tsrange" GENERATED ALWAYS AS ("tsrange"(("date" + "start_time"), (("date" + "end_time") +
CASE
    WHEN ("end_time" <= "start_time") THEN '1 day'::interval
    ELSE '00:00:00'::interval
END))) STORED,
    "duration_hours" numeric GENERATED ALWAYS AS ((EXTRACT(epoch FROM (("end_time" - "start_time") +
CASE
    WHEN ("end_time" <= "start_time") THEN '1 day'::interval
    ELSE '00:00:00'::interval
END)) / (3600)::numeric)) STORED,
    "play_mode" "text",
    "extra_controllers" integer DEFAULT 0,
    "payment_status" "text" DEFAULT 'unpaid'::"text",
    "shift_id" "uuid",
    "duration_minutes" integer DEFAULT 60,
    "payment_method" "text" DEFAULT 'cash'::"text" NOT NULL,
    "discount_amount" numeric(12,2) DEFAULT 0,
    "discount_percentage" numeric DEFAULT 0,
    "discount_reason" "text",
    "discount_approved_by" "uuid",
    "actual_start_time" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "extension_status" "text" DEFAULT 'none'::"text",
    "requested_extension_minutes" integer DEFAULT 0,
    "start_at" time without time zone,
    "end_at" time without time zone,
    "receipt_url" "text",
    "expires_at" timestamp with time zone DEFAULT ("now"() + '00:30:00'::interval),
    "sender_wallet_phone" "text",
    "is_first_booking" boolean DEFAULT false NOT NULL,
    "checked_in_at" timestamp with time zone,
    "cancellation_reason" "text",
    "addons_total" numeric DEFAULT 0,
    "approved_at" timestamp with time zone,
    "approved_by" "uuid",
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "is_open_time" boolean DEFAULT false NOT NULL,
    "open_time_started_at" timestamp with time zone,
    "open_time_closed_at" timestamp with time zone,
    "open_time_billing_minutes" integer,
    "open_time_pricing_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "confirmation_status" "text" DEFAULT 'confirmed'::"text" NOT NULL,
    "deposit_required" boolean DEFAULT false NOT NULL,
    "deposit_amount" numeric DEFAULT 0 NOT NULL,
    "deposit_paid" boolean DEFAULT false NOT NULL,
    "confirmation_sent_at" timestamp with time zone,
    "contact_alert_sent_at" timestamp with time zone,
    "cashier_closed_at" timestamp with time zone,
    "cashier_booking_timezone" "text",
    "cashier_capacity_period" "tsrange" GENERATED ALWAYS AS ("tsrange"(("date" + "start_time"),
CASE
    WHEN (("status" = 'completed'::"public"."booking_status") AND ("cashier_closed_at" IS NOT NULL) AND ("cashier_booking_timezone" IS NOT NULL)) THEN GREATEST(("date" + "start_time"), LEAST((("date" + "end_time") +
    CASE
        WHEN ("end_time" <= "start_time") THEN '1 day'::interval
        ELSE '00:00:00'::interval
    END), ("cashier_closed_at" AT TIME ZONE "cashier_booking_timezone")))
    ELSE (("date" + "end_time") +
    CASE
        WHEN ("end_time" <= "start_time") THEN '1 day'::interval
        ELSE '00:00:00'::interval
    END)
END, '[)'::"text")) STORED,
    "applied_voucher_code" "text",
    "pricing_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "pricing_rule_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    CONSTRAINT "bookings_confirmation_status_check" CHECK (("confirmation_status" = ANY (ARRAY['confirmed'::"text", 'pending_confirmation'::"text", 'rejected_by_lounge'::"text", 'expired_unconfirmed'::"text"]))),
    CONSTRAINT "bookings_open_time_billing_minutes_check" CHECK ((("open_time_billing_minutes" IS NULL) OR (("open_time_billing_minutes" >= 1) AND ("open_time_billing_minutes" <= 1440)))),
    CONSTRAINT "bookings_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['cash'::"text", 'manual_transfer'::"text", 'card'::"text", 'vodafone_cash'::"text", 'fawry'::"text", 'instapay'::"text", 'app_wallet'::"text"]))),
    CONSTRAINT "bookings_total_price_non_negative" CHECK (("total_price" >= (0)::numeric)),
    CONSTRAINT "check_booking_prices_non_negative" CHECK (((("total_price" IS NULL) OR ("total_price" >= (0)::numeric)) AND (("addons_price" IS NULL) OR ("addons_price" >= (0)::numeric)) AND (("room_price" IS NULL) OR ("room_price" >= (0)::numeric)))),
    CONSTRAINT "check_discount_amount_not_negative" CHECK (("discount_amount" >= (0)::numeric)),
    CONSTRAINT "check_discount_percentage_range" CHECK ((("discount_percentage" >= (0)::numeric) AND ("discount_percentage" <= (100)::numeric))),
    CONSTRAINT "check_total_price_not_negative" CHECK (("total_price" >= (0)::numeric))
);


ALTER TABLE "public"."bookings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."booking_extension_quote"("p_booking" "public"."bookings", "p_minutes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_start timestamp; v_end timestamp; v_quote jsonb; v_controller_rate numeric; v_cost numeric;
BEGIN
 IF p_minutes IS NULL OR p_minutes<=0 OR p_minutes>720 OR p_booking.is_open_time IS TRUE THEN
   RAISE EXCEPTION 'INVALID_FIXED_SESSION_EXTENSION' USING ERRCODE='22023';
 END IF;
 v_start:=p_booking.date+p_booking.start_time+make_interval(mins=>p_booking.duration_minutes);
 v_end:=v_start+make_interval(mins=>p_minutes);
 v_quote:=private.price_room_interval(p_booking.room_id,v_start::date,v_start::time,v_end::time,COALESCE(p_booking.play_mode,'single'));
 SELECT COALESCE(r.extra_controller_price,0) INTO v_controller_rate FROM public.rooms r WHERE r.id=p_booking.room_id;
 v_cost:=round((v_quote->>'room_subtotal')::numeric
   +GREATEST(0,COALESCE(p_booking.extra_controllers,0))*v_controller_rate*p_minutes/60.0,2);
 RETURN jsonb_build_object('extension_cost',v_cost,'new_total',COALESCE(p_booking.total_price,0)+v_cost,
   'room_price',COALESCE(p_booking.room_price,0)+v_cost,'quote',v_quote);
END $$;


ALTER FUNCTION "private"."booking_extension_quote"("p_booking" "public"."bookings", "p_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."build_my_booking_checkout_quote"("p_user_id" "uuid", "p_hold_token" "uuid", "p_room_requests" "jsonb", "p_extra_items" "jsonb" DEFAULT '[]'::"jsonb", "p_voucher_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_hold_count integer;
  v_request_count integer;
  v_lounge_id uuid;
  v_start_at timestamp without time zone;
  v_end_at timestamp without time zone;
  v_duration_hours numeric;
  v_request jsonb;
  v_room_id uuid;
  v_play_mode text;
  v_extra_controllers integer;
  v_room record;
  v_base_rate numeric;
  v_pricing jsonb;
  v_priced_room_subtotal numeric;
  v_effective_rate numeric;
  v_controller_rate numeric;
  v_discounted_base_rate numeric;
  v_original_subtotal numeric;
  v_discounted_subtotal numeric;
  v_promo_discount numeric;
  v_discount_type text;
  v_discount_value numeric;
  v_discount_label text;
  v_discount_source text;
  v_rooms jsonb := '[]'::jsonb;
  v_original_rooms_total numeric := 0;
  v_discounted_rooms_total numeric := 0;
  v_room_discount_total numeric := 0;
  v_primary_rate numeric := 0;
  v_primary_discounted_subtotal numeric := 0;
  v_extra jsonb;
  v_extra_id uuid;
  v_quantity integer;
  v_extra_row record;
  v_extras jsonb := '[]'::jsonb;
  v_extras_total numeric := 0;
  v_voucher public.user_vouchers%ROWTYPE;
  v_voucher_discount numeric := 0;
  v_voucher_code text := NULLIF(upper(btrim(p_voucher_code)), '');
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_hold_token IS NULL THEN
    RAISE EXCEPTION 'Booking hold is required' USING ERRCODE = '22023';
  END IF;

  SELECT count(*)
  INTO v_hold_count
  FROM public.booking_holds h
  WHERE h.hold_token = p_hold_token
    AND h.user_id = p_user_id
    AND h.released_at IS NULL
    AND h.expires_at > now();

  IF v_hold_count < 1 THEN
    RAISE EXCEPTION 'BOOKING_HOLD_EXPIRED' USING ERRCODE = '55000';
  END IF;

  SELECT h.lounge_id, h.start_at, h.end_at
  INTO v_lounge_id, v_start_at, v_end_at
  FROM public.booking_holds h
  WHERE h.hold_token = p_hold_token
    AND h.user_id = p_user_id
    AND h.released_at IS NULL
    AND h.expires_at > now()
  ORDER BY h.id
  LIMIT 1;

  IF EXISTS (
    SELECT 1
    FROM public.booking_holds h
    WHERE h.hold_token = p_hold_token
      AND h.user_id = p_user_id
      AND (
        h.lounge_id IS DISTINCT FROM v_lounge_id
        OR h.start_at IS DISTINCT FROM v_start_at
        OR h.end_at IS DISTINCT FROM v_end_at
      )
  ) THEN
    RAISE EXCEPTION 'Invalid booking hold' USING ERRCODE = '23514';
  END IF;

  IF p_room_requests IS NULL
     OR jsonb_typeof(p_room_requests) <> 'array'
     OR jsonb_array_length(p_room_requests) < 1 THEN
    RAISE EXCEPTION 'Room requests must be a non-empty JSON array'
      USING ERRCODE = '22023';
  END IF;

  IF v_start_at IS DISTINCT FROM date_trunc('minute',v_start_at)
     OR v_end_at IS DISTINCT FROM date_trunc('minute',v_end_at) THEN
    RAISE EXCEPTION 'Booking intervals must use whole minutes' USING ERRCODE = '22023';
  END IF;

  v_request_count := jsonb_array_length(p_room_requests);

  IF v_request_count <> v_hold_count THEN
    RAISE EXCEPTION 'Room request count does not match booking hold'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_room_requests) req(value)
    LEFT JOIN public.booking_holds h
      ON h.hold_token = p_hold_token
     AND h.user_id = p_user_id
     AND h.room_id = NULLIF(req.value->>'room_id', '')::uuid
     AND h.released_at IS NULL
     AND h.expires_at > now()
    WHERE h.id IS NULL
  ) THEN
    RAISE EXCEPTION 'Room request is not covered by the booking hold'
      USING ERRCODE = '23514';
  END IF;

  IF (
    SELECT count(DISTINCT req.value->>'room_id')
    FROM jsonb_array_elements(p_room_requests) req(value)
  ) <> v_request_count THEN
    RAISE EXCEPTION 'Duplicate room request' USING ERRCODE = '22023';
  END IF;

  v_duration_hours :=
    extract(epoch FROM (v_end_at - v_start_at)) / 3600.0;

  IF v_duration_hours <= 0 OR v_duration_hours > 24 THEN
    RAISE EXCEPTION 'Invalid booking duration' USING ERRCODE = '22023';
  END IF;

  FOR v_request IN
    SELECT req.value
    FROM jsonb_array_elements(p_room_requests) WITH ORDINALITY req(value, ord)
    ORDER BY req.ord
  LOOP
    BEGIN
      v_room_id := NULLIF(v_request->>'room_id', '')::uuid;
      v_extra_controllers :=
        GREATEST(0, COALESCE((v_request->>'extra_controllers')::integer, 0));
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'Invalid room request' USING ERRCODE = '22023';
    END;

    IF v_extra_controllers > 20 THEN
      RAISE EXCEPTION 'Too many extra controllers requested'
        USING ERRCODE = '22023';
    END IF;

    v_play_mode := lower(COALESCE(NULLIF(v_request->>'play_mode', ''), 'single'));
    IF v_play_mode NOT IN ('single', 'multi') THEN
      RAISE EXCEPTION 'Invalid play mode' USING ERRCODE = '22023';
    END IF;

    SELECT
      r.id,
      r.lounge_id,
      r.name_ar,
      r.name_en,
      r.hourly_rate_single,
      r.hourly_rate_multi,
      r.extra_controller_price
    INTO v_room
    FROM public.rooms r
    WHERE r.id = v_room_id
      AND r.lounge_id = v_lounge_id
      AND r.is_active IS TRUE
      AND (r.is_available IS TRUE OR r.status = 'occupied')
      AND COALESCE(r.status, 'available') NOT IN ('maintenance','deleted');

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Room unavailable: %', v_room_id
        USING ERRCODE = '23514';
    END IF;

    v_base_rate := CASE
      WHEN v_play_mode = 'multi'
        AND COALESCE(v_room.hourly_rate_multi, 0) > 0
      THEN v_room.hourly_rate_multi
      ELSE v_room.hourly_rate_single
    END;

    IF COALESCE(v_base_rate, 0) <= 0 THEN
      RAISE EXCEPTION 'Room has no valid hourly rate: %', v_room_id
        USING ERRCODE = '23514';
    END IF;

    v_pricing := private.price_room_interval(
      v_room_id,
      v_start_at::date,
      v_start_at::time,
      v_end_at::time,
      v_play_mode
    );
    v_effective_rate := COALESCE(
      (v_pricing->>'effective_hourly_rate')::numeric,
      v_base_rate
    );
    v_priced_room_subtotal := COALESCE(
      (v_pricing->>'room_subtotal')::numeric,
      v_base_rate * v_duration_hours
    );

    v_controller_rate :=
      v_extra_controllers * COALESCE(v_room.extra_controller_price, 0);

    v_discounted_base_rate := v_effective_rate;
    v_discount_type := NULL;
    v_discount_value := 0;
    v_discount_label := NULL;
    v_discount_source := 'none';

    SELECT
      p.discount_type,
      COALESCE(p.discount_value, 0),
      COALESCE(p.tag_en, p.tag_ar, p.title_en, p.title_ar, p.title)
    INTO
      v_discount_type,
      v_discount_value,
      v_discount_label
    FROM public.promotions p
    WHERE p.is_active IS TRUE
      AND p.room_id = v_room_id
      AND COALESCE(p.discount_value, 0) > 0
      AND (p.expires_at IS NULL OR p.expires_at > now())
    ORDER BY p.created_at DESC, p.id DESC
    LIMIT 1;

    IF FOUND THEN
      v_discount_source := 'room';
    ELSE
      SELECT
        p.discount_type,
        COALESCE(p.discount_value, 0),
        COALESCE(p.tag_en, p.tag_ar, p.title_en, p.title_ar, p.title)
      INTO
        v_discount_type,
        v_discount_value,
        v_discount_label
      FROM public.promotions p
      WHERE p.is_active IS TRUE
        AND p.lounge_id = v_lounge_id
        AND COALESCE(p.is_room_specific, false) IS FALSE
        AND p.room_id IS NULL
        AND COALESCE(p.discount_value, 0) > 0
        AND (p.expires_at IS NULL OR p.expires_at > now())
      ORDER BY p.created_at DESC, p.id DESC
      LIMIT 1;

      IF FOUND THEN
        v_discount_source := 'lounge';
      ELSE
        SELECT
          'percentage',
          l.discount_percentage::numeric,
          COALESCE(l.discount_title_en, l.discount_title_ar)
        INTO
          v_discount_type,
          v_discount_value,
          v_discount_label
        FROM public.lounges l
        WHERE l.id = v_lounge_id
          AND COALESCE(l.has_discount, false) IS TRUE
          AND COALESCE(l.discount_percentage, 0) > 0
          AND (
            l.discount_expires_at IS NULL
            OR l.discount_expires_at > now()
          );

        IF FOUND THEN
          v_discount_source := 'lounge';
        END IF;
      END IF;
    END IF;

    v_original_subtotal :=
      round(v_priced_room_subtotal + (v_controller_rate * v_duration_hours),2);

    IF COALESCE(v_discount_value, 0) > 0 THEN
      IF lower(COALESCE(v_discount_type, 'percentage')) = 'fixed' THEN
        v_promo_discount :=
          LEAST(v_priced_room_subtotal, GREATEST(0, v_discount_value));
      ELSE
        v_promo_discount :=
          ROUND(
            v_priced_room_subtotal
            * LEAST(GREATEST(v_discount_value, 0), 100)
            / 100.0,
            2
          );
      END IF;
    ELSE
      v_promo_discount := 0;
    END IF;

    v_discounted_subtotal :=
      round(GREATEST(0, v_original_subtotal - v_promo_discount),2);

    v_discounted_base_rate := CASE
      WHEN v_duration_hours > 0
      THEN GREATEST(
        0,
        (v_priced_room_subtotal - v_promo_discount) / v_duration_hours
      )
      ELSE v_effective_rate
    END;

    IF jsonb_array_length(v_rooms) = 0 THEN
      v_primary_rate := v_discounted_base_rate;
      v_primary_discounted_subtotal := v_discounted_subtotal;
    END IF;

    v_original_rooms_total :=
      v_original_rooms_total + v_original_subtotal;

    v_discounted_rooms_total :=
      v_discounted_rooms_total + v_discounted_subtotal;

    v_room_discount_total :=
      v_room_discount_total + v_promo_discount;

    v_rooms := v_rooms || jsonb_build_array(
      jsonb_build_object(
        'room_id', v_room_id,
        'room_name_ar', v_room.name_ar,
        'room_name_en', v_room.name_en,
        'play_mode', v_play_mode,
        'extra_controllers', v_extra_controllers,
        'base_hourly_rate', v_base_rate,
        'effective_hourly_rate', v_effective_rate,
        'pricing_segments', COALESCE(v_pricing->'segments', '[]'::jsonb),
        'controller_hourly_rate', v_controller_rate,
        'applied_hourly_rate', v_discounted_base_rate + v_controller_rate,
        'original_subtotal', v_original_subtotal,
        'discounted_subtotal', v_discounted_subtotal,
        'promo_discount_amount', v_promo_discount,
        'discount_type', v_discount_type,
        'discount_value', v_discount_value,
        'discount_label', v_discount_label,
        'discount_source', v_discount_source
      )
    );
  END LOOP;

  IF p_extra_items IS NULL THEN
    p_extra_items := '[]'::jsonb;
  END IF;

  IF jsonb_typeof(p_extra_items) <> 'array'
     OR jsonb_array_length(p_extra_items) > 50 THEN
    RAISE EXCEPTION 'Extra items must be a JSON array'
      USING ERRCODE = '22023';
  END IF;

  FOR v_extra IN
    SELECT e.value
    FROM jsonb_array_elements(p_extra_items) e(value)
  LOOP
    BEGIN
      v_extra_id := NULLIF(
        COALESCE(
          v_extra->>'extra_id',
          v_extra->>'id',
          v_extra->>'product_id'
        ),
        ''
      )::uuid;
      v_quantity := COALESCE((v_extra->>'quantity')::integer, 1);
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'Invalid extra item' USING ERRCODE = '22023';
    END;

    IF v_extra_id IS NULL OR v_quantity < 1 OR v_quantity > 100 THEN
      RAISE EXCEPTION 'Invalid extra item quantity'
        USING ERRCODE = '22023';
    END IF;

    SELECT
      e.id,
      e.name,
      e.name_ar,
      e.name_en,
      e.price,
      e.track_stock,
      e.stock_quantity
    INTO v_extra_row
    FROM public.extras e
    WHERE e.id = v_extra_id
      AND e.lounge_id = v_lounge_id
      AND e.is_active IS TRUE
      AND e.is_available IS TRUE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Extra unavailable: %', v_extra_id
        USING ERRCODE = '23514';
    END IF;

    IF v_extra_row.track_stock IS TRUE
       AND COALESCE(v_extra_row.stock_quantity, 0) < v_quantity THEN
      RAISE EXCEPTION 'Extra has insufficient stock: %', v_extra_id
        USING ERRCODE = '23514';
    END IF;

    v_extras_total :=
      v_extras_total + round(v_extra_row.price * v_quantity,2);

    v_extras := v_extras || jsonb_build_array(
      jsonb_build_object(
        'extra_id', v_extra_id,
        'name', COALESCE(
          v_extra_row.name_ar,
          v_extra_row.name_en,
          v_extra_row.name
        ),
        'quantity', v_quantity,
        'unit_price', v_extra_row.price,
        'total_price', round(v_extra_row.price * v_quantity,2)
      )
    );
  END LOOP;

  IF v_voucher_code IS NOT NULL THEN
    SELECT uv.*
    INTO v_voucher
    FROM public.user_vouchers uv
    WHERE upper(btrim(uv.code)) = v_voucher_code
      AND uv.user_id = p_user_id
      AND uv.status = 'active'
      AND (uv.expires_at IS NULL OR uv.expires_at > now())
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'VOUCHER_INVALID' USING ERRCODE = '23514';
    END IF;

    IF v_voucher.reward_type = 'discount_fixed' THEN
      v_voucher_discount := GREATEST(
        0,
        COALESCE(v_voucher.reward_value, 0)
      );
    ELSIF v_voucher.reward_type = 'free_hour' THEN
      v_voucher_discount := GREATEST(
        0,
        LEAST(
          v_primary_discounted_subtotal,
          v_primary_rate * COALESCE(v_voucher.reward_value, 0)
        )
      );
    ELSE
      RAISE EXCEPTION 'Unsupported voucher type'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  v_voucher_discount := round(LEAST(
    v_voucher_discount,
    v_discounted_rooms_total + v_extras_total
  ),2);

  RETURN jsonb_build_object(
    'success', true,
    'hold_token', p_hold_token,
    'lounge_id', v_lounge_id,
    'start_at', v_start_at,
    'end_at', v_end_at,
    'duration_minutes',
      round(extract(epoch FROM (v_end_at - v_start_at)) / 60.0)::integer,
    'rooms', v_rooms,
    'extras', v_extras,
    'original_rooms_total', v_original_rooms_total,
    'promo_discount_total', v_room_discount_total,
    'discounted_rooms_total', v_discounted_rooms_total,
    'extras_total', v_extras_total,
    'voucher_code', v_voucher_code,
    'voucher_discount', v_voucher_discount,
    'original_total', v_original_rooms_total + v_extras_total,
    'final_total',
      GREATEST(
        0,
        v_discounted_rooms_total + v_extras_total - v_voucher_discount
      )
  );
END;
$$;


ALTER FUNCTION "private"."build_my_booking_checkout_quote"("p_user_id" "uuid", "p_hold_token" "uuid", "p_room_requests" "jsonb", "p_extra_items" "jsonb", "p_voucher_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_manage_playspot_lounge"("p_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT p_lounge_id IS NOT NULL AND auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id = p.id
      WHERE p.id = auth.uid() AND p.is_active IS TRUE
        AND p.is_banned IS FALSE
        AND (
          public.is_super_admin()
          OR EXISTS (SELECT 1 FROM public.lounges l
                     WHERE l.id = p_lounge_id AND l.owner_id = p.id)
          OR (p.lounge_id = p_lounge_id
              AND p.role IN ('owner', 'lounge_admin', 'admin', 'manager'))
          OR EXISTS (SELECT 1 FROM public.lounge_staff ls
                     WHERE ls.user_id = p.id AND ls.lounge_id = p_lounge_id
                       AND ls.role IN ('lounge_owner', 'manager'))
        )
    );
$$;


ALTER FUNCTION "private"."can_manage_playspot_lounge"("p_lounge_id" "uuid") OWNER TO "postgres";


