    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lounge_id" "uuid" NOT NULL,
    "name_ar" "text" NOT NULL,
    "name_en" "text",
    "description_ar" "text",
    "description_en" "text",
    "image_url" "text",
    "price" numeric NOT NULL,
    "days_of_week" integer[],
    "available_from" time without time zone,
    "available_to" time without time zone,
    "valid_from" "date",
    "valid_to" "date",
    "is_active" boolean DEFAULT true NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "canteen_combos_days_range" CHECK ((("days_of_week" IS NULL) OR ("days_of_week" <@ ARRAY[0, 1, 2, 3, 4, 5, 6]))),
    CONSTRAINT "canteen_combos_price_check" CHECK (("price" >= (0)::numeric)),
    CONSTRAINT "canteen_combos_valid_date_range" CHECK ((("valid_from" IS NULL) OR ("valid_to" IS NULL) OR ("valid_to" >= "valid_from")))
);


ALTER TABLE "public"."canteen_combos" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."canteen_combo_window_available"("p_combo" "public"."canteen_combos", "p_now" timestamp without time zone) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT COALESCE(p_combo.is_active, false)
    AND (p_combo.valid_from IS NULL OR p_now::date >= p_combo.valid_from)
    AND (p_combo.valid_to IS NULL OR p_now::date <= p_combo.valid_to)
    AND (p_combo.days_of_week IS NULL OR extract(dow FROM p_now)::integer = ANY(p_combo.days_of_week))
    AND (p_combo.available_from IS NULL OR p_combo.available_to IS NULL
      OR CASE WHEN p_combo.available_to > p_combo.available_from
        THEN p_now::time >= p_combo.available_from AND p_now::time < p_combo.available_to
        ELSE p_now::time >= p_combo.available_from OR p_now::time < p_combo.available_to END);
$$;


ALTER FUNCTION "private"."canteen_combo_window_available"("p_combo" "public"."canteen_combos", "p_now" timestamp without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."capture_booking_moderation_timestamps"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.approved_at := NULL;
    NEW.approved_by := NULL;
    NEW.cancelled_at := NULL;
    NEW.cancelled_by := NULL;

    IF NEW.status = 'upcoming'::public.booking_status THEN
      IF (SELECT auth.uid()) IS NOT NULL
         AND ((SELECT auth.uid()) = NEW.user_id
              OR NOT private.is_lounge_member(NEW.lounge_id)) THEN
        RAISE EXCEPTION 'Only authorized lounge staff can create an approved booking.'
          USING ERRCODE = '42501';
      END IF;
      NEW.approved_at := statement_timestamp();
      NEW.approved_by := (SELECT auth.uid());
    ELSIF NEW.status = 'cancelled'::public.booking_status THEN
      NEW.cancelled_at := statement_timestamp();
      NEW.cancelled_by := (SELECT auth.uid());
    END IF;

    RETURN NEW;
  END IF;

  -- These audit fields are database-controlled; ignore client-supplied values.
  NEW.approved_at := OLD.approved_at;
  NEW.approved_by := OLD.approved_by;
  NEW.cancelled_at := OLD.cancelled_at;
  NEW.cancelled_by := OLD.cancelled_by;

  IF OLD.status = 'pending'::public.booking_status
     AND NEW.status = 'upcoming'::public.booking_status THEN
    IF (SELECT auth.uid()) IS NOT NULL
       AND ((SELECT auth.uid()) = NEW.user_id
            OR NOT private.is_lounge_member(NEW.lounge_id)) THEN
      RAISE EXCEPTION 'Only authorized lounge staff can approve a booking.'
        USING ERRCODE = '42501';
    END IF;
    NEW.approved_at := statement_timestamp();
    NEW.approved_by := (SELECT auth.uid());
  END IF;

  IF OLD.status IS DISTINCT FROM NEW.status
     AND NEW.status = 'cancelled'::public.booking_status THEN
    NEW.cancelled_at := statement_timestamp();
    NEW.cancelled_by := (SELECT auth.uid());
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."capture_booking_moderation_timestamps"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."cash_collection_paid_amount"("p_booking_id" "uuid", "p_lounge_id" "uuid", "p_payment_status" "text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_payment public.payments%ROWTYPE;v_cash numeric;
BEGIN
  SELECT COALESCE(sum(amount),0) INTO v_cash FROM public.shift_payments
    WHERE booking_id=p_booking_id AND lounge_id=p_lounge_id AND payment_method='cash';
  SELECT * INTO v_payment FROM public.payments WHERE booking_id=p_booking_id FOR UPDATE;
  IF FOUND THEN
    IF v_payment.payment_method IS DISTINCT FROM 'cash' OR v_payment.status IS DISTINCT FROM 'completed'
      OR v_payment.lounge_id IS DISTINCT FROM p_lounge_id OR v_payment.payout_id IS NOT NULL
      OR v_payment.amount IS NULL OR v_payment.amount<0
      OR v_payment.amount::text IN ('NaN','Infinity','-Infinity')
      OR v_payment.amount<>round(v_payment.amount,2) OR v_payment.amount IS DISTINCT FROM v_cash THEN
      RAISE EXCEPTION 'PAYMENT_REQUIRES_RECONCILIATION' USING ERRCODE='55000';
    END IF;
    RETURN v_payment.amount;
  ELSIF p_payment_status IS DISTINCT FROM 'unpaid' OR v_cash<>0 THEN
    RAISE EXCEPTION 'PAYMENT_REQUIRES_RECONCILIATION' USING ERRCODE='55000';
  END IF;
  RETURN 0;
END; $$;


ALTER FUNCTION "private"."cash_collection_paid_amount"("p_booking_id" "uuid", "p_lounge_id" "uuid", "p_payment_status" "text") OWNER TO "postgres";


