CREATE OR REPLACE FUNCTION "private"."freeze_pending_review_data"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_lounge_id uuid; v_old_lounge_id uuid;
BEGIN
 IF TG_TABLE_NAME='lounges' THEN
  v_lounge_id:=COALESCE(NEW.id,OLD.id);
 ELSE
  IF TG_OP<>'DELETE' THEN v_lounge_id:=NEW.lounge_id; END IF;
  IF TG_OP<>'INSERT' THEN v_old_lounge_id:=OLD.lounge_id; END IF;
 END IF;
 PERFORM 1 FROM public.lounges WHERE id IN (v_lounge_id,v_old_lounge_id) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM private.lounge_review_requests
  WHERE lounge_id IN (v_lounge_id,v_old_lounge_id) AND status='pending') THEN
  RAISE EXCEPTION 'PENDING_REVIEW_IMMUTABLE' USING ERRCODE='55000';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."freeze_pending_review_data"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."get_canteen_upsell_suggestions"("p_booking_id" "uuid", "p_for_order" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_now timestamp := timezone('Africa/Cairo', now());
  v_start_at timestamp;
  v_elapsed_minutes integer;
  v_result jsonb := '[]'::jsonb;
  v_rule public.upsell_rules%ROWTYPE;
  v_trigger_ok boolean;
  v_target_type text;
  v_target_id uuid;
  v_name_ar text;
  v_name_en text;
  v_image_url text;
  v_original_price numeric;
  v_discount numeric;
  v_final_price numeric;
  v_start_time time;
  v_end_time time;
  v_category text;
  v_minutes integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
    AND b.user_id = auth.uid();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE='P0002';
  END IF;

  IF v_booking.status <> 'in_progress'::public.booking_status THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT timezone(l.timezone, now()) INTO v_now FROM public.lounges l WHERE l.id = v_booking.lounge_id;
  v_start_at := COALESCE(timezone((SELECT timezone FROM public.lounges WHERE id = v_booking.lounge_id),
    COALESCE(v_booking.actual_start_time, v_booking.open_time_started_at)),
    v_booking.date + v_booking.start_time);
  v_elapsed_minutes := GREATEST(
    0,
    floor(extract(epoch FROM (v_now - v_start_at))/60.0)::integer
  );

  FOR v_rule IN
    SELECT r.*
    FROM public.upsell_rules AS r
    WHERE r.lounge_id = v_booking.lounge_id
      AND r.is_active IS TRUE
      AND NOT EXISTS (SELECT 1 FROM public.canteen_upsell_events ev
        WHERE ev.rule_id = r.id AND ev.booking_id = p_booking_id
          AND ev.event_type IN ('accepted','conversion','dismissed'))
      AND (p_for_order OR (
        SELECT count(*)
        FROM public.canteen_upsell_events AS ev
        WHERE ev.rule_id = r.id
          AND ev.booking_id = p_booking_id
          AND ev.event_type IN ('shown','impression')
      ) < r.max_impressions_per_booking)
    ORDER BY r.priority DESC, r.created_at ASC
  LOOP
    v_trigger_ok := false;

    CASE v_rule.trigger_type
      WHEN 'session_minutes_elapsed' THEN
        BEGIN
          v_minutes := COALESCE((v_rule.trigger_params->>'minutes')::integer,45);
        EXCEPTION WHEN OTHERS THEN
          v_minutes := 45;
        END;
        v_trigger_ok := v_elapsed_minutes >= GREATEST(0,v_minutes);

      WHEN 'session_start' THEN
        v_trigger_ok := v_elapsed_minutes BETWEEN 0 AND 15;

      WHEN 'time_of_day' THEN
        BEGIN
          v_start_time := COALESCE(
            NULLIF(v_rule.trigger_params->>'start_time','')::time,
            '00:00'::time
          );
          v_end_time := COALESCE(
            NULLIF(v_rule.trigger_params->>'end_time','')::time,
            '23:59:59'::time
          );
        EXCEPTION WHEN OTHERS THEN
          v_start_time := '00:00'::time;
          v_end_time := '23:59:59'::time;
        END;
        v_trigger_ok := CASE
          WHEN v_end_time > v_start_time
            THEN v_now::time >= v_start_time AND v_now::time < v_end_time
          ELSE v_now::time >= v_start_time OR v_now::time < v_end_time
        END;

      WHEN 'cart_contains_category' THEN
        v_category := lower(btrim(COALESCE(
          v_rule.trigger_params->>'category',''
        )));
        v_trigger_ok := v_category <> ''
          AND EXISTS (
            SELECT 1
            FROM public.canteen_orders AS co
            JOIN public.canteen_order_items AS coi ON coi.order_id = co.id
            JOIN public.extras AS e ON e.id = coi.extra_id
            WHERE co.booking_id = p_booking_id
              AND lower(btrim(e.category)) = v_category
          );

      WHEN 'room_type' THEN
        v_trigger_ok := EXISTS (SELECT 1 FROM public.rooms room WHERE room.id = v_booking.room_id
          AND (room.room_type = v_rule.trigger_params->>'room_type'
            OR room.space_type_id::text = v_rule.trigger_params->>'space_type_id'));
      ELSE
        v_trigger_ok := false;
    END CASE;

    IF NOT v_trigger_ok THEN
      CONTINUE;
    END IF;

    IF v_rule.suggest_combo_id IS NOT NULL THEN
      SELECT
        'combo',
        c.id,
        c.name_ar,
        c.name_en,
        c.image_url,
        c.price
      INTO
        v_target_type,
        v_target_id,
        v_name_ar,
        v_name_en,
        v_image_url,
        v_original_price
      FROM public.canteen_combos AS c
      WHERE c.id = v_rule.suggest_combo_id
        AND c.lounge_id = v_booking.lounge_id
        AND private.canteen_combo_window_available(c, v_now)
        AND EXISTS (SELECT 1 FROM public.canteen_combo_items ci WHERE ci.combo_id = c.id)
        AND NOT EXISTS (
          SELECT 1
          FROM public.canteen_combo_items AS ci
          JOIN public.extras AS e ON e.id = ci.extra_id
          WHERE ci.combo_id = c.id
            AND (
              e.lounge_id IS DISTINCT FROM v_booking.lounge_id
                    OR COALESCE(e.is_active,true) IS FALSE
              OR COALESCE(e.is_available,true) IS FALSE
              OR (
                COALESCE(e.track_stock,false) IS TRUE
                AND COALESCE(e.stock_quantity,0) < ci.quantity
              )
            )
        );
    ELSE
      SELECT
        'extra',
        e.id,
        COALESCE(e.name_ar,e.name),
        COALESCE(e.name_en,e.name),
        e.image_url,
        e.price
      INTO
        v_target_type,
        v_target_id,
        v_name_ar,
        v_name_en,
        v_image_url,
        v_original_price
      FROM public.extras AS e
      WHERE e.id = v_rule.suggest_extra_id
        AND e.lounge_id = v_booking.lounge_id
        AND COALESCE(e.is_active,true) IS TRUE
        AND COALESCE(e.is_available,true) IS TRUE
        AND (
          COALESCE(e.track_stock,false) IS FALSE
          OR COALESCE(e.stock_quantity,0) > 0
        );
    END IF;

    IF v_target_id IS NULL THEN
      CONTINUE;
    END IF;

    v_discount := LEAST(
      100,
      GREATEST(0,COALESCE(v_rule.discount_percent,0))
    );
    v_final_price := round(
      GREATEST(0,v_original_price * (1 - v_discount/100.0)),
      2
    );

    v_result := v_result || jsonb_build_array(
      jsonb_build_object(
        'rule_id', v_rule.id,
        'suggestion_type', v_target_type,
        'target_id', v_target_id,
        'name_ar', v_name_ar,
        'name_en', v_name_en,
        'original_price', v_original_price,
        'discount_percent', v_discount,
        'final_price', v_final_price,
        'image_url', v_image_url
      )
    );

    v_target_id := NULL;
    IF NOT p_for_order AND jsonb_array_length(v_result) >= 2 THEN EXIT; END IF;
  END LOOP;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "private"."get_canteen_upsell_suggestions"("p_booking_id" "uuid", "p_for_order" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_active_room_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
 IF (NEW.status IS DISTINCT FROM OLD.status OR NEW.is_available IS DISTINCT FROM OLD.is_available)
  AND (NEW.status IS DISTINCT FROM 'occupied' OR NEW.is_available IS DISTINCT FROM false)
  AND EXISTS(SELECT FROM public.bookings b WHERE b.room_id=NEW.id AND b.status::text='in_progress') THEN
  RAISE EXCEPTION 'ROOM_HAS_ACTIVE_SESSION' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION "private"."guard_active_room_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_booking_against_active_holds"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_start_at timestamp without time zone;
  v_end_at timestamp without time zone;
BEGIN
  IF NEW.room_id IS NULL
     OR NEW.date IS NULL
     OR NEW.start_time IS NULL
     OR NEW.end_time IS NULL
     OR NEW.status NOT IN (
       'pending'::public.booking_status,
       'upcoming'::public.booking_status,
       'in_progress'::public.booking_status
     ) THEN
    RETURN NEW;
  END IF;

  v_start_at := NEW.date::timestamp + NEW.start_time;
  v_end_at := NEW.date::timestamp + NEW.end_time;

  IF NEW.end_time <= NEW.start_time THEN
    v_end_at := v_end_at + interval '1 day';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(NEW.room_id::text, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM public.booking_holds AS h
    WHERE h.room_id = NEW.room_id
      AND h.user_id IS DISTINCT FROM NEW.user_id
      AND h.released_at IS NULL
      AND h.expires_at > now()
      AND pg_catalog.tsrange(h.start_at, h.end_at, '[)')
          && pg_catalog.tsrange(v_start_at, v_end_at, '[)')
  ) THEN
    RAISE EXCEPTION 'SLOT_HELD_BY_ANOTHER_USER'
      USING ERRCODE = '23P01';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."guard_booking_against_active_holds"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_booking_customer_updates"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_is_staff boolean;
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  SELECT (
    public.is_super_admin()
    OR public.is_lounge_admin(NEW.lounge_id)
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.lounge_id = NEW.lounge_id
        AND p.role IN ('staff', 'cashier')
    )
  ) INTO v_is_staff;

  IF v_is_staff THEN
    RETURN NEW;
  END IF;

  IF auth.uid() IS NULL OR auth.uid() <> OLD.user_id THEN
    RAISE EXCEPTION 'Not authorized to update this booking';
  END IF;

  IF NEW.total_price IS DISTINCT FROM OLD.total_price THEN
    RAISE EXCEPTION 'Customers cannot modify booking price';
  END IF;

  IF NEW.payment_status IS DISTINCT FROM OLD.payment_status THEN
    RAISE EXCEPTION 'Customers cannot modify payment status directly';
  END IF;

  IF NEW.room_id IS DISTINCT FROM OLD.room_id 
     OR NEW.lounge_id IS DISTINCT FROM OLD.lounge_id
     OR NEW.date IS DISTINCT FROM OLD.date
     OR NEW.start_time IS DISTINCT FROM OLD.start_time
     OR NEW.end_time IS DISTINCT FROM OLD.end_time THEN
    RAISE EXCEPTION 'Customers cannot modify room or schedule directly';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status <> 'cancelled'::public.booking_status THEN
      RAISE EXCEPTION 'Customers can only cancel bookings';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."guard_booking_customer_updates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_cashier_capacity_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_kind text;
BEGIN
  IF TG_OP='INSERT' AND NEW.cashier_closed_at IS NULL AND NEW.cashier_booking_timezone IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND (NEW.cashier_closed_at,NEW.cashier_booking_timezone)
    IS NOT DISTINCT FROM (OLD.cashier_closed_at,OLD.cashier_booking_timezone) THEN RETURN NEW; END IF;
  SELECT command.kind INTO v_kind FROM private.cashier_booking_command_context command
    JOIN private.cashier_sync_context context USING(transaction_id)
    JOIN private.cashier_writer_authorities writer ON writer.lounge_id=context.lounge_id
    WHERE command.transaction_id=txid_current() AND command.booking_id=NEW.id
      AND context.actor_id=auth.uid() AND context.actor_id=writer.actor_id
      AND private.cashier_sync_permit_matches_writer(context.lounge_id,context.actor_id,context.permit_id)
      AND context.lounge_id=NEW.lounge_id;
  IF NOT FOUND OR (v_kind<>'close' AND NEW.cashier_closed_at IS NOT NULL)
    OR (v_kind='close' AND (TG_OP<>'UPDATE' OR NEW.status<>'completed'::public.booking_status
      OR NEW.cashier_booking_timezone IS DISTINCT FROM OLD.cashier_booking_timezone)) THEN
    RAISE EXCEPTION 'CASHIER_CAPACITY_FIELDS_SERVER_ONLY' USING ERRCODE='42501';
  END IF;
  IF NEW.cashier_booking_timezone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names
    WHERE name=NEW.cashier_booking_timezone) THEN RAISE EXCEPTION 'INVALID_LOUNGE_TIMEZONE' USING ERRCODE='22023'; END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "private"."guard_cashier_capacity_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_cashier_online_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_room_lounge uuid;
BEGIN
  IF NEW.room_id IS NOT NULL THEN
    SELECT lounge_id INTO v_room_lounge FROM public.rooms WHERE id=NEW.room_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'ROOM_NOT_FOUND' USING ERRCODE='22023'; END IF;
    IF NEW.lounge_id IS NOT NULL AND NEW.lounge_id IS DISTINCT FROM v_room_lounge THEN
      RAISE EXCEPTION 'BOOKING_ROOM_SCOPE_MISMATCH' USING ERRCODE='42501';
    END IF;
    NEW.lounge_id:=v_room_lounge;
  END IF;
  IF TG_OP='UPDATE' AND NEW.status::text IN ('cancelled','rejected','completed') THEN
    RETURN NEW;
  END IF;
  -- A row trigger can run after an online RPC has already locked its booking
  -- or room. Waiting here would invert the reconciliation lounge-first order.
  -- Refuse a busy writer transaction with a retryable error instead of entering
  -- a deadlock or admitting an unverified online booking.
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION 'CASHIER_REQUIRES_READ_COMMITTED' USING ERRCODE='25001';
  END IF;
  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended('cashier-online:' || NEW.lounge_id::text,0)) THEN
    RAISE EXCEPTION 'CASHIER_WRITER_BUSY_RETRY' USING ERRCODE='55P03';
  END IF;
  -- Also serialize administrative writer updates that do not use the RPC.
  PERFORM 1 FROM private.cashier_writer_authorities WHERE lounge_id=NEW.lounge_id FOR SHARE NOWAIT;
  IF EXISTS (SELECT 1 FROM private.cashier_writer_authorities WHERE lounge_id=NEW.lounge_id)
     AND public.get_lounge_online_availability(NEW.lounge_id) IS NOT TRUE THEN
    IF NOT EXISTS (
      SELECT 1 FROM private.cashier_sync_context AS context
      JOIN private.cashier_writer_authorities AS writer ON writer.lounge_id=context.lounge_id
      JOIN public.profiles AS profile ON profile.id=context.actor_id
      JOIN auth.users AS identity ON identity.id=profile.id
      JOIN public.lounges AS lounge ON lounge.id=writer.lounge_id
      WHERE context.transaction_id=txid_current() AND context.actor_id=auth.uid()
        AND context.actor_id=writer.actor_id
        AND private.cashier_sync_permit_matches_writer(context.lounge_id,context.actor_id,context.permit_id)
        AND context.lounge_id=NEW.lounge_id AND profile.is_active IS TRUE
        AND profile.is_banned IS FALSE AND lounge.status='active' AND lounge.is_active IS TRUE
        AND (public.is_super_admin() IS TRUE OR public.has_lounge_permission(NEW.lounge_id,'bookings.manage') IS TRUE
          OR (TG_OP='UPDATE' AND public.has_lounge_permission(NEW.lounge_id,'sessions_control') IS TRUE
            AND NEW.status::text='in_progress' AND OLD.status::text='upcoming'
            AND (NEW.room_id,NEW.lounge_id,NEW.user_id,NEW.date,NEW.start_time,NEW.end_time)
              IS NOT DISTINCT FROM (OLD.room_id,OLD.lounge_id,OLD.user_id,OLD.date,OLD.start_time,OLD.end_time)
            AND EXISTS(SELECT 1 FROM private.cashier_booking_command_context command
              WHERE command.transaction_id=txid_current() AND command.booking_id=NEW.id AND command.kind='start')))
    ) THEN RAISE EXCEPTION 'LOUNGE_OFFLINE' USING ERRCODE='55000'; END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."guard_cashier_online_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_cashier_online_hold"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_lounge uuid;
BEGIN
 IF NEW.released_at IS NOT NULL THEN RETURN NEW; END IF;
 SELECT lounge_id INTO v_lounge FROM public.rooms WHERE id=NEW.room_id;
 IF NOT FOUND OR NEW.lounge_id IS DISTINCT FROM v_lounge THEN
   RAISE EXCEPTION 'BOOKING_ROOM_SCOPE_MISMATCH' USING ERRCODE='42501';
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
   RAISE EXCEPTION 'CASHIER_REQUIRES_READ_COMMITTED' USING ERRCODE='25001';
 END IF;
 IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('cashier-online:'||v_lounge::text,0)) THEN
   RAISE EXCEPTION 'CASHIER_WRITER_BUSY_RETRY' USING ERRCODE='55P03';
 END IF;
 PERFORM 1 FROM private.cashier_writer_authorities WHERE lounge_id=v_lounge FOR SHARE NOWAIT;
 IF EXISTS(SELECT 1 FROM private.cashier_writer_authorities WHERE lounge_id=v_lounge)
   AND public.get_lounge_online_availability(v_lounge) IS NOT TRUE THEN
   RAISE EXCEPTION 'LOUNGE_OFFLINE' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END; $$;


ALTER FUNCTION "private"."guard_cashier_online_hold"() OWNER TO "postgres";


