CREATE OR REPLACE FUNCTION "private"."guard_catalogue_tombstone"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND OLD.deleted_at IS NOT NULL THEN
    IF (to_jsonb(NEW)-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'updated_at') THEN
      RAISE EXCEPTION 'CATALOGUE_ITEM_DELETED' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.deleted_at IS NOT NULL THEN
    NEW.deleted_at:=clock_timestamp();
    NEW.is_active:=false;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "private"."guard_catalogue_tombstone"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_partial_cash_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM private.cash_collection_receipts WHERE booking_id=NEW.booking_id)
    AND NOT EXISTS (SELECT 1 FROM private.cash_collection_context
      WHERE transaction_id=txid_current() AND booking_id=NEW.booking_id) THEN
    RAISE EXCEPTION 'CASH_LEDGER_REQUIRES_CANONICAL_COLLECTION' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END; $$;


