CREATE OR REPLACE FUNCTION "private"."guard_profile_sensitive_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_changed text[] := '{}'::text[];
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.role is distinct from 'user' then v_changed := array_append(v_changed, 'role'); end if;
    if new.lounge_id is not null then v_changed := array_append(v_changed, 'lounge_id'); end if;
    if coalesce(new.is_banned, false) then v_changed := array_append(v_changed, 'is_banned'); end if;
    if new.banned_reason is not null then v_changed := array_append(v_changed, 'banned_reason'); end if;
    if coalesce(new.points, 0) <> 0 then v_changed := array_append(v_changed, 'points'); end if;
    if coalesce(new.completed_bookings_count, 0) <> 0 then v_changed := array_append(v_changed, 'completed_bookings_count'); end if;
    new.role := 'user';
    new.lounge_id := null;
    new.is_banned := false;
    new.banned_reason := null;
    new.points := 0;
    new.completed_bookings_count := 0;
    if new.referred_by is not null and new.referred_by = new.id then
      new.referred_by := null;
    end if;
  else
    if new.role is distinct from old.role then
      v_changed := array_append(v_changed, 'role'); new.role := old.role;
    end if;
    if new.lounge_id is distinct from old.lounge_id then
      v_changed := array_append(v_changed, 'lounge_id'); new.lounge_id := old.lounge_id;
    end if;
    if new.is_banned is distinct from old.is_banned then
      v_changed := array_append(v_changed, 'is_banned'); new.is_banned := old.is_banned;
    end if;
    if new.banned_reason is distinct from old.banned_reason then
      v_changed := array_append(v_changed, 'banned_reason'); new.banned_reason := old.banned_reason;
    end if;
    if new.points is distinct from old.points then
      v_changed := array_append(v_changed, 'points'); new.points := old.points;
    end if;
    if new.completed_bookings_count is distinct from old.completed_bookings_count then
      v_changed := array_append(v_changed, 'completed_bookings_count'); new.completed_bookings_count := old.completed_bookings_count;
    end if;
    -- referral fields: may be set once (when currently NULL), never changed afterwards
    if new.referral_code is distinct from old.referral_code and old.referral_code is not null then
      v_changed := array_append(v_changed, 'referral_code'); new.referral_code := old.referral_code;
    end if;
    if new.referred_by is distinct from old.referred_by
       and (old.referred_by is not null or new.referred_by = new.id) then
      v_changed := array_append(v_changed, 'referred_by'); new.referred_by := old.referred_by;
    end if;
  end if;

  if coalesce(array_length(v_changed, 1), 0) > 0 then
    raise warning 'profile_guard: % tried to change protected columns % (op=%, profile=%)',
      current_user, v_changed, tg_op, new.id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."guard_profile_sensitive_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_running_booking_room"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE room_status text;
BEGIN
 IF NEW.status::text <> 'in_progress' OR NEW.room_id IS NULL THEN RETURN NEW; END IF;
 SELECT r.status INTO room_status FROM public.rooms r WHERE r.id=NEW.room_id FOR UPDATE;
 IF NOT FOUND OR room_status IN ('maintenance','deleted') THEN
  RAISE EXCEPTION 'ROOM_NOT_AVAILABLE_FOR_SESSION' USING ERRCODE='55000';
 END IF;
 IF EXISTS(SELECT FROM public.bookings b WHERE b.room_id=NEW.room_id AND b.status::text='in_progress' AND b.id<>NEW.id) THEN
  RAISE EXCEPTION 'ROOM_HAS_ACTIVE_SESSION' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION "private"."guard_running_booking_room"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."insert_offline_order_lines"("p_operation" "jsonb", "p_lines" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_line jsonb;v_extra_id uuid;v_quantity integer;v_price numeric;
BEGIN
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    v_extra_id:=(v_line->>'extra_id')::uuid;v_quantity:=(v_line->>'quantity')::integer;v_price:=(v_line->>'price')::numeric;
    UPDATE public.extras SET stock_quantity=stock_quantity-v_quantity WHERE id=v_extra_id AND track_stock IS TRUE;
    INSERT INTO public.canteen_order_items(order_id,extra_id,quantity,unit_price,total_price,item_name)
      VALUES((p_operation->>'id')::uuid,v_extra_id,v_quantity,v_price,v_price*v_quantity,v_line->>'name');
    INSERT INTO public.booking_items(booking_id,product_id,extra_id,quantity,unit_price,total_price,price,name,note,status)
      VALUES((p_operation->>'booking_id')::uuid,v_extra_id,v_extra_id,v_quantity,v_price,v_price*v_quantity,v_price,
        v_line->>'name',p_operation->'payload'->>'note','pending');
  END LOOP;
END; $$;


ALTER FUNCTION "private"."insert_offline_order_lines"("p_operation" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_lounge_manager"("p_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = (SELECT auth.uid())
      AND p.lounge_id = p_lounge_id
      AND p.role IN ('owner','lounge_admin','admin','manager')
  ) OR EXISTS (
    SELECT 1 FROM public.lounge_staff ls
    WHERE ls.user_id = (SELECT auth.uid()) AND ls.lounge_id = p_lounge_id AND ls.role IN ('lounge_owner','manager')
  );
$$;


ALTER FUNCTION "private"."is_lounge_manager"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_lounge_member"("p_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 SELECT p_lounge_id IS NOT NULL AND auth.uid() IS NOT NULL AND EXISTS (
   SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id = p.id
   WHERE p.id = auth.uid() AND p.is_active IS TRUE AND p.is_banned IS FALSE
     AND (public.is_super_admin()
       OR EXISTS (SELECT 1 FROM public.lounges l WHERE l.id=p_lounge_id AND l.owner_id=p.id)
       OR (p.lounge_id=p_lounge_id AND p.role IN ('owner','lounge_owner','lounge_admin','admin','manager','cashier','staff','super_admin'))
       OR EXISTS (SELECT 1 FROM public.lounge_staff ls WHERE ls.user_id=p.id AND ls.lounge_id=p_lounge_id))
 );
 $$;


ALTER FUNCTION "private"."is_lounge_member"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_cash_collection_booking"("p_booking_id" "uuid") RETURNS "public"."bookings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_booking public.bookings%ROWTYPE;v_lounge_id uuid;
BEGIN
  SELECT lounge_id INTO v_lounge_id FROM public.bookings WHERE id=p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'BOOKING_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  PERFORM private.assert_cash_collector(auth.uid(),v_lounge_id);
  SELECT * INTO v_booking FROM public.bookings WHERE id=p_booking_id FOR UPDATE;
  IF NOT FOUND OR v_booking.lounge_id IS DISTINCT FROM v_lounge_id THEN
    RAISE EXCEPTION 'BOOKING_SCOPE_CHANGED' USING ERRCODE='55000';
  END IF;
  IF v_booking.status::text IN ('cancelled','rejected')
    OR (v_booking.is_open_time IS TRUE AND v_booking.status::text<>'completed') THEN
    RAISE EXCEPTION 'BOOKING_NOT_READY_FOR_COLLECTION' USING ERRCODE='55000';
  END IF;
  IF v_booking.total_price IS NULL OR v_booking.total_price<0
    OR v_booking.total_price::text IN ('NaN','Infinity','-Infinity')
    OR v_booking.total_price<>round(v_booking.total_price,2) THEN
    RAISE EXCEPTION 'INVALID_BOOKING_TOTAL' USING ERRCODE='22023';
  END IF;
  RETURN v_booking;
END; $$;


ALTER FUNCTION "private"."lock_cash_collection_booking"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_cash_collection_shift"("p_shift_id" "uuid", "p_lounge_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_shift public.shifts%ROWTYPE;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id=p_shift_id FOR SHARE;
  IF NOT FOUND OR v_shift.lounge_id IS DISTINCT FROM p_lounge_id
    OR v_shift.status IS DISTINCT FROM 'open' OR v_shift.closed_at IS NOT NULL
    OR v_shift.cashier_id IS DISTINCT FROM auth.uid()
    OR (v_shift.staff_user_id IS NOT NULL AND v_shift.staff_user_id IS DISTINCT FROM auth.uid()) THEN
    RAISE EXCEPTION 'OWN_OPEN_SHIFT_REQUIRED' USING ERRCODE='55000';
  END IF;
END; $$;


ALTER FUNCTION "private"."lock_cash_collection_shift"("p_shift_id" "uuid", "p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_cashier_lounge"("p_lounge_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STRICT SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION 'CASHIER_REQUIRES_READ_COMMITTED' USING ERRCODE='25001';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('cashier-online:' || p_lounge_id::text,0)
  );
END;
$$;


ALTER FUNCTION "private"."lock_cashier_lounge"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "private"."cashier_writer_authorities" (
    "lounge_id" "uuid" NOT NULL,
    "actor_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
    "permit_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "permit_expires_at" timestamp with time zone NOT NULL,
    "heartbeat_expires_at" timestamp with time zone NOT NULL,
    "online_requested" boolean DEFAULT false NOT NULL,
    "last_applied_sequence" bigint DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "released_at" timestamp with time zone,
    "writer_generation" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    CONSTRAINT "cashier_writer_authorities_last_applied_sequence_check" CHECK (("last_applied_sequence" >= 0))
);


ALTER TABLE "private"."cashier_writer_authorities" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_cashier_operation_writer"("p_operation" "jsonb") RETURNS "private"."cashier_writer_authorities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_writer private.cashier_writer_authorities%ROWTYPE;v_permit private.cashier_writer_permits%ROWTYPE;
  v_time timestamptz:=(p_operation->>'occurred_at')::timestamptz;v_permission text;
BEGIN
  IF auth.uid() IS DISTINCT FROM (p_operation->>'actor_id')::uuid THEN
    RAISE EXCEPTION 'OFFLINE_ACTOR_MISMATCH' USING ERRCODE='42501';
  END IF;
  PERFORM private.lock_cashier_lounge((p_operation->>'lounge_id')::uuid);
  PERFORM private.assert_offline_cashier_permission(p_operation);
  SELECT * INTO v_writer FROM private.cashier_writer_authorities
    WHERE lounge_id=(p_operation->>'lounge_id')::uuid FOR UPDATE;
  IF NOT FOUND OR v_writer.released_at IS NOT NULL OR v_writer.actor_id IS DISTINCT FROM auth.uid()
    OR v_writer.device_id IS DISTINCT FROM (p_operation->>'device_id')::uuid THEN
    RAISE EXCEPTION 'OFFLINE_WRITER_MISMATCH' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_permit FROM private.cashier_writer_permits WHERE permit_id=(p_operation->>'permit_id')::uuid FOR SHARE;
  IF NOT FOUND OR (v_permit.lounge_id,v_permit.actor_id,v_permit.device_id)
    IS DISTINCT FROM (v_writer.lounge_id,v_writer.actor_id,v_writer.device_id) THEN
    RAISE EXCEPTION 'OFFLINE_WRITER_MISMATCH' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM private.cashier_permit_generations WHERE permit_id=v_permit.permit_id
    AND writer_generation=v_writer.writer_generation) THEN
    RAISE EXCEPTION 'OFFLINE_WRITER_GENERATION_MISMATCH' USING ERRCODE='42501';
  END IF;
  v_permission:=CASE p_operation->>'kind' WHEN 'reserve' THEN 'bookings.manage'
    WHEN 'collectCash' THEN 'billing_checkout' ELSE 'sessions_control' END;
  IF v_permit.permissions->v_permission IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'OFFLINE_PERMISSION_NOT_ISSUED' USING ERRCODE='42501';
  END IF;
  IF v_time<v_permit.issued_at OR v_time>=v_permit.expires_at
    OR v_time>statement_timestamp()+interval '5 minutes' THEN
    RAISE EXCEPTION 'OFFLINE_OPERATION_OUTSIDE_PERMIT' USING ERRCODE='22023';
  END IF;
  RETURN v_writer;
END; $$;


ALTER FUNCTION "private"."lock_cashier_operation_writer"("p_operation" "jsonb") OWNER TO "postgres";


