CREATE OR REPLACE FUNCTION "private"."price_offline_order_lines"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_line jsonb;v_extra public.extras%ROWTYPE;v_lines jsonb:='[]';v_quantity integer;v_requested integer;
BEGIN
  PERFORM 1 FROM public.extras WHERE id IN
    (SELECT (value->>'product_id')::uuid FROM jsonb_array_elements(p_operation->'quoted_items')) ORDER BY id FOR UPDATE;
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_operation->'quoted_items') LOOP
    SELECT * INTO v_extra FROM public.extras WHERE id=(v_line->>'product_id')::uuid;
    IF NOT FOUND OR v_extra.lounge_id IS DISTINCT FROM (p_operation->>'lounge_id')::uuid
      OR v_extra.is_active IS NOT TRUE OR v_extra.is_available IS NOT TRUE THEN
      RAISE EXCEPTION 'OFFLINE_PRODUCT_UNAVAILABLE' USING ERRCODE='55000';
    END IF;
    IF v_extra.price<0 OR v_extra.price IS NULL OR v_extra.price::text IN ('NaN','Infinity','-Infinity')
      OR v_extra.price<>round(v_extra.price,2) OR v_extra.price*100 IS DISTINCT FROM (v_line->>'unit_price_minor')::numeric THEN
      RAISE EXCEPTION 'OFFLINE_PRODUCT_PRICE_CHANGED' USING ERRCODE='22023';
    END IF;
    v_quantity:=(v_line->>'quantity')::integer;
    SELECT sum((value->>'quantity')::integer) INTO v_requested FROM jsonb_array_elements(p_operation->'quoted_items')
      WHERE (value->>'product_id')::uuid=v_extra.id;
    IF v_extra.track_stock IS NULL OR (v_extra.track_stock AND
      (v_extra.stock_quantity IS NULL OR v_extra.stock_quantity<v_requested)) THEN
      RAISE EXCEPTION 'OFFLINE_INSUFFICIENT_STOCK' USING ERRCODE='55000';
    END IF;
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('product_id',v_extra.id,'extra_id',v_extra.id,
      'quantity',v_quantity,'price',v_extra.price,'unit_price',v_extra.price,
      'total_price',v_extra.price*v_quantity,'name',v_extra.name));
  END LOOP;
  RETURN v_lines;
END; $$;


ALTER FUNCTION "private"."price_offline_order_lines"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."price_room_interval"("p_room_id" "uuid", "p_date" "date", "p_start" time without time zone, "p_end" time without time zone, "p_play_mode" "text" DEFAULT 'single'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
  v_base_rate numeric;
  v_start_min integer;
  v_end_min integer;
  v_boundaries integer[];
  v_sorted integer[];
  v_rule public.pricing_rules%ROWTYPE;
  v_offset integer;
  v_rule_date date;
  v_rule_start integer;
  v_rule_end integer;
  v_i integer;
  v_seg_start integer;
  v_seg_end integer;
  v_mid integer;
  v_mid_date date;
  v_mid_time time;
  v_match public.pricing_rules%ROWTYPE;
  v_rate numeric;
  v_minutes integer;
  v_amount numeric;
  v_total numeric := 0;
  v_segments jsonb := '[]'::jsonb;
  v_has_rule boolean := false;
  v_duration integer;
  v_avg_rate numeric;
BEGIN
  IF p_room_id IS NULL OR p_date IS NULL OR p_start IS NULL OR p_end IS NULL THEN
    RAISE EXCEPTION 'Missing pricing interval arguments' USING ERRCODE='22023';
  END IF;

  SELECT r.* INTO v_room
  FROM public.rooms AS r
  WHERE r.id=p_room_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found' USING ERRCODE='P0002';
  END IF;

  v_base_rate := CASE
    WHEN lower(COALESCE(p_play_mode,'single'))='multi'
      AND COALESCE(v_room.hourly_rate_multi,0)>0
      THEN v_room.hourly_rate_multi
    ELSE COALESCE(v_room.hourly_rate_single,v_room.hourly_rate,0)
  END;

  IF COALESCE(v_base_rate,0)<=0 THEN
    RAISE EXCEPTION 'Room has no valid hourly rate' USING ERRCODE='23514';
  END IF;

  v_start_min := (
    extract(hour from p_start)*60 + extract(minute from p_start)
  )::integer;
  v_end_min := (
    extract(hour from p_end)*60 + extract(minute from p_end)
  )::integer;
  IF v_end_min <= v_start_min THEN
    v_end_min := v_end_min + 1440;
  END IF;

  v_duration := v_end_min-v_start_min;
  IF v_duration<=0 OR v_duration>1440 THEN
    RAISE EXCEPTION 'Invalid pricing duration' USING ERRCODE='22023';
  END IF;

  v_boundaries := ARRAY[v_start_min,v_end_min];

  FOR v_rule IN
    SELECT pr.*
    FROM public.pricing_rules AS pr
    WHERE pr.lounge_id=v_room.lounge_id
      AND pr.is_active IS TRUE
      AND (pr.room_id IS NULL OR pr.room_id=v_room.id)
      AND (
        pr.space_type_id IS NULL
        OR pr.space_type_id=v_room.space_type_id
      )
  LOOP
    FOR v_offset IN -1..1 LOOP
      v_rule_date := p_date + v_offset;

      IF (v_rule.start_date IS NULL OR v_rule_date>=v_rule.start_date)
         AND (v_rule.end_date IS NULL OR v_rule_date<=v_rule.end_date)
         AND extract(isodow from v_rule_date)::integer = ANY(v_rule.days_of_week)
      THEN
        v_rule_start :=
          v_offset*1440
          + (extract(hour from v_rule.start_time)*60
             + extract(minute from v_rule.start_time))::integer;
        v_rule_end :=
          v_offset*1440
          + (extract(hour from v_rule.end_time)*60
             + extract(minute from v_rule.end_time))::integer;

        IF v_rule.end_time<=v_rule.start_time THEN
          v_rule_end:=v_rule_end+1440;
        END IF;

        IF v_rule_start>v_start_min AND v_rule_start<v_end_min THEN
          v_boundaries:=array_append(v_boundaries,v_rule_start);
        END IF;
        IF v_rule_end>v_start_min AND v_rule_end<v_end_min THEN
          v_boundaries:=array_append(v_boundaries,v_rule_end);
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  SELECT array_agg(DISTINCT x ORDER BY x)
  INTO v_sorted
  FROM unnest(v_boundaries) AS x;

  FOR v_i IN 1..cardinality(v_sorted)-1 LOOP
    v_seg_start:=v_sorted[v_i];
    v_seg_end:=v_sorted[v_i+1];
    v_minutes:=v_seg_end-v_seg_start;
    IF v_minutes<=0 THEN CONTINUE; END IF;

    v_mid:=floor((v_seg_start+v_seg_end)/2.0)::integer;
    v_mid_date:=p_date + floor(v_mid/1440.0)::integer;
    v_mid_time:=
      '00:00:00'::time
      + ((v_mid % 1440)::text || ' minutes')::interval;

    v_match:=NULL;

    SELECT pr.*
    INTO v_match
    FROM public.pricing_rules AS pr
    WHERE pr.lounge_id=v_room.lounge_id
      AND pr.is_active IS TRUE
      AND (pr.room_id IS NULL OR pr.room_id=v_room.id)
      AND (
        pr.space_type_id IS NULL
        OR pr.space_type_id=v_room.space_type_id
      )
      AND (
        (
          pr.end_time>pr.start_time
          AND v_mid_time>=pr.start_time
          AND v_mid_time<pr.end_time
        )
        OR (
          pr.end_time<=pr.start_time
          AND (v_mid_time>=pr.start_time OR v_mid_time<pr.end_time)
        )
      )
      AND (
        pr.start_date IS NULL
        OR (
          CASE
            WHEN pr.end_time<=pr.start_time AND v_mid_time<pr.end_time
              THEN v_mid_date-1
            ELSE v_mid_date
          END
        )>=pr.start_date
      )
      AND (
        pr.end_date IS NULL
        OR (
          CASE
            WHEN pr.end_time<=pr.start_time AND v_mid_time<pr.end_time
              THEN v_mid_date-1
            ELSE v_mid_date
          END
        )<=pr.end_date
      )
      AND extract(
        isodow FROM
        CASE
          WHEN pr.end_time<=pr.start_time AND v_mid_time<pr.end_time
            THEN v_mid_date-1
          ELSE v_mid_date
        END
      )::integer = ANY(pr.days_of_week)
    ORDER BY
      pr.priority DESC,
      (pr.room_id IS NOT NULL) DESC,
      (pr.space_type_id IS NOT NULL) DESC,
      pr.created_at DESC,
      pr.id
    LIMIT 1;

    IF FOUND THEN
      v_has_rule:=true;
      v_rate:=CASE v_match.adjustment_type
        WHEN 'multiplier' THEN v_base_rate*v_match.adjustment_value
        WHEN 'percentage' THEN
          v_base_rate*(1+(v_match.adjustment_value/100.0))
        WHEN 'fixed' THEN v_match.adjustment_value
        ELSE v_base_rate
      END;
    ELSE
      v_rate:=v_base_rate;
    END IF;

    v_rate:=GREATEST(0,round(v_rate,2));
    v_amount:=round((v_rate/60.0)*v_minutes,2);
    v_total:=v_total+v_amount;

    v_segments:=v_segments || jsonb_build_array(
      jsonb_build_object(
        'from',
          to_char(
            '00:00:00'::time
            + ((v_seg_start % 1440)::text || ' minutes')::interval,
            'HH24:MI:SS'
          ),
        'to',
          to_char(
            '00:00:00'::time
            + ((v_seg_end % 1440)::text || ' minutes')::interval,
            'HH24:MI:SS'
          ),
        'minutes',v_minutes,
        'rate',v_rate,
        'amount',v_amount,
        'rule_id',CASE WHEN FOUND THEN v_match.id ELSE NULL END,
        'rule_name_ar',CASE WHEN FOUND THEN v_match.name_ar ELSE NULL END,
        'rule_name_en',CASE WHEN FOUND THEN v_match.name_en ELSE NULL END
      )
    );
  END LOOP;

  v_avg_rate:=CASE
    WHEN v_duration>0 THEN round(v_total/(v_duration/60.0),2)
    ELSE v_base_rate
  END;

  RETURN jsonb_build_object(
    'room_id',p_room_id,
    'base_rate',v_base_rate,
    'effective_hourly_rate',v_avg_rate,
    'room_subtotal',round(v_total,2),
    'duration_minutes',v_duration,
    'has_peak_rates',v_has_rule,
    'segments',v_segments
  );
END;
$$;


ALTER FUNCTION "private"."price_room_interval"("p_room_id" "uuid", "p_date" "date", "p_start" time without time zone, "p_end" time without time zone, "p_play_mode" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pricing_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lounge_id" "uuid" NOT NULL,
    "space_type_id" "uuid",
    "room_id" "uuid",
    "name_ar" "text" NOT NULL,
    "name_en" "text" NOT NULL,
    "rule_type" "text" DEFAULT 'peak'::"text" NOT NULL,
    "days_of_week" integer[] DEFAULT ARRAY[1, 2, 3, 4, 5, 6, 7] NOT NULL,
    "start_time" time without time zone NOT NULL,
    "end_time" time without time zone NOT NULL,
    "start_date" "date",
    "end_date" "date",
    "adjustment_type" "text" DEFAULT 'multiplier'::"text" NOT NULL,
    "adjustment_value" numeric NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "priority" integer DEFAULT 10 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "pricing_rules_adjustment_type_check" CHECK (("adjustment_type" = ANY (ARRAY['multiplier'::"text", 'percentage'::"text", 'fixed'::"text"]))),
    CONSTRAINT "pricing_rules_adjustment_valid" CHECK (((("adjustment_type" = 'multiplier'::"text") AND ("adjustment_value" > (0)::numeric)) OR (("adjustment_type" = 'percentage'::"text") AND ("adjustment_value" >= ('-100'::integer)::numeric)) OR (("adjustment_type" = 'fixed'::"text") AND ("adjustment_value" >= (0)::numeric)))),
    CONSTRAINT "pricing_rules_dates_valid" CHECK ((("start_date" IS NULL) OR ("end_date" IS NULL) OR ("end_date" >= "start_date"))),
    CONSTRAINT "pricing_rules_days_valid" CHECK ((("cardinality"("days_of_week") > 0) AND ("days_of_week" <@ ARRAY[1, 2, 3, 4, 5, 6, 7]))),
    CONSTRAINT "pricing_rules_rule_type_check" CHECK (("rule_type" = ANY (ARRAY['peak'::"text", 'off_peak'::"text", 'standard'::"text", 'custom'::"text"])))
);


ALTER TABLE "public"."pricing_rules" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."pricing_rule_windows_overlap"("p_existing" "public"."pricing_rules", "p_start" time without time zone, "p_end" time without time zone, "p_days" integer[], "p_start_date" "date", "p_end_date" "date") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  v_day integer;
  v_offset integer;
  v_start integer := extract(epoch FROM p_start)::integer;
  v_end integer := extract(epoch FROM p_end)::integer;
  v_existing_start integer := extract(epoch FROM p_existing.start_time)::integer;
  v_existing_end integer := extract(epoch FROM p_existing.end_time)::integer;
  v_low date;
  v_high date;
  v_first date;
BEGIN
  IF v_end <= v_start THEN v_end := v_end + 86400; END IF;
  IF v_existing_end <= v_existing_start THEN v_existing_end := v_existing_end + 86400; END IF;
  FOREACH v_day IN ARRAY p_existing.days_of_week LOOP
    FOR v_offset IN -1..1 LOOP
      IF ((v_day + v_offset + 6) % 7 + 1) = ANY(p_days)
         AND v_existing_start < v_end + v_offset * 86400
         AND v_start + v_offset * 86400 < v_existing_end THEN
        v_low := GREATEST(COALESCE(p_existing.start_date,'0001-01-01'::date),
          COALESCE(p_start_date - v_offset,'0001-01-01'::date));
        v_high := LEAST(COALESCE(p_existing.end_date,'9999-12-31'::date),
          COALESCE(p_end_date - v_offset,'9999-12-31'::date));
        v_first := v_low + ((v_day - extract(isodow FROM v_low)::integer + 7) % 7);
        IF v_first <= v_high THEN RETURN true; END IF;
      END IF;
    END LOOP;
  END LOOP;
  RETURN false;
END;
$$;


ALTER FUNCTION "private"."pricing_rule_windows_overlap"("p_existing" "public"."pricing_rules", "p_start" time without time zone, "p_end" time without time zone, "p_days" integer[], "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."pricing_time_windows_overlap"("p_start_a" time without time zone, "p_end_a" time without time zone, "p_start_b" time without time zone, "p_end_b" time without time zone) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  a1 integer;
  a2 integer;
  b1 integer;
  b2 integer;
BEGIN
  a1 := (extract(hour from p_start_a)*60 + extract(minute from p_start_a))::integer;
  a2 := (extract(hour from p_end_a)*60 + extract(minute from p_end_a))::integer;
  b1 := (extract(hour from p_start_b)*60 + extract(minute from p_start_b))::integer;
  b2 := (extract(hour from p_end_b)*60 + extract(minute from p_end_b))::integer;
  IF a2 <= a1 THEN a2 := a2 + 1440; END IF;
  IF b2 <= b1 THEN b2 := b2 + 1440; END IF;

  RETURN
    (a1 < b2 AND b1 < a2)
    OR (a1 < b2 + 1440 AND b1 + 1440 < a2)
    OR (a1 + 1440 < b2 AND b1 < a2 + 1440);
END;
$$;


ALTER FUNCTION "private"."pricing_time_windows_overlap"("p_start_a" time without time zone, "p_end_a" time without time zone, "p_start_b" time without time zone, "p_end_b" time without time zone) OWNER TO "postgres";


