    "registration_status" "text" DEFAULT 'pending_payment'::"text" NOT NULL,
    "payment_status" "text" DEFAULT 'unpaid'::"text" NOT NULL,
    "payment_method" "text",
    "receipt_url" "text",
    "payment_deadline" timestamp with time zone,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "payment_rejection_reason" "text",
    "is_checked_in" boolean DEFAULT false NOT NULL,
    "checked_in_at" timestamp with time zone,
    "waitlist_position" integer,
    "cash_received_by" "uuid",
    "cash_received_at" timestamp with time zone,
    "cash_reference_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "participant_deadline_check" CHECK (((("registration_status" = 'waitlist'::"text") AND ("payment_deadline" IS NULL)) OR ("registration_status" <> 'waitlist'::"text"))),
    CONSTRAINT "participant_waitlist_position_check" CHECK (((("registration_status" = 'waitlist'::"text") AND ("waitlist_position" IS NOT NULL) AND ("waitlist_position" > 0)) OR ("registration_status" <> 'waitlist'::"text"))),
    CONSTRAINT "tournament_participants_payment_method_check" CHECK ((("payment_method" IS NULL) OR ("payment_method" = ANY (ARRAY['instapay'::"text", 'vodafone_cash'::"text", 'cash'::"text"])))),
    CONSTRAINT "tournament_participants_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['unpaid'::"text", 'pending'::"text", 'paid'::"text"]))),
    CONSTRAINT "tournament_participants_registration_status_check" CHECK (("registration_status" = ANY (ARRAY['pending_payment'::"text", 'waitlist'::"text", 'confirmed'::"text", 'checked_in'::"text", 'eliminated'::"text", 'expired'::"text", 'cancelled'::"text", 'withdrawn'::"text", 'no_show'::"text"])))
);


ALTER TABLE "public"."tournament_participants" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."promote_tournament_waitlist_internal"("p_tournament_id" "uuid") RETURNS "public"."tournament_participants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_p public.tournament_participants%ROWTYPE;
  v_count integer;
  v_old_position integer;
BEGIN
  SELECT * INTO v_t
  FROM public.tournaments
  WHERE id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament_not_found';
  END IF;

  SELECT count(*) INTO v_count
  FROM public.tournament_participants
  WHERE tournament_id = p_tournament_id
    AND registration_status IN ('pending_payment', 'confirmed', 'checked_in');

  IF v_count >= v_t.max_participants THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_p
  FROM public.tournament_participants
  WHERE tournament_id = p_tournament_id
    AND registration_status = 'waitlist'
  ORDER BY waitlist_position, created_at, id
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_old_position := v_p.waitlist_position;

  UPDATE public.tournament_participants
  SET registration_status = 'pending_payment',
      payment_status = 'unpaid',
      payment_deadline = now() + make_interval(mins => v_t.payment_deadline_minutes),
      waitlist_position = NULL,
      updated_at = now()
  WHERE id = v_p.id
  RETURNING * INTO v_p;

  UPDATE public.tournament_participants
  SET waitlist_position = waitlist_position - 1,
      updated_at = now()
  WHERE tournament_id = p_tournament_id
    AND registration_status = 'waitlist'
    AND waitlist_position > v_old_position;

  PERFORM public.tournament_audit(
    p_tournament_id,
    'waitlist_promoted',
    v_p.id,
    NULL,
    NULL,
    to_jsonb(v_p),
    'Automatic promotion after a seat became available'
  );

  RETURN v_p;
END;
$$;


ALTER FUNCTION "private"."promote_tournament_waitlist_internal"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."queue_auth_disabling"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.is_active IS NOT TRUE OR NEW.is_banned IS NOT FALSE THEN
    INSERT INTO private.auth_disable_tasks(user_id) VALUES(NEW.id)
    ON CONFLICT(user_id) DO UPDATE SET status='pending',attempts=0,requested_at=now(),
      next_attempt_at=now(),lease_id=NULL,leased_until=NULL,completed_at=NULL,last_error_code=NULL;
  ELSE
    UPDATE private.auth_disable_tasks SET status='cancelled',lease_id=NULL,leased_until=NULL
    WHERE user_id=NEW.id AND status IN ('pending','running','failed');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."queue_auth_disabling"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."quote_offline_fixed_booking"("p_operation" "jsonb", "p_interval" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_quote jsonb;v_total numeric;
BEGIN
  IF p_operation->'payload'->>'play_mode' NOT IN ('single','multi') OR p_operation->'payload'->>'play_mode' IS NULL
    OR jsonb_typeof(p_operation->'quoted_total_minor') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_operation->'payload'->'customer_name') IS DISTINCT FROM 'string'
    OR (p_operation->'payload' ? 'customer_phone' AND p_operation->'payload'->'customer_phone'<>'null'::jsonb
      AND jsonb_typeof(p_operation->'payload'->'customer_phone') IS DISTINCT FROM 'string')
    OR nullif(btrim(p_operation->'payload'->>'customer_name'),'') IS NULL
    OR length(p_operation->'payload'->>'customer_name')>120
    OR length(coalesce(p_operation->'payload'->>'customer_phone',''))>32 THEN
    RAISE EXCEPTION 'INVALID_OFFLINE_BOOKING' USING ERRCODE='22023';
  END IF;
  v_total:=(p_operation->>'quoted_total_minor')::numeric;
  IF v_total<=0 OR v_total<>trunc(v_total) OR v_total>9007199254740991 THEN
    RAISE EXCEPTION 'INVALID_OFFLINE_BOOKING' USING ERRCODE='22023';
  END IF;
  v_quote:=public.quote_booking_price((p_operation->'payload'->>'room_id')::uuid,
    (p_interval->>'start')::timestamp::date,(p_interval->>'start')::timestamp::time,(p_interval->>'end')::timestamp::time,
    p_operation->'payload'->>'play_mode',0,NULL);
  IF (v_quote->>'final_total')::numeric*100 IS DISTINCT FROM v_total
    OR (v_quote->>'room_subtotal')::numeric IS DISTINCT FROM (v_quote->>'final_total')::numeric
    OR (v_quote->>'duration_minutes')::numeric IS DISTINCT FROM (p_interval->>'minutes')::numeric THEN
    RAISE EXCEPTION 'OFFLINE_BOOKING_PRICE_CHANGED' USING ERRCODE='22023';
  END IF;
  RETURN v_quote;
END; $$;


ALTER FUNCTION "private"."quote_offline_fixed_booking"("p_operation" "jsonb", "p_interval" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_booking_cancellation_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid := (SELECT auth.uid());
  v_source text;
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status
     AND NEW.status = 'cancelled'::public.booking_status THEN
    v_source := CASE
      WHEN v_actor IS NULL THEN 'system'
      WHEN v_actor = OLD.user_id THEN 'user'
      ELSE 'staff'
    END;

    INSERT INTO private.booking_cancellation_events (
      booking_id, user_id, lounge_id, cancellation_reason,
      cancellation_source, was_approved, cancelled_by, cancelled_at,
      booking_date, start_time, end_time, room_name
    ) VALUES (
      NEW.id, OLD.user_id, OLD.lounge_id,
      COALESCE(NEW.cancellation_reason, OLD.cancellation_reason),
      v_source,
      (OLD.status = 'upcoming'::public.booking_status OR OLD.approved_at IS NOT NULL),
      NEW.cancelled_by,
      COALESCE(NEW.cancelled_at, statement_timestamp()),
      OLD.date, OLD.start_time, OLD.end_time, OLD.room_name
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."record_booking_cancellation_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."require_active_booking_actor"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id = p.id
    WHERE p.id = v_actor AND p.is_active IS TRUE AND p.is_banned IS FALSE
  ) THEN
    RAISE EXCEPTION 'Active account required' USING ERRCODE = '42501';
  END IF;
  RETURN v_actor;
END;
$$;


ALTER FUNCTION "private"."require_active_booking_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."role_permission_value"("p_role" "text", "p_lounge_id" "uuid", "p_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT CASE
    WHEN NOT private.permission_key_allowed_for_role(p_role, p_key) THEN false
    ELSE COALESCE((
      SELECT COALESCE(
        (
          SELECT lrp.is_enabled
          FROM public.lounge_role_permissions AS lrp
          WHERE lrp.lounge_id = p_lounge_id
            AND lrp.role = p_role
            AND lrp.permission_key = a.key
        ),
        CASE p_role
          WHEN 'super_admin' THEN a.default_super_admin
          WHEN 'owner' THEN a.default_owner
          WHEN 'manager' THEN a.default_owner
          WHEN 'cashier' THEN a.default_cashier
          ELSE false
        END,
        false
      )
      FROM public.app_permissions AS a
      WHERE a.key = p_key
    ), false)
  END;
$$;


ALTER FUNCTION "private"."role_permission_value"("p_role" "text", "p_lounge_id" "uuid", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."user_permission_value"("p_user_id" "uuid", "p_lounge_id" "uuid", "p_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT COALESCE((SELECT CASE
    WHEN private.permission_role(p_user_id,p_lounge_id) IS NULL THEN false
    ELSE COALESCE(
      (SELECT sp.is_enabled FROM public.staff_permissions sp
       WHERE sp.user_id=p_user_id AND sp.lounge_id IS NOT DISTINCT FROM p_lounge_id
         AND sp.permission_key=a.key),
      private.role_permission_value(private.permission_role(p_user_id,p_lounge_id),p_lounge_id,a.key),false)
    END FROM public.app_permissions a WHERE a.key=p_key),false);
$$;


ALTER FUNCTION "private"."user_permission_value"("p_user_id" "uuid", "p_lounge_id" "uuid", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_cashier_operation"("p_operation" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE v_id uuid;v_sequence numeric;v_time timestamptz;v_name text;
BEGIN
  IF p_operation IS NULL OR jsonb_typeof(p_operation)<>'object' OR length(p_operation::text)>65536
    OR jsonb_typeof(p_operation->'payload') IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_operation->'sequence') IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION 'INVALID_OFFLINE_OPERATION' USING ERRCODE='22023';
  END IF;
  FOREACH v_name IN ARRAY ARRAY['id','actor_id','lounge_id','device_id','permit_id','booking_id','shift_id'] LOOP
    v_id:=(p_operation->>v_name)::uuid;
    IF v_id IS NULL THEN RAISE EXCEPTION 'INVALID_OFFLINE_OPERATION' USING ERRCODE='22023'; END IF;
  END LOOP;
  v_sequence:=(p_operation->>'sequence')::numeric;
  IF v_sequence<=0 OR v_sequence<>trunc(v_sequence) OR v_sequence>9007199254740991
    OR (p_operation->>'occurred_at') IS NULL
    OR (p_operation->>'occurred_at')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
    RAISE EXCEPTION 'INVALID_OFFLINE_OPERATION' USING ERRCODE='22023';
  END IF;
  v_time:=(p_operation->>'occurred_at')::timestamptz;
  IF NOT isfinite(v_time) THEN RAISE EXCEPTION 'INVALID_OFFLINE_OPERATION' USING ERRCODE='22023'; END IF;
  IF p_operation->>'kind' IS NULL OR p_operation->>'kind' NOT IN ('collectCash','addItems','reserve','start','close') THEN
    RAISE EXCEPTION 'OFFLINE_OPERATION_KIND_NOT_IMPLEMENTED' USING ERRCODE='0A000';
  END IF;
END; $_$;


ALTER FUNCTION "private"."validate_cashier_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_offline_order_lines"("p_operation" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_items jsonb:=p_operation->'payload'->'items';v_quotes jsonb:=p_operation->'quoted_items';
  v_line jsonb;v_quote jsonb;v_index integer;v_id uuid;v_quantity numeric;v_price numeric;v_total numeric;
BEGIN
  IF jsonb_typeof(v_items) IS DISTINCT FROM 'array' OR jsonb_typeof(v_quotes) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'INVALID_OFFLINE_ORDER' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(v_items) NOT BETWEEN 1 AND 50 OR jsonb_array_length(v_quotes)<>jsonb_array_length(v_items)
    OR jsonb_typeof(p_operation->'quoted_total_minor') IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION 'INVALID_OFFLINE_ORDER' USING ERRCODE='22023';
  END IF;
  v_total:=(p_operation->>'quoted_total_minor')::numeric;
  IF v_total<0 OR v_total<>trunc(v_total) OR v_total>9007199254740991 THEN
    RAISE EXCEPTION 'INVALID_OFFLINE_ORDER' USING ERRCODE='22023';
  END IF;
  FOR v_index IN 0..jsonb_array_length(v_items)-1 LOOP
    v_line:=v_items->v_index;v_quote:=v_quotes->v_index;v_id:=(v_line->>'product_id')::uuid;
    IF v_id IS NULL OR jsonb_typeof(v_line->'quantity') IS DISTINCT FROM 'number'
      OR jsonb_typeof(v_quote->'unit_price_minor') IS DISTINCT FROM 'number'
      OR v_quote->'product_id' IS DISTINCT FROM v_line->'product_id'
      OR v_quote->'quantity' IS DISTINCT FROM v_line->'quantity' THEN
      RAISE EXCEPTION 'INVALID_OFFLINE_ORDER' USING ERRCODE='22023';
    END IF;
    v_quantity:=(v_line->>'quantity')::numeric;v_price:=(v_quote->>'unit_price_minor')::numeric;
    IF v_quantity NOT BETWEEN 1 AND 100 OR v_quantity<>trunc(v_quantity)
      OR v_price<0 OR v_price<>trunc(v_price) OR v_price>9007199254740991 THEN
      RAISE EXCEPTION 'INVALID_OFFLINE_ORDER' USING ERRCODE='22023';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION "private"."validate_offline_order_lines"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_offline_session_snapshot"("p_operation" "jsonb", "p_receipt" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_snapshot jsonb:=p_operation->'quoted_session';v_field text;v_started jsonb;
BEGIN
  IF jsonb_typeof(v_snapshot) IS DISTINCT FROM 'object'
    OR NOT v_snapshot ?& ARRAY['room_id','timezone','start_ms','end_ms','started_ms','paid_minor'] THEN
    RAISE EXCEPTION 'OFFLINE_SESSION_SNAPSHOT_REQUIRED' USING ERRCODE='22023';
  END IF;
  FOREACH v_field IN ARRAY ARRAY['room_id','timezone','start_ms','end_ms','paid_minor'] LOOP
    IF v_snapshot->v_field IS DISTINCT FROM p_receipt->v_field THEN
      RAISE EXCEPTION 'OFFLINE_SESSION_SNAPSHOT_CHANGED' USING ERRCODE='22023';
    END IF;
  END LOOP;
  v_started:=CASE WHEN p_receipt->>'started_at' IS NULL THEN 'null'::jsonb
    ELSE to_jsonb(floor(extract(epoch FROM (p_receipt->>'started_at')::timestamptz)*1000)) END;
  IF v_snapshot->'started_ms' IS DISTINCT FROM v_started THEN
    RAISE EXCEPTION 'OFFLINE_SESSION_SNAPSHOT_CHANGED' USING ERRCODE='22023';
  END IF;
END; $$;


ALTER FUNCTION "private"."validate_offline_session_snapshot"("p_operation" "jsonb", "p_receipt" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_playspot_guard_lounge_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_is_super_admin boolean := public._playspot_is_super_admin();
  v_owner_id uuid;
BEGIN
  v_owner_id := COALESCE(NEW.owner_id, OLD.owner_id);

  IF NOT v_is_super_admin THEN
    IF TG_OP = 'UPDATE'
       AND NEW.owner_id IS DISTINCT FROM OLD.owner_id
    THEN
      RAISE EXCEPTION 'Only a super admin may change lounge ownership'
        USING ERRCODE = '42501';
    END IF;

    IF TG_OP = 'UPDATE'
       AND OLD.owner_id IS DISTINCT FROM auth.uid()
       AND (
         NEW.brand_id IS DISTINCT FROM OLD.brand_id
         OR NEW.parent_lounge_id IS DISTINCT FROM OLD.parent_lounge_id
         OR NEW.is_main_branch IS DISTINCT FROM OLD.is_main_branch
       )
    THEN
      RAISE EXCEPTION 'Branch structure may only be changed by its owner'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NEW.brand_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.brands b
       WHERE b.id = NEW.brand_id
         AND b.owner_id = v_owner_id
     )
  THEN
    RAISE EXCEPTION 'Brand must belong to the lounge owner'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.parent_lounge_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.lounges parent
       WHERE parent.id = NEW.parent_lounge_id
         AND parent.owner_id = v_owner_id
     )
  THEN
    RAISE EXCEPTION 'Parent lounge must belong to the same owner'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_playspot_guard_lounge_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_playspot_has_lounge_access"("p_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT p_lounge_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id = p.id
      WHERE p.id = auth.uid() AND p.is_active IS TRUE AND p.is_banned IS FALSE
    )
    AND (
      public._playspot_is_super_admin()
      OR EXISTS (SELECT 1 FROM public.lounges l
                 WHERE l.id = p_lounge_id AND l.owner_id = auth.uid())
      OR EXISTS (SELECT 1 FROM public.lounge_staff ls
                 WHERE ls.lounge_id = p_lounge_id AND ls.user_id = auth.uid())
      OR EXISTS (SELECT 1 FROM public.profiles p
                 WHERE p.id = auth.uid() AND p.lounge_id = p_lounge_id
                   AND p.role IN ('owner','lounge_admin','admin','manager','cashier','staff'))
    );
$$;


ALTER FUNCTION "public"."_playspot_has_lounge_access"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_playspot_is_super_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT public.is_super_admin() IS TRUE;
$$;


ALTER FUNCTION "public"."_playspot_is_super_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_booking_hold"("p_room_ids" "uuid"[], "p_start_at" timestamp without time zone, "p_end_at" timestamp without time zone, "p_hold_minutes" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_room_ids uuid[];
  v_room_id uuid;
  v_room_count integer;
  v_found_count integer;
  v_lounge_count integer;
  v_lounge_id uuid;
  v_lounge public.lounges%ROWTYPE;
  v_has_open_shift boolean;
  v_is_future boolean;
  v_tz text := 'Africa/Cairo';
  v_local_now timestamp without time zone;
  v_hold_token uuid := gen_random_uuid();
  v_expires_at timestamptz;
  v_is_request_only boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM private.require_active_booking_actor();

  IF p_start_at IS NULL OR p_end_at IS NULL OR p_end_at <= p_start_at THEN
    RAISE EXCEPTION 'Invalid booking hold range' USING ERRCODE = '22023';
  END IF;

  IF p_end_at - p_start_at > interval '24 hours' THEN
    RAISE EXCEPTION 'Booking hold range is too long' USING ERRCODE = '22023';
  END IF;

  IF p_room_ids IS NULL OR cardinality(p_room_ids) = 0 THEN
    RAISE EXCEPTION 'At least one room is required' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(room_id ORDER BY room_id), count(*)
  INTO v_room_ids, v_room_count
  FROM (
    SELECT DISTINCT unnest(p_room_ids) AS room_id
  ) AS requested_rooms;

  IF v_room_count > 20 THEN
    RAISE EXCEPTION 'Too many rooms requested' USING ERRCODE = '22023';
  END IF;

  -- Advisory lock on room IDs in deterministic order to prevent race conditions
  FOR v_room_id IN
    SELECT unnest(v_room_ids)
    ORDER BY 1
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_room_id::text, 0)
    );
  END LOOP;

  SELECT
    count(*),
    count(DISTINCT r.lounge_id),
    (array_agg(r.lounge_id ORDER BY r.lounge_id))[1]
  INTO v_found_count, v_lounge_count, v_lounge_id
  FROM public.rooms AS r
  WHERE r.id = ANY(v_room_ids)
    AND r.is_active IS TRUE
    -- Occupancy is temporal; administrative disablement still rejects.
    AND (r.is_available IS TRUE OR r.status = 'occupied')
    AND COALESCE(r.status, '') NOT IN ('maintenance', 'deleted');

  IF v_found_count <> v_room_count THEN
    RAISE EXCEPTION 'One or more rooms are unavailable' USING ERRCODE = '23514';
  END IF;

  IF v_lounge_count <> 1 THEN
    RAISE EXCEPTION 'All held rooms must belong to the same lounge' USING ERRCODE = '22023';
  END IF;

  SELECT l.* INTO v_lounge FROM public.lounges l WHERE l.id = v_lounge_id;

  IF COALESCE(v_lounge.is_active, false) IS FALSE THEN
    RAISE EXCEPTION 'Lounge is not active' USING ERRCODE = '55000';
  END IF;

  v_tz := COALESCE(NULLIF(btrim(v_lounge.timezone), ''), 'Africa/Cairo');
  v_local_now := now() AT TIME ZONE v_tz;

  -- Determine if this is a future request
  v_is_future := (p_start_at::date > v_local_now::date)
                 OR (p_start_at > (v_local_now + interval '2 hours'));

  SELECT EXISTS (
    SELECT 1 FROM public.shifts s
    WHERE s.lounge_id = v_lounge_id
      AND s.status = 'open'
      AND s.closed_at IS NULL
  ) INTO v_has_open_shift;

  -- Shift & Future booking policy evaluations
  IF NOT v_has_open_shift THEN
    IF NOT v_is_future THEN
      RAISE EXCEPTION 'Lounge currently has no active shift open for immediate walk-ins'
        USING ERRCODE = '55000';
    END IF;

    IF COALESCE(v_lounge.allow_future_bookings, true) IS FALSE THEN
      RAISE EXCEPTION 'Future bookings are disabled for this lounge' USING ERRCODE = '55000';
    END IF;

    IF COALESCE(v_lounge.allow_request_without_shift, true) IS FALSE THEN
      RAISE EXCEPTION 'Lounge does not accept requests while shifts are closed' USING ERRCODE = '55000';
    END IF;

    v_is_request_only := true;
  END IF;

  -- Check advance days limit
  IF v_is_future AND (p_start_at::date - v_local_now::date) > COALESCE(v_lounge.future_booking_max_days_advance, 14) THEN
    RAISE EXCEPTION 'Requested date exceeds lounge advance booking limit of % days',
      v_lounge.future_booking_max_days_advance USING ERRCODE = '22023';
  END IF;

  -- Check operating hours against operational day
  IF v_lounge.opening_time IS NOT NULL AND v_lounge.closing_time IS NOT NULL THEN
    IF v_lounge.closing_time <= v_lounge.opening_time THEN
      -- Overnight hours: valid if after opening or before closing
      IF NOT (p_start_at::time >= v_lounge.opening_time OR p_start_at::time < v_lounge.closing_time) THEN
        RAISE EXCEPTION 'Selected range is outside lounge working hours' USING ERRCODE = '22023';
      END IF;
    ELSE
      IF p_start_at::time < v_lounge.opening_time OR p_end_at::time > v_lounge.closing_time THEN
        RAISE EXCEPTION 'Selected range is outside lounge working hours' USING ERRCODE = '22023';
      END IF;
    END IF;
  END IF;

  -- Release existing user holds
  UPDATE public.booking_holds
  SET released_at = now()
  WHERE user_id = v_user_id
    AND released_at IS NULL
    AND expires_at > now();

  -- Conflict check against existing confirmed bookings
  IF EXISTS (
    SELECT 1
    FROM public.bookings AS b
    WHERE b.room_id = ANY(v_room_ids)
      AND b.booking_period IS NOT NULL
      AND b.status IN ('upcoming'::public.booking_status, 'in_progress'::public.booking_status)
      AND b.confirmation_status = 'confirmed'
      AND b.booking_period && pg_catalog.tsrange(p_start_at, p_end_at, '[)')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'SLOT_OVERLAP_CONFLICT',
      'message', 'Slot is already booked'
    );
  END IF;

  -- Conflict check against other user active holds
  IF EXISTS (
    SELECT 1
    FROM public.booking_holds AS h
    WHERE h.room_id = ANY(v_room_ids)
      AND h.user_id IS DISTINCT FROM v_user_id
      AND h.released_at IS NULL
      AND h.expires_at > now()
      AND pg_catalog.tsrange(h.start_at, h.end_at, '[)') && pg_catalog.tsrange(p_start_at, p_end_at, '[)')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'SLOT_HELD_BY_ANOTHER_USER',
      'message', 'Slot is temporarily held by another customer'
    );
  END IF;

  v_expires_at := now() + make_interval(mins => LEAST(GREATEST(p_hold_minutes, 3), 30));

  INSERT INTO public.booking_holds (
    hold_token, user_id, lounge_id, room_id, start_at, end_at, expires_at
  )
  SELECT
    v_hold_token, v_user_id, v_lounge_id, room_id, p_start_at, p_end_at, v_expires_at
  FROM unnest(v_room_ids) AS room_id;

  RETURN jsonb_build_object(
    'success', true,
    'hold_token', v_hold_token,
    'lounge_id', v_lounge_id,
    'room_ids', v_room_ids,
    'start_at', p_start_at,
    'end_at', p_end_at,
    'expires_at', v_expires_at,
    'is_request_only', v_is_request_only,
    'has_open_shift', v_has_open_shift
  );
END;
$$;


ALTER FUNCTION "public"."acquire_booking_hold"("p_room_ids" "uuid"[], "p_start_at" timestamp without time zone, "p_end_at" timestamp without time zone, "p_hold_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_lounge_branch"("p_branch_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_owner_id uuid := auth.uid();
  v_brand_id uuid;
  v_parent_lounge_id uuid;
  v_lounge_id uuid;
  v_location_point geography;
  v_images text[];
BEGIN
  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required'
      USING ERRCODE = '42501';
  END IF;

  IF p_branch_data IS NULL
     OR jsonb_typeof(p_branch_data) <> 'object'
  THEN
    RAISE EXCEPTION 'p_branch_data must be a JSON object';
  END IF;

  IF NULLIF(btrim(p_branch_data->>'name'), '') IS NULL THEN
    RAISE EXCEPTION 'Branch name is required';
  END IF;

  v_brand_id := NULLIF(p_branch_data->>'brand_id', '')::uuid;

  IF v_brand_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.brands b
       WHERE b.id = v_brand_id
         AND b.owner_id = v_owner_id
     )
  THEN
    RAISE EXCEPTION 'Brand does not belong to the authenticated owner'
      USING ERRCODE = '42501';
  END IF;

  SELECT l.id
  INTO v_parent_lounge_id
  FROM public.lounges l
  WHERE l.owner_id = v_owner_id
    AND l.is_main_branch = true
    AND l.brand_id IS NOT DISTINCT FROM v_brand_id
  ORDER BY l.created_at
  LIMIT 1;

  IF jsonb_typeof(p_branch_data->'images') = 'array' THEN
    SELECT COALESCE(array_agg(value), ARRAY[]::text[])
    INTO v_images
    FROM jsonb_array_elements_text(p_branch_data->'images') AS e(value);
  END IF;

  IF NULLIF(p_branch_data->>'lat', '') IS NOT NULL
     AND NULLIF(p_branch_data->>'lng', '') IS NOT NULL
  THEN
    v_location_point := ST_SetSRID(
      ST_MakePoint(
        (p_branch_data->>'lng')::double precision,
        (p_branch_data->>'lat')::double precision
      ),
      4326
    )::geography;
  END IF;

  INSERT INTO public.lounges (
    owner_id,
    brand_id,
    branch_name,
    parent_lounge_id,
    is_main_branch,
    name,
    city,
    city_id,
    location,
    opening_time,
    closing_time,
    location_point,
    image_url,
    images
  )
  VALUES (
    v_owner_id,
    v_brand_id,
    NULLIF(p_branch_data->>'branch_name', ''),
    v_parent_lounge_id,
    false,
    p_branch_data->>'name',
    COALESCE(NULLIF(p_branch_data->>'city', ''), 'Cairo'),
    NULLIF(p_branch_data->>'city_id', '')::uuid,
    NULLIF(p_branch_data->>'location', ''),
    NULLIF(p_branch_data->>'opening_time', '')::time,
    NULLIF(p_branch_data->>'closing_time', '')::time,
    v_location_point,
    NULLIF(p_branch_data->>'image_url', ''),
    v_images
  )
  RETURNING id INTO v_lounge_id;

  RETURN v_lounge_id;
END;
$$;


ALTER FUNCTION "public"."add_lounge_branch"("p_branch_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_session_extra"("p_booking_id" "uuid", "p_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  item record;
begin
  for item in select * from jsonb_to_recordset(p_items) as x(id uuid, quantity int, price numeric)
  loop
    insert into booking_items (booking_id, item_id, quantity, price)
    values (p_booking_id, item.id, item.quantity, item.price);
  end loop;
end;
$$;


ALTER FUNCTION "public"."add_session_extra"("p_booking_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."shift_expenses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "lounge_id" "uuid" NOT NULL,
    "amount" numeric(10,2) NOT NULL,
    "reason" "text" NOT NULL,
    "expense_type" "text" DEFAULT 'expense'::"text",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "created_by" "uuid",
    "type" "text",
    CONSTRAINT "shift_expenses_expense_type_check" CHECK (("expense_type" = ANY (ARRAY['cash_drop'::"text", 'expense'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."shift_expenses" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_shift_expense"("p_shift_id" "uuid", "p_amount" numeric, "p_reason" "text", "p_type" "text" DEFAULT 'expense'::"text") RETURNS "public"."shift_expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_shift public.shifts%ROWTYPE;
  v_expense public.shift_expenses%ROWTYPE;
  v_type text := lower(btrim(coalesce(p_type,'expense')));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Expense amount must be greater than zero'
      USING ERRCODE='22023';
  END IF;

  SELECT *
  INTO v_shift
  FROM public.shifts
  WHERE id = p_shift_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Shift not found' USING ERRCODE='P0002';
  END IF;

  IF v_shift.status <> 'open' OR v_shift.closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot add expense to a closed shift'
      USING ERRCODE='55000';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR v_shift.cashier_id = auth.uid()
    OR public.is_lounge_member_or_admin(v_shift.lounge_id)
  ) THEN
    RAISE EXCEPTION 'Not authorized for this shift'
      USING ERRCODE='42501';
  END IF;

  IF v_type NOT IN ('cash_drop','expense','other') THEN
    v_type := 'expense';
  END IF;

  INSERT INTO public.shift_expenses(
    shift_id,
    lounge_id,
    amount,
    reason,
    type,
    expense_type,
    created_by
  )
  VALUES(
    v_shift.id,
    v_shift.lounge_id,
    p_amount,
    btrim(coalesce(p_reason,'')),
    v_type,
    v_type,
    auth.uid()
  )
  RETURNING * INTO v_expense;

  RETURN v_expense;
END;
$$;


ALTER FUNCTION "public"."add_shift_expense"("p_shift_id" "uuid", "p_amount" numeric, "p_reason" "text", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_faq"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  DELETE FROM public.faqs WHERE id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'FAQ not found' USING ERRCODE='P0002';
  END IF;

  RETURN jsonb_build_object('success', true, 'id', p_id);
END;
$$;


ALTER FUNCTION "public"."admin_delete_faq"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_faq"("p_id" "uuid", "p_question_ar" "text", "p_answer_ar" "text", "p_question_en" "text", "p_answer_en" "text", "p_sort_order" integer, "p_is_active" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid := coalesce(p_id, gen_random_uuid());
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF nullif(btrim(p_question_ar), '') IS NULL
     OR nullif(btrim(p_question_en), '') IS NULL
     OR nullif(btrim(p_answer_ar), '') IS NULL
     OR nullif(btrim(p_answer_en), '') IS NULL THEN
    RAISE EXCEPTION 'FAQ question and answer are required' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.faqs (
    id, question_ar, answer_ar, question_en, answer_en,
    sort_order, is_active, created_by, updated_by, updated_at
  )
  VALUES (
    v_id, btrim(p_question_ar), btrim(p_answer_ar),
    btrim(p_question_en), btrim(p_answer_en),
    coalesce(p_sort_order, 0), coalesce(p_is_active, true),
    auth.uid(), auth.uid(), now()
  )
  ON CONFLICT (id) DO UPDATE SET
    question_ar = EXCLUDED.question_ar,
    answer_ar = EXCLUDED.answer_ar,
    question_en = EXCLUDED.question_en,
    answer_en = EXCLUDED.answer_en,
    sort_order = EXCLUDED.sort_order,
    is_active = EXCLUDED.is_active,
    updated_by = auth.uid(),
    updated_at = now();

  RETURN jsonb_build_object('success', true, 'id', v_id);
END;
$$;


ALTER FUNCTION "public"."admin_save_faq"("p_id" "uuid", "p_question_ar" "text", "p_answer_ar" "text", "p_question_en" "text", "p_answer_en" "text", "p_sort_order" integer, "p_is_active" boolean) OWNER TO "postgres";


