ALTER FUNCTION "public"."admin_update_support_settings"("p_whatsapp_phone" "text", "p_support_phone" "text", "p_support_email" "text", "p_vodafone_cash_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_support_ticket"("p_ticket_id" "uuid", "p_status" "text", "p_admin_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_status text := lower(btrim(coalesce(p_status, '')));
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_status NOT IN ('new','in_progress','resolved') THEN
    RAISE EXCEPTION 'Invalid support ticket status' USING ERRCODE='22023';
  END IF;

  UPDATE public.support_tickets
  SET status = v_status,
      admin_notes = nullif(btrim(p_admin_notes), ''),
      assigned_to = CASE
        WHEN v_status = 'new' THEN assigned_to
        ELSE auth.uid()
      END,
      resolved_at = CASE
        WHEN v_status = 'resolved' THEN now()
        ELSE NULL
      END,
      updated_at = now()
  WHERE id = p_ticket_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Support ticket not found' USING ERRCODE='P0002';
  END IF;

  RETURN jsonb_build_object('success', true, 'ticket_id', p_ticket_id, 'status', v_status);
END;
$$;


ALTER FUNCTION "public"."admin_update_support_ticket"("p_ticket_id" "uuid", "p_status" "text", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_legal_policy"("p_policy_key" "text", "p_title_ar" "text", "p_title_en" "text", "p_content_ar" "text", "p_content_en" "text", "p_is_published" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_key text := btrim(coalesce(p_policy_key, ''));
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_key = '' THEN
    RAISE EXCEPTION 'policy_key is required' USING ERRCODE='22023';
