ALTER FUNCTION "public"."admin_upsert_legal_policy"("p_policy_key" "text", "p_title_ar" "text", "p_title_en" "text", "p_content_ar" "text", "p_content_en" "text", "p_is_published" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_loyalty_mission"("p_user_id" "uuid", "p_mission_code" "text", "p_increment" integer DEFAULT 1) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_mission public.loyalty_missions;
  v_progress integer;
  v_completed_at timestamptz;
BEGIN
  IF p_increment IS NULL OR p_increment <= 0 THEN
    RETURN;
  END IF;

  SELECT * INTO v_mission
  FROM public.loyalty_missions
  WHERE code = p_mission_code AND is_active = true;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  INSERT INTO public.user_mission_progress (user_id, mission_id, progress)
  VALUES (p_user_id, v_mission.id, LEAST(p_increment, v_mission.target_count))
  ON CONFLICT (user_id, mission_id) DO UPDATE SET
    progress = LEAST(public.user_mission_progress.progress + EXCLUDED.progress, v_mission.target_count),
    updated_at = now();

  SELECT progress, completed_at INTO v_progress, v_completed_at
  FROM public.user_mission_progress
  WHERE user_id = p_user_id AND mission_id = v_mission.id
  FOR UPDATE;

  IF v_progress >= v_mission.target_count AND v_completed_at IS NULL THEN
    UPDATE public.user_mission_progress
    SET completed_at = now(), updated_at = now()
    WHERE user_id = p_user_id AND mission_id = v_mission.id;

    PERFORM public.award_points(
      p_user_id,
      v_mission.reward_points,
      'earn_mission',
      v_mission.id,
      'مكافأة مهمة: ' || v_mission.title_ar,
      'mission',
      v_mission.id,
      'mission:' || p_user_id::text || ':' || v_mission.id::text,
      jsonb_build_object('mission_code', v_mission.code)
    );

    INSERT INTO public.notifications (
      user_id, title_ar, title_en, body_ar, body_en, type, is_read, metadata
    ) VALUES (
      p_user_id,
      'مبروك! أكملت مهمة بنجاح 🎉', 'Mission Completed! 🎉',
      'تهانينا! لقد أكملت مهمة "' || COALESCE(v_mission.title_ar, v_mission.title_en, '') || '" وحصلت على ' || v_mission.reward_points || ' نقطة ولاء جديدة.',
      'Congratulations! You completed "' || COALESCE(v_mission.title_en, v_mission.title_ar, '') || '" and earned ' || v_mission.reward_points || ' loyalty points.',
      'loyalty_points', false,
      jsonb_build_object('mission_id', v_mission.id, 'mission_code', v_mission.code, 'reward_points', v_mission.reward_points)
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."advance_loyalty_mission"("p_user_id" "uuid", "p_mission_code" "text", "p_increment" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anonymize_account_for_deletion"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'USER_REQUIRED' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;
  INSERT INTO public.account_deletion_requests(user_id) VALUES(p_user_id)
  ON CONFLICT (user_id) DO NOTHING;
  DELETE FROM public.points_transactions WHERE user_id = p_user_id;
  DELETE FROM public.user_vouchers WHERE user_id = p_user_id;
  DELETE FROM public.notifications WHERE user_id = p_user_id;
  DELETE FROM public.notification_settings WHERE user_id = p_user_id;
  DELETE FROM public.favorites WHERE user_id = p_user_id;
  UPDATE public.profiles
  SET full_name = 'Deleted User', phone = NULL, email = NULL,
      avatar_url = NULL, fcm_token = NULL, is_active = false,
      is_banned = true, updated_at = now()
  WHERE id = p_user_id;
  -- Bookings, payments and ownership are preserved under the existing deletion policy.
  RETURN jsonb_build_object('success', true, 'deactivated', true);
END;
$$;


ALTER FUNCTION "public"."anonymize_account_for_deletion"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_booking_discount"("p_booking_id" "uuid", "p_discount_amount" numeric DEFAULT 0, "p_discount_percentage" numeric DEFAULT 0, "p_discount_reason" "text" DEFAULT NULL::"text", "p_voucher_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_amount numeric := GREATEST(COALESCE(p_discount_amount, 0), 0);
  v_percentage numeric := GREATEST(COALESCE(p_discount_percentage, 0), 0);
  v_reason text := NULLIF(btrim(p_discount_reason), '');
  v_clean_voucher text := NULLIF(upper(btrim(p_voucher_code)), '');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM private.assert_lounge_operator(v_booking.lounge_id, false);

  IF v_amount > 0 AND v_percentage > 0 THEN
    RAISE EXCEPTION 'Use either a fixed discount or a percentage discount, not both'
      USING ERRCODE = '22023';
  END IF;

  IF v_percentage > 100 THEN
    RAISE EXCEPTION 'Discount percentage must be between 0 and 100'
      USING ERRCODE = '22023';
  END IF;

  IF (v_amount > 0 OR v_percentage > 0) AND v_reason IS NULL AND v_clean_voucher IS NULL THEN
    RAISE EXCEPTION 'Discount reason or voucher code is required'
      USING ERRCODE = '22023';
  END IF;

  IF v_clean_voucher IS NOT NULL AND v_reason IS NULL THEN
    v_reason := 'Voucher: ' || v_clean_voucher;
  END IF;

  UPDATE public.bookings
  SET
    discount_amount = v_amount,
    discount_percentage = v_percentage,
    discount_reason = v_reason,
    applied_voucher_code = COALESCE(v_clean_voucher, applied_voucher_code),
    discount_approved_by = auth.uid(),
    updated_at = now()
  WHERE id = p_booking_id
  RETURNING *
  INTO v_booking;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', v_booking.id,
    'discount_amount', v_booking.discount_amount,
    'discount_percentage', v_booking.discount_percentage,
    'discount_reason', v_booking.discount_reason,
    'applied_voucher_code', v_booking.applied_voucher_code,
    'total_price', v_booking.total_price
  );
END;
$$;


ALTER FUNCTION "public"."apply_booking_discount"("p_booking_id" "uuid", "p_discount_amount" numeric, "p_discount_percentage" numeric, "p_discount_reason" "text", "p_voucher_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_offline_cashier_operation"("p_operation" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_writer private.cashier_writer_authorities%ROWTYPE;
  v_receipt private.cashier_operation_receipts%ROWTYPE;
  v_review uuid;v_retry boolean:=false;v_result jsonb;v_code text;v_sequence bigint;v_id uuid;v_lounge uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  PERFORM private.validate_cashier_operation(p_operation);
  v_writer:=private.lock_cashier_operation_writer(p_operation);
  v_sequence:=(p_operation->>'sequence')::bigint;v_id:=(p_operation->>'id')::uuid;v_lounge:=v_writer.lounge_id;
  SELECT * INTO v_receipt FROM private.cashier_operation_receipts WHERE operation_id=v_id;
  IF FOUND THEN
    IF v_receipt.request IS DISTINCT FROM p_operation THEN
      RAISE EXCEPTION 'OFFLINE_OPERATION_REPLAY_CONFLICT' USING ERRCODE='22023';
    END IF;
    IF v_receipt.result->>'status'='applied' THEN
      RETURN v_receipt.result||jsonb_build_object('status','replayed');
    END IF;
    SELECT o.result INTO v_result FROM private.cashier_conflict_outcomes o
      JOIN private.cashier_conflict_reviews r ON r.id=o.review_id
      WHERE r.operation_id=v_id AND o.result->>'status'='applied';
    IF FOUND THEN RETURN v_result||jsonb_build_object('status','replayed'); END IF;
    SELECT r.id INTO v_review FROM private.cashier_conflict_reviews r
      WHERE r.operation_id=v_id AND NOT EXISTS
        (SELECT 1 FROM private.cashier_conflict_outcomes o WHERE o.review_id=r.id)
      ORDER BY r.created_at DESC LIMIT 1;
    IF NOT FOUND THEN RETURN v_receipt.result; END IF;
    v_retry:=true;
  END IF;
  IF v_sequence<>v_writer.last_applied_sequence+1 THEN
    RETURN jsonb_build_object('operation_id',v_id,'lounge_id',v_lounge,'sequence',v_sequence,
      'status','conflict','code','OFFLINE_SEQUENCE_GAP');
  END IF;
  IF NOT v_retry AND EXISTS (SELECT 1 FROM private.cashier_operation_receipts
    WHERE lounge_id=v_lounge AND sequence=v_sequence) THEN
    RETURN jsonb_build_object('operation_id',v_id,'lounge_id',v_lounge,'sequence',v_sequence,
      'status','conflict','code','OFFLINE_SEQUENCE_BLOCKED');
  END IF;
  BEGIN
    IF p_operation->>'kind'='collectCash' THEN
      v_result:=jsonb_build_object('financial_receipt',private.apply_cashier_cash_operation(p_operation));
    ELSIF p_operation->>'kind'='addItems' THEN
      v_result:=jsonb_build_object('order_receipt',private.apply_cashier_order_operation(p_operation));
    ELSE
      v_result:=jsonb_build_object('session_receipt',private.apply_cashier_fixed_operation(p_operation));
    END IF;
    v_result:=v_result||jsonb_build_object('operation_id',v_id,'lounge_id',v_lounge,'sequence',v_sequence,'status','applied');
  EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '55000' OR SQLSTATE '42501' OR SQLSTATE 'P0002' THEN
    GET STACKED DIAGNOSTICS v_code=MESSAGE_TEXT;
    v_result:=jsonb_build_object('operation_id',v_id,'lounge_id',v_lounge,'sequence',v_sequence,
      'status','conflict','code',v_code);
  WHEN exclusion_violation THEN
    v_result:=jsonb_build_object('operation_id',v_id,'lounge_id',v_lounge,'sequence',v_sequence,
      'status','conflict','code','OFFLINE_ROOM_CONFLICT');
  WHEN unique_violation THEN
    v_result:=jsonb_build_object('operation_id',v_id,'lounge_id',v_lounge,'sequence',v_sequence,
      'status','conflict','code','OFFLINE_RECORD_ID_CONFLICT');
  END;
  IF v_retry THEN
    INSERT INTO private.cashier_conflict_outcomes(review_id,result) VALUES(v_review,v_result);
  ELSE
    INSERT INTO private.cashier_operation_receipts(operation_id,permit_id,sequence,actor_id,lounge_id,request,result)
      VALUES(v_id,(p_operation->>'permit_id')::uuid,v_sequence,auth.uid(),v_lounge,p_operation,v_result);
  END IF;
  IF v_result->>'status'='applied' THEN
    UPDATE private.cashier_writer_authorities SET last_applied_sequence=v_sequence WHERE lounge_id=v_lounge;
  END IF;
  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."apply_offline_cashier_operation"("p_operation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_tournament_walkovers"("p_tournament_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE m public.tournament_matches; changed integer:=0; total integer:=0; v_winner uuid;
BEGIN
  LOOP
    changed:=0;
    FOR m IN
      SELECT * FROM public.tournament_matches
      WHERE tournament_id=p_tournament_id AND status='scheduled'
        AND ((player1_id IS NULL AND player2_id IS NOT NULL) OR (player1_id IS NOT NULL AND player2_id IS NULL))
      ORDER BY round_number, match_order
      FOR UPDATE SKIP LOCKED
    LOOP
      v_winner:=COALESCE(m.player1_id,m.player2_id);
      UPDATE public.tournament_matches
      SET winner_id=v_winner,status='walkover',completed_at=COALESCE(completed_at,now()),updated_at=now()
      WHERE id=m.id;
      IF m.next_match_id IS NOT NULL THEN
        IF m.next_match_slot=1 THEN
          UPDATE public.tournament_matches SET player1_id=v_winner WHERE id=m.next_match_id AND player1_id IS NULL;
        ELSE
          UPDATE public.tournament_matches SET player2_id=v_winner WHERE id=m.next_match_id AND player2_id IS NULL;
        END IF;
      END IF;
      PERFORM public.tournament_audit(p_tournament_id,'match_walkover',v_winner,m.id,NULL,jsonb_build_object('winner_id',v_winner));
      changed:=changed+1; total:=total+1;
    END LOOP;
    EXIT WHEN changed=0;
  END LOOP;
  RETURN total;
END;
$$;


ALTER FUNCTION "public"."apply_tournament_walkovers"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_booking_extension"("p_booking_id" "uuid", "p_additional_cost" numeric DEFAULT NULL::numeric, "p_payment_method" "text" DEFAULT 'cash'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_new_duration integer;
  v_new_end timestamp without time zone;
  v_new_end_time time without time zone;
  v_hourly_rate numeric;
  v_cost numeric;
  v_shift_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE = '28000';
  END IF;

  SELECT b.* INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BOOKING_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  PERFORM private.assert_lounge_operator(v_booking.lounge_id, true);

  IF v_booking.status NOT IN ('upcoming'::public.booking_status, 'in_progress'::public.booking_status)
     OR COALESCE(v_booking.extension_status, 'none') <> 'pending'
     OR COALESCE(v_booking.requested_extension_minutes, 0) <= 0 THEN
    RAISE EXCEPTION 'NO_ELIGIBLE_PENDING_EXTENSION' USING ERRCODE = '55000';
  END IF;

  SELECT CASE
           WHEN lower(COALESCE(v_booking.play_mode, '')) = 'single' THEN r.hourly_rate_single
           ELSE r.hourly_rate_multi
         END
  INTO v_hourly_rate
  FROM public.rooms AS r
  WHERE r.id = v_booking.room_id
    AND r.lounge_id = v_booking.lounge_id;

  IF v_hourly_rate IS NULL OR v_hourly_rate < 0 THEN
    RAISE EXCEPTION 'ROOM_RATE_NOT_CONFIGURED' USING ERRCODE = '22023';
  END IF;

  v_new_duration := COALESCE(v_booking.duration_minutes, 0) + v_booking.requested_extension_minutes;
  IF v_new_duration <= 0 OR v_new_duration > 1440 THEN
    RAISE EXCEPTION 'INVALID_TOTAL_SESSION_DURATION' USING ERRCODE = '22023';
  END IF;

  v_new_end := v_booking.date + v_booking.start_time + make_interval(mins => v_new_duration);
  v_new_end_time := v_new_end::time;
  v_cost := (private.booking_extension_quote(v_booking,v_booking.requested_extension_minutes)->>'extension_cost')::numeric;

  IF EXISTS (
    SELECT 1
    FROM public.bookings AS next_booking
    WHERE next_booking.id <> v_booking.id
      AND next_booking.room_id = v_booking.room_id
      AND next_booking.status IN ('pending'::public.booking_status, 'upcoming'::public.booking_status, 'in_progress'::public.booking_status)
      AND next_booking.booking_period IS NOT NULL
      AND next_booking.booking_period && tsrange(
        (v_booking.date + v_booking.start_time)::timestamp,
        v_new_end,
        '[)'
      )
      AND (next_booking.status <> 'pending'::public.booking_status
           OR next_booking.expires_at IS NULL
           OR next_booking.expires_at > now())
  ) THEN
    RAISE EXCEPTION 'BOOKING_EXTENSION_CONFLICT' USING ERRCODE = '23P01';
  END IF;

  SELECT s.id INTO v_shift_id
  FROM public.shifts AS s
  WHERE s.lounge_id = v_booking.lounge_id AND s.status = 'open'
  ORDER BY s.opened_at DESC
  LIMIT 1;

  IF v_booking.payment_status = 'paid' AND v_cost > 0 AND v_shift_id IS NOT NULL THEN
    INSERT INTO public.shift_payments (
      shift_id, lounge_id, booking_id, payment_method, category, amount, paid_at
    ) VALUES (
      v_shift_id, v_booking.lounge_id, p_booking_id, 
      COALESCE(p_payment_method, v_booking.payment_method, 'cash'), 
      'gaming_time', v_cost, now()
    );

    INSERT INTO public.payments (
      booking_id,
      user_id,
      lounge_id,
      amount,
      commission,
      net_to_lounge,
      payment_method,
      status,
      paid_at,
      discount_amount,
      discount_percentage,
      discount_reason,
      discount_approved_by
    )
    VALUES (
      p_booking_id,
      v_booking.user_id,
      v_booking.lounge_id,
      (COALESCE(v_booking.total_price,0)+v_cost),
      round((COALESCE(v_booking.total_price,0)+v_cost) * 0.15, 2),
      (COALESCE(v_booking.total_price,0)+v_cost) - round((COALESCE(v_booking.total_price,0)+v_cost) * 0.15, 2),
      COALESCE(p_payment_method,v_booking.payment_method,'cash'),
      'completed',
      now(),
      COALESCE(v_booking.discount_amount, 0),
      COALESCE(v_booking.discount_percentage, 0),
      v_booking.discount_reason,
      v_booking.discount_approved_by
    )
    ON CONFLICT (booking_id)
    DO UPDATE SET
      amount = EXCLUDED.amount,
      commission = EXCLUDED.commission,
      net_to_lounge = EXCLUDED.net_to_lounge,
      payment_method = EXCLUDED.payment_method,
      status = 'completed',
      paid_at = COALESCE(public.payments.paid_at, EXCLUDED.paid_at),
      discount_amount = EXCLUDED.discount_amount,
      discount_percentage = EXCLUDED.discount_percentage,
      discount_reason = EXCLUDED.discount_reason,
      discount_approved_by = EXCLUDED.discount_approved_by;
  END IF;


  UPDATE public.bookings AS b
  SET duration_minutes = v_new_duration,
      end_time = v_new_end_time,
      end_at = v_new_end_time,
      total_price = COALESCE(b.total_price, 0) + v_cost,
      extension_status = 'approved',
      requested_extension_minutes = NULL,
      updated_at = now()
  WHERE b.id = p_booking_id;

  IF (SELECT b.total_price FROM public.bookings b WHERE b.id=p_booking_id) IS DISTINCT FROM COALESCE(v_booking.total_price,0)+v_cost THEN
    RAISE EXCEPTION 'EXTENSION_PRICE_MISMATCH' USING ERRCODE='22023';
  END IF;
  IF v_booking.payment_status='paid' AND v_cost>0 AND v_shift_id IS NULL THEN
    RAISE EXCEPTION 'OPEN_SHIFT_REQUIRED_FOR_PAID_EXTENSION' USING ERRCODE='55000';
  END IF;

  INSERT INTO public.notifications(
    user_id, lounge_id, title_ar, title_en, body_ar, body_en, type, is_read, metadata
  ) VALUES (
    v_booking.user_id, v_booking.lounge_id,
    'تمت الموافقة على تمديد الحجز ✅', 'Booking Extension Approved ✅',
    'تمت الموافقة على طلب تمديد وقت الحجز بمقدار ' || v_booking.requested_extension_minutes || ' دقيقة.', 
    'Your booking extension request was approved for ' || v_booking.requested_extension_minutes || ' minutes.',
    'booking_extension_approved', false,
    jsonb_build_object(
      'booking_id', p_booking_id,
      'extension_minutes', v_booking.requested_extension_minutes,
      'extension_cost', v_cost
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'status', 'approved',
    'booking_id', p_booking_id,
    'new_duration', v_new_duration,
    'new_end_time', v_new_end_time,
    'extension_cost', v_cost,
    'new_total', COALESCE(v_booking.total_price, 0) + v_cost,
    'shift_payment_recorded', (v_booking.payment_status = 'paid' AND v_cost > 0)
  );
END;
$$;


ALTER FUNCTION "public"."approve_booking_extension"("p_booking_id" "uuid", "p_additional_cost" numeric, "p_payment_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_cashier_conflict_retry"("p_lounge_id" "uuid", "p_operation_id" "uuid", "p_review_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE r private.cashier_operation_receipts%ROWTYPE;a private.cashier_conflict_reviews%ROWTYPE;
BEGIN
 PERFORM private.lock_cashier_lounge(p_lounge_id);
 PERFORM private.assert_cashier_conflict_reviewer(p_lounge_id);
 IF p_review_id IS NULL OR p_operation_id IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 1000 THEN
  RAISE EXCEPTION 'INVALID_CONFLICT_REVIEW' USING ERRCODE='22023'; END IF;
 SELECT * INTO a FROM private.cashier_conflict_reviews WHERE id=p_review_id;
 IF FOUND THEN
  IF (a.lounge_id,a.operation_id,a.reviewer_id,a.reason) IS DISTINCT FROM
   (p_lounge_id,p_operation_id,auth.uid(),btrim(p_reason)) THEN
   RAISE EXCEPTION 'CONFLICT_REVIEW_REPLAY_MISMATCH' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('review_id',a.id,'operation_id',a.operation_id,'lounge_id',a.lounge_id,'status','approved');
 END IF;
 SELECT * INTO r FROM private.cashier_operation_receipts WHERE operation_id=p_operation_id AND lounge_id=p_lounge_id;
 IF NOT FOUND OR r.result->>'status'<>'conflict' THEN RAISE EXCEPTION 'CONFLICT_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.cashier_writer_authorities w WHERE w.lounge_id=p_lounge_id
  AND w.last_applied_sequence+1=r.sequence AND w.released_at IS NULL) THEN
  RAISE EXCEPTION 'CONFLICT_SEQUENCE_NOT_CURRENT' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM private.cashier_conflict_reviews x WHERE x.operation_id=p_operation_id
  AND NOT EXISTS(SELECT 1 FROM private.cashier_conflict_outcomes o WHERE o.review_id=x.id)) THEN
  RAISE EXCEPTION 'CONFLICT_RETRY_ALREADY_APPROVED' USING ERRCODE='55000'; END IF;
 INSERT INTO private.cashier_conflict_reviews(id,operation_id,lounge_id,reviewer_id,reason)
  VALUES(p_review_id,p_operation_id,p_lounge_id,auth.uid(),btrim(p_reason));
 RETURN jsonb_build_object('review_id',p_review_id,'operation_id',p_operation_id,'lounge_id',p_lounge_id,'status','approved');
END; $$;


ALTER FUNCTION "public"."approve_cashier_conflict_retry"("p_lounge_id" "uuid", "p_operation_id" "uuid", "p_review_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_ban_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lounge_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "booking_id" "uuid",
    "reason" "text" NOT NULL,
    "evidence_notes" "text",
    "status" "public"."user_ban_request_status" DEFAULT 'pending'::"public"."user_ban_request_status" NOT NULL,
    "admin_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_ban_requests_reason_check" CHECK (("length"("btrim"("reason")) > 0))
);


ALTER TABLE "public"."user_ban_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_global_ban_request"("p_request_id" "uuid", "p_admin_notes" "text" DEFAULT NULL::"text") RETURNS "public"."user_ban_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request public.user_ban_requests;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only super admins can approve ban requests';
  END IF;

  SELECT * INTO v_request
  FROM public.user_ban_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ban request not found';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Ban request is not pending';
  END IF;

  UPDATE public.profiles
  SET is_banned = true,
      banned_reason = v_request.reason,
      updated_at = now()
  WHERE id = v_request.user_id;

  UPDATE public.user_ban_requests
  SET status = 'approved_global', admin_notes = p_admin_notes
  WHERE id = p_request_id
  RETURNING * INTO v_request;

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."approve_global_ban_request"("p_request_id" "uuid", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_lounge_ban_request"("p_request_id" "uuid", "p_admin_notes" "text" DEFAULT NULL::"text") RETURNS "public"."user_ban_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request public.user_ban_requests;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only super admins can approve ban requests';
  END IF;

  SELECT * INTO v_request
  FROM public.user_ban_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ban request not found';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Ban request is not pending';
  END IF;

  INSERT INTO public.lounge_banned_users (lounge_id, user_id)
  VALUES (v_request.lounge_id, v_request.user_id)
  ON CONFLICT (lounge_id, user_id) DO NOTHING;

  UPDATE public.user_ban_requests
  SET status = 'approved_lounge_only', admin_notes = p_admin_notes
  WHERE id = p_request_id
  RETURNING * INTO v_request;

  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."approve_lounge_ban_request"("p_request_id" "uuid", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_manual_booking"("p_booking_id" "uuid", "p_action_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_actor uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_action_by IS NOT NULL AND p_action_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Action actor does not match authenticated user'
      USING ERRCODE = '42501';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM private.assert_lounge_operator(v_booking.lounge_id, true);

  IF COALESCE(v_booking.payment_method, '') <> 'manual_transfer' THEN
    RAISE EXCEPTION 'Only manual transfer bookings require manual approval'
      USING ERRCODE = '55000';
  END IF;

  IF NULLIF(btrim(COALESCE(v_booking.receipt_url, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Payment receipt is required before approval'
      USING ERRCODE = '22023';
  END IF;

  IF v_booking.status NOT IN (
    'pending'::public.booking_status,
    'upcoming'::public.booking_status
  ) THEN
    RAISE EXCEPTION 'Booking cannot be approved in its current status'
      USING ERRCODE = '55000';
  END IF;

  v_result := public.complete_booking_payment(
    p_booking_id,
    'manual_transfer',
    NULL
  );

  RETURN v_result || jsonb_build_object('approved_by', v_actor);
END;
$$;


ALTER FUNCTION "public"."approve_manual_booking"("p_booking_id" "uuid", "p_action_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_payout"("p_payout_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_owner_id UUID;
  v_amount NUMERIC;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE public.payouts
  SET status = 'approved', approved_by = auth.uid(), approved_at = NOW(), notes = COALESCE(p_notes, notes)
  WHERE id = p_payout_id AND status = 'pending'
  RETURNING created_by, total_amount INTO v_owner_id, v_amount;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payout not found or not pending';
  END IF;

  -- In-App Notification (Type strictly matching CHECK constraint 'payout')
  IF v_owner_id IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, title, title_ar, title_en, body, body_ar, body_en, type, metadata)
    VALUES (
      v_owner_id,
      'Payout Request Approved',
      'تم اعتماد طلب سحب الأرباح',
      'Payout Request Approved',
      'تمت الموافقة على طلب سحب الأرباح بقيمة ' || v_amount || ' ج.م',
      'تمت الموافقة على طلب سحب الأرباح بقيمة ' || v_amount || ' ج.م',
      'Your payout request for EGP ' || v_amount || ' has been approved.',
      'payout',
      jsonb_build_object('payout_id', p_payout_id, 'status', 'approved', 'amount', v_amount)
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'payout_id', p_payout_id, 'status', 'approved');
END;
$$;


ALTER FUNCTION "public"."approve_payout"("p_payout_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_shift"("p_shift_id" "uuid", "p_manager_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE v_lounge_id uuid; v_status text;
BEGIN
  IF (select auth.uid()) IS NULL OR (select private.current_user_role()) = 'super_admin' THEN
    RAISE EXCEPTION 'Super admins are restricted from shift operational RPCs.';
  END IF;
  IF p_manager_id IS DISTINCT FROM (select auth.uid()) THEN RAISE EXCEPTION 'The approving manager must be the authenticated user.'; END IF;
  SELECT lounge_id, status INTO v_lounge_id, v_status FROM public.shifts WHERE id=p_shift_id;
  IF v_lounge_id IS NULL THEN RAISE EXCEPTION 'Shift not found.'; END IF;
  IF NOT (select private.is_lounge_manager(v_lounge_id)) THEN RAISE EXCEPTION 'Only a manager of this lounge can approve the shift.'; END IF;
  IF v_status <> 'closed' THEN RAISE EXCEPTION 'Only closed shifts can be approved.'; END IF;
  UPDATE public.shifts SET is_approved=true, approved_by=(select auth.uid()), approved_at=now(), manager_notes=p_notes WHERE id=p_shift_id;
  RETURN json_build_object('success',true,'shift_id',p_shift_id,'approved_by',(select auth.uid()));
END;
$$;


ALTER FUNCTION "public"."approve_shift"("p_shift_id" "uuid", "p_manager_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_tournament_payment"("p_submission_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."tournament_participants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$ DECLARE v_s public.tournament_payment_submissions%ROWTYPE; v_p public.tournament_participants%ROWTYPE; v_t public.tournaments%ROWTYPE; v_count integer; BEGIN SELECT * INTO v_s FROM public.tournament_payment_submissions WHERE id=p_submission_id FOR UPDATE; SELECT * INTO v_p FROM public.tournament_participants WHERE id=v_s.participant_id FOR UPDATE; SELECT * INTO v_t FROM public.tournaments WHERE id=v_p.tournament_id FOR UPDATE; IF NOT(is_super_admin() OR private.is_lounge_manager(v_t.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF; IF v_s.status<>'pending' OR v_p.payment_status='paid' THEN RAISE EXCEPTION 'payment_already_reviewed'; END IF; IF v_t.status IN('in_progress','completed','cancelled') THEN RAISE EXCEPTION 'tournament_not_open_for_payment'; END IF; IF v_s.amount<>v_t.entry_fee AND(p_reason IS NULL OR btrim(p_reason)='') THEN RAISE EXCEPTION 'amount_mismatch_reason_required'; END IF; SELECT count(*) INTO v_count FROM public.tournament_participants WHERE tournament_id=v_t.id AND registration_status IN('confirmed','checked_in'); IF v_count>=v_t.max_participants THEN RAISE EXCEPTION 'capacity_reached'; END IF; UPDATE public.tournament_payment_submissions SET status='approved',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=v_s.id; UPDATE public.tournament_participants SET payment_status='paid',registration_status='confirmed',payment_method=v_s.payment_method,receipt_url=v_s.receipt_url,approved_by=auth.uid(),approved_at=now(),payment_rejection_reason=NULL,updated_at=now() WHERE id=v_p.id RETURNING * INTO v_p; PERFORM public.tournament_audit(v_t.id,'payment_approved',v_p.id,NULL,NULL,jsonb_build_object('submission_id',v_s.id,'participant',to_jsonb(v_p)),p_reason); RETURN v_p; END $$;


ALTER FUNCTION "public"."approve_tournament_payment"("p_submission_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_canteen_catalogue_item"("p_kind" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_lounge uuid;v_deleted timestamptz;
BEGIN
  PERFORM private.require_active_booking_actor();
  IF p_id IS NULL OR p_kind IS NULL OR p_kind NOT IN ('combo','upsell_rule') THEN
    RAISE EXCEPTION 'INVALID_CATALOGUE_ARCHIVE_REQUEST' USING ERRCODE='22023';
  END IF;
  IF p_kind='combo' THEN
    SELECT lounge_id,deleted_at INTO v_lounge,v_deleted FROM public.canteen_combos WHERE id=p_id FOR UPDATE;
  ELSE
    SELECT lounge_id,deleted_at INTO v_lounge,v_deleted FROM public.upsell_rules WHERE id=p_id FOR UPDATE;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'CATALOGUE_ITEM_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF public.is_super_admin() IS NOT TRUE AND public.has_lounge_permission(v_lounge,'menu_manage_items') IS NOT TRUE THEN
    RAISE EXCEPTION 'CATALOGUE_ARCHIVE_DENIED' USING ERRCODE='42501';
  END IF;
  IF v_deleted IS NULL THEN
    IF p_kind='combo' THEN
      UPDATE public.canteen_combos SET deleted_at=clock_timestamp(),is_active=false WHERE id=p_id;
      -- Keep the suggestion row for reports/editing, but stop promoting an
      -- archived combo. Its activation remains separate from deletion.
      UPDATE public.upsell_rules SET is_active=false WHERE suggest_combo_id=p_id AND deleted_at IS NULL;
    ELSE
      UPDATE public.upsell_rules SET deleted_at=clock_timestamp(),is_active=false WHERE id=p_id;
    END IF;
  END IF;
  RETURN jsonb_build_object('success',true,'id',p_id,'kind',p_kind);
END; $$;


ALTER FUNCTION "public"."archive_canteen_catalogue_item"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_lounge_extra"("p_extra_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_extra public.extras%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  SELECT e.* INTO v_extra
  FROM public.extras e
  WHERE e.id=p_extra_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EXTRA_NOT_FOUND' USING ERRCODE='P0002';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR public.has_lounge_permission(v_extra.lounge_id, 'menu_manage_items')
  ) THEN
    RAISE EXCEPTION 'MENU_MANAGE_ITEMS_PERMISSION_REQUIRED' USING ERRCODE='42501';
  END IF;

  UPDATE public.extras
  SET is_active=false,
      is_available=false
  WHERE id=p_extra_id;

  RETURN jsonb_build_object(
    'success',true,
    'extra_id',p_extra_id,
    'archived',true
  );
END;
$$;


ALTER FUNCTION "public"."archive_lounge_extra"("p_extra_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_lounge_room"("p_room_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000';
  END IF;

  SELECT * INTO v_room
  FROM public.rooms
  WHERE id=p_room_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ROOM_NOT_FOUND' USING ERRCODE='P0002';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_room.lounge_id,'rooms_manage') THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE='42501';
  END IF;

  IF EXISTS(
    SELECT 1 FROM public.bookings b
    WHERE b.room_id=p_room_id AND b.status='in_progress'
  ) THEN
    RAISE EXCEPTION 'ROOM_HAS_ACTIVE_SESSION' USING ERRCODE='55000';
  END IF;

  UPDATE public.rooms
  SET status='deleted',is_available=false,is_active=false,updated_at=now()
  WHERE id=p_room_id;

  RETURN jsonb_build_object(
    'success',true,'room_id',p_room_id,'status','deleted'
  );
END;
$$;


ALTER FUNCTION "public"."archive_lounge_room"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_redemption_option_admin"("p_option_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_updated uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'SUPER_ADMIN_REQUIRED' USING ERRCODE='42501';
  END IF;

  UPDATE public.redemption_options
  SET is_active = false
  WHERE id = p_option_id
  RETURNING id INTO v_updated;

  IF v_updated IS NULL THEN
    RAISE EXCEPTION 'REDEMPTION_OPTION_NOT_FOUND' USING ERRCODE='P0002';
  END IF;

  RETURN jsonb_build_object(
    'success',true,
    'option_id',v_updated,
    'archived',true
  );
END;
$$;


ALTER FUNCTION "public"."archive_redemption_option_admin"("p_option_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_booking_to_active_shift"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_shift_id uuid;
  v_shift_lounge_id uuid;
  v_shift_status text;
  v_requires_open_shift boolean :=
    NEW.status::text = 'in_progress' 
    OR NEW.actual_start_time IS NOT NULL 
    OR NEW.checked_in_at IS NOT NULL;
BEGIN
  -- If active booking needs a shift and none is assigned, find the active shift for this lounge
  IF v_requires_open_shift
     AND NEW.shift_id IS NULL
     AND NEW.lounge_id IS NOT NULL THEN
    SELECT s.id
    INTO v_shift_id
    FROM public.shifts AS s
    WHERE s.lounge_id = NEW.lounge_id
      AND s.status = 'open'
      AND s.closed_at IS NULL
    ORDER BY s.opened_at DESC
    LIMIT 1
    FOR SHARE;

    IF v_shift_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'NO_OPEN_SHIFT';
    END IF;

    NEW.shift_id := v_shift_id;
  END IF;

  -- If shift_id is provided, validate it belongs to the same lounge and is valid
  IF NEW.shift_id IS NOT NULL THEN
    SELECT s.lounge_id, s.status
    INTO v_shift_lounge_id, v_shift_status
    FROM public.shifts AS s
    WHERE s.id = NEW.shift_id
    FOR SHARE;

    IF v_shift_lounge_id IS NULL THEN
      RAISE EXCEPTION 'The selected shift does not exist.' USING ERRCODE = '22023';
    END IF;

    IF NEW.lounge_id IS DISTINCT FROM v_shift_lounge_id THEN
      RAISE EXCEPTION 'Booking and shift must belong to the same lounge.' USING ERRCODE = '22023';
    END IF;

    IF v_requires_open_shift AND v_shift_status <> 'open' THEN
      RAISE EXCEPTION 'An active booking must be linked to an open shift.' USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."attach_booking_to_active_shift"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_my_booking_receipt"("p_booking_id" "uuid", "p_receipt_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_receipt_url text := NULLIF(btrim(p_receipt_url), '');
  v_expected_prefix text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF v_receipt_url IS NULL THEN
    RAISE EXCEPTION 'Receipt reference is required' USING ERRCODE = '22023';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_booking.status NOT IN (
    'pending'::public.booking_status,
    'upcoming'::public.booking_status
  ) THEN
    RAISE EXCEPTION 'Receipt cannot be changed in the current booking status'
      USING ERRCODE = '55000';
  END IF;

  v_expected_prefix := auth.uid()::text || '/' || p_booking_id::text || '/';

  IF v_receipt_url NOT LIKE v_expected_prefix || '%' THEN
    RAISE EXCEPTION 'Receipt reference does not belong to this booking'
      USING ERRCODE = '42501';
  END IF;

  IF v_receipt_url LIKE 'http://%' OR v_receipt_url LIKE 'https://%' THEN
    RAISE EXCEPTION 'Receipt reference must be a private storage object path'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.bookings
  SET receipt_url = v_receipt_url,
      updated_at = now()
  WHERE id = p_booking_id;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'receipt_url', v_receipt_url
  );
END;
$$;


ALTER FUNCTION "public"."attach_my_booking_receipt"("p_booking_id" "uuid", "p_receipt_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_payout_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_action text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'created';
    INSERT INTO public.payout_audit_logs(payout_id, action, actor_user_id, new_data)
    VALUES (NEW.id, v_action, auth.uid(), to_jsonb(NEW));
    RETURN NEW;
  END IF;

  IF OLD.status = 'paid' AND (
    NEW.lounge_id IS DISTINCT FROM OLD.lounge_id OR
    NEW.period_start IS DISTINCT FROM OLD.period_start OR
    NEW.period_end IS DISTINCT FROM OLD.period_end OR
    NEW.total_amount IS DISTINCT FROM OLD.total_amount OR
    NEW.status IS DISTINCT FROM OLD.status
  ) THEN
    RAISE EXCEPTION 'Paid payouts cannot be financially modified';
  END IF;

  v_action := CASE
    WHEN NEW.status IS DISTINCT FROM OLD.status THEN NEW.status
    ELSE 'updated'
  END;

  INSERT INTO public.payout_audit_logs(payout_id, action, actor_user_id, old_data, new_data)
  VALUES (NEW.id, v_action, auth.uid(), to_jsonb(OLD), to_jsonb(NEW));
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_payout_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_cancel_expired_bookings"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
    r RECORD;
BEGIN
    -- Cancel pending/expired bookings whose expires_at has elapsed
    FOR r IN
        SELECT id, room_id
        FROM public.bookings
        WHERE status = 'pending'
          AND expires_at IS NOT NULL
          AND expires_at <= NOW()
    LOOP
        UPDATE public.bookings
        SET status = 'cancelled',
            updated_at = NOW()
        WHERE id = r.id;

        -- Synchronize room status defensively:
        PERFORM public.sync_room_status(r.room_id);
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."auto_cancel_expired_bookings"() OWNER TO "postgres";


