CREATE OR REPLACE FUNCTION "public"."auto_cancel_no_show_bookings"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now_local timestamp without time zone := pg_catalog.now() AT TIME ZONE 'Africa/Cairo';
  r record;
BEGIN
  FOR r IN
    UPDATE public.bookings AS b
    SET status = 'cancelled'::public.booking_status,
        cancellation_reason = 'NO_SHOW: Booking was not checked in within 20 minutes of start',
        updated_at = pg_catalog.now()
    WHERE b.status = 'upcoming'::public.booking_status
      AND b.payment_status IS DISTINCT FROM 'paid'
      AND b.payment_method IS DISTINCT FROM 'cash'
      AND b.checked_in_at IS NULL
      AND b.booking_period IS NOT NULL
      AND lower(b.booking_period) + interval '20 minutes' <= v_now_local
    RETURNING b.room_id
  LOOP
    IF r.room_id IS NOT NULL THEN
      PERFORM public.sync_room_status(r.room_id);
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."auto_cancel_no_show_bookings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_complete_ended_bookings"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now_local timestamp without time zone := pg_catalog.now() AT TIME ZONE 'Africa/Cairo';
  r record;
BEGIN
  FOR r IN
    UPDATE public.bookings AS b
    SET status = 'completed'::public.booking_status,
        updated_at = pg_catalog.now()
    WHERE b.status = 'in_progress'::public.booking_status
      AND (
        (b.booking_period IS NOT NULL AND upper(b.booking_period) <= v_now_local)
        OR
        (b.booking_period IS NULL AND b.date IS NOT NULL AND b.end_time IS NOT NULL
          AND b.date + b.end_time + CASE WHEN b.end_time <= b.start_time THEN interval '1 day' ELSE interval '0' END <= v_now_local)
      )
    RETURNING b.room_id
  LOOP
    IF r.room_id IS NOT NULL THEN
      PERFORM public.sync_room_status(r.room_id);
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."auto_complete_ended_bookings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_confirm_tournament_results"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  m public.tournament_matches;
  winner uuid;
  v_tournament_id uuid;
  v_tournament_ids uuid[] := ARRAY[]::uuid[];
  n integer := 0;
BEGIN
  FOR m IN
    SELECT *
    FROM public.tournament_matches
    WHERE status = 'pending_confirmation'
      AND confirmation_deadline IS NOT NULL
      AND confirmation_deadline <= now()
      AND score_player1 IS NOT NULL
      AND score_player2 IS NOT NULL
      AND score_player1 <> score_player2
      AND player1_id IS NOT NULL
      AND player2_id IS NOT NULL
    FOR UPDATE SKIP LOCKED
  LOOP
    winner := CASE
      WHEN m.score_player1 > m.score_player2 THEN m.player1_id
      ELSE m.player2_id
    END;

    UPDATE public.tournament_matches
    SET winner_id = winner,
        status = 'completed',
        completed_at = COALESCE(completed_at, now()),
        updated_at = now()
    WHERE id = m.id
      AND status = 'pending_confirmation';

    IF FOUND THEN
      IF m.next_match_id IS NOT NULL AND m.next_match_slot IN (1, 2) THEN
        IF m.next_match_slot = 1 THEN
          UPDATE public.tournament_matches
          SET player1_id = winner, updated_at = now()
          WHERE id = m.next_match_id AND player1_id IS NULL;
        ELSE
          UPDATE public.tournament_matches
          SET player2_id = winner, updated_at = now()
          WHERE id = m.next_match_id AND player2_id IS NULL;
        END IF;
      END IF;

      PERFORM public.tournament_audit(
        m.tournament_id,
        'match_auto_confirmed',
        winner,
        m.id,
        NULL,
        jsonb_build_object(
          'score_player1', m.score_player1,
          'score_player2', m.score_player2,
          'confirmation_deadline', m.confirmation_deadline
        )
      );

      IF NOT (m.tournament_id = ANY(v_tournament_ids)) THEN
        v_tournament_ids := array_append(v_tournament_ids, m.tournament_id);
      END IF;

      n := n + 1;
    END IF;
  END LOOP;

  FOREACH v_tournament_id IN ARRAY v_tournament_ids LOOP
    PERFORM public.apply_tournament_walkovers(v_tournament_id);
  END LOOP;

  RETURN n;
END;
$$;


ALTER FUNCTION "public"."auto_confirm_tournament_results"() OWNER TO "postgres";


