CREATE OR REPLACE FUNCTION "public"."award_points"("p_user_id" "uuid", "p_points" integer, "p_type" "text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_description" "text" DEFAULT NULL::"text", "p_source_type" "text" DEFAULT NULL::"text", "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_transaction_id uuid;
  v_balance integer;
BEGIN
  IF p_user_id IS NULL OR p_points = 0 THEN
    RAISE EXCEPTION 'Invalid points transaction';
  END IF;

  IF p_type IS NULL OR p_type !~ '^[a-z][a-z0-9_]{1,63}$' THEN
    RAISE EXCEPTION 'Invalid points transaction type';
  END IF;

  INSERT INTO public.points_transactions (
    user_id, points, type, reference_id, description,
    source_type, source_id, idempotency_key, metadata
  )
  VALUES (
    p_user_id, p_points, lower(trim(p_type)), p_reference_id, p_description,
    p_source_type, p_source_id, p_idempotency_key, COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL
  DO NOTHING
  RETURNING id INTO v_transaction_id;

  IF v_transaction_id IS NULL THEN
    SELECT points INTO v_balance
    FROM public.profiles
    WHERE id = p_user_id;

    RETURN jsonb_build_object(
      'success', true,
      'applied', false,
      'duplicate', true,
      'balance', COALESCE(v_balance, 0)
    );
  END IF;

  UPDATE public.profiles
  SET points = GREATEST(0, COALESCE(points, 0) + p_points),
      updated_at = now()
  WHERE id = p_user_id
  RETURNING points INTO v_balance;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'applied', true,
    'duplicate', false,
    'transaction_id', v_transaction_id,
    'balance', v_balance
  );
END;
$_$;


ALTER FUNCTION "public"."award_points"("p_user_id" "uuid", "p_points" integer, "p_type" "text", "p_reference_id" "uuid", "p_description" "text", "p_source_type" "text", "p_source_id" "uuid", "p_idempotency_key" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_points_for_booking"("p_booking_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid;
  v_amount numeric;
  v_points integer;
  v_award jsonb;
BEGIN
  SELECT b.user_id, b.total_price
  INTO v_user_id, v_amount
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
    AND b.status = 'completed'::public.booking_status
    AND COALESCE(b.payment_status, 'unpaid') = 'paid';

  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  v_points := GREATEST(
    1,
    ROUND(COALESCE(v_amount, 0) / 10.0)::integer
  );

  v_award := public.award_points(
    p_user_id => v_user_id,
    p_points => v_points,
    p_type => 'earn_booking',
    p_reference_id => p_booking_id,
    p_description => 'نقاط حجز رقم: ' || p_booking_id,
    p_source_type => 'booking',
    p_source_id => p_booking_id,
    p_idempotency_key => 'booking:' || p_booking_id::text,
    p_metadata => jsonb_build_object('booking_id', p_booking_id)
  );

  IF COALESCE((v_award->>'applied')::boolean, false) IS NOT TRUE THEN
    RETURN;
  END IF;

  INSERT INTO public.notifications (
    user_id,
    title,
    title_ar,
    title_en,
    body,
    body_ar,
    body_en,
    type,
    metadata
  )
  VALUES (
    v_user_id,
    'Points Earned',
    'نقاط ولاء جديدة! 🎉',
    'New Loyalty Points Earned!',
    'تم إضافة ' || v_points || ' نقطة ولاء لحسابك مقابل حجزك',
    'تم إضافة ' || v_points || ' نقطة ولاء لحسابك مقابل حجزك',
    'You earned ' || v_points || ' loyalty points for your booking!',
    'loyalty_points',
    jsonb_build_object(
      'booking_id', p_booking_id,
      'points', v_points,
      'event', 'booking_completed'
    )
  );
END;
$$;


ALTER FUNCTION "public"."award_points_for_booking"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_signup_bonus"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
