  INSERT INTO public.points_transactions (
    user_id,
    points,
    type,
    reference_id,
    description
  )
  SELECT
    NEW.id,
    100,
    'earn_signup_bonus',
    NEW.id,
    'هدية التسجيل'
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.points_transactions
    WHERE user_id = NEW.id
      AND type = 'earn_signup_bonus'
  );

  IF FOUND THEN
    UPDATE public.profiles
    SET points = COALESCE(points, 0) + 100,
        updated_at = now()
    WHERE id = NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


