CREATE OR REPLACE FUNCTION "public"."award_tournament_prizes"("p_tournament_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  t public.tournaments%ROWTYPE;
  p public.tournament_prizes%ROWTYPE;
  pl public.tournament_placements%ROWTYPE;
  v_user_id uuid;
  v_inserted boolean;
  n integer := 0;
BEGIN
  SELECT * INTO t
  FROM public.tournaments
  WHERE id=p_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament_not_found' USING ERRCODE='P0002';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR private.is_lounge_manager(t.lounge_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;

  IF t.status<>'completed' THEN
    RAISE EXCEPTION 'tournament_not_completed' USING ERRCODE='55000';
  END IF;

  FOR p IN
    SELECT *
    FROM public.tournament_prizes
    WHERE tournament_id=t.id
    ORDER BY placement
  LOOP
    SELECT *
    INTO pl
    FROM public.tournament_placements
    WHERE tournament_id=t.id
      AND placement=p.placement;

    IF pl.participant_id IS NULL THEN
      CONTINUE;
    END IF;

    SELECT tp.user_id
    INTO v_user_id
    FROM public.tournament_participants AS tp
    WHERE tp.id=pl.participant_id;

    IF v_user_id IS NULL THEN
      CONTINUE;
    END IF;

    IF (p.points+p.bonus)>0 THEN
      INSERT INTO public.points_transactions(
        user_id,points,type,reference_id,description,
        source_type,source_id,idempotency_key,metadata
      )
      VALUES(
        v_user_id,
        p.points+p.bonus,
        'tournament_prize',
        p.id,
        'Tournament prize: '||COALESCE(t.title_en,t.title_ar,'Tournament'),
        'tournament',
        t.id,
        'tournament:'||t.id::text||':placement:'||p.placement,
        jsonb_build_object(
          'placement',p.placement,
          'tournament',COALESCE(t.title_en,t.title_ar),
          'bonus',p.bonus
        )
      )
      ON CONFLICT(idempotency_key) DO NOTHING;

      v_inserted := FOUND;

      IF EXISTS (
        SELECT 1
        FROM public.points_transactions AS pt
        WHERE pt.idempotency_key =
          'tournament:'||t.id::text||':placement:'||p.placement
      ) THEN
        UPDATE public.tournament_prize_rewards
        SET is_delivered=true,
            delivered_at=COALESCE(delivered_at,now()),
            updated_at=now()
        WHERE prize_id=p.id
          AND reward_type='points'
          AND is_delivered IS FALSE;
      END IF;

      IF v_inserted THEN
        INSERT INTO public.notifications(
          user_id,lounge_id,title_ar,title_en,body_ar,body_en,type,metadata
        )
        VALUES(
          v_user_id,
          t.lounge_id,
          'مبروك! حصلت على جائزة البطولة 🏆',
          'Congratulations! You won a tournament prize 🏆',
          'تمت إضافة '||(p.points+p.bonus)||' نقطة إلى حسابك عن المركز '||p.placement||'.',
          'You received '||(p.points+p.bonus)||' points for placement '||p.placement||'.',
          'tournament_prize',
          jsonb_build_object(
            'tournament_id',t.id,
            'placement',p.placement,
            'points',p.points,
            'bonus',p.bonus
          )
        );
        n:=n+1;
      END IF;
    END IF;
  END LOOP;

  PERFORM public.tournament_audit(
    t.id,
    'tournament_prizes_awarded',
    NULL,
    NULL,
    NULL,
    jsonb_build_object('entries',n)
  );

  RETURN n;
END;
$$;


ALTER FUNCTION "public"."award_tournament_prizes"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_complete_onboarding"("p_lounge_id" "uuid", "p_lounge_data" "jsonb", "p_rooms" "jsonb", "p_extras" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_owner_id uuid := auth.uid();
  v_updated_count integer;
BEGIN
  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required'
      USING ERRCODE = '42501';
  END IF;


  PERFORM 1 FROM public.lounges WHERE id=p_lounge_id AND owner_id=v_owner_id AND status IN ('pending','rejected') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OWNED_DRAFT_REQUIRED' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.bookings WHERE lounge_id=p_lounge_id AND status='in_progress') THEN
    RAISE EXCEPTION 'ONBOARDING_OPERATIONAL_CONFLICT' USING ERRCODE='55000';
  END IF;
  IF p_rooms IS NULL OR jsonb_typeof(p_rooms)<>'array' OR jsonb_array_length(p_rooms)<1 OR jsonb_array_length(p_rooms)>250
    OR p_extras IS NULL OR jsonb_typeof(p_extras)<>'array' OR jsonb_array_length(p_extras)>500 THEN
    RAISE EXCEPTION 'INVALID_ONBOARDING_RESOURCES' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rooms) r WHERE NULLIF(r->>'id','') IS NULL
    OR NULLIF(btrim(r->>'name'),'') IS NULL OR COALESCE((r->>'max_capacity')::integer,0)<1
    OR COALESCE((r->>'hourly_rate_single')::numeric,-1)<0 OR COALESCE((r->>'hourly_rate_multi')::numeric,-1)<0
    OR (r->>'hourly_rate_single') IN ('NaN','Infinity','-Infinity') OR (r->>'hourly_rate_multi') IN ('NaN','Infinity','-Infinity'))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_extras) e WHERE NULLIF(e->>'id','') IS NULL
      OR NULLIF(btrim(e->>'name'),'') IS NULL OR COALESCE((e->>'price')::numeric,-1)<0 OR (e->>'price') IN ('NaN','Infinity','-Infinity')) THEN
    RAISE EXCEPTION 'INVALID_ONBOARDING_RESOURCE_FIELDS' USING ERRCODE='22023';
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_rooms))<>(SELECT count(DISTINCT r->>'id') FROM jsonb_array_elements(p_rooms) r)
    OR (SELECT count(*) FROM jsonb_array_elements(p_extras))<>(SELECT count(DISTINCT e->>'id') FROM jsonb_array_elements(p_extras) e) THEN
    RAISE EXCEPTION 'DUPLICATE_ONBOARDING_RESOURCE' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rooms) r JOIN public.rooms existing ON existing.id=(r->>'id')::uuid WHERE existing.lounge_id<>p_lounge_id)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_extras) e JOIN public.extras existing ON existing.id=(e->>'id')::uuid WHERE existing.lounge_id<>p_lounge_id) THEN
    RAISE EXCEPTION 'CROSS_LOUNGE_RESOURCE' USING ERRCODE='42501';
  END IF;

  IF p_lounge_data IS NOT NULL
     AND jsonb_typeof(p_lounge_data) <> 'object'
  THEN
    RAISE EXCEPTION 'p_lounge_data must be a JSON object';
  END IF;

  IF p_rooms IS NOT NULL
     AND jsonb_typeof(p_rooms) <> 'array'
  THEN
    RAISE EXCEPTION 'p_rooms must be a JSON array';
  END IF;

  IF p_extras IS NOT NULL
     AND jsonb_typeof(p_extras) <> 'array'
  THEN
    RAISE EXCEPTION 'p_extras must be a JSON array';
  END IF;

  IF p_lounge_data ? 'brand_id'
     AND NULLIF(p_lounge_data->>'brand_id', '') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.brands b
       WHERE b.id = (p_lounge_data->>'brand_id')::uuid
         AND b.owner_id = v_owner_id
     )
  THEN
    RAISE EXCEPTION 'Brand does not belong to the authenticated owner'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.lounges l
  SET
    vodafone_cash_number=CASE WHEN p_lounge_data ? 'vodafone_cash_number' THEN NULLIF(btrim(p_lounge_data->>'vodafone_cash_number'),'') ELSE l.vodafone_cash_number END,
    instapay_account=CASE WHEN p_lounge_data ? 'instapay_account' THEN NULLIF(btrim(p_lounge_data->>'instapay_account'),'') ELSE l.instapay_account END,
    name = COALESCE(p_lounge_data->>'name', l.name),
    name_ar = COALESCE(p_lounge_data->>'name_ar', l.name_ar),
    name_en = COALESCE(p_lounge_data->>'name_en', l.name_en),

    brand_id = CASE
      WHEN p_lounge_data ? 'brand_id'
        THEN NULLIF(p_lounge_data->>'brand_id', '')::uuid
      ELSE l.brand_id
    END,

    branch_name = CASE
      WHEN p_lounge_data ? 'branch_name'
        THEN NULLIF(p_lounge_data->>'branch_name', '')
      ELSE l.branch_name
    END,

    city = COALESCE(p_lounge_data->>'city', l.city),

    city_id = CASE
      WHEN p_lounge_data ? 'city_id'
        THEN NULLIF(p_lounge_data->>'city_id', '')::uuid
      ELSE l.city_id
    END,

    location = COALESCE(p_lounge_data->>'location', l.location),

    opening_time = CASE
      WHEN p_lounge_data ? 'opening_time'
        THEN NULLIF(p_lounge_data->>'opening_time', '')::time
      ELSE l.opening_time
    END,

    closing_time = CASE
      WHEN p_lounge_data ? 'closing_time'
        THEN NULLIF(p_lounge_data->>'closing_time', '')::time
      ELSE l.closing_time
    END,

    image_url = COALESCE(p_lounge_data->>'image_url', l.image_url),

    images = CASE
      WHEN jsonb_typeof(p_lounge_data->'images') = 'array' THEN
        ARRAY(
          SELECT jsonb_array_elements_text(p_lounge_data->'images')
        )
      WHEN p_lounge_data->'images' = 'null'::jsonb THEN NULL
      ELSE l.images
    END,

    description_ar = COALESCE(
      p_lounge_data->>'description_ar', l.description_ar
    ),

    description_en = COALESCE(
      p_lounge_data->>'description_en', l.description_en
    ),

    address = COALESCE(p_lounge_data->>'address', l.address),

    contact_phone = COALESCE(
      p_lounge_data->>'contact_phone', l.contact_phone
    ),

    location_point = CASE
      WHEN NULLIF(p_lounge_data->>'lat', '') IS NOT NULL
       AND NULLIF(p_lounge_data->>'lng', '') IS NOT NULL
      THEN public.ST_SetSRID(
        public.ST_MakePoint(
          (p_lounge_data->>'lng')::double precision,
          (p_lounge_data->>'lat')::double precision
        ),
        4326
      )::public.geography
      ELSE l.location_point
    END

  WHERE l.id = p_lounge_id
    AND l.owner_id = v_owner_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  IF v_updated_count <> 1 THEN
    RAISE EXCEPTION 'Lounge not found or not owned by the authenticated user'
      USING ERRCODE = '42501';
  END IF;

  IF p_rooms IS NOT NULL AND jsonb_array_length(p_rooms) > 0 THEN
    INSERT INTO public.rooms (
      id,
      lounge_id,
      name,
      photo_url,
      images,
      features,
      is_available,
      controllers_count,
      screen_size,
      status,
      name_ar,
      name_en,
      features_ar,
      features_en,
      description_ar,
      description_en,
      extra_controller_price,
      device_type,
      room_type,
      hourly_rate_single,
      hourly_rate_multi,
      max_capacity,
      description,
      is_active,
      space_type_id
    )
    SELECT
      r.id,
      p_lounge_id,
      r.name,
      r.photo_url,
      r.images,
      r.features,
      COALESCE(r.is_available, true),
      COALESCE(r.controllers_count, 2),
      COALESCE(r.screen_size, '43"'),
      COALESCE(r.status, 'available'),
      r.name_ar,
      r.name_en,
      r.features_ar,
      r.features_en,
      r.description_ar,
      r.description_en,
      COALESCE(r.extra_controller_price, 0),
      r.device_type,
      COALESCE(r.room_type, 'standard'),
      COALESCE(r.hourly_rate_single, 0),
      COALESCE(r.hourly_rate_multi, 0),
      COALESCE(r.max_capacity, 4),
      r.description,
      COALESCE(r.is_active, true),
      r.space_type_id
    FROM jsonb_populate_recordset(
      NULL::public.rooms,
      p_rooms
    ) AS r ON CONFLICT(id) DO UPDATE SET
      name=EXCLUDED.name,
      photo_url=EXCLUDED.photo_url,
      images=EXCLUDED.images,
      features=EXCLUDED.features,
      controllers_count=EXCLUDED.controllers_count,
      screen_size=EXCLUDED.screen_size,
      name_ar=EXCLUDED.name_ar,
      name_en=EXCLUDED.name_en,
      features_ar=EXCLUDED.features_ar,
      features_en=EXCLUDED.features_en,
      description_ar=EXCLUDED.description_ar,
      description_en=EXCLUDED.description_en,
      extra_controller_price=EXCLUDED.extra_controller_price,
      device_type=EXCLUDED.device_type,
      room_type=EXCLUDED.room_type,
      hourly_rate_single=EXCLUDED.hourly_rate_single,
      hourly_rate_multi=EXCLUDED.hourly_rate_multi,
      max_capacity=EXCLUDED.max_capacity,
      description=EXCLUDED.description,
      is_active=EXCLUDED.is_active,
      space_type_id=EXCLUDED.space_type_id;
  END IF;

  IF p_extras IS NOT NULL AND jsonb_array_length(p_extras) > 0 THEN
    INSERT INTO public.extras (
      id,
      lounge_id,
      name,
      price,
      category,
      icon,
      is_available,
      name_ar,
      name_en,
      is_active,
      stock_quantity,
      track_stock,
      min_stock_alert,
      icon_key,
      image_url
    )
    SELECT
      e.id,
      p_lounge_id,
      e.name,
      e.price,
      e.category,
      e.icon,
      COALESCE(e.is_available, true),
      e.name_ar,
      e.name_en,
      COALESCE(e.is_active, true),
      COALESCE(e.stock_quantity, 0),
      COALESCE(e.track_stock, true),
      COALESCE(e.min_stock_alert, 5),
      COALESCE(e.icon_key, 'fastfood'),
      e.image_url
    FROM jsonb_populate_recordset(
      NULL::public.extras,
      p_extras
    ) AS e ON CONFLICT(id) DO UPDATE SET
      name=EXCLUDED.name,
      price=EXCLUDED.price,
      category=EXCLUDED.category,
      icon=EXCLUDED.icon,
      is_available=EXCLUDED.is_available,
      name_ar=EXCLUDED.name_ar,
      name_en=EXCLUDED.name_en,
      is_active=EXCLUDED.is_active,
      stock_quantity=EXCLUDED.stock_quantity,
      track_stock=EXCLUDED.track_stock,
      min_stock_alert=EXCLUDED.min_stock_alert,
      icon_key=EXCLUDED.icon_key,
      image_url=EXCLUDED.image_url;
  END IF;

  IF EXISTS(SELECT 1 FROM public.bookings b
    WHERE b.lounge_id=p_lounge_id AND b.status::text IN ('pending','upcoming','in_progress')
    AND NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(p_rooms) AS chosen(id uuid) WHERE chosen.id=b.room_id)) THEN
    RAISE EXCEPTION 'RESOURCE_HAS_BOOKINGS' USING ERRCODE='55000';
  END IF;
  UPDATE public.rooms r SET is_active=false,is_available=false
   WHERE r.lounge_id=p_lounge_id AND NOT EXISTS(
    SELECT 1 FROM jsonb_to_recordset(p_rooms) AS chosen(id uuid) WHERE chosen.id=r.id);
  UPDATE public.extras e SET is_active=false,is_available=false
   WHERE e.lounge_id=p_lounge_id AND NOT EXISTS(
    SELECT 1 FROM jsonb_to_recordset(COALESCE(p_extras,'[]'::jsonb)) AS chosen(id uuid) WHERE chosen.id=e.id);

  UPDATE public.profiles
  SET is_setup_completed = false,
      updated_at = now()
  WHERE id = v_owner_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Owner profile not found';
  END IF;
END;
$$;


ALTER FUNCTION "public"."batch_complete_onboarding"("p_lounge_id" "uuid", "p_lounge_data" "jsonb", "p_rooms" "jsonb", "p_extras" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_complete_onboarding_v2"("p_lounge_id" "uuid", "p_lounge_data" "jsonb", "p_rooms" "jsonb", "p_extras" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room jsonb;
  v_room_id uuid;
  v_activity_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required' USING ERRCODE='28000';
  END IF;

  PERFORM public.batch_complete_onboarding(
    p_lounge_id,
    p_lounge_data,
    p_rooms,
    p_extras
  );

  FOR v_room IN
    SELECT value
    FROM jsonb_array_elements(COALESCE(p_rooms,'[]'::jsonb))
  LOOP
    BEGIN
      v_room_id := (v_room->>'id')::uuid;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'INVALID_ONBOARDING_ROOM_ID'
          USING ERRCODE='22023';
    END;

    IF NOT EXISTS (
      SELECT 1
      FROM public.rooms AS r
      WHERE r.id = v_room_id
        AND r.lounge_id = p_lounge_id
    ) THEN
      RAISE EXCEPTION 'ONBOARDING_ROOM_SCOPE_MISMATCH'
        USING ERRCODE='42501';
    END IF;

    UPDATE public.rooms AS r
    SET resource_type = CASE
          WHEN v_room ? 'resource_type'
          THEN NULLIF(btrim(v_room->>'resource_type'),'')
          ELSE r.resource_type
        END,
        requires_screen = CASE
          WHEN v_room ? 'requires_screen'
          THEN (v_room->>'requires_screen')::boolean
          ELSE r.requires_screen
        END,
        requires_controllers = CASE
          WHEN v_room ? 'requires_controllers'
          THEN (v_room->>'requires_controllers')::boolean
          ELSE r.requires_controllers
        END,
        pricing_model = CASE
          WHEN v_room ? 'pricing_model'
          THEN NULLIF(btrim(v_room->>'pricing_model'),'')
          ELSE r.pricing_model
        END,
        open_time_enabled = CASE
          WHEN v_room ? 'open_time_enabled'
          THEN (v_room->>'open_time_enabled')::boolean
          ELSE r.open_time_enabled
        END,
        open_time_pricing_mode = CASE
          WHEN v_room ? 'open_time_pricing_mode'
          THEN NULLIF(btrim(v_room->>'open_time_pricing_mode'),'')
          ELSE r.open_time_pricing_mode
        END,
        open_time_custom_hourly_rate = CASE
          WHEN v_room ? 'open_time_custom_hourly_rate'
          THEN NULLIF(v_room->>'open_time_custom_hourly_rate','')::numeric
          ELSE r.open_time_custom_hourly_rate
        END,
        open_time_price_multiplier = CASE
          WHEN v_room ? 'open_time_price_multiplier'
          THEN COALESCE(NULLIF(v_room->>'open_time_price_multiplier','')::numeric,1)
          ELSE r.open_time_price_multiplier
        END,
        open_time_minimum_minutes = CASE
          WHEN v_room ? 'open_time_minimum_minutes'
          THEN COALESCE(NULLIF(v_room->>'open_time_minimum_minutes','')::integer,30)
          ELSE r.open_time_minimum_minutes
        END,
        open_time_rounding_minutes = CASE
          WHEN v_room ? 'open_time_rounding_minutes'
          THEN COALESCE(NULLIF(v_room->>'open_time_rounding_minutes','')::integer,15)
          ELSE r.open_time_rounding_minutes
        END,
        open_time_max_minutes = CASE
          WHEN v_room ? 'open_time_max_minutes'
          THEN NULLIF(v_room->>'open_time_max_minutes','')::integer
          ELSE r.open_time_max_minutes
        END,
        open_time_buffer_before_booking_minutes = CASE
          WHEN v_room ? 'open_time_buffer_before_booking_minutes'
          THEN COALESCE(
            NULLIF(v_room->>'open_time_buffer_before_booking_minutes','')::integer,
            15
          )
          ELSE r.open_time_buffer_before_booking_minutes
        END,
        updated_at = now()
    WHERE r.id = v_room_id;

    IF v_room ? 'activity_ids' THEN
      IF jsonb_typeof(v_room->'activity_ids') <> 'array' THEN
        RAISE EXCEPTION 'ROOM_ACTIVITY_IDS_MUST_BE_ARRAY'
          USING ERRCODE='22023';
      END IF;

      DELETE FROM public.room_activities
      WHERE room_id = v_room_id;

      FOR v_activity_id IN
        SELECT value::uuid
        FROM jsonb_array_elements_text(v_room->'activity_ids')
      LOOP
        IF NOT EXISTS (
          SELECT 1
          FROM public.activity_types AS a
          WHERE a.id = v_activity_id
        ) THEN
          RAISE EXCEPTION 'UNKNOWN_ACTIVITY_TYPE: %', v_activity_id
            USING ERRCODE='22023';
        END IF;

        INSERT INTO public.room_activities(room_id,activity_type_id)
        VALUES(v_room_id,v_activity_id)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."batch_complete_onboarding_v2"("p_lounge_id" "uuid", "p_lounge_data" "jsonb", "p_rooms" "jsonb", "p_extras" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blind_close_shift"("p_shift_id" "uuid", "p_cashier_id" "uuid", "p_counted_cash" numeric, "p_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_shift public.shifts%ROWTYPE;
  v_cash_sales numeric;
  v_expenses numeric;
  v_expected numeric;
  v_difference numeric;
  v_manager boolean;
  v_actor uuid := auth.uid();
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_counted_cash IS NULL OR p_counted_cash < 0 THEN RAISE EXCEPTION 'Counted cash must be non-negative' USING ERRCODE = '22023'; END IF;
  SELECT s.* INTO v_shift FROM public.shifts s WHERE s.id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Shift not found' USING ERRCODE = 'P0002'; END IF;
  IF v_shift.status <> 'open' THEN RAISE EXCEPTION 'Shift is not open' USING ERRCODE = '55000'; END IF;
  IF v_shift.cashier_id IS DISTINCT FROM p_cashier_id THEN RAISE EXCEPTION 'Shift does not belong to the specified cashier' USING ERRCODE = '42501'; END IF;
  IF auth.role() IS DISTINCT FROM 'service_role' AND (
    NOT COALESCE(private.can_operate_playspot_lounge(v_shift.lounge_id), false)
    OR NOT COALESCE(public.has_lounge_permission(v_shift.lounge_id, 'shifts_blind_close'), false)
  ) THEN
    RAISE EXCEPTION 'Shift closure is not permitted for this actor' USING ERRCODE = '42501';
  END IF;
  v_manager := private.can_manage_playspot_lounge(v_shift.lounge_id);
  IF v_actor IS DISTINCT FROM p_cashier_id AND NOT v_manager AND auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Only the shift cashier or an authorized manager may close this shift' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(SUM(sp.amount), 0) INTO v_cash_sales FROM public.shift_payments sp
  WHERE sp.shift_id = p_shift_id AND sp.payment_method = 'cash';
  SELECT COALESCE(SUM(se.amount), 0) INTO v_expenses FROM public.shift_expenses se WHERE se.shift_id = p_shift_id;
  v_expected := COALESCE(v_shift.starting_cash, 0) + v_cash_sales - v_expenses;
  v_difference := p_counted_cash - v_expected;
  UPDATE public.shifts SET actual_cash_counted = p_counted_cash, expected_cash = v_expected,
    difference = v_difference, status = 'closed', closed_at = v_now, end_time = v_now,
    notes = COALESCE(p_notes, notes)
  WHERE id = p_shift_id;

  -- Release cashier writer authority if held by this cashier
  UPDATE private.cashier_writer_authorities
  SET released_at = v_now,
      online_requested = false,
      heartbeat_expires_at = v_now,
      updated_at = v_now
  WHERE lounge_id = v_shift.lounge_id
    AND actor_id = v_shift.cashier_id
    AND released_at IS NULL;

  INSERT INTO public.shift_audit_logs
    (lounge_id, shift_id, entity_type, entity_id, action, actor_user_id, old_data, new_data)
  VALUES
    (v_shift.lounge_id, p_shift_id, 'shift', p_shift_id, 'update', v_actor,
     jsonb_build_object('status', v_shift.status, 'expected_cash', v_shift.expected_cash,
                        'actual_cash_counted', v_shift.actual_cash_counted, 'difference', v_shift.difference),
     jsonb_build_object('status', 'closed', 'expected_cash', v_expected,
                        'actual_cash_counted', p_counted_cash, 'difference', v_difference,
                        'cash_sales', v_cash_sales, 'expenses', v_expenses, 'notes', p_notes));
  RETURN jsonb_build_object('success', true, 'shift_id', p_shift_id, 'status', 'closed',
    'actual_cash_counted', p_counted_cash,
    'expected_cash', CASE WHEN private.can_view_shift_financials(v_shift.lounge_id) THEN to_jsonb(v_expected) ELSE 'null'::jsonb END,
    'difference', CASE WHEN private.can_view_shift_financials(v_shift.lounge_id) THEN to_jsonb(v_difference) ELSE 'null'::jsonb END,
    'manager_report', private.can_view_shift_financials(v_shift.lounge_id), 'financials_visible', private.can_view_shift_financials(v_shift.lounge_id));
END;
$$;


ALTER FUNCTION "public"."blind_close_shift"("p_shift_id" "uuid", "p_cashier_id" "uuid", "p_counted_cash" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bootstrap_offline_cashier"("p_lounge_id" "uuid", "p_device_id" "uuid", "p_online" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_authority jsonb;
  v_shift_id uuid;
  v_shift_count integer;
  v_timezone text;
  v_from bigint;
  v_until bigint;
  v_blind_cash boolean;
  v_menu_view boolean;
  v_snapshot jsonb;
BEGIN
  -- refresh performs canonical active/unbanned Auth and scoped permission checks,
  -- then acquires the same lounge mutex as booking/reconciliation mutations.
  -- An error later in bootstrap rolls back a first writer claim as well.
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  INSERT INTO private.cashier_bootstrap_claim_context VALUES(txid_current(),p_lounge_id,v_actor,p_device_id);
  v_authority := public.refresh_cashier_writer(p_lounge_id,p_device_id,p_online);
  DELETE FROM private.cashier_bootstrap_claim_context WHERE transaction_id=txid_current() AND lounge_id=p_lounge_id;
  IF public.is_super_admin() IS NOT TRUE
    AND public.has_lounge_permission(p_lounge_id,'bookings.view') IS NOT TRUE THEN
    RAISE EXCEPTION 'OFFLINE_BOOTSTRAP_READ_PERMISSION_DENIED' USING ERRCODE='42501';
  END IF;
  v_timezone := v_authority->>'timezone';
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=v_timezone) THEN
    RAISE EXCEPTION 'INVALID_LOUNGE_TIMEZONE' USING ERRCODE='22023';
  END IF;
  SELECT count(*) INTO v_shift_count FROM public.shifts
    WHERE lounge_id=p_lounge_id AND coalesce(cashier_id,staff_user_id)=v_actor
      AND status='open' AND closed_at IS NULL;
  IF v_shift_count<>1 THEN
    RAISE EXCEPTION 'OFFLINE_BOOTSTRAP_REQUIRES_ONE_OWN_SHIFT' USING ERRCODE='55000';
  END IF;
  SELECT id INTO v_shift_id FROM public.shifts
    WHERE lounge_id=p_lounge_id AND coalesce(cashier_id,staff_user_id)=v_actor
      AND status='open' AND closed_at IS NULL FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OFFLINE_BOOTSTRAP_REQUIRES_ONE_OWN_SHIFT' USING ERRCODE='55000';
  END IF;
  v_from := floor((v_authority->>'server_time_ms')::numeric/60000)::bigint*60000;
  v_until := (v_authority->>'expires_ms')::bigint;
  v_blind_cash := public.is_super_admin() IS TRUE OR
    public.has_lounge_permission(p_lounge_id,'shifts_view_blind_cash') IS TRUE;
  v_menu_view := public.is_super_admin() IS TRUE OR
    public.has_lounge_permission(p_lounge_id,'menu_view') IS TRUE;

  -- A single SQL statement gives resources, capacity and receipts one MVCC
  -- snapshot. Do not lock rooms then bookings: existing online start paths take
  -- booking locks first, so that would introduce a reverse-order deadlock.
  WITH room_rows AS MATERIALIZED (
    SELECT r.*, coalesce(r.hourly_rate_single,r.hourly_rate,50) AS single_rate,
      CASE WHEN coalesce(r.hourly_rate_multi,0)>0 THEN r.hourly_rate_multi
        ELSE coalesce(r.hourly_rate_single,r.hourly_rate,50) END AS multi_rate
    FROM public.rooms r WHERE r.lounge_id=p_lounge_id
  ), intervals AS MATERIALIZED (
    SELECT m.room_id,floor(extract(epoch FROM m.scheduled_at)*1000)::bigint AS start_ms,
      ceil(extract(epoch FROM m.scheduled_end_at)*1000)::bigint AS end_ms
    FROM public.tournament_matches m JOIN room_rows r ON r.id=m.room_id
    WHERE m.status<>'cancelled' AND m.scheduled_at IS NOT NULL
      AND m.scheduled_end_at>m.scheduled_at
      AND extract(epoch FROM m.scheduled_at)*1000<v_until
      AND extract(epoch FROM m.scheduled_end_at)*1000>v_from
    UNION ALL
    SELECT h.room_id,floor(extract(epoch FROM (h.start_at AT TIME ZONE v_timezone))*1000)::bigint,
      ceil(extract(epoch FROM (h.end_at AT TIME ZONE v_timezone))*1000)::bigint
    FROM public.booking_holds h JOIN room_rows r ON r.id=h.room_id
    WHERE h.lounge_id=p_lounge_id AND h.released_at IS NULL
      AND h.expires_at>statement_timestamp() AND h.end_at>h.start_at
      AND extract(epoch FROM (h.start_at AT TIME ZONE v_timezone))*1000<v_until
      AND extract(epoch FROM (h.end_at AT TIME ZONE v_timezone))*1000>v_from
  ), booking_rows AS MATERIALIZED (
    SELECT b.*, floor(extract(epoch FROM ((b.date+b.start_time) AT TIME ZONE v_timezone))*1000)::bigint AS start_ms,
      ceil(extract(epoch FROM (((b.date+b.end_time)+CASE WHEN b.end_time<=b.start_time
        THEN interval '1 day' ELSE interval '0' END) AT TIME ZONE v_timezone))*1000)::bigint AS end_ms,
      ceil(extract(epoch FROM (upper(b.cashier_capacity_period) AT TIME ZONE v_timezone))*1000)::bigint AS capacity_end_ms,
      coalesce(p.amount,0) AS paid_amount,
      (p.id IS NULL OR (p.status='completed' AND p.payment_method='cash'
        AND p.lounge_id=p_lounge_id AND p.payout_id IS NULL
        AND p.amount=(SELECT coalesce(sum(sp.amount),0) FROM public.shift_payments sp
          WHERE sp.booking_id=b.id AND sp.lounge_id=p_lounge_id AND sp.payment_method='cash')))
        AND (p.id IS NOT NULL OR b.payment_status='unpaid') AS payment_supported
    FROM public.bookings b JOIN room_rows r ON r.id=b.room_id
    LEFT JOIN public.payments p ON p.booking_id=b.id
    WHERE b.lounge_id=p_lounge_id AND b.date IS NOT NULL
      AND b.start_time IS NOT NULL AND b.end_time IS NOT NULL
      AND b.status NOT IN ('cancelled','rejected')
  ), scoped_bookings AS MATERIALIZED (
    SELECT * FROM booking_rows b WHERE b.status='in_progress'
      OR (b.start_ms<v_until AND b.end_ms>v_from)
      OR (b.shift_id=v_shift_id AND b.total_price>b.paid_amount)
  )
  SELECT jsonb_build_object(
    'protocol_version',2,'complete',true,'authority',v_authority,
    'coverage',jsonb_build_object('from_ms',v_from,'until_ms',v_until),
    'shift',jsonb_build_object('id',v_shift_id,'actor_id',v_actor,
      'lounge_id',p_lounge_id,'status','open','cash_total_visible',v_blind_cash,
      'collected_cash_minor',CASE WHEN v_blind_cash THEN private.offline_minor_amount(
        (SELECT coalesce(sum(amount),0) FROM public.shift_payments
          WHERE shift_id=v_shift_id AND lounge_id=p_lounge_id AND payment_method='cash')) ELSE 0 END),
    'rooms',coalesce((SELECT jsonb_object_agg(r.id::text,jsonb_build_object(
      'id',r.id,'lounge_id',r.lounge_id,'name',r.name,
      'is_active',r.is_active IS TRUE,'is_available',r.is_available IS TRUE,'status',r.status,
      'single_hour_minor',private.offline_minor_amount(r.single_rate),
      'multi_hour_minor',private.offline_minor_amount(r.multi_rate),
      'offline_supported',coalesce(r.pricing_model,'single_multi_hour')='single_multi_hour'
        AND r.single_rate>0 AND r.multi_rate>0,
      'blocked_intervals',coalesce((SELECT jsonb_agg(jsonb_build_object(
        'start_ms',i.start_ms,'end_ms',i.end_ms)) FROM intervals i WHERE i.room_id=r.id),'[]'::jsonb)
    )) FROM room_rows r),'{}'::jsonb),
    'products',coalesce((SELECT jsonb_object_agg(e.id::text,jsonb_build_object(
      'id',e.id,'lounge_id',e.lounge_id,'name',e.name,
      'is_active',e.is_active IS TRUE,'is_available',e.is_available IS TRUE,
      'track_stock',e.track_stock IS TRUE,'stock_quantity',e.stock_quantity,
      'unit_price_minor',private.offline_minor_amount(e.price)
    )) FROM public.extras e WHERE e.lounge_id=p_lounge_id AND v_menu_view),'{}'::jsonb),
    'bookings',coalesce((SELECT jsonb_object_agg(b.id::text,jsonb_build_object(
      'id',b.id,'lounge_id',b.lounge_id,'room_id',b.room_id,'shift_id',b.shift_id,
      'customer_name',b.user_name,'customer_phone',b.user_phone,'play_mode',b.play_mode,
      'timezone',v_timezone,'start_ms',b.start_ms,'end_ms',b.end_ms,
      'capacity_end_ms',coalesce(b.capacity_end_ms,b.start_ms),
      'started_ms',floor(extract(epoch FROM b.actual_start_time)*1000)::bigint,
      'total_minor',private.offline_minor_amount(b.total_price),
      'paid_minor',private.offline_minor_amount(b.paid_amount),
      'payment_status',CASE WHEN b.paid_amount=b.total_price THEN 'paid'
        WHEN b.paid_amount>0 THEN 'partial' ELSE 'unpaid' END,
      'status',b.status,'sync_status','synced',
      'offline_supported',b.is_open_time IS NOT TRUE AND b.payment_supported
        AND b.shift_id=v_shift_id AND b.play_mode IN ('single','multi')
        AND coalesce(b.extra_controllers,0)=0
        AND coalesce(b.discount_amount,0)=0 AND coalesce(b.discount_percentage,0)=0,
      'items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'items',o.items,
        'total_minor',private.offline_minor_amount(o.total_price)))
        FROM public.canteen_orders o WHERE o.booking_id=b.id AND o.lounge_id=p_lounge_id
          AND o.status<>'cancelled'),'[]'::jsonb)
    )) FROM scoped_bookings b),'{}'::jsonb)
  ) INTO v_snapshot;

  -- Never label a truncated oversized snapshot as complete.
  IF octet_length(v_snapshot::text)>8388608 THEN
    RAISE EXCEPTION 'OFFLINE_BOOTSTRAP_TOO_LARGE' USING ERRCODE='54000';
  END IF;
  RETURN v_snapshot;
END; $$;


ALTER FUNCTION "public"."bootstrap_offline_cashier"("p_lounge_id" "uuid", "p_device_id" "uuid", "p_online" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."broadcast_promo_notification"("p_promo_id" "uuid", "p_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM private.assert_lounge_operator(p_lounge_id, false);

  WITH inserted_rows AS (
    INSERT INTO public.notifications (
      user_id,
      title_ar,
      title_en,
      body_ar,
      body_en,
      type,
      metadata,
      is_read,
      created_at
    )
    SELECT
      p.id,
      p_title_ar,
      p_title_en,
      p_body_ar,
      p_body_en,
      'offer',
      jsonb_build_object('promo_id', p_promo_id, 'lounge_id', p_lounge_id),
      false,
      now()
    FROM public.profiles AS p
    WHERE p.is_active = true
    RETURNING id
  )
  SELECT count(*) INTO v_count
  FROM inserted_rows;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."broadcast_promo_notification"("p_promo_id" "uuid", "p_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."business_date"("p_lounge_id" "uuid", "p_ts" timestamp with time zone DEFAULT "now"()) RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tz text;
  v_opening_time time without time zone;
  v_closing_time time without time zone;
  v_local_ts timestamp without time zone;
  v_local_date date;
  v_local_time time without time zone;
BEGIN
  SELECT
    COALESCE(NULLIF(btrim(l.timezone), ''), 'Africa/Cairo'),
    l.opening_time,
    l.closing_time
  INTO v_tz, v_opening_time, v_closing_time
  FROM public.lounges AS l
  WHERE l.id = p_lounge_id;

  IF v_tz IS NULL THEN
    v_tz := 'Africa/Cairo';
  END IF;

  v_local_ts := COALESCE(p_ts, now()) AT TIME ZONE v_tz;
  v_local_date := v_local_ts::date;
  v_local_time := v_local_ts::time;

  -- Handle operating hours crossing midnight (e.g. 10:00 AM to 03:00 AM next day)
  IF v_opening_time IS NOT NULL AND v_closing_time IS NOT NULL THEN
    IF v_closing_time <= v_opening_time THEN
      IF v_local_time < v_closing_time THEN
        RETURN (v_local_date - INTERVAL '1 day')::date;
      END IF;
    END IF;
  END IF;

  RETURN v_local_date;
END;
$$;


ALTER FUNCTION "public"."business_date"("p_lounge_id" "uuid", "p_ts" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_booking_price"("p_hourly_rate" numeric, "p_duration_minutes" integer) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN ROUND((p_hourly_rate * (p_duration_minutes::numeric / 60.0)), 2);
END;
$$;


ALTER FUNCTION "public"."calculate_booking_price"("p_hourly_rate" numeric, "p_duration_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_booking_total"("p_room_id" "uuid", "p_duration_hours" numeric, "p_voucher_code" "text" DEFAULT NULL::"text", "p_manual_discount" numeric DEFAULT 0, "p_manual_discount_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
  v_base_subtotal numeric;
  v_voucher_discount numeric := 0;
  v_staff_discount numeric := COALESCE(p_manual_discount, 0);
  v_final_total numeric;
  v_voucher_res jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF p_duration_hours IS NULL OR p_duration_hours <= 0 THEN
    RAISE EXCEPTION 'Invalid duration' USING ERRCODE='22023';
  END IF;

  IF v_staff_discount < 0 THEN
    RAISE EXCEPTION 'Invalid manual discount' USING ERRCODE='22023';
  END IF;

  SELECT *
  INTO v_room
  FROM public.rooms
  WHERE id = p_room_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found' USING ERRCODE='P0002';
  END IF;

  IF NOT public.has_lounge_permission(v_room.lounge_id, 'billing_checkout') THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_staff_discount > 0
     AND NOT public.has_lounge_permission(v_room.lounge_id, 'billing_apply_discount') THEN
    RAISE EXCEPTION 'Discount permission required' USING ERRCODE='42501';
  END IF;

  IF v_staff_discount > 0
     AND NULLIF(btrim(COALESCE(p_manual_discount_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Manual discount reason required' USING ERRCODE='22023';
  END IF;

  v_base_subtotal := COALESCE(v_room.hourly_rate_single, 0) * p_duration_hours;

  IF p_voucher_code IS NOT NULL AND btrim(p_voucher_code) <> '' THEN
    v_voucher_res := public.validate_voucher_by_code(p_voucher_code);
    IF COALESCE((v_voucher_res->>'valid')::boolean, false) THEN
      IF (v_voucher_res->>'reward_type') = 'discount_fixed' THEN
        v_voucher_discount := COALESCE((v_voucher_res->>'reward_value')::numeric, 0);
      ELSIF (v_voucher_res->>'reward_type') = 'free_hour' THEN
        v_voucher_discount :=
          COALESCE(v_room.hourly_rate_single, 0)
          * COALESCE((v_voucher_res->>'reward_value')::numeric, 0);
      END IF;
    END IF;
  END IF;

  v_final_total := GREATEST(
    0,
    v_base_subtotal - v_voucher_discount - v_staff_discount
  );

  RETURN jsonb_build_object(
    'base_subtotal', v_base_subtotal,
    'voucher_discount', v_voucher_discount,
    'staff_manual_discount', v_staff_discount,
    'manual_discount_reason', p_manual_discount_reason,
    'final_total', v_final_total
  );
END;
$$;


ALTER FUNCTION "public"."calculate_booking_total"("p_room_id" "uuid", "p_duration_hours" numeric, "p_voucher_code" "text", "p_manual_discount" numeric, "p_manual_discount_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."call_staff_request"("p_lounge_id" "uuid", "p_booking_id" "uuid", "p_reason" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_admin_id UUID;
    v_lounge_name TEXT;
BEGIN

  -- guard:caller_check
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.id = p_booking_id AND b.user_id = auth.uid() AND b.lounge_id = p_lounge_id
  ) THEN
    RAISE EXCEPTION 'Not authorized' USING errcode = '42501';
  END IF;

    SELECT name, owner_id INTO v_lounge_name, v_admin_id
    FROM public.lounges
    WHERE id = p_lounge_id;

    INSERT INTO public.notifications (
        user_id, title_ar, title_en, body_ar, body_en, type, is_read, metadata, created_at
    )
    VALUES (
        v_admin_id,
        'طلب خدمة عاجل! 🔔',
        'Staff Assistance Required! 🔔',
        'العميل طلب مساعدة (' || p_reason || '). ملاحظة: ' || COALESCE(p_note, 'لا يوجد'),
        'Client requested assistance (' || p_reason || '). Note: ' || COALESCE(p_note, 'None'),
        'booking',
        false,
        jsonb_build_object(
            'booking_id', p_booking_id, 
            'lounge_id', p_lounge_id, 
            'request_type', 'call_staff',
            'reason', p_reason,
            'note', p_note
        ),
        now()
    );

    RETURN jsonb_build_object('success', true, 'message', 'Staff called successfully');
END;
$$;


ALTER FUNCTION "public"."call_staff_request"("p_lounge_id" "uuid", "p_booking_id" "uuid", "p_reason" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_modify_profile_record"("target_user_id" "uuid", "target_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_my_lounge_id UUID;
    v_my_role TEXT;
BEGIN
    IF auth.uid() = target_user_id THEN
        RETURN TRUE;
    END IF;

    SELECT lounge_id, role INTO v_my_lounge_id, v_my_role
    FROM public.profiles
    WHERE id = auth.uid();

    IF v_my_role = 'super_admin' THEN
        RETURN TRUE;
    END IF;

    IF v_my_role IN ('lounge_owner', 'manager') AND v_my_lounge_id IS NOT NULL AND target_lounge_id = v_my_lounge_id THEN
        RETURN TRUE;
    END IF;

    RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_modify_profile_record"("target_user_id" "uuid", "target_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_profile_record"("target_user_id" "uuid", "target_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_my_lounge_id UUID;
    v_my_role TEXT;
BEGIN
    -- إذا كان المستخدم يستعلم عن بروفايله الشخصي
    IF auth.uid() = target_user_id THEN
        RETURN TRUE;
    END IF;

    -- جلب بيانات المستخدم الحالي مباشرة دون تفعيل RLS
    SELECT lounge_id, role INTO v_my_lounge_id, v_my_role
    FROM public.profiles
    WHERE id = auth.uid();

    -- السوبر أدمن يرى كل شيء
    IF v_my_role = 'super_admin' THEN
        RETURN TRUE;
    END IF;

    -- صاحب ومدير الصالة يرون موظفي نفس الصالة
    IF v_my_lounge_id IS NOT NULL AND target_lounge_id IS NOT NULL AND v_my_lounge_id = target_lounge_id THEN
        RETURN TRUE;
    END IF;

    RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_view_profile_record"("target_user_id" "uuid", "target_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_booking_waitlist"("p_waitlist_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_entry public.booking_waitlist%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_entry
  FROM public.booking_waitlist
  WHERE id = p_waitlist_id
    AND user_id = v_user_id
    AND status IN ('waiting', 'active', 'notified')
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  UPDATE public.booking_waitlist
  SET status = 'cancelled', updated_at = now()
  WHERE id = v_entry.id;

  -- If entry was part of an intent batch, cancel all sibling waiting rooms
  IF v_entry.intent_id IS NOT NULL THEN
    UPDATE public.booking_waitlist
    SET status = 'cancelled', updated_at = now()
    WHERE intent_id = v_entry.intent_id
      AND user_id = v_user_id
      AND status IN ('waiting', 'active', 'notified');
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."cancel_booking_waitlist"("p_waitlist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_expired_pending_bookings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer := 0;
BEGIN
  -- Only cancel confirmed bookings that had payment timeouts or explicit expired_at
  UPDATE public.bookings
  SET status = 'cancelled'::booking_status,
      cancellation_reason = 'Payment deadline expired',
      updated_at = now()
  WHERE status = 'pending'::booking_status
    AND confirmation_status = 'confirmed'
    AND (
      (expires_at IS NOT NULL AND expires_at < now())
      OR (expires_at IS NULL AND created_at < now() - interval '30 minutes' AND payment_method <> 'cash')
    );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."cancel_expired_pending_bookings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_my_booking"("p_booking_id" "uuid", "p_reason" "text" DEFAULT 'Cancelled by user'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_booking.status NOT IN (
    'pending'::public.booking_status,
    'upcoming'::public.booking_status
  ) THEN
    RAISE EXCEPTION 'Booking cannot be cancelled in its current status'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.bookings
  SET status = 'cancelled'::public.booking_status,
      cancellation_reason = COALESCE(NULLIF(btrim(p_reason), ''), 'Cancelled by user'),
      cancelled_at = now(),
      cancelled_by = auth.uid(),
      updated_at = now()
  WHERE id = p_booking_id;

  IF v_booking.room_id IS NOT NULL THEN
    PERFORM public.sync_room_status(v_booking.room_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'status', 'cancelled'
  );
END;
$$;


ALTER FUNCTION "public"."cancel_my_booking"("p_booking_id" "uuid", "p_reason" "text") OWNER TO "postgres";


