CREATE OR REPLACE FUNCTION "public"."cancel_overdue_cash_bookings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now_local timestamp without time zone := now() AT TIME ZONE 'Africa/Cairo';
  r record;
  v_cancelled_count integer := 0;
BEGIN
  FOR r IN
    UPDATE public.bookings AS b
    SET status = 'cancelled'::public.booking_status,
        cancellation_reason = 'Auto-cancelled: cash booking was not checked in within the grace period',
        updated_at = now()
    FROM public.lounges AS l
    WHERE l.id = b.lounge_id
      AND b.payment_method = 'cash'
      AND b.status IN ('pending'::public.booking_status, 'upcoming'::public.booking_status)
      AND b.checked_in_at IS NULL
      AND b.booking_period IS NOT NULL
      AND v_now_local >= lower(b.booking_period)
        + make_interval(mins => GREATEST(COALESCE(l.cash_grace_period_minutes, 0), 0))
    RETURNING b.room_id
  LOOP
    v_cancelled_count := v_cancelled_count + 1;
    IF r.room_id IS NOT NULL THEN
      PERFORM public.sync_room_status(r.room_id);
    END IF;
  END LOOP;

  RETURN v_cancelled_count;
END;
$$;


ALTER FUNCTION "public"."cancel_overdue_cash_bookings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_payout"("p_payout_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE public.payouts
  SET status = 'cancelled', cancelled_by = auth.uid(), cancelled_at = now(), cancelled_reason = p_reason
  WHERE id = p_payout_id AND status IN ('pending','approved','failed','needs_review');

  IF NOT FOUND THEN RAISE EXCEPTION 'Payout not found or cannot be cancelled'; END IF;

  UPDATE public.payments
  SET payout_id = NULL
  WHERE payout_id = p_payout_id;

  RETURN jsonb_build_object('success', true, 'payout_id', p_payout_id, 'status', 'cancelled');
END;
$$;


ALTER FUNCTION "public"."cancel_payout"("p_payout_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."tournaments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lounge_id" "uuid" NOT NULL,
    "city_id" "uuid" NOT NULL,
    "title_ar" "text" NOT NULL,
    "title_en" "text",
    "description_ar" "text",
    "description_en" "text",
    "game_name" "text" NOT NULL,
    "bracket_size" integer NOT NULL,
    "max_participants" integer NOT NULL,
    "entry_fee" numeric(12,2) DEFAULT 0 NOT NULL,
    "registration_opens_at" timestamp with time zone NOT NULL,
    "registration_closes_at" timestamp with time zone NOT NULL,
    "payment_deadline_minutes" integer DEFAULT 60 NOT NULL,
    "check_in_opens_at" timestamp with time zone NOT NULL,
    "check_in_closes_at" timestamp with time zone NOT NULL,
    "tournament_starts_at" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "champion_participant_id" "uuid",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "banner_url" "text",
    "visibility_scope" "text" DEFAULT 'all'::"text" NOT NULL,
    "visibility_radius_km" numeric(6,2),
    CONSTRAINT "tournaments_bracket_size_check" CHECK (("bracket_size" = ANY (ARRAY[8, 16, 32]))),
    CONSTRAINT "tournaments_check" CHECK ((("max_participants" > 0) AND ("max_participants" <= "bracket_size"))),
    CONSTRAINT "tournaments_entry_fee_check" CHECK (("entry_fee" >= (0)::numeric)),
    CONSTRAINT "tournaments_payment_deadline_minutes_check" CHECK (("payment_deadline_minutes" > 0)),
    CONSTRAINT "tournaments_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'registration_open'::"text", 'registration_closed'::"text", 'check_in_open'::"text", 'check_in_closed'::"text", 'draw_completed'::"text", 'in_progress'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "tournaments_time_order_check" CHECK ((("registration_opens_at" < "registration_closes_at") AND ("registration_closes_at" <= "check_in_opens_at") AND ("check_in_opens_at" <= "check_in_closes_at") AND ("check_in_closes_at" <= "tournament_starts_at"))),
    CONSTRAINT "tournaments_visibility_radius_check" CHECK (((("visibility_scope" <> 'radius'::"text") AND ("visibility_radius_km" IS NULL)) OR (("visibility_scope" = 'radius'::"text") AND ("visibility_radius_km" >= (1)::numeric) AND ("visibility_radius_km" <= (500)::numeric)))),
    CONSTRAINT "tournaments_visibility_scope_check" CHECK (("visibility_scope" = ANY (ARRAY['all'::"text", 'city'::"text", 'radius'::"text"])))
);


ALTER TABLE "public"."tournaments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."tournaments"."visibility_scope" IS 'Visibility mode: all, city, or radius';



COMMENT ON COLUMN "public"."tournaments"."visibility_radius_km" IS 'Maximum distance in kilometers when visibility_scope is radius';



CREATE OR REPLACE FUNCTION "public"."cancel_tournament"("p_tournament_id" "uuid", "p_reason" "text") RETURNS "public"."tournaments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v public.tournaments%ROWTYPE;
  old jsonb;
BEGIN
  SELECT * INTO v FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament_not_found';
  END IF;

  IF NOT (is_super_admin() OR private.can_operate_playspot_lounge(v.lounge_id) OR is_lounge_member_or_admin(v.lounge_id)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF v.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'tournament_already_closed';
  END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'cancel_reason_required';
  END IF;

  old := to_jsonb(v);

  UPDATE public.tournaments
  SET status = 'cancelled', updated_at = now()
  WHERE id = v.id
  RETURNING * INTO v;

  INSERT INTO public.tournament_refunds(tournament_id, participant_id, user_id, amount, reason)
  SELECT v.id, p.id, p.user_id, v.entry_fee, p_reason
  FROM public.tournament_participants p
  WHERE p.tournament_id = v.id AND p.user_id IS NOT NULL AND p.payment_status = 'paid'
  ON CONFLICT DO NOTHING;

  UPDATE public.tournament_participants
  SET registration_status = 'cancelled',
      payment_status = CASE WHEN payment_status = 'paid' THEN 'refund_pending' ELSE 'cancelled' END,
      updated_at = now()
  WHERE tournament_id = v.id;

  PERFORM public.tournament_audit(v.id, 'tournament_cancelled', NULL, NULL, old, to_jsonb(v), p_reason);

  RETURN v;
END;
$$;


ALTER FUNCTION "public"."cancel_tournament"("p_tournament_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_active_shift_before_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IN (
       'pending'::public.booking_status,
       'upcoming'::public.booking_status,
       'in_progress'::public.booking_status
     )
     AND NOT EXISTS (
       SELECT 1
       FROM public.shifts AS s
       WHERE s.lounge_id = NEW.lounge_id
         AND s.status = 'open'
         AND s.closed_at IS NULL
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'NO_OPEN_SHIFT';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_active_shift_before_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_and_alert_unconfirmed_future_bookings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_booking record;
  v_alerted_count integer := 0;
BEGIN
  FOR v_booking IN
    SELECT
      b.id,
      b.lounge_id,
      b.user_name,
      b.user_phone,
      b.room_name,
      b.date,
      b.start_time,
      l.unconfirmed_alert_lead_minutes,
      l.timezone
    FROM public.bookings b
    JOIN public.lounges l ON l.id = b.lounge_id
    WHERE b.confirmation_status = 'pending_confirmation'
      AND b.contact_alert_sent_at IS NULL
      AND (b.date + b.start_time) <= (
        (now() AT TIME ZONE COALESCE(NULLIF(btrim(l.timezone),''), 'Africa/Cairo'))
        + make_interval(mins => COALESCE(l.unconfirmed_alert_lead_minutes, 60))
      )
  LOOP
    -- Insert staff notification task
    INSERT INTO public.notifications (
      user_id, title, title_ar, title_en, body, body_ar, body_en, type, metadata
    )
    SELECT
      ls.user_id,
      'Action Required: Unconfirmed Booking Approaching',
      'تنبيه: حجز بانتظار التأكيد قرب موعده!',
      'Urgent: Unconfirmed booking request approaching start time!',
      'العميل ' || COALESCE(v_booking.user_name, 'زائر') || ' طلب حجز الغرفة ' || v_booking.room_name || ' والموعد اقترب. يرجى التواصل معه لتأكيد الحجز أو إلغائه.',
      'العميل ' || COALESCE(v_booking.user_name, 'زائر') || ' طلب حجز الغرفة ' || v_booking.room_name || ' والموعد اقترب. يرجى التواصل معه لتأكيد الحجز أو إلغائه.',
      'Customer ' || COALESCE(v_booking.user_name, 'Guest') || ' has an unconfirmed request for room ' || v_booking.room_name || '. Please contact them.',
      'staff_action_required',
      jsonb_build_object(
        'booking_id', v_booking.id,
        'user_phone', v_booking.user_phone,
        'action', 'contact_customer_for_confirmation'
      )
    FROM public.lounge_staff ls
    WHERE ls.lounge_id = v_booking.lounge_id
      AND ls.status = 'active';

    UPDATE public.bookings
    SET contact_alert_sent_at = now()
    WHERE id = v_booking.id;

    v_alerted_count := v_alerted_count + 1;
  END LOOP;

  RETURN v_alerted_count;
END;
$$;


ALTER FUNCTION "public"."check_and_alert_unconfirmed_future_bookings"() OWNER TO "postgres";


