CREATE OR REPLACE FUNCTION "public"."check_and_send_booking_reminders"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now_local timestamp without time zone :=
    pg_catalog.now() AT TIME ZONE 'Africa/Cairo';
BEGIN
  INSERT INTO public.notifications (
    id, user_id, title, body, title_ar, title_en, body_ar, body_en,
    type, is_read, created_at, metadata, lounge_id
  )
  SELECT
    gen_random_uuid(),
    b.user_id,
    r.title_ar,
    r.body_ar,
    r.title_ar,
    r.title_en,
    r.body_ar,
    r.body_en,
    'booking',
    false,
    now(),
    jsonb_build_object(
      'booking_id', b.id,
      'lounge_id', b.lounge_id,
      'event', 'booking_reminder:' || r.reminder_key,
      'reminder_key', r.reminder_key,
      'scheduled_for', CASE
        WHEN r.reminder_key = 'extension_offer' THEN upper(b.booking_period)
        ELSE b.date + b.start_time
      END,
      'extension_minutes', CASE
        WHEN r.reminder_key = 'extension_offer' THEN 60
        ELSE NULL
      END
    ),
    b.lounge_id
  FROM public.bookings AS b
  CROSS JOIN LATERAL (
    VALUES
      (
        'one_hour',
        'تذكير بموعد الحجز ⏰',
        'حجزك يبدأ خلال ساعة، حضّر نفسك واستمتع بوقتك!',
        'Booking reminder ⏰',
        'Your booking starts in one hour.'
      ),
      (
        'five_minutes',
        'حجزك سيبدأ بعد 5 دقائق ⏰',
        'حجزك في الصالة سيبدأ خلال 5 دقائق، استعد!',
        'Your booking starts in 5 minutes ⏰',
        'Your lounge booking starts in 5 minutes.'
      ),
      (
        'extension_offer',
        'هل تريد تمديد وقت الحجز؟ ⏰',
        'متبقي 5 دقائق على انتهاء حجزك. الساعة التالية متاحة، هل تريد تمديد الوقت؟',
        'Would you like to extend your booking? ⏰',
        'Your booking ends in 5 minutes. The next hour is available. Would you like to extend?'
      )
  ) AS r(reminder_key, title_ar, body_ar, title_en, body_en)
  WHERE b.user_id IS NOT NULL
    AND b.status IN ('upcoming', 'in_progress')
    AND (
      (
        r.reminder_key = 'one_hour'
        AND (b.date + b.start_time)
          BETWEEN (v_now_local + interval '59 minutes')
          AND (v_now_local + interval '61 minutes')
      )
      OR (
        r.reminder_key = 'five_minutes'
        AND (b.date + b.start_time)
          BETWEEN (v_now_local + interval '4 minutes')
          AND (v_now_local + interval '6 minutes')
      )
      OR (
        r.reminder_key = 'extension_offer'
        AND b.room_id IS NOT NULL
        AND upper(b.booking_period)
          BETWEEN (v_now_local + interval '4 minutes')
          AND (v_now_local + interval '6 minutes')
        AND NOT EXISTS (
          SELECT 1
          FROM public.bookings AS next_booking
          WHERE next_booking.id <> b.id
            AND next_booking.room_id = b.room_id
            AND next_booking.status IN ('upcoming', 'in_progress')
            AND next_booking.booking_period && tsrange(
              upper(b.booking_period),
              upper(b.booking_period) + interval '1 hour',
              '[)'
            )
        )
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.notifications AS n
      WHERE n.user_id = b.user_id
        AND n.type = 'booking'
        AND n.metadata->>'booking_id' = b.id::text
        AND n.metadata->>'reminder_key' = r.reminder_key
        AND n.metadata->>'scheduled_for' = (
          CASE
            WHEN r.reminder_key = 'extension_offer' THEN upper(b.booking_period)
            ELSE b.date + b.start_time
          END
        )::text
    );
END;
$$;


ALTER FUNCTION "public"."check_and_send_booking_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_booking_no_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('pending', 'upcoming', 'in_progress') THEN
    IF EXISTS (
      SELECT 1 FROM public.bookings
      WHERE room_id = NEW.room_id
        AND date = NEW.date
        AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
        AND status IN ('pending', 'upcoming', 'in_progress')
        AND (NEW.start_time, NEW.end_time) OVERLAPS (start_time, end_time)
    ) THEN
      RAISE EXCEPTION 'هذه الغرفة محجوزة بالفعل في هذا التوقيت'
        USING ERRCODE = '23P01';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_booking_no_overlap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_in_tournament_participant"("p_participant_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE
  v_p public.tournament_participants%ROWTYPE;
  v_t public.tournaments%ROWTYPE;
BEGIN
  SELECT * INTO v_p FROM public.tournament_participants WHERE id=p_participant_id FOR UPDATE;
  SELECT * INTO v_t FROM public.tournaments WHERE id=v_p.tournament_id;
  IF v_p.user_id<>auth.uid() AND NOT(is_super_admin() OR private.is_lounge_manager(v_t.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_p.payment_status<>'paid' OR v_p.registration_status NOT IN('confirmed','checked_in') THEN RAISE EXCEPTION 'checkin_not_allowed'; END IF;
  IF now()<v_t.check_in_opens_at OR now()>v_t.check_in_closes_at THEN RAISE EXCEPTION 'checkin_closed'; END IF;
  UPDATE public.tournament_participants SET is_checked_in=true,checked_in_at=now(),registration_status='checked_in',updated_at=now() WHERE id=v_p.id RETURNING * INTO v_p;
  PERFORM public.tournament_audit(v_t.id,'participant_checked_in',v_p.id,NULL,NULL,to_jsonb(v_p));
  RETURN row_to_json(v_p);
END
$$;


ALTER FUNCTION "public"."check_in_tournament_participant"("p_participant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_lounge_working_hours"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_is_open BOOLEAN;
    v_opening_time TIME;
    v_closing_time TIME;
BEGIN
    -- 1. جلب بيانات مواعيد الصالة المرتبطة بالحجز
    SELECT is_open, opening_time, closing_time 
    INTO v_is_open, v_opening_time, v_closing_time
    FROM public.lounges
    WHERE id = NEW.lounge_id;

    -- 2. التحقق هل الصالة مغلقة يدوياً (is_open = false)
    IF v_is_open IS FALSE OR v_is_open IS NULL THEN
        RAISE EXCEPTION 'عذراً، هذه الصالة مغلقة حالياً ولا تقبل حجوزات.';
    END IF;

    -- 3. التحقق من ساعات العمل الرسمية باستخدام start_time الخاص بالحجز
    IF v_opening_time IS NOT NULL AND v_closing_time IS NOT NULL AND NEW.start_time IS NOT NULL THEN
        IF v_closing_time > v_opening_time THEN
            -- الحالة العادية (مثلاً من 10 صباحاً لـ 10 مساءً)
            IF NEW.start_time < v_opening_time OR NEW.start_time > v_closing_time THEN
                RAISE EXCEPTION 'عذراً، وقت البدء (%) خارج ساعات العمل الرسمية (من % إلى %).', NEW.start_time, v_opening_time, v_closing_time;
            END IF;
        ELSE
            -- لو الصالة بتمتد لبعد منتصف الليل (مثلاً من 4 عصراً لـ 3 فجراً)
            IF NEW.start_time < v_opening_time AND NEW.start_time > v_closing_time THEN
                RAISE EXCEPTION 'عذراً، وقت البدء (%) خارج ساعات العمل الرسمية (من % إلى %).', NEW.start_time, v_opening_time, v_closing_time;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_lounge_working_hours"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_pricing_rule_conflicts"("p_lounge_id" "uuid", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_days" integer[], "p_space_type_id" "uuid" DEFAULT NULL::"uuid", "p_room_id" "uuid" DEFAULT NULL::"uuid", "p_exclude_rule_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."pricing_rules"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT * FROM public.check_pricing_rule_conflicts_v2(p_lounge_id,p_start_time,p_end_time,p_days,
    p_space_type_id,p_room_id,p_exclude_rule_id,NULL,NULL);
$$;


ALTER FUNCTION "public"."check_pricing_rule_conflicts"("p_lounge_id" "uuid", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_days" integer[], "p_space_type_id" "uuid", "p_room_id" "uuid", "p_exclude_rule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_pricing_rule_conflicts_v2"("p_lounge_id" "uuid", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_days" integer[], "p_space_type_id" "uuid" DEFAULT NULL::"uuid", "p_room_id" "uuid" DEFAULT NULL::"uuid", "p_exclude_rule_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS SETOF "public"."pricing_rules"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT pr.* FROM public.pricing_rules pr
  WHERE pr.lounge_id = p_lounge_id AND pr.is_active IS TRUE
    AND (p_exclude_rule_id IS NULL OR pr.id <> p_exclude_rule_id)
    AND (p_room_id IS NULL OR pr.room_id IS NULL OR pr.room_id = p_room_id)
    AND (p_space_type_id IS NULL OR pr.space_type_id IS NULL OR pr.space_type_id = p_space_type_id)
    AND (p_room_id IS NULL OR pr.space_type_id IS NULL OR EXISTS(
      SELECT 1 FROM public.rooms r WHERE r.id = p_room_id AND r.space_type_id = pr.space_type_id))
    AND (pr.room_id IS NULL OR p_space_type_id IS NULL OR EXISTS(
      SELECT 1 FROM public.rooms r WHERE r.id = pr.room_id AND r.space_type_id = p_space_type_id))
    AND private.pricing_rule_windows_overlap(pr,p_start_time,p_end_time,p_days,p_start_date,p_end_date)
    AND (public.is_super_admin() OR public._playspot_has_lounge_access(p_lounge_id))
  ORDER BY pr.priority DESC,pr.created_at DESC;
$$;


ALTER FUNCTION "public"."check_pricing_rule_conflicts_v2"("p_lounge_id" "uuid", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_days" integer[], "p_space_type_id" "uuid", "p_room_id" "uuid", "p_exclude_rule_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_room_availability"("p_room_id" "uuid", "p_start_time" timestamp with time zone, "p_end_time" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_start_local timestamp without time zone;
  v_end_local timestamp without time zone;
BEGIN
  IF p_room_id IS NULL OR p_start_time IS NULL OR p_end_time IS NULL OR p_end_time <= p_start_time THEN
    RAISE EXCEPTION 'Invalid room or time range' USING ERRCODE = '22023';
  END IF;

  v_start_local := p_start_time AT TIME ZONE 'Africa/Cairo';
  v_end_local := p_end_time AT TIME ZONE 'Africa/Cairo';

  RETURN NOT EXISTS (
    SELECT 1
    FROM public.bookings AS b
    WHERE b.room_id = p_room_id
      AND b.status IN ('pending'::public.booking_status, 'upcoming'::public.booking_status, 'in_progress'::public.booking_status)
      AND b.booking_period IS NOT NULL
      AND b.booking_period && pg_catalog.tsrange(v_start_local, v_end_local, '[)')
      AND (b.status <> 'pending'::public.booking_status OR b.expires_at IS NULL OR b.expires_at > now())
  );
END;
$$;


ALTER FUNCTION "public"."check_room_availability"("p_room_id" "uuid", "p_start_time" timestamp with time zone, "p_end_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_room_availability_local"("p_room_id" "uuid", "p_start_time" timestamp without time zone, "p_end_time" timestamp without time zone) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    p_room_id IS NOT NULL
    AND p_start_time IS NOT NULL
    AND p_end_time IS NOT NULL
    AND p_end_time > p_start_time
    AND NOT EXISTS (
      SELECT 1
      FROM public.bookings AS b
      WHERE b.room_id = p_room_id
        AND b.booking_period IS NOT NULL
        AND b.status IN (
          'pending'::public.booking_status,
          'upcoming'::public.booking_status,
          'in_progress'::public.booking_status
        )
        AND (
          b.status <> 'pending'::public.booking_status
          OR b.expires_at IS NULL
          OR b.expires_at > now()
        )
        AND b.booking_period && pg_catalog.tsrange(
          p_start_time,
          p_end_time,
          '[)'
        )
    );
$$;


ALTER FUNCTION "public"."check_room_availability_local"("p_room_id" "uuid", "p_start_time" timestamp without time zone, "p_end_time" timestamp without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_auth_disable_tasks"("p_limit" integer DEFAULT 10) RETURNS TABLE("user_id" "uuid", "lease_id" "uuid", "attempt" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 20 THEN
    RAISE EXCEPTION 'INVALID_RECOVERY_BATCH_SIZE' USING ERRCODE='22023';
  END IF;
  UPDATE private.auth_disable_tasks t SET status='failed',last_error_code='RETRY_LIMIT_REACHED',lease_id=NULL,leased_until=NULL
  WHERE t.status='running' AND t.leased_until<=now() AND t.attempts>=5;
  UPDATE private.auth_disable_tasks t SET status='cancelled',lease_id=NULL,leased_until=NULL
  WHERE t.status IN ('pending','running') AND EXISTS(
    SELECT 1 FROM public.profiles p WHERE p.id=t.user_id AND p.is_active IS TRUE AND p.is_banned IS FALSE);
  RETURN QUERY
  WITH due AS (
    SELECT t.user_id FROM private.auth_disable_tasks t
    WHERE (t.status='pending' AND t.next_attempt_at<=now()
      OR t.status='running' AND t.leased_until<=now()) AND t.attempts<5
    ORDER BY t.next_attempt_at,t.user_id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) UPDATE private.auth_disable_tasks t
    SET status='running',attempts=t.attempts+1,lease_id=gen_random_uuid(),leased_until=now()+interval '2 minutes'
    FROM due WHERE t.user_id=due.user_id RETURNING t.user_id,t.lease_id,t.attempts;
END;
$$;


ALTER FUNCTION "public"."claim_auth_disable_tasks"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_referral_code"("p_referral_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_referrer_id uuid;
  v_referral public.referrals%ROWTYPE;
  v_email_confirmed_at timestamptz;
  v_referrer_award jsonb;
  v_referred_award jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT u.email_confirmed_at
  INTO v_email_confirmed_at
  FROM auth.users AS u
  WHERE u.id = v_user_id;

  IF v_email_confirmed_at IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'confirm_email_first'
    );
  END IF;

  SELECT p.id
  INTO v_referrer_id
  FROM public.profiles AS p
  WHERE p.referral_code = upper(btrim(p_referral_code))
    AND p.id <> v_user_id
  LIMIT 1;

  IF v_referrer_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'invalid_referral_code'
    );
  END IF;

  SELECT *
  INTO v_referral
  FROM public.referrals
  WHERE referred_id = v_user_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_referral.referrer_id <> v_referrer_id THEN
      RETURN jsonb_build_object(
        'success', false,
        'already_claimed', true,
        'status', v_referral.status,
        'reward_claimed', v_referral.reward_claimed
      );
    END IF;

    IF v_referral.reward_claimed IS TRUE THEN
      RETURN jsonb_build_object(
        'success', false,
        'already_claimed', true,
        'status', v_referral.status,
        'reward_claimed', true
      );
    END IF;
  ELSE
    UPDATE public.profiles
    SET referred_by = v_referrer_id,
        updated_at = now()
    WHERE id = v_user_id
      AND referred_by IS NULL;

    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'success', false,
        'already_claimed', true
      );
    END IF;

    INSERT INTO public.referrals (
      referrer_id,
      referred_id,
      status,
      reward_claimed
    )
    VALUES (
      v_referrer_id,
      v_user_id,
      'pending',
      false
    )
    RETURNING *
    INTO v_referral;
  END IF;

  v_referrer_award := public.award_points(
    p_user_id => v_referrer_id,
    p_points => 100,
    p_type => 'earn_referral',
    p_reference_id => v_user_id,
    p_description => 'مكافأة دعوة صديق',
    p_source_type => 'referral',
    p_source_id => v_referral.id,
    p_idempotency_key => 'referral:referrer:' || v_referral.id::text,
    p_metadata => jsonb_build_object(
      'referral_id', v_referral.id,
      'referred_user_id', v_user_id
    )
  );

  v_referred_award := public.award_points(
    p_user_id => v_user_id,
    p_points => 50,
    p_type => 'earn_referral',
    p_reference_id => v_referral.id,
    p_description => 'هدية ترحيبية من دعوة صديق',
    p_source_type => 'referral',
    p_source_id => v_referral.id,
    p_idempotency_key => 'referral:referred:' || v_referral.id::text,
    p_metadata => jsonb_build_object(
      'referral_id', v_referral.id,
      'referrer_user_id', v_referrer_id
    )
  );

  UPDATE public.referrals
  SET status = 'completed',
      reward_claimed = true
  WHERE id = v_referral.id;

  RETURN jsonb_build_object(
    'success', true,
    'referral_id', v_referral.id,
    'referrer_points', 100,
    'referred_points', 50,
    'referrer_award_applied',
      COALESCE((v_referrer_award->>'applied')::boolean, false),
    'referred_award_applied',
      COALESCE((v_referred_award->>'applied')::boolean, false)
  );
END;
$$;


ALTER FUNCTION "public"."claim_referral_code"("p_referral_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_waitlist_slot"("p_waitlist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_entry public.booking_waitlist%ROWTYPE;
  v_room public.rooms%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_hold_token uuid := gen_random_uuid();
  v_hold_id uuid;
  v_expires_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT w.* INTO v_entry
  FROM public.booking_waitlist w
  WHERE w.id = p_waitlist_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Waitlist request not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_entry.user_id <> v_user_id THEN
    RAISE EXCEPTION 'Unauthorized to claim this waitlist slot' USING ERRCODE = '42501';
  END IF;

  IF v_entry.status NOT IN ('notified', 'waiting', 'active') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'NOT_CLAIMABLE',
      'message', 'Waitlist request is not in a claimable state'
    );
  END IF;

  -- Enforce 10-minute fair claim window if entry was notified
  IF v_entry.status = 'notified' AND COALESCE(v_entry.claim_expires_at, v_entry.notified_at + interval '10 minutes') <= now() THEN
    UPDATE public.booking_waitlist
    SET status = 'expired', updated_at = now()
    WHERE id = v_entry.id;

    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'CLAIM_EXPIRED',
      'message', 'Claim window has expired'
    );
  END IF;

  -- Lock room
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_entry.room_id::text, 0)
  );

  SELECT r.* INTO v_room
  FROM public.rooms r
  WHERE r.id = v_entry.room_id;

  IF NOT FOUND OR COALESCE(v_room.is_active, true) IS FALSE
     OR COALESCE(v_room.status, 'available') = 'deleted' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'ROOM_UNAVAILABLE',
      'message', 'Room is currently unavailable'
    );
  END IF;

  -- Check for existing confirmed or active bookings
  IF EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.room_id = v_entry.room_id
      AND b.status IN ('pending'::public.booking_status,
                       'upcoming'::public.booking_status,
                       'in_progress'::public.booking_status)
      AND (b.status <> 'pending'::public.booking_status
           OR b.expires_at IS NULL OR b.expires_at > now())
      AND b.booking_period && pg_catalog.tsrange(v_entry.start_at, v_entry.end_at, '[)')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'SLOT_ALREADY_BOOKED',
      'message', 'Slot has already been reserved'
    );
  END IF;

  -- Check for competing holds by other users
  IF EXISTS (
    SELECT 1 FROM public.booking_holds h
    WHERE h.room_id = v_entry.room_id
      AND h.user_id <> v_user_id
      AND h.released_at IS NULL
      AND h.expires_at > now()
      AND pg_catalog.tsrange(h.start_at, h.end_at, '[)')
          && pg_catalog.tsrange(v_entry.start_at, v_entry.end_at, '[)')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'SLOT_HELD_BY_ANOTHER_USER',
      'message', 'Slot is currently held by another customer'
    );
  END IF;

  -- Release any older active hold for this user
  UPDATE public.booking_holds
  SET released_at = now()
  WHERE user_id = v_user_id
    AND released_at IS NULL
    AND expires_at > now();

  -- Create 10-minute hold token
  v_expires_at := now() + interval '10 minutes';

  INSERT INTO public.booking_holds (
    hold_token,
    user_id,
    lounge_id,
    room_id,
    start_at,
    end_at,
    expires_at
  ) VALUES (
    v_hold_token,
    v_user_id,
    v_entry.lounge_id,
    v_entry.room_id,
    v_entry.start_at,
    v_entry.end_at,
    v_expires_at
  )
  RETURNING id INTO v_hold_id;

  -- Update waitlist entry to claimed
  UPDATE public.booking_waitlist
  SET status = 'claimed',
      hold_id = v_hold_id,
      updated_at = now()
  WHERE id = v_entry.id;

  -- Automatically cancel other waiting rooms for the same intent batch
  IF v_entry.intent_id IS NOT NULL THEN
    UPDATE public.booking_waitlist
    SET status = 'cancelled', updated_at = now()
    WHERE intent_id = v_entry.intent_id
      AND id <> v_entry.id
      AND status IN ('waiting', 'active', 'notified');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'waitlist_id', v_entry.id,
    'hold_token', v_hold_token,
    'hold_expires_at', v_expires_at,
    'room_id', v_entry.room_id,
    'lounge_id', v_entry.lounge_id,
    'start_at', v_entry.start_at,
    'end_at', v_entry.end_at
  );
END;
$$;


ALTER FUNCTION "public"."claim_waitlist_slot"("p_waitlist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clean_promotions_uuid_payload"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- ملء حقل title الإلزامي إذا لم يتم إرساله
    IF NEW.title IS NULL OR NEW.title = '' THEN
        NEW.title := COALESCE(NEW.title_ar, NEW.title_en, 'عرض جديد');
    END IF;

    -- ملء حقل tag إذا كان فارغاً
    IF NEW.tag IS NULL OR NEW.tag = '' THEN
        NEW.tag := COALESCE(NEW.tag_ar, NEW.tag_en, 'عرض محدود');
    END IF;

    -- التأكد من تحويل room_id الفارغ لـ NULL
    IF NEW.room_id IS NULL OR NEW.room_id::text = '' THEN
        NEW.room_id := NULL;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."clean_promotions_uuid_payload"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."shifts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lounge_id" "uuid" NOT NULL,
    "staff_user_id" "uuid",
    "opened_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "starting_cash" numeric DEFAULT 0 NOT NULL,
    "expected_cash" numeric DEFAULT 0,
    "actual_cash_counted" numeric,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "cashier_id" "uuid",
    "start_time" timestamp with time zone DEFAULT "now"(),
    "end_time" timestamp with time zone,
    "difference" numeric(10,2) DEFAULT 0.00,
    "total_cash_sales" numeric(10,2) DEFAULT 0.00,
    "total_digital_sales" numeric(10,2) DEFAULT 0.00,
    "total_expenses" numeric(10,2) DEFAULT 0.00,
    "payment_method" "text" DEFAULT 'cash'::"text",
    "is_approved" boolean DEFAULT false,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "manager_notes" "text",
    CONSTRAINT "shifts_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'closed'::"text"])))
);


ALTER TABLE "public"."shifts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_lounge_shift"("p_lounge_id" "uuid", "p_actual_cash_counted" numeric DEFAULT NULL::numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."shifts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_shift public.shifts%ROWTYPE;
  v_cash numeric := 0;
  v_digital numeric := 0;
  v_expenses numeric := 0;
  v_expected_cash numeric := 0;
  v_actual_cash numeric;
  v_difference numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required' USING ERRCODE = '28000';
  END IF;

  IF p_lounge_id IS NULL OR (p_actual_cash_counted IS NOT NULL AND p_actual_cash_counted < 0) THEN
    RAISE EXCEPTION 'Invalid lounge or cash count' USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_super_admin() THEN
    PERFORM private.assert_lounge_operator(p_lounge_id, false);
  END IF;

  SELECT s.* INTO v_shift
  FROM public.shifts AS s
  WHERE s.lounge_id = p_lounge_id
    AND s.status = 'open'
    AND s.closed_at IS NULL
  ORDER BY s.opened_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'There is no open shift for this lounge' USING ERRCODE = '55000';
  END IF;

  IF NOT (
    COALESCE(private.can_operate_playspot_lounge(v_shift.lounge_id), false)
    AND COALESCE(public.has_lounge_permission(v_shift.lounge_id, 'shifts_blind_close'), false)
    AND (v_shift.cashier_id = auth.uid()
         OR private.can_manage_playspot_lounge(v_shift.lounge_id))
  ) THEN
    RAISE EXCEPTION 'Only the assigned cashier or an authorized manager can close this shift' USING ERRCODE = '42501';
  END IF;

  IF NOT private.can_view_shift_financials(v_shift.lounge_id) THEN RAISE EXCEPTION 'Use blind_close_shift for blind closure' USING ERRCODE='42501'; END IF;

  SELECT
    COALESCE(sum(sp.amount) FILTER (WHERE sp.payment_method = 'cash'), 0),
    COALESCE(sum(sp.amount) FILTER (WHERE sp.payment_method <> 'cash'), 0)
  INTO v_cash, v_digital
  FROM public.shift_payments AS sp
  WHERE sp.shift_id = v_shift.id;

  SELECT COALESCE(sum(se.amount), 0)
  INTO v_expenses
  FROM public.shift_expenses AS se
  WHERE se.shift_id = v_shift.id;

  v_expected_cash := COALESCE(v_shift.starting_cash, 0) + v_cash - v_expenses;
  v_actual_cash := COALESCE(p_actual_cash_counted, v_shift.actual_cash_counted);
  v_difference := CASE WHEN v_actual_cash IS NULL THEN NULL ELSE v_actual_cash - v_expected_cash END;

  UPDATE public.shifts AS s
  SET status = 'closed',
      closed_at = now(),
      end_time = now(),
      expected_cash = v_expected_cash,
      actual_cash_counted = v_actual_cash,
      total_cash_sales = v_cash,
      total_digital_sales = v_digital,
      total_expenses = v_expenses,
      difference = v_difference,
      notes = COALESCE(p_notes, s.notes)
  WHERE s.id = v_shift.id
  RETURNING s.* INTO v_shift;

  RETURN v_shift;
END;
$$;


ALTER FUNCTION "public"."close_lounge_shift"("p_lounge_id" "uuid", "p_actual_cash_counted" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_shift"("p_shift_id" "uuid", "p_actual_cash" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_shift public.shifts;
  v_cash numeric := 0;
  v_digital numeric := 0;
  v_expenses numeric := 0;
  v_cash_expenses numeric := 0;
  v_expected numeric := 0;
  v_diff numeric := 0;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Authentication required.';
  END IF;

  IF p_actual_cash IS NULL OR p_actual_cash < 0 THEN
    RAISE EXCEPTION 'Actual cash cannot be negative.';
  END IF;

  SELECT * INTO v_shift
  FROM public.shifts
  WHERE id = p_shift_id
    AND status = 'open'
  FOR UPDATE;

  IF v_shift.id IS NULL THEN
    RAISE EXCEPTION 'Shift not found or already closed.';
  END IF;

  IF NOT (
    private.can_operate_playspot_lounge(v_shift.lounge_id)
    AND public.has_lounge_permission(v_shift.lounge_id, 'shifts_blind_close')
    AND (v_shift.cashier_id = auth.uid()
         OR private.can_manage_playspot_lounge(v_shift.lounge_id))
  ) THEN
    RAISE EXCEPTION 'Only the assigned cashier or an authorized manager can close this shift.' USING ERRCODE = '42501';
  END IF;

  IF NOT private.can_view_shift_financials(v_shift.lounge_id) THEN RAISE EXCEPTION 'Use blind_close_shift for blind closure' USING ERRCODE='42501'; END IF;

  SELECT
    COALESCE(SUM(CASE WHEN payment_method = 'cash' THEN amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN payment_method <> 'cash' THEN amount ELSE 0 END), 0)
  INTO v_cash, v_digital
  FROM public.shift_payments
  WHERE shift_id = p_shift_id;

  SELECT
    COALESCE(SUM(amount), 0),
    COALESCE(SUM(CASE WHEN expense_type IN ('cash_drop', 'expense', 'other') THEN amount ELSE 0 END), 0)
  INTO v_expenses, v_cash_expenses
  FROM public.shift_expenses
  WHERE shift_id = p_shift_id;

  v_expected := COALESCE(v_shift.starting_cash, 0) + v_cash - v_cash_expenses;
  v_diff := p_actual_cash - v_expected;

  UPDATE public.shifts
  SET status = 'closed',
      closed_at = now(),
      end_time = now(),
      actual_cash_counted = p_actual_cash,
      expected_cash = v_expected,
      total_cash_sales = v_cash,
      total_digital_sales = v_digital,
      total_expenses = v_expenses,
      difference = v_diff,
      notes = COALESCE(p_notes, notes)
  WHERE id = p_shift_id;

  RETURN json_build_object(
    'success', true,
    'shift_id', p_shift_id,
    'starting_cash', COALESCE(v_shift.starting_cash, 0),
    'cash_sales', v_cash,
    'digital_sales', v_digital,
    'total_expenses', v_expenses,
    'expected_cash', v_expected,
    'actual_cash', p_actual_cash,
    'difference', v_diff,
    'status', 'closed'
  );
END;
$$;


ALTER FUNCTION "public"."close_shift"("p_shift_id" "uuid", "p_actual_cash" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_shift_and_calculate_z_report"("p_shift_id" "uuid", "p_actual_cash" numeric, "p_notes" "text" DEFAULT ''::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_starting_cash NUMERIC := 0;
    v_cash_revenue NUMERIC := 0;
    v_digital_revenue NUMERIC := 0;
    v_expenses NUMERIC := 0;
    v_total_expected_cash NUMERIC := 0;
    v_total_revenue NUMERIC := 0;
    v_discrepancy NUMERIC := 0;
    v_closed_shift RECORD;
BEGIN
    SELECT COALESCE(starting_cash, 0) INTO v_starting_cash
    FROM public.shifts
    WHERE id = p_shift_id;

    SELECT COALESCE(SUM(amount), 0) INTO v_cash_revenue
    FROM public.shift_payments
    WHERE shift_id = p_shift_id AND payment_method = 'cash';

    SELECT COALESCE(SUM(amount), 0) INTO v_digital_revenue
    FROM public.shift_payments
    WHERE shift_id = p_shift_id AND payment_method <> 'cash';

    SELECT COALESCE(SUM(amount), 0) INTO v_expenses
    FROM public.shift_expenses
    WHERE shift_id = p_shift_id;

    v_total_revenue := v_cash_revenue + v_digital_revenue;
    v_total_expected_cash := v_starting_cash + v_cash_revenue - v_expenses;
    v_discrepancy := p_actual_cash - v_total_expected_cash;

    UPDATE public.shifts
    SET
        status = 'closed',
        closed_at = now(),
        expected_cash = v_total_expected_cash,
        actual_cash_counted = p_actual_cash,
        total_cash_sales = v_cash_revenue,
        total_digital_sales = v_digital_revenue,
        total_expenses = v_expenses,
        difference = v_discrepancy,
        notes = p_notes
    WHERE id = p_shift_id
    RETURNING * INTO v_closed_shift;

    RETURN json_build_object(
        'shift', row_to_json(v_closed_shift),
        'summary', json_build_object(
            'starting_cash', v_starting_cash,
            'cash_revenue', v_cash_revenue,
            'digital_revenue', v_digital_revenue,
            'total_revenue', v_total_revenue,
            'total_expenses', v_expenses,
            'expected_cash', v_total_expected_cash,
            'actual_cash', p_actual_cash,
            'discrepancy', v_discrepancy
        )
    );
END;
$$;


ALTER FUNCTION "public"."close_shift_and_calculate_z_report"("p_shift_id" "uuid", "p_actual_cash" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."collect_booking_cash_partial"("p_booking_id" "uuid", "p_shift_id" "uuid", "p_amount_minor" numeric, "p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_receipt private.cash_collection_receipts%ROWTYPE; v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF p_operation_id IS NULL OR p_booking_id IS NULL OR p_shift_id IS NULL OR p_amount_minor IS NULL
    OR p_amount_minor::text IN ('NaN','Infinity','-Infinity') OR p_amount_minor<=0
    OR p_amount_minor<>trunc(p_amount_minor) OR p_amount_minor>9007199254740991 THEN
    RAISE EXCEPTION 'INVALID_CASH_COLLECTION_REQUEST' USING ERRCODE='22023';
  END IF;
  INSERT INTO private.cash_collection_receipts(operation_id,actor_id,booking_id,shift_id,amount_minor)
    VALUES(p_operation_id,auth.uid(),p_booking_id,p_shift_id,p_amount_minor) ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT v_receipt FROM private.cash_collection_receipts WHERE operation_id=p_operation_id FOR UPDATE;
  IF v_receipt.actor_id IS DISTINCT FROM auth.uid() OR v_receipt.booking_id IS DISTINCT FROM p_booking_id
    OR v_receipt.shift_id IS DISTINCT FROM p_shift_id OR v_receipt.amount_minor IS DISTINCT FROM p_amount_minor THEN
    RAISE EXCEPTION 'CASH_COLLECTION_REPLAY_CONFLICT' USING ERRCODE='22023';
  END IF;
  IF v_receipt.result IS NOT NULL THEN
    PERFORM private.assert_cash_collector(auth.uid(),(v_receipt.result->>'lounge_id')::uuid);
    RETURN v_receipt.result||jsonb_build_object('replayed',true);
  END IF;
  v_result:=private.apply_partial_cash_collection(p_booking_id,p_shift_id,p_amount_minor)
    ||jsonb_build_object('operation_id',p_operation_id,'replayed',false);
  UPDATE private.cash_collection_receipts SET result=v_result WHERE operation_id=p_operation_id;
  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."collect_booking_cash_partial"("p_booking_id" "uuid", "p_shift_id" "uuid", "p_amount_minor" numeric, "p_operation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_booking_payment"("p_booking_id" "uuid", "p_payment_method" "text" DEFAULT 'cash'::"text", "p_final_amount" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_total_amount numeric;
  v_already_paid numeric := 0;
  v_delta numeric := 0;
  v_commission numeric;
  v_shift_id uuid;
  v_new_status public.booking_status;
  v_voucher_to_consume text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_payment_method IS NULL OR p_payment_method NOT IN (
    'cash','manual_transfer','card','vodafone_cash','fawry','instapay','app_wallet'
  ) THEN
    RAISE EXCEPTION 'Invalid payment method' USING ERRCODE = '22023';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_booking.lounge_id, 'billing_checkout') THEN
    RAISE EXCEPTION 'Not authorized for billing checkout in this lounge' USING ERRCODE = '42501';
  END IF;

  -- Check already paid amounts
  SELECT COALESCE(SUM(p.amount), 0)
  INTO v_already_paid
  FROM public.payments AS p
  WHERE p.booking_id = p_booking_id
    AND p.status = 'completed';

  v_total_amount := round(v_booking.total_price, 2);
  v_delta := GREATEST(0, v_total_amount - v_already_paid);

  -- Idempotency check: if already fully paid and delta is 0
  IF v_booking.payment_status = 'paid' AND v_delta = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'booking_id', p_booking_id,
      'room_id', v_booking.room_id,
      'status', v_booking.status::text,
      'amount_paid', v_total_amount,
      'payment_method', v_booking.payment_method,
      'idempotent', true
    );
  END IF;

  IF v_booking.status::text IN ('cancelled', 'rejected') THEN
    RAISE EXCEPTION 'Cannot collect payment for a cancelled or rejected booking' USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.payments AS p
    WHERE p.booking_id = p_booking_id AND p.status = 'refunded'
  ) THEN
    RAISE EXCEPTION 'A refunded payment cannot be completed again through this RPC' USING ERRCODE = '55000';
  END IF;

  IF v_booking.total_price IS NULL OR v_booking.total_price < 0 THEN
    RAISE EXCEPTION 'Booking has an invalid server-calculated total' USING ERRCODE = '22023';
  END IF;

  IF p_final_amount IS NOT NULL AND round(p_final_amount, 2) NOT IN (v_total_amount, v_delta) THEN
    RAISE EXCEPTION 'Payment amount must match the booking total or remaining balance'
      USING ERRCODE = '22023';
  END IF;

  SELECT s.id
  INTO v_shift_id
  FROM public.shifts AS s
  WHERE s.lounge_id = v_booking.lounge_id
    AND s.status = 'open'
    AND s.closed_at IS NULL
  ORDER BY s.opened_at DESC
  LIMIT 1
  FOR SHARE;

  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION 'An open shift is required to collect payment' USING ERRCODE = '55000';
  END IF;

  IF v_booking.status = 'completed'::public.booking_status THEN
    v_new_status := 'completed'::public.booking_status;
  ELSIF v_booking.status = 'in_progress'::public.booking_status THEN
    v_new_status := 'in_progress'::public.booking_status;
  ELSE
    v_new_status := 'upcoming'::public.booking_status;
  END IF;

  -- Consume attached voucher if exists
  v_voucher_to_consume := COALESCE(
    v_booking.applied_voucher_code,
    CASE 
      WHEN v_booking.discount_reason ~* '^voucher:\s*([A-Za-z0-9_-]+)' 
      THEN substring(v_booking.discount_reason from '(?i)^voucher:\s*([A-Za-z0-9_-]+)')
      ELSE NULL 
    END
  );

  IF v_voucher_to_consume IS NOT NULL THEN
    -- Mark user voucher as used
    UPDATE public.user_vouchers
    SET status = 'used',
        used_at = now(),
        used_booking_id = p_booking_id
    WHERE UPPER(TRIM(code)) = UPPER(TRIM(v_voucher_to_consume))
      AND (v_booking.user_id IS NULL OR user_id = v_booking.user_id)
      AND status = 'active';
  END IF;

  v_commission := round(v_total_amount * 0.15, 2);

  -- Upsert payments record for authoritative financial total
  INSERT INTO public.payments (
    booking_id, user_id, lounge_id, amount, commission, net_to_lounge,
    payment_method, status, paid_at, discount_amount, discount_percentage,
    discount_reason, discount_approved_by
  ) VALUES (
    p_booking_id, v_booking.user_id, v_booking.lounge_id, v_total_amount,
    v_commission, v_total_amount - v_commission, p_payment_method, 'completed', now(),
    COALESCE(v_booking.discount_amount, 0), COALESCE(v_booking.discount_percentage, 0),
    v_booking.discount_reason, v_booking.discount_approved_by
  )
  ON CONFLICT (booking_id) DO UPDATE SET
    amount = EXCLUDED.amount,
    commission = EXCLUDED.commission,
    net_to_lounge = EXCLUDED.net_to_lounge,
    payment_method = EXCLUDED.payment_method,
    status = 'completed',
    paid_at = EXCLUDED.paid_at,
    discount_amount = EXCLUDED.discount_amount,
    discount_percentage = EXCLUDED.discount_percentage,
    discount_reason = EXCLUDED.discount_reason,
    discount_approved_by = EXCLUDED.discount_approved_by;

  -- Record only the delta in the current active shift (prevents double-counting previously collected cash)
  IF v_delta > 0 THEN
    INSERT INTO public.shift_payments (
      shift_id, lounge_id, booking_id, payment_method, category, amount, paid_at
    ) VALUES (
      v_shift_id, v_booking.lounge_id, p_booking_id, p_payment_method, 'gaming_time', v_delta, now()
    );
  END IF;

  UPDATE public.bookings AS b
  SET status = v_new_status,
      payment_status = 'paid',
      payment_method = p_payment_method,
      total_price = v_total_amount,
      shift_id = v_shift_id,
      updated_at = now()
  WHERE b.id = p_booking_id;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'room_id', v_booking.room_id,
    'status', v_new_status::text,
    'amount_paid', v_total_amount,
    'delta_collected', v_delta,
    'payment_method', p_payment_method,
    'commission', v_commission,
    'net_to_lounge', v_total_amount - v_commission,
    'shift_id', v_shift_id
  );
END;
$$;


ALTER FUNCTION "public"."complete_booking_payment"("p_booking_id" "uuid", "p_payment_method" "text", "p_final_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_booking_session"("p_booking_id" "uuid", "p_action_by" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_room public.rooms%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_now timestamptz := now();
  v_start_time timestamptz;
  v_elapsed_minutes integer;
  v_billable_raw integer;
  v_billable_minutes integer;
  v_rounding integer := 15;
  v_minimum integer := 30;
  v_max integer := 720;
  v_rate numeric := 50;
  v_room_price numeric;
  v_total_price numeric;
  v_amount_paid numeric := 0;
  v_amount_due numeric := 0;
  v_new_payment_status text := 'unpaid';
  v_snap jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_booking.lounge_id, 'sessions_control') THEN
    RAISE EXCEPTION 'Not authorized for session control in this lounge' USING ERRCODE = '42501';
  END IF;

  -- Compute actual cash/online collected payments already recorded
  SELECT COALESCE(SUM(p.amount), 0)
  INTO v_amount_paid
  FROM public.payments AS p
  WHERE p.booking_id = p_booking_id
    AND p.status = 'completed';

  -- Idempotency: if already completed, return existing numbers
  IF v_booking.status = 'completed'::public.booking_status THEN
    v_amount_due := GREATEST(0, COALESCE(v_booking.total_price, 0) - v_amount_paid);

    RETURN json_build_object(
      'success', true,
      'booking_id', p_booking_id,
      'lounge_id', v_booking.lounge_id,
      'status', 'completed',
      'final_total', v_booking.total_price,
      'amount_paid', v_amount_paid,
      'amount_due', v_amount_due,
      'payment_status', v_booking.payment_status,
      'idempotent', true
    );
  END IF;

  IF v_booking.status <> 'in_progress'::public.booking_status THEN
    RAISE EXCEPTION 'Only in-progress sessions can be completed' USING ERRCODE = '55000';
  END IF;

  -- If this is an Open Time session, calculate billing
  IF COALESCE(v_booking.is_open_time, false) IS TRUE THEN
    v_snap := v_booking.open_time_pricing_snapshot;

    IF v_snap IS NOT NULL AND v_snap <> '{}'::jsonb THEN
      v_rate := COALESCE((v_snap->>'effective_hourly_rate')::numeric, (v_snap->>'base_hourly_rate')::numeric, 50);
      v_minimum := COALESCE((v_snap->>'minimum_minutes')::integer, 30);
      v_rounding := COALESCE((v_snap->>'rounding_minutes')::integer, 15);
      v_max := COALESCE((v_snap->>'max_minutes')::integer, 720);
    ELSE
      SELECT l.* INTO v_lounge FROM public.lounges l WHERE l.id = v_booking.lounge_id;
      SELECT r.* INTO v_room FROM public.rooms r WHERE r.id = v_booking.room_id;
      v_minimum := COALESCE(v_room.open_time_minimum_minutes, v_lounge.open_time_minimum_minutes, 30);
      v_rounding := COALESCE(v_room.open_time_rounding_minutes, v_lounge.open_time_rounding_minutes, 15);
      v_max := COALESCE(v_room.open_time_max_minutes, v_lounge.open_time_max_minutes, 720);
      v_rate := CASE
        WHEN v_booking.play_mode = 'multi' AND COALESCE(v_room.hourly_rate_multi, 0) > 0 THEN v_room.hourly_rate_multi
        ELSE COALESCE(v_room.hourly_rate_single, v_room.hourly_rate, 50)
      END;
    END IF;

    v_start_time := COALESCE(v_booking.open_time_started_at, v_booking.actual_start_time, v_booking.created_at);
    v_elapsed_minutes := GREATEST(1, ROUND(EXTRACT(EPOCH FROM (v_now - v_start_time)) / 60.0)::integer);

    IF v_max IS NOT NULL AND v_max > 0 THEN
      v_billable_raw := LEAST(v_elapsed_minutes, v_max);
    ELSE
      v_billable_raw := v_elapsed_minutes;
    END IF;

    v_billable_raw := GREATEST(v_billable_raw, v_minimum);
    v_billable_minutes := CEIL(v_billable_raw::numeric / v_rounding::numeric)::integer * v_rounding;

    v_room_price := ROUND((v_rate / 60.0) * v_billable_minutes, 2);
    v_total_price := v_room_price + COALESCE(v_booking.addons_total, v_booking.addons_price, 0) - COALESCE(v_booking.discount_amount, 0);
    v_amount_due := GREATEST(0, v_total_price - v_amount_paid);

    IF v_amount_due > 0 THEN
      v_new_payment_status := 'unpaid';
    ELSE
      v_new_payment_status := 'paid';
    END IF;

    UPDATE public.bookings
    SET status = 'completed'::public.booking_status,
        payment_status = v_new_payment_status,
        open_time_closed_at = v_now,
        open_time_billing_minutes = v_billable_minutes,
        duration_minutes = v_billable_minutes,
        room_price = v_room_price,
        total_price = v_total_price,
        updated_at = v_now
    WHERE id = p_booking_id;
  ELSE
    v_total_price := v_booking.total_price;
    v_amount_due := GREATEST(0, v_total_price - v_amount_paid);
    v_new_payment_status := CASE WHEN v_amount_due = 0 THEN 'paid' ELSE 'unpaid' END;

    UPDATE public.bookings
    SET status = 'completed'::public.booking_status,
        payment_status = v_new_payment_status,
        updated_at = v_now
    WHERE id = p_booking_id;
  END IF;

  -- Release room
  IF v_booking.room_id IS NOT NULL THEN
    UPDATE public.rooms AS r
    SET status = 'available',
        is_available = true,
        updated_at = v_now
    WHERE r.id = v_booking.room_id
      AND r.lounge_id = v_booking.lounge_id
      AND r.status = 'occupied';
  END IF;

  RETURN json_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'lounge_id', v_booking.lounge_id,
    'status', 'completed',
    'final_total', v_total_price,
    'amount_paid', v_amount_paid,
    'amount_due', v_amount_due,
    'payment_status', v_new_payment_status
  );
END;
$$;


ALTER FUNCTION "public"."complete_booking_session"("p_booking_id" "uuid", "p_action_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payout"("p_payout_id" "uuid", "p_transfer_method" "text", "p_transfer_reference" "text", "p_receipt_url" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF p_transfer_method IS NULL OR p_transfer_method NOT IN ('bank_transfer','instapay','vodafone_cash','cash','other') THEN
    RAISE EXCEPTION 'Invalid transfer method';
  END IF;
  IF NULLIF(trim(p_transfer_reference), '') IS NULL THEN RAISE EXCEPTION 'Transfer reference is required'; END IF;

  UPDATE public.payouts
  SET status = 'paid',
      paid_at = now(),
      paid_by = auth.uid(),
      transfer_method = p_transfer_method,
      transfer_reference = p_transfer_reference,
      receipt_url = p_receipt_url,
      notes = COALESCE(p_notes, notes)
  WHERE id = p_payout_id AND status IN ('approved','processing');

  IF NOT FOUND THEN RAISE EXCEPTION 'Payout not found or not ready to be paid'; END IF;
  RETURN jsonb_build_object('success', true, 'payout_id', p_payout_id, 'status', 'paid');
END;
$$;


ALTER FUNCTION "public"."complete_payout"("p_payout_id" "uuid", "p_transfer_method" "text", "p_transfer_reference" "text", "p_receipt_url" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_tournament"("p_tournament_id" "uuid") RETURNS "public"."tournaments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$ DECLARE t public.tournaments%ROWTYPE; f public.tournament_matches%ROWTYPE; BEGIN SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE; IF NOT(is_super_admin() OR private.is_lounge_manager(t.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF; SELECT * INTO f FROM public.tournament_matches WHERE tournament_id=t.id ORDER BY round_number DESC,match_order LIMIT 1; IF f.status<>'completed' OR f.winner_id IS NULL THEN RAISE EXCEPTION 'final_not_completed'; END IF; UPDATE public.tournaments SET status='completed',champion_participant_id=f.winner_id,updated_at=now() WHERE id=t.id RETURNING * INTO t; INSERT INTO public.tournament_placements(tournament_id,placement,participant_id) VALUES(t.id,1,f.winner_id) ON CONFLICT(tournament_id,placement) DO UPDATE SET participant_id=EXCLUDED.participant_id; PERFORM public.tournament_audit(t.id,'tournament_completed',f.winner_id,f.id,NULL,to_jsonb(t)); RETURN t; END $$;


ALTER FUNCTION "public"."complete_tournament"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_cash_payment"("p_booking_id" "uuid", "p_shift_id" "uuid" DEFAULT NULL::"uuid", "p_discount_amount" numeric DEFAULT 0, "p_discount_percentage" numeric DEFAULT 0, "p_discount_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_now_local timestamp := (now() AT TIME ZONE 'Africa/Cairo');
  v_new_status public.booking_status;
  v_shift_id uuid;
BEGIN
  SELECT * INTO v_booking
  FROM public.bookings
  WHERE id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;

  IF NOT public.is_admin_of_lounge(v_booking.lounge_id) THEN
    RAISE EXCEPTION 'Only lounge management or authorized staff can approve cash bookings'
      USING ERRCODE = '42501';
  END IF;

  IF v_booking.payment_method <> 'cash' THEN
    RAISE EXCEPTION 'This function only confirms cash bookings';
  END IF;

  IF v_booking.booking_period IS NULL OR v_now_local >= upper(v_booking.booking_period) THEN
    RAISE EXCEPTION 'Booking period has already ended';
  END IF;

  IF COALESCE(p_discount_amount, 0) < 0
     OR COALESCE(p_discount_percentage, 0) < 0
     OR COALESCE(p_discount_percentage, 0) > 100 THEN
    RAISE EXCEPTION 'Invalid discount';
  END IF;

  v_new_status := CASE
    WHEN v_now_local >= lower(v_booking.booking_period)
     AND v_now_local < upper(v_booking.booking_period)
      THEN 'in_progress'::public.booking_status
    ELSE 'upcoming'::public.booking_status
  END;

  v_shift_id := COALESCE(p_shift_id, v_booking.shift_id);
  IF v_shift_id IS NULL THEN
    SELECT id INTO v_shift_id
    FROM public.shifts
    WHERE lounge_id = v_booking.lounge_id
      AND status = 'open'
    ORDER BY opened_at DESC
    LIMIT 1;
  END IF;

  UPDATE public.payments
  SET status = 'completed', paid_at = now()
  WHERE booking_id = p_booking_id;

  UPDATE public.bookings
  SET payment_status = 'paid',
      status = v_new_status,
      shift_id = v_shift_id,
      discount_amount = COALESCE(p_discount_amount, 0),
      discount_percentage = COALESCE(p_discount_percentage, 0),
      discount_reason = p_discount_reason,
      updated_at = now()
  WHERE id = p_booking_id;

  UPDATE public.rooms
  SET status = 'occupied',
      is_available = false,
      updated_at = now()
  WHERE id = v_booking.room_id;
END;
$$;


ALTER FUNCTION "public"."confirm_cash_payment"("p_booking_id" "uuid", "p_shift_id" "uuid", "p_discount_amount" numeric, "p_discount_percentage" numeric, "p_discount_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_future_booking_request"("p_booking_id" "uuid", "p_action" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_shift_id uuid;
  v_action text := lower(btrim(COALESCE(p_action, '')));
  v_deposit_amount numeric := 0;
  v_deposit_required boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF v_action NOT IN ('confirm', 'reject') THEN
    RAISE EXCEPTION 'Invalid action: must be confirm or reject' USING ERRCODE = '22023';
  END IF;

  SELECT b.* INTO v_booking
  FROM public.bookings b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_booking.lounge_id, 'bookings_create')
     AND NOT public.has_lounge_permission(v_booking.lounge_id, 'billing_checkout') THEN
    RAISE EXCEPTION 'Not authorized to moderate booking requests for this lounge' USING ERRCODE = '42501';
  END IF;

  IF v_booking.confirmation_status <> 'pending_confirmation' THEN
    RAISE EXCEPTION 'Booking is already moderated with status: %', v_booking.confirmation_status
      USING ERRCODE = '55000';
  END IF;

  SELECT l.* INTO v_lounge FROM public.lounges l WHERE l.id = v_booking.lounge_id;

  IF v_action = 'confirm' THEN
    -- Verify active shift exists for the lounge
    SELECT s.id INTO v_shift_id
    FROM public.shifts s
    WHERE s.lounge_id = v_booking.lounge_id
      AND s.status = 'open'
      AND s.closed_at IS NULL
    ORDER BY s.opened_at DESC
    LIMIT 1
    FOR SHARE;

    IF v_shift_id IS NULL THEN
      RAISE EXCEPTION 'Cannot confirm request: An open shift is required in the lounge to accept bookings'
        USING ERRCODE = '55000';
    END IF;

    -- Verify slot is still available and not taken
    IF EXISTS (
      SELECT 1 FROM public.bookings b
      WHERE b.room_id = v_booking.room_id
        AND b.id <> v_booking.id
        AND b.confirmation_status = 'confirmed'
        AND b.status IN ('upcoming'::public.booking_status, 'in_progress'::public.booking_status)
        AND b.booking_period && v_booking.booking_period
    ) THEN
      RAISE EXCEPTION 'Room slot conflict: another confirmed booking now occupies this time'
        USING ERRCODE = '55000';
    END IF;

    -- Check if deposit is required
    IF COALESCE(v_lounge.require_deposit_for_future, false) IS TRUE THEN
      v_deposit_required := true;
      v_deposit_amount := ROUND(v_booking.total_price * (COALESCE(v_lounge.future_deposit_percentage, 20) / 100.0), 2);
    END IF;

    UPDATE public.bookings
    SET confirmation_status = 'confirmed',
        status = 'upcoming'::public.booking_status,
        shift_id = v_shift_id,
        approved_at = now(),
        approved_by = auth.uid(),
        deposit_required = v_deposit_required,
        deposit_amount = v_deposit_amount,
        updated_at = now()
    WHERE id = p_booking_id;

    -- Notify customer
    IF v_booking.user_id IS NOT NULL THEN
      INSERT INTO public.notifications (
        user_id, title, title_ar, title_en, body, body_ar, body_en, type, metadata
      ) VALUES (
        v_booking.user_id,
        'Booking Confirmed',
        'تم تأكيد حجزك بنجاح! 🎉',
        'Your booking has been confirmed! 🎉',
        'وافقت الصالة على طلب حجزك للغرفة ' || v_booking.room_name || '. نتمنى لك وقتاً ممتعاً!',
        'وافقت الصالة على طلب حجزك للغرفة ' || v_booking.room_name || '. نتمنى لك وقتاً ممتعاً!',
        'The lounge confirmed your booking request for room ' || v_booking.room_name || '.',
        'booking_confirmed',
        jsonb_build_object(
          'booking_id', p_booking_id,
          'deposit_required', v_deposit_required,
          'deposit_amount', v_deposit_amount
        )
      );
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'booking_id', p_booking_id,
      'confirmation_status', 'confirmed',
      'deposit_required', v_deposit_required,
      'deposit_amount', v_deposit_amount,
      'shift_id', v_shift_id
    );

  ELSE
    -- Reject
    UPDATE public.bookings
    SET confirmation_status = 'rejected_by_lounge',
        status = 'rejected'::public.booking_status,
        cancellation_reason = COALESCE(p_notes, 'اعتذرت الصالة عن قبول الحجز في هذا التوقيت'),
        cancelled_at = now(),
        cancelled_by = auth.uid(),
        updated_at = now()
    WHERE id = p_booking_id;

    IF v_booking.user_id IS NOT NULL THEN
      INSERT INTO public.notifications (
        user_id, title, title_ar, title_en, body, body_ar, body_en, type, metadata
      ) VALUES (
        v_booking.user_id,
        'Booking Request Rejected',
        'عذراً، لم تتمكن الصالة من قبول طلبك',
        'Booking request could not be accepted',
        COALESCE(p_notes, 'اعتذرت الصالة عن قبول الحجز في هذا التوقيت. يمكنك اختيار موعد آخر.'),
        COALESCE(p_notes, 'اعتذرت الصالة عن قبول الحجز في هذا التوقيت. يمكنك اختيار موعد آخر.'),
        'The lounge was unable to accept your request. Please choose an alternative slot.',
        'booking_rejected',
        jsonb_build_object('booking_id', p_booking_id)
      );
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'booking_id', p_booking_id,
      'confirmation_status', 'rejected_by_lounge'
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."confirm_future_booking_request"("p_booking_id" "uuid", "p_action" "text", "p_notes" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."tournament_matches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "round_number" integer NOT NULL,
    "match_order" integer NOT NULL,
    "player1_id" "uuid",
    "player2_id" "uuid",
    "score_player1" integer,
    "score_player2" integer,
    "winner_id" "uuid",
    "room_id" "uuid",
    "station_number" integer,
    "scheduled_at" timestamp with time zone,
    "scheduled_end_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "next_match_id" "uuid",
    "next_match_slot" smallint,
    "status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "proof_image_url" "text",
    "submitted_by" "uuid",
    "result_submitted_at" timestamp with time zone,
    "confirmation_deadline" timestamp with time zone,
    "dispute_reason" "text",
    "disputed_by" "uuid",
    "disputed_at" timestamp with time zone,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "resolution_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "match_not_self_next" CHECK ((("next_match_id" IS NULL) OR ("next_match_id" <> "id"))),
    CONSTRAINT "match_players_distinct" CHECK ((("player1_id" IS NULL) OR ("player2_id" IS NULL) OR ("player1_id" <> "player2_id"))),
    CONSTRAINT "match_time_check" CHECK ((("scheduled_end_at" IS NULL) OR ("scheduled_at" IS NULL) OR ("scheduled_end_at" > "scheduled_at"))),
    CONSTRAINT "tournament_matches_match_order_check" CHECK (("match_order" > 0)),
    CONSTRAINT "tournament_matches_next_match_slot_check" CHECK ((("next_match_slot" IS NULL) OR ("next_match_slot" = ANY (ARRAY[1, 2])))),
    CONSTRAINT "tournament_matches_round_number_check" CHECK (("round_number" > 0)),
    CONSTRAINT "tournament_matches_score_player1_check" CHECK ((("score_player1" IS NULL) OR ("score_player1" >= 0))),
    CONSTRAINT "tournament_matches_score_player2_check" CHECK ((("score_player2" IS NULL) OR ("score_player2" >= 0))),
    CONSTRAINT "tournament_matches_station_number_check" CHECK ((("station_number" IS NULL) OR ("station_number" > 0))),
    CONSTRAINT "tournament_matches_status_check" CHECK (("status" = ANY (ARRAY['scheduled'::"text", 'in_progress'::"text", 'pending_confirmation'::"text", 'disputed'::"text", 'completed'::"text", 'cancelled'::"text", 'walkover'::"text", 'no_show'::"text"])))
);


ALTER TABLE "public"."tournament_matches" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_match_result"("p_match_id" "uuid") RETURNS "public"."tournament_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_match public.tournament_matches%ROWTYPE;
  v_next public.tournament_matches%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
  v_winner uuid;
  v_slot smallint;
  v_is_manager boolean := false;
  v_is_participant boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT *
  INTO v_match
  FROM public.tournament_matches
  WHERE id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'match_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_tournament
  FROM public.tournaments
  WHERE id = v_match.tournament_id
  FOR UPDATE;

  v_is_manager :=
    public.is_super_admin()
    OR private.is_lounge_manager(v_tournament.lounge_id);

  SELECT EXISTS (
    SELECT 1
    FROM public.tournament_participants AS p
    WHERE p.user_id = auth.uid()
      AND p.id IN (v_match.player1_id, v_match.player2_id)
  )
  INTO v_is_participant;

  IF NOT v_is_manager AND NOT v_is_participant THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_manager
     AND v_match.submitted_by IS NOT NULL
     AND v_match.submitted_by = auth.uid() THEN
    RAISE EXCEPTION 'result_submitter_cannot_self_confirm'
      USING ERRCODE = '42501';
  END IF;

  IF v_match.status <> 'pending_confirmation'
     OR v_match.score_player1 IS NULL
     OR v_match.score_player2 IS NULL
     OR v_match.score_player1 = v_match.score_player2 THEN
    RAISE EXCEPTION 'result_not_pending' USING ERRCODE = '55000';
  END IF;

  v_winner := CASE
    WHEN v_match.score_player1 > v_match.score_player2
      THEN v_match.player1_id
    ELSE v_match.player2_id
  END;

  UPDATE public.tournament_matches
  SET winner_id = v_winner,
      status = 'completed',
      completed_at = now(),
      updated_at = now()
  WHERE id = v_match.id
  RETURNING *
  INTO v_match;

  IF v_match.next_match_id IS NOT NULL THEN
    SELECT *
    INTO v_next
    FROM public.tournament_matches
    WHERE id = v_match.next_match_id
    FOR UPDATE;

    v_slot := v_match.next_match_slot;

    IF v_slot = 1 THEN
      UPDATE public.tournament_matches
      SET player1_id = v_winner,
          updated_at = now()
      WHERE id = v_next.id
        AND player1_id IS NULL;
    ELSE
      UPDATE public.tournament_matches
      SET player2_id = v_winner,
          updated_at = now()
      WHERE id = v_next.id
        AND player2_id IS NULL;
    END IF;
  END IF;

  PERFORM public.tournament_audit(
    v_tournament.id,
    'match_result_confirmed',
    v_winner,
    v_match.id,
    NULL,
    to_jsonb(v_match)
  );

  RETURN v_match;
END;
$$;


ALTER FUNCTION "public"."confirm_match_result"("p_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_voucher"("p_voucher_id" "uuid", "p_booking_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update user_vouchers
  set status = 'used', used_at = now(), used_booking_id = p_booking_id
  where id = p_voucher_id and user_id = auth.uid() and status = 'active' and expires_at >= now();

  if not found then
    raise exception 'Voucher invalid or already used';
  end if;
end;
$$;


ALTER FUNCTION "public"."consume_voucher"("p_voucher_id" "uuid", "p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_voucher_by_code"("p_code" "text", "p_booking_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthenticated user';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.bookings b WHERE b.id = p_booking_id AND b.user_id = v_user_id) THEN
    RAISE EXCEPTION 'Voucher booking mismatch' USING ERRCODE = '42501';
  END IF;

  UPDATE public.user_vouchers
  SET status = 'used',
      used_at = NOW(),
      used_booking_id = p_booking_id
  WHERE UPPER(TRIM(code)) = UPPER(TRIM(p_code))
    AND user_id = v_user_id
    AND status = 'active'
    AND (expires_at IS NULL OR expires_at >= NOW());

  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."consume_voucher_by_code"("p_code" "text", "p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_lounge_admin"("p_lounge_id" "uuid", "p_email" "text", "p_password" "text", "p_full_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
    new_user_id uuid;
BEGIN
    SELECT id INTO new_user_id FROM auth.users WHERE email = p_email;
    IF new_user_id IS NULL THEN
        new_user_id := gen_random_uuid();
        INSERT INTO auth.users (
            id, instance_id, email, encrypted_password, email_confirmed_at,
            raw_user_meta_data, role, aud, created_at, updated_at
        ) VALUES (
            new_user_id, '00000000-0000-0000-0000-000000000000', p_email,
            extensions.crypt(p_password, extensions.gen_salt('bf')), NOW(),
            jsonb_build_object('full_name', p_full_name),
            'authenticated', 'authenticated', NOW(), NOW()
        );
    END IF;

    INSERT INTO public.profiles (
        id, email, full_name, role, lounge_id, is_active, is_setup_completed
    ) VALUES (
        new_user_id, p_email, p_full_name, 'lounge_admin', p_lounge_id, true, true
    )
    ON CONFLICT (id) DO UPDATE SET
        lounge_id = p_lounge_id,
        role = 'lounge_admin',
        full_name = EXCLUDED.full_name;

    RETURN jsonb_build_object('user_id', new_user_id, 'success', true);
END;
$$;


ALTER FUNCTION "public"."create_lounge_admin"("p_lounge_id" "uuid", "p_email" "text", "p_password" "text", "p_full_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_lounge_staff"("p_email" "text", "p_password" "text", "p_full_name" "text", "p_lounge_id" "uuid", "p_role" "text" DEFAULT 'cashier'::"text", "p_phone" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  new_user_id uuid;
  encrypted_pw text;
  v_staff_role text;
  v_actor_role text;
  v_clean_email text := lower(btrim(p_email));
  v_clean_phone text := btrim(COALESCE(p_phone, ''));
  v_clean_name text := btrim(COALESCE(p_full_name, 'Staff Member'));
  v_requested_role text := lower(btrim(COALESCE(p_role, 'cashier')));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Lounge ID is required' USING ERRCODE = '22023';
  END IF;

  v_actor_role := private.permission_role(auth.uid(), p_lounge_id);

  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role NOT IN ('super_admin', 'owner', 'manager') THEN
    RAISE EXCEPTION 'Only lounge administrators can manage staff'
      USING ERRCODE = '42501';
  END IF;

  IF v_actor_role <> 'super_admin'
     AND NOT public.has_lounge_permission(p_lounge_id, 'staff_manage') THEN
    RAISE EXCEPTION 'Missing staff_manage permission'
      USING ERRCODE = '42501';
  END IF;

  IF v_requested_role IN ('owner', 'lounge_owner', 'super_admin', 'superadmin') THEN
    RAISE EXCEPTION 'Owner accounts cannot be created through staff management'
      USING ERRCODE = '42501';
  END IF;

  v_staff_role := CASE
    WHEN v_requested_role IN ('manager', 'admin', 'lounge_admin') THEN 'manager'
    WHEN v_requested_role = 'staff' THEN 'staff'
    ELSE 'cashier'
  END;

  IF v_actor_role = 'manager' AND v_staff_role = 'manager' THEN
    RAISE EXCEPTION 'Managers cannot create or promote peer managers'
      USING ERRCODE = '42501';
  END IF;

  IF v_clean_email = ''
     OR p_password IS NULL
     OR length(p_password) < 6 THEN
    RAISE EXCEPTION 'Valid email and password (min 6 characters) are required'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM auth.users
    WHERE lower(email) = v_clean_email
  ) THEN
    RAISE EXCEPTION 'Email already registered'
      USING ERRCODE = '23505';
  END IF;

  new_user_id := gen_random_uuid();
  encrypted_pw := crypt(p_password, gen_salt('bf'));

  INSERT INTO auth.users (
    instance_id,
    id,
    aud,
    role,
    email,
    encrypted_password,
    email_confirmed_at,
    raw_app_meta_data,
    raw_user_meta_data,
    created_at,
    updated_at
  )
  VALUES (
    '00000000-0000-0000-0000-000000000000',
    new_user_id,
    'authenticated',
    'authenticated',
    v_clean_email,
    encrypted_pw,
    now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object(
      'full_name', v_clean_name,
      'name', v_clean_name,
      'role', v_staff_role
    ),
    now(),
    now()
  );

  INSERT INTO auth.identities (
    id,
    user_id,
    identity_data,
    provider,
    provider_id,
    last_sign_in_at,
    created_at,
    updated_at
  )
  VALUES (
    gen_random_uuid(),
    new_user_id,
    jsonb_build_object(
      'sub', new_user_id::text,
      'email', v_clean_email
    ),
    'email',
    v_clean_email,
    now(),
    now(),
    now()
  );

  INSERT INTO public.profiles (
    id,
    email,
    full_name,
    phone,
    role,
    lounge_id,
    is_active,
    updated_at
  )
  VALUES (
    new_user_id,
    v_clean_email,
    v_clean_name,
    v_clean_phone,
    v_staff_role,
    p_lounge_id,
    true,
    now()
  )
  ON CONFLICT (id)
  DO UPDATE SET
    email = EXCLUDED.email,
    full_name = EXCLUDED.full_name,
    phone = EXCLUDED.phone,
    role = EXCLUDED.role,
    lounge_id = EXCLUDED.lounge_id,
    is_active = true,
    updated_at = now();

  INSERT INTO public.lounge_staff (
    lounge_id,
    user_id,
    role
  )
  VALUES (
    p_lounge_id,
    new_user_id,
    v_staff_role
  )
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', new_user_id,
    'role', v_staff_role
  );
END;
$$;


ALTER FUNCTION "public"."create_lounge_staff"("p_email" "text", "p_password" "text", "p_full_name" "text", "p_lounge_id" "uuid", "p_role" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_lounge_with_admin"("p_lounge_name" "text", "p_owner_email" "text", "p_owner_password" "text", "p_owner_name" "text", "p_banner_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
    new_user_id uuid;
    new_lounge_id uuid;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid() AND role = 'super_admin'
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Super Admin access required.';
    END IF;

    SELECT id INTO new_user_id FROM auth.users WHERE email = p_owner_email;
    IF new_user_id IS NULL THEN
        new_user_id := gen_random_uuid();
        INSERT INTO auth.users (
            id, instance_id, email, encrypted_password, email_confirmed_at,
            raw_user_meta_data, role, aud, created_at, updated_at
        ) VALUES (
            new_user_id, '00000000-0000-0000-0000-000000000000', p_owner_email,
            extensions.crypt(p_owner_password, extensions.gen_salt('bf')), NOW(),
            jsonb_build_object('full_name', p_owner_name),
            'authenticated', 'authenticated', NOW(), NOW()
        );
    END IF;

    INSERT INTO lounges (
        name, image_url, owner_id, is_active
    ) VALUES (
        p_lounge_name, p_banner_url, new_user_id, true
    ) RETURNING id INTO new_lounge_id;

    INSERT INTO public.profiles (
        id, email, full_name, role, lounge_id, is_active
    ) VALUES (
        new_user_id, p_owner_email, p_owner_name, 'lounge_owner', new_lounge_id, true
    )
    ON CONFLICT (id) DO UPDATE SET
        lounge_id = new_lounge_id,
        role = 'lounge_owner',
        full_name = EXCLUDED.full_name;

    RETURN jsonb_build_object(
        'lounge_id', new_lounge_id,
        'owner_id', new_user_id,
        'success', true
    );
END;
$$;


ALTER FUNCTION "public"."create_lounge_with_admin"("p_lounge_name" "text", "p_owner_email" "text", "p_owner_password" "text", "p_owner_name" "text", "p_banner_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_lounge_with_owner"("p_owner_email" "text", "p_owner_password" "text", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  v_user_id uuid;
  v_lounge_id uuid;
  v_encrypted_pw text;
BEGIN
  SELECT id INTO v_user_id
  FROM public.profiles
  WHERE lower(email) = lower(p_owner_email)
  LIMIT 1;

  IF v_user_id IS NULL THEN
    SELECT id INTO v_user_id
    FROM auth.users
    WHERE lower(email) = lower(p_owner_email)
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    v_user_id := gen_random_uuid();
    v_encrypted_pw := crypt(p_owner_password, gen_salt('bf'));

    INSERT INTO auth.users (
      id, instance_id, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      role, aud
    ) VALUES (
      v_user_id,
      '00000000-0000-0000-0000-000000000000',
      lower(p_owner_email),
      v_encrypted_pw,
      now(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      jsonb_build_object('full_name', p_owner_name, 'role', 'owner'),
      now(), now(), 'authenticated', 'authenticated'
    );
  END IF;

  INSERT INTO public.profiles (
    id, email, full_name, role, is_active, is_setup_completed, phone
  ) VALUES (
    v_user_id, lower(p_owner_email), p_owner_name,
    'owner', false, false, p_phone
  )
  ON CONFLICT (id) DO UPDATE
  SET email = EXCLUDED.email,
      full_name = EXCLUDED.full_name,
      role = 'owner',
      is_active = false,
      is_setup_completed = false,
      phone = COALESCE(EXCLUDED.phone, public.profiles.phone),
      updated_at = now();

  INSERT INTO public.lounges (
    name, city, location, owner_id, status, is_open, is_active
  ) VALUES (
    p_lounge_name, p_city, p_address, v_user_id,
    'pending', false, false
  )
  RETURNING id INTO v_lounge_id;

  UPDATE public.profiles
  SET lounge_id = v_lounge_id,
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'lounge_id', v_lounge_id,
    'owner_id', v_user_id,
    'status', 'pending',
    'success', true
  );
END;
$$;


ALTER FUNCTION "public"."create_lounge_with_owner"("p_owner_email" "text", "p_owner_password" "text", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text", "p_address" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_manual_booking_admin"("p_lounge_id" "uuid", "p_room_id" "uuid", "p_booking_date" "date", "p_start_time" time without time zone, "p_duration_minutes" integer, "p_customer_name" "text" DEFAULT NULL::"text", "p_customer_phone" "text" DEFAULT NULL::"text", "p_play_mode" "text" DEFAULT 'single'::"text", "p_extra_items" "jsonb" DEFAULT '[]'::"jsonb", "p_start_immediately" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
  v_booking public.bookings%ROWTYPE;
  v_booking_id uuid;
  v_shift_id uuid;
  v_end_ts timestamp;
  v_item jsonb;
  v_extra public.extras%ROWTYPE;
  v_extra_id uuid;
  v_quantity integer;
  v_line_total numeric;
  v_addons_total numeric := 0;
  v_payment jsonb;
  v_session jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE = '28000';
  END IF;

  IF p_lounge_id IS NULL OR p_room_id IS NULL
     OR p_booking_date IS NULL OR p_start_time IS NULL THEN
    RAISE EXCEPTION 'BOOKING_FIELDS_REQUIRED' USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(p_lounge_id, 'bookings_create') THEN
    RAISE EXCEPTION 'BOOKING_CREATE_PERMISSION_REQUIRED' USING ERRCODE = '42501';
  END IF;

  IF p_duration_minutes IS NULL
     OR p_duration_minutes < 1
     OR p_duration_minutes > 1440 THEN
    RAISE EXCEPTION 'INVALID_BOOKING_DURATION' USING ERRCODE = '22023';
  END IF;

  IF p_extra_items IS NULL OR jsonb_typeof(p_extra_items) <> 'array'
     OR jsonb_array_length(p_extra_items) > 50 THEN
    RAISE EXCEPTION 'EXTRA_ITEMS_MUST_BE_ARRAY' USING ERRCODE = '22023';
  END IF;

  SELECT r.*
  INTO v_room
  FROM public.rooms AS r
  WHERE r.id = p_room_id
    AND r.lounge_id = p_lounge_id
    AND COALESCE(r.is_active, true) IS TRUE
    AND COALESCE(r.status, 'available') NOT IN ('maintenance', 'deleted')
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ROOM_NOT_BOOKABLE' USING ERRCODE = '55000';
  END IF;

  SELECT s.id
  INTO v_shift_id
  FROM public.shifts AS s
  WHERE s.lounge_id = p_lounge_id
    AND s.status = 'open'
    AND s.closed_at IS NULL
  ORDER BY s.opened_at DESC
  LIMIT 1
  FOR SHARE;

  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION 'NO_OPEN_SHIFT' USING ERRCODE = '55000';
  END IF;

  v_end_ts :=
    (p_booking_date + p_start_time)::timestamp
    + make_interval(mins => p_duration_minutes);

  INSERT INTO public.bookings (
    user_id,
    lounge_id,
    room_id,
    date,
    start_time,
    end_time,
    duration_minutes,
    status,
    payment_status,
    payment_method,
    user_name,
    user_phone,
    room_name,
    shift_id,
    play_mode,
    addons_price,
    addons_total
  )
  VALUES (
    NULL,
    p_lounge_id,
    p_room_id,
    p_booking_date,
    p_start_time,
    v_end_ts::time,
    p_duration_minutes,
    'pending'::public.booking_status,
    'unpaid',
    'cash',
    COALESCE(NULLIF(btrim(p_customer_name), ''), 'Walk-in Customer'),
    NULLIF(btrim(p_customer_phone), ''),
    COALESCE(v_room.name_ar, v_room.name_en, v_room.name),
    v_shift_id,
    COALESCE(NULLIF(btrim(lower(p_play_mode)), ''), 'single'),
    0,
    0
  )
  RETURNING *
  INTO v_booking;

  v_booking_id := v_booking.id;

  FOR v_item IN
    SELECT item.value
    FROM jsonb_array_elements(p_extra_items) AS item(value)
  LOOP
    IF jsonb_typeof(v_item) <> 'object'
       OR NULLIF(v_item->>'extra_id', '') IS NULL THEN
      RAISE EXCEPTION 'INVALID_EXTRA_ITEM' USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_extra_id := (v_item->>'extra_id')::uuid;
      v_quantity := COALESCE((v_item->>'quantity')::integer, 1);
    EXCEPTION
      WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RAISE EXCEPTION 'INVALID_EXTRA_ITEM' USING ERRCODE = '22023';
    END;

    IF v_quantity < 1 OR v_quantity > 100 THEN
      RAISE EXCEPTION 'INVALID_EXTRA_QUANTITY' USING ERRCODE = '22023';
    END IF;

    SELECT e.*
    INTO v_extra
    FROM public.extras AS e
    WHERE e.id = v_extra_id
      AND e.lounge_id = p_lounge_id
      AND COALESCE(e.is_active, true) IS TRUE
      AND COALESCE(e.is_available, true) IS TRUE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'EXTRA_NOT_AVAILABLE: %', v_extra_id
        USING ERRCODE = '23514';
    END IF;

    IF v_extra.price IS NULL OR v_extra.price < 0 THEN
      RAISE EXCEPTION 'INVALID_EXTRA_PRICE' USING ERRCODE = '23514';
    END IF;

    v_line_total := round(v_extra.price * v_quantity, 2);
    v_addons_total := v_addons_total + v_line_total;

    INSERT INTO public.booking_items (
      booking_id,
      product_id,
      extra_id,
      quantity,
      unit_price,
      total_price,
      price,
      name,
      status
    )
    VALUES (
      v_booking_id,
      v_extra.id,
      v_extra.id,
      v_quantity,
      v_extra.price,
      v_line_total,
      v_extra.price,
      COALESCE(v_extra.name_ar, v_extra.name_en, v_extra.name),
      'pending'
    );
  END LOOP;

  IF v_addons_total > 0 THEN
    UPDATE public.bookings AS b
    SET addons_price = v_addons_total,
        addons_total = v_addons_total,
        updated_at = now()
    WHERE b.id = v_booking_id
    RETURNING *
    INTO v_booking;
  END IF;

  IF p_start_immediately THEN
    v_payment := public.complete_booking_payment(
      v_booking_id,
      'cash',
      NULL
    );

    IF COALESCE((v_payment->>'success')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'BOOKING_PAYMENT_NOT_CONFIRMED' USING ERRCODE = '55000';
    END IF;

    v_session := public.start_booking_session(v_booking_id);

    IF COALESCE((v_session->>'success')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'BOOKING_SESSION_NOT_STARTED' USING ERRCODE = '55000';
    END IF;
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = v_booking_id;

  RETURN jsonb_build_object(
    'success', true,
    'booking', to_jsonb(v_booking),
    'booking_id', v_booking_id,
    'addons_total', COALESCE(v_booking.addons_price, 0),
    'started', p_start_immediately
  );
END;
$$;


ALTER FUNCTION "public"."create_manual_booking_admin"("p_lounge_id" "uuid", "p_room_id" "uuid", "p_booking_date" "date", "p_start_time" time without time zone, "p_duration_minutes" integer, "p_customer_name" "text", "p_customer_phone" "text", "p_play_mode" "text", "p_extra_items" "jsonb", "p_start_immediately" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_my_booking_checkout"("p_hold_token" "uuid", "p_room_requests" "jsonb", "p_extra_items" "jsonb" DEFAULT '[]'::"jsonb", "p_voucher_code" "text" DEFAULT NULL::"text", "p_payment_method" "text" DEFAULT 'cash'::"text", "p_sender_wallet_phone" "text" DEFAULT NULL::"text", "p_receipt_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_quote jsonb;
  v_lounge_id uuid;
  v_start_at timestamp without time zone;
  v_end_at timestamp without time zone;
  v_duration_minutes integer;
  v_room jsonb;
  v_room_id uuid;
  v_room_name text;
  v_play_mode text;
  v_extra_controllers integer;
  v_room_price numeric;
  v_promo_discount numeric;
  v_voucher_discount numeric := 0;
  v_discount_amount numeric;
  v_discount_percentage numeric;
  v_discount_label text;
  v_primary boolean := true;
  v_booking_id uuid;
  v_primary_booking_id uuid;
  v_booking_ids jsonb := '[]'::jsonb;
  v_user_name text;
  v_user_phone text;
  v_clean_payment_method text := lower(btrim(COALESCE(p_payment_method, '')));
  v_clean_sender text := NULLIF(btrim(p_sender_wallet_phone), '');
  v_clean_receipt text := NULLIF(btrim(p_receipt_url), '');
  v_canteen_items jsonb := '[]'::jsonb;
  v_remaining_voucher numeric;
  v_voucher_share numeric;
  v_booking public.bookings%ROWTYPE;
  v_persisted_total numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM private.require_active_booking_actor();

  IF v_clean_payment_method NOT IN ('cash', 'manual_transfer') THEN
    RAISE EXCEPTION 'Invalid payment method' USING ERRCODE = '22023';
  END IF;

  IF v_clean_payment_method = 'manual_transfer'
     AND v_clean_sender IS NULL THEN
    RAISE EXCEPTION 'sender_wallet_phone is required for manual_transfer'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.booking_holds h
  WHERE h.hold_token = p_hold_token
    AND h.user_id = v_user_id
    AND h.released_at IS NULL
    AND h.expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BOOKING_HOLD_EXPIRED' USING ERRCODE = '55000';
  END IF;

  v_quote := private.build_my_booking_checkout_quote(
    v_user_id,
    p_hold_token,
    p_room_requests,
    p_extra_items,
    p_voucher_code
  );

  v_lounge_id := (v_quote->>'lounge_id')::uuid;
  v_start_at := (v_quote->>'start_at')::timestamp;
  v_end_at := (v_quote->>'end_at')::timestamp;
  v_duration_minutes := (v_quote->>'duration_minutes')::integer;
  v_voucher_discount := COALESCE(
    (v_quote->>'voucher_discount')::numeric,
    0
  );

  SELECT
    p.full_name,
    p.phone
  INTO
    v_user_name,
    v_user_phone
  FROM public.profiles p
  WHERE p.id = v_user_id;

  FOR v_room IN
    SELECT r.value
    FROM jsonb_array_elements(v_quote->'rooms') WITH ORDINALITY r(value, ord)
    ORDER BY r.ord
  LOOP
    v_room_id := (v_room->>'room_id')::uuid;
    v_room_name := COALESCE(
      NULLIF(v_room->>'room_name_en', ''),
      NULLIF(v_room->>'room_name_ar', ''),
      ''
    );
    v_play_mode := v_room->>'play_mode';
    v_extra_controllers := COALESCE(
      (v_room->>'extra_controllers')::integer,
      0
    );
    v_room_price := COALESCE(
      (v_room->>'original_subtotal')::numeric,
      0
    );
    v_promo_discount := COALESCE(
      (v_room->>'promo_discount_amount')::numeric,
      0
    );

    v_discount_amount :=
      v_promo_discount;

    v_discount_percentage := CASE
      WHEN lower(COALESCE(v_room->>'discount_type', '')) = 'percentage'
      THEN COALESCE((v_room->>'discount_value')::numeric, 0)
      ELSE 0
    END;

    v_discount_label := NULLIF(v_room->>'discount_label', '');

    INSERT INTO public.bookings (
      user_id,
      room_id,
      lounge_id,
      date,
      start_time,
      end_time,
      room_price,
      addons_price,
      addons_total,
      total_price,
      status,
      user_name,
      user_phone,
      room_name,
      duration_minutes,
      play_mode,
      extra_controllers,
      payment_status,
      payment_method,
      discount_amount,
      discount_percentage,
      discount_reason,
      receipt_url,
      sender_wallet_phone
    )
    VALUES (
      v_user_id,
      v_room_id,
      v_lounge_id,
      v_start_at::date,
      v_start_at::time,
      v_end_at::time,
      v_room_price,
      0,
      0,
      GREATEST(0, v_room_price - v_discount_amount),
      'pending'::public.booking_status,
      v_user_name,
      v_user_phone,
      v_room_name,
      v_duration_minutes,
      v_play_mode,
      v_extra_controllers,
      'unpaid',
      v_clean_payment_method,
      v_discount_amount,
      v_discount_percentage,
      v_discount_label,
      v_clean_receipt,
      CASE
        WHEN v_clean_payment_method = 'manual_transfer'
        THEN v_clean_sender
        ELSE NULL
      END
    )
    RETURNING id INTO v_booking_id;

    IF v_primary THEN
      v_primary_booking_id := v_booking_id;
    END IF;

    v_booking_ids :=
      v_booking_ids || jsonb_build_array(v_booking_id);

    v_primary := false;
  END LOOP;

  IF jsonb_array_length(COALESCE(v_quote->'extras', '[]'::jsonb)) > 0 THEN
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'extra_id', item.value->>'extra_id',
          'quantity', (item.value->>'quantity')::integer
        )
      ),
      '[]'::jsonb
    )
    INTO v_canteen_items
    FROM jsonb_array_elements(v_quote->'extras') item(value);

    PERFORM public.place_canteen_order(
      v_primary_booking_id,
      v_canteen_items,
      NULL
    );
  END IF;

  -- Extras are attached before allocating the voucher, so a fixed voucher can
  -- cover their price and spill across rooms without the row clamp losing it.
  v_remaining_voucher := v_voucher_discount;
  FOR v_booking IN
    SELECT b.* FROM jsonb_array_elements_text(v_booking_ids)
      WITH ORDINALITY ids(id, ord)
    JOIN public.bookings b ON b.id = ids.id::uuid
    ORDER BY ids.ord
    FOR UPDATE OF b
  LOOP
    v_voucher_share := LEAST(v_remaining_voucher, v_booking.total_price);
    IF v_voucher_share > 0 THEN
      UPDATE public.bookings
      SET discount_amount = COALESCE(v_booking.discount_amount, 0) + v_voucher_share,
          discount_reason = concat_ws(' + ', NULLIF(v_booking.discount_reason, ''), 'voucher'),
          applied_voucher_code = upper(btrim(p_voucher_code)),
          updated_at = now()
      WHERE id = v_booking.id;
      v_remaining_voucher := v_remaining_voucher - v_voucher_share;
    END IF;
  END LOOP;

  SELECT COALESCE(sum(b.total_price), 0)
  INTO v_persisted_total
  FROM public.bookings b
  WHERE b.id IN (SELECT value::uuid FROM jsonb_array_elements_text(v_booking_ids));
  IF v_remaining_voucher <> 0
     OR v_persisted_total IS DISTINCT FROM (v_quote->>'final_total')::numeric THEN
    RAISE EXCEPTION 'CHECKOUT_PRICE_CHANGED' USING ERRCODE = '40001';
  END IF;

  IF NULLIF(btrim(p_voucher_code), '') IS NOT NULL THEN
    IF NOT public.consume_voucher_by_code(
      p_voucher_code,
      v_primary_booking_id
    ) THEN
      RAISE EXCEPTION 'VOUCHER_CONSUMPTION_FAILED'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  UPDATE public.booking_holds
  SET released_at = now()
  WHERE hold_token = p_hold_token
    AND user_id = v_user_id
    AND released_at IS NULL;

  RETURN jsonb_build_object(
    'success', true,
    'primary_booking_id', v_primary_booking_id,
    'booking_ids', v_booking_ids,
    'quote', v_quote
  );
END;
$$;


ALTER FUNCTION "public"."create_my_booking_checkout"("p_hold_token" "uuid", "p_room_requests" "jsonb", "p_extra_items" "jsonb", "p_voucher_code" "text", "p_payment_method" "text", "p_sender_wallet_phone" "text", "p_receipt_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payout"("p_lounge_id" "uuid", "p_period_start" "date", "p_period_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payout_id uuid;
  v_total numeric;
  v_count integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_start > p_period_end THEN
    RAISE EXCEPTION 'Invalid payout period';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_lounge_id::text, 0));

  IF EXISTS (
    SELECT 1 FROM public.payouts
    WHERE lounge_id = p_lounge_id
      AND status IN ('pending','approved','processing','paid')
      AND daterange(period_start, period_end, '[]') && daterange(p_period_start, p_period_end, '[]')
  ) THEN
    RAISE EXCEPTION 'Overlapping active payout exists for this lounge and period';
  END IF;

  -- Strictly aggregate platform-held non-cash payments
  SELECT COUNT(*), COALESCE(SUM(COALESCE(net_to_lounge, amount - COALESCE(commission, 0))), 0)
  INTO v_count, v_total
  FROM public.payments
  WHERE lounge_id = p_lounge_id
    AND status = 'completed'
    AND payout_id IS NULL
    AND payment_method NOT IN ('cash')
    AND paid_at::date BETWEEN p_period_start AND p_period_end;

  IF v_count = 0 OR v_total <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'لا يوجد مبلغ مستحق في الفترة دي للدفعات الإلكترونية');
  END IF;

  INSERT INTO public.payouts (lounge_id, period_start, period_end, total_amount, status, created_by)
  VALUES (p_lounge_id, p_period_start, p_period_end, v_total, 'pending', auth.uid())
  RETURNING id INTO v_payout_id;

  UPDATE public.payments
  SET payout_id = v_payout_id
  WHERE lounge_id = p_lounge_id
    AND status = 'completed'
    AND payout_id IS NULL
    AND payment_method NOT IN ('cash')
    AND paid_at::date BETWEEN p_period_start AND p_period_end;

  RETURN jsonb_build_object('success', true, 'payout_id', v_payout_id, 'amount', v_total, 'payment_count', v_count);
END;
$$;


ALTER FUNCTION "public"."create_payout"("p_lounge_id" "uuid", "p_period_start" "date", "p_period_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_promotion"("p_lounge_id" "uuid", "p_room_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_tag_ar" "text", "p_tag_en" "text", "p_discount_type" "text", "p_discount_value" numeric, "p_expires_at" timestamp with time zone, "p_colors" "text"[], "p_icon_key" "text", "p_image_url" "text" DEFAULT NULL::"text", "p_deep_link" "text" DEFAULT NULL::"text", "p_target_audience" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid;
  v_type text := lower(btrim(COALESCE(p_discount_type, 'percentage')));
  v_value numeric := COALESCE(p_discount_value, 0);
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF NOT private.can_manage_promotion(p_lounge_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_type NOT IN ('percentage','fixed') THEN
    RAISE EXCEPTION 'Unsupported discount type' USING ERRCODE='22023';
  END IF;

  IF v_value < 0 OR (v_type='percentage' AND v_value > 100) THEN
    RAISE EXCEPTION 'Invalid discount value' USING ERRCODE='22023';
  END IF;

  IF p_room_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.rooms r
    WHERE r.id=p_room_id AND r.lounge_id=p_lounge_id
  ) THEN
    RAISE EXCEPTION 'Room does not belong to lounge' USING ERRCODE='22023';
  END IF;

  IF p_colors IS NULL OR array_length(p_colors,1) < 2 THEN
    RAISE EXCEPTION 'At least two colors are required' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.promotions(
    lounge_id, room_id, title, title_ar, title_en,
    tag, tag_ar, tag_en, colors, icon_key, image_url, deep_link,
    expires_at, is_room_specific, target_audience,
    discount_type, discount_value, is_active
  )
  VALUES(
    p_lounge_id,
    p_room_id,
    COALESCE(NULLIF(btrim(p_title_ar),''), NULLIF(btrim(p_title_en),''), 'Offer'),
    p_title_ar,
    p_title_en,
    COALESCE(NULLIF(btrim(p_tag_ar),''), NULLIF(btrim(p_tag_en),'')),
    p_tag_ar,
    p_tag_en,
    p_colors,
    COALESCE(NULLIF(btrim(p_icon_key),''),'local_offer'),
    p_image_url,
    p_deep_link,
    p_expires_at,
    p_room_id IS NOT NULL,
    COALESCE(NULLIF(btrim(p_target_audience),''),'all'),
    v_type,
    v_value,
    true
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success',true,
    'promo_id',v_id,
    'discount_type',v_type,
    'discount_value',v_value
  );
END;
$$;


ALTER FUNCTION "public"."create_promotion"("p_lounge_id" "uuid", "p_room_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_tag_ar" "text", "p_tag_en" "text", "p_discount_type" "text", "p_discount_value" numeric, "p_expires_at" timestamp with time zone, "p_colors" "text"[], "p_icon_key" "text", "p_image_url" "text", "p_deep_link" "text", "p_target_audience" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."support_tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "user_name" "text",
    "user_phone" "text",
    "issue_type" "text" NOT NULL,
    "message" "text" NOT NULL,
    "status" "text" DEFAULT 'new'::"text" NOT NULL,
    "admin_notes" "text",
    "assigned_to" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    CONSTRAINT "support_tickets_issue_type_check" CHECK ((("length"("btrim"("issue_type")) >= 1) AND ("length"("btrim"("issue_type")) <= 100))),
    CONSTRAINT "support_tickets_message_check" CHECK ((("length"("btrim"("message")) >= 1) AND ("length"("btrim"("message")) <= 5000))),
    CONSTRAINT "support_tickets_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'in_progress'::"text", 'resolved'::"text"])))
);


ALTER TABLE "public"."support_tickets" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_support_ticket"("p_issue_type" "text", "p_message" "text") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_ticket public.support_tickets;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING errcode = '28000';
  END IF;

  INSERT INTO public.support_tickets (user_id, user_name, user_phone, issue_type, message)
  SELECT v_user_id, p.full_name, p.phone, btrim(p_issue_type), btrim(p_message)
  FROM public.profiles p
  WHERE p.id = v_user_id
  RETURNING * INTO v_ticket;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;

  RETURN v_ticket;
END;
$$;


ALTER FUNCTION "public"."create_support_ticket"("p_issue_type" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_system_announcement"("p_id" "uuid", "p_target_audience" "text", "p_target_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text" DEFAULT 'info'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid := COALESCE(p_id, gen_random_uuid());
  v_db_audience public.announcement_target_audience;
  v_db_type public.announcement_type;
  v_count integer := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  v_db_audience := CASE lower(btrim(COALESCE(p_target_audience, 'all')))
    WHEN 'all' THEN 'all'::public.announcement_target_audience
    WHEN 'owners' THEN 'owners'::public.announcement_target_audience
    WHEN 'lounge_owners' THEN 'owners'::public.announcement_target_audience
    WHEN 'specific_venue' THEN 'specific_venue'::public.announcement_target_audience
    WHEN 'specific_lounge' THEN 'specific_venue'::public.announcement_target_audience
    ELSE NULL
  END;

  IF v_db_audience IS NULL THEN
    RAISE EXCEPTION 'invalid_target_audience' USING ERRCODE = '22023';
  END IF;

  v_db_type := CASE lower(btrim(COALESCE(p_type, 'info')))
    WHEN 'info' THEN 'info'::public.announcement_type
    WHEN 'warning' THEN 'warning'::public.announcement_type
    WHEN 'update' THEN 'update'::public.announcement_type
    ELSE NULL
  END;

  IF v_db_type IS NULL THEN
    RAISE EXCEPTION 'invalid_announcement_type' USING ERRCODE = '22023';
  END IF;

  IF v_db_audience = 'specific_venue'::public.announcement_target_audience
     AND (
       p_target_lounge_id IS NULL
       OR NOT EXISTS (
         SELECT 1 FROM public.lounges l
         WHERE l.id = p_target_lounge_id
       )
     ) THEN
    RAISE EXCEPTION 'target_lounge_required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.announcements (
    id,
    title_ar,
    title_en,
    body_ar,
    body_en,
    target_audience,
    target_venue_id,
    type,
    is_active,
    start_at,
    created_by,
    created_at
  )
  VALUES (
    v_id,
    btrim(p_title_ar),
    btrim(p_title_en),
    btrim(p_body_ar),
    btrim(p_body_en),
    v_db_audience,
    CASE
      WHEN v_db_audience = 'specific_venue'::public.announcement_target_audience
      THEN p_target_lounge_id
      ELSE NULL
    END,
    v_db_type,
    true,
    now(),
    auth.uid(),
    now()
  );

  WITH recipients AS (
    SELECT p.id AS user_id
    FROM public.profiles p
    WHERE v_db_audience = 'all'::public.announcement_target_audience
      AND COALESCE(p.is_active, true)

    UNION

    SELECT l.owner_id
    FROM public.lounges l
    JOIN public.profiles p ON p.id = l.owner_id
    WHERE v_db_audience = 'owners'::public.announcement_target_audience
      AND l.owner_id IS NOT NULL
      AND COALESCE(p.is_active, true)

    UNION

    SELECT l.owner_id
    FROM public.lounges l
    JOIN public.profiles p ON p.id = l.owner_id
    WHERE v_db_audience = 'specific_venue'::public.announcement_target_audience
      AND l.id = p_target_lounge_id
      AND l.owner_id IS NOT NULL
      AND COALESCE(p.is_active, true)

    UNION

    SELECT ls.user_id
    FROM public.lounge_staff ls
    JOIN public.profiles p ON p.id = ls.user_id
    WHERE v_db_audience = 'specific_venue'::public.announcement_target_audience
      AND ls.lounge_id = p_target_lounge_id
      AND COALESCE(p.is_active, true)

    UNION

    SELECT p.id
    FROM public.profiles p
    WHERE v_db_audience = 'specific_venue'::public.announcement_target_audience
      AND p.lounge_id = p_target_lounge_id
      AND COALESCE(p.is_active, true)
  ),
  inserted AS (
    INSERT INTO public.notifications (
      user_id,
      lounge_id,
      title_ar,
      title_en,
      body_ar,
      body_en,
      type,
      is_read,
      metadata,
      created_at
    )
    SELECT
      r.user_id,
      CASE
        WHEN v_db_audience = 'specific_venue'::public.announcement_target_audience
        THEN p_target_lounge_id
        ELSE NULL
      END,
      btrim(p_title_ar),
      btrim(p_title_en),
      btrim(p_body_ar),
      btrim(p_body_en),
      'system',
      false,
      jsonb_build_object(
        'announcement_id', v_id,
        'announcement_type', v_db_type::text,
        'target_audience', v_db_audience::text,
        'lounge_id', p_target_lounge_id
      ),
      now()
    FROM recipients r
    WHERE r.user_id IS NOT NULL
    RETURNING id
  )
  SELECT count(*) INTO v_count FROM inserted;

  RETURN jsonb_build_object(
    'success', true,
    'announcement_id', v_id,
    'notifications_created', v_count
  );
END;
$$;


ALTER FUNCTION "public"."create_system_announcement"("p_id" "uuid", "p_target_audience" "text", "p_target_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tournament"("p_lounge_id" "uuid", "p_city_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_game_name" "text", "p_bracket_size" integer, "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone) RETURNS "public"."tournaments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE
  v public.tournaments;
BEGIN
  IF NOT (is_super_admin() OR private.can_operate_playspot_lounge(p_lounge_id) OR is_lounge_member_or_admin(p_lounge_id)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF NOT EXISTS(SELECT 1 FROM public.lounges l WHERE l.id=p_lounge_id AND l.city_id=p_city_id) THEN
    RAISE EXCEPTION 'lounge_city_mismatch';
  END IF;

  INSERT INTO public.tournaments(lounge_id,city_id,title_ar,title_en,game_name,bracket_size,max_participants,entry_fee,registration_opens_at,registration_closes_at,payment_deadline_minutes,check_in_opens_at,check_in_closes_at,tournament_starts_at,created_by)
  VALUES(p_lounge_id,p_city_id,p_title_ar,p_title_en,p_game_name,p_bracket_size,p_max_participants,p_entry_fee,p_registration_opens_at,p_registration_closes_at,p_payment_deadline_minutes,p_check_in_opens_at,p_check_in_closes_at,p_tournament_starts_at,auth.uid())
  RETURNING * INTO v;

  PERFORM public.tournament_audit(v.id,'tournament_created',NULL,NULL,NULL,to_jsonb(v));
  RETURN v;
END
$$;


ALTER FUNCTION "public"."create_tournament"("p_lounge_id" "uuid", "p_city_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_game_name" "text", "p_bracket_size" integer, "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tournament_with_visibility"("p_lounge_id" "uuid", "p_city_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_game_name" "text", "p_bracket_size" integer, "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone, "p_visibility_scope" "text" DEFAULT 'all'::"text", "p_visibility_radius_km" numeric DEFAULT NULL::numeric) RETURNS "public"."tournaments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v public.tournaments;
BEGIN
  IF p_visibility_scope NOT IN ('all', 'city', 'radius') THEN
    RAISE EXCEPTION 'invalid_visibility_scope';
  END IF;

  IF p_visibility_scope = 'radius'
     AND (p_visibility_radius_km IS NULL OR p_visibility_radius_km < 1 OR p_visibility_radius_km > 500) THEN
    RAISE EXCEPTION 'invalid_visibility_radius';
  END IF;

  IF p_visibility_scope <> 'radius' AND p_visibility_radius_km IS NOT NULL THEN
    RAISE EXCEPTION 'radius_only_for_radius_scope';
  END IF;

  v := public.create_tournament(
    p_lounge_id, p_city_id, p_title_ar, p_title_en, p_game_name,
    p_bracket_size, p_max_participants, p_entry_fee,
    p_registration_opens_at, p_registration_closes_at,
    p_payment_deadline_minutes, p_check_in_opens_at,
    p_check_in_closes_at, p_tournament_starts_at
  );

  UPDATE public.tournaments
  SET visibility_scope = p_visibility_scope,
      visibility_radius_km = p_visibility_radius_km,
      updated_at = now()
  WHERE id = v.id
  RETURNING * INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION "public"."create_tournament_with_visibility"("p_lounge_id" "uuid", "p_city_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_game_name" "text", "p_bracket_size" integer, "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone, "p_visibility_scope" "text", "p_visibility_radius_km" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_ban_request"("p_lounge_id" "uuid", "p_user_id" "uuid", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_evidence_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_role text;
  v_request_id uuid;
  v_reason text := NULLIF(btrim(COALESCE(p_reason,'')),'');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF p_lounge_id IS NULL OR p_user_id IS NULL OR v_reason IS NULL THEN
    RAISE EXCEPTION 'LOUNGE_USER_AND_REASON_REQUIRED' USING ERRCODE='22023';
  END IF;

  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'CANNOT_REQUEST_SELF_BAN' USING ERRCODE='42501';
  END IF;

  v_actor_role := private.permission_role(auth.uid(), p_lounge_id);
  IF v_actor_role NOT IN ('owner','manager') THEN
    RAISE EXCEPTION 'LOUNGE_OWNER_OR_MANAGER_REQUIRED' USING ERRCODE='42501';
  END IF;

  IF p_booking_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.bookings b
    WHERE b.id=p_booking_id
      AND b.lounge_id=p_lounge_id
      AND b.user_id=p_user_id
  ) THEN
    RAISE EXCEPTION 'BOOKING_SCOPE_MISMATCH' USING ERRCODE='22023';
  END IF;

  SELECT r.id
  INTO v_request_id
  FROM public.user_ban_requests r
  WHERE r.lounge_id=p_lounge_id
    AND r.user_id=p_user_id
    AND r.status='pending'
  ORDER BY r.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_request_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success',true,
      'request_id',v_request_id,
      'status','pending',
      'idempotent',true
    );
  END IF;

  INSERT INTO public.user_ban_requests(
    lounge_id,user_id,booking_id,reason,evidence_notes,status
  )
  VALUES(
    p_lounge_id,p_user_id,p_booking_id,v_reason,
    NULLIF(btrim(COALESCE(p_evidence_notes,'')),''),
    'pending'
  )
  RETURNING id INTO v_request_id;

  RETURN jsonb_build_object(
    'success',true,
    'request_id',v_request_id,
    'status','pending',
    'idempotent',false
  );
END;
$$;


ALTER FUNCTION "public"."create_user_ban_request"("p_lounge_id" "uuid", "p_user_id" "uuid", "p_booking_id" "uuid", "p_reason" "text", "p_evidence_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_lounge_admin"("p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_target public.profiles%ROWTYPE;
  v_unassigned_lounges integer := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'SUPER_ADMIN_REQUIRED' USING ERRCODE = '42501';
  END IF;

  IF p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'TARGET_USER_REQUIRED' USING ERRCODE = '22023';
  END IF;

  IF p_target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'CANNOT_DEACTIVATE_SELF' USING ERRCODE = '42501';
  END IF;

  SELECT p.*
  INTO v_target
  FROM public.profiles AS p
  WHERE p.id = p_target_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_PROFILE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_target.role IN ('super_admin', 'superadmin')
     OR EXISTS (
       SELECT 1
       FROM public.platform_super_admins AS sa
       WHERE sa.user_id = p_target_user_id
     ) THEN
    RAISE EXCEPTION 'CANNOT_DEACTIVATE_SUPER_ADMIN' USING ERRCODE = '42501';
  END IF;

  UPDATE public.lounges
  SET owner_id = NULL,
      updated_at = now()
  WHERE owner_id = p_target_user_id;
  GET DIAGNOSTICS v_unassigned_lounges = ROW_COUNT;

  DELETE FROM public.lounge_staff
  WHERE user_id = p_target_user_id;

  UPDATE public.profiles
  SET is_active = false,
      role = 'inactive',
      lounge_id = NULL,
      fcm_token = NULL,
      updated_at = now()
  WHERE id = p_target_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'target_user_id', p_target_user_id,
    'unassigned_lounges', v_unassigned_lounges
  );
END;
$$;


ALTER FUNCTION "public"."deactivate_lounge_admin"("p_target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_system_announcement"("p_announcement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  UPDATE public.announcements
  SET is_active = false
  WHERE id = p_announcement_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Announcement not found' USING ERRCODE='P0002';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'announcement_id', p_announcement_id
  );
END;
$$;


ALTER FUNCTION "public"."deactivate_system_announcement"("p_announcement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_draft_tournament"("p_tournament_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE v public.tournaments;
BEGIN
  SELECT * INTO v FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  IF NOT (is_super_admin() OR private.is_lounge_manager(v.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v.status <> 'draft' THEN RAISE EXCEPTION 'only_draft_can_be_deleted'; END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_participants WHERE tournament_id=v.id)
     OR EXISTS (SELECT 1 FROM public.tournament_matches WHERE tournament_id=v.id) THEN
    RAISE EXCEPTION 'tournament_has_related_data';
  END IF;
  DELETE FROM public.tournaments WHERE id=v.id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."delete_draft_tournament"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_lounge_admin"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  UPDATE public.lounges
  SET is_active = false,
      updated_at = now()
  WHERE id = p_lounge_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lounge not found' USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'lounge_id', p_lounge_id,
    'message', 'Lounge deactivated successfully'
  );
END;
$$;


ALTER FUNCTION "public"."delete_lounge_admin"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_promotion"("p_promotion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lounge_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  SELECT p.lounge_id
  INTO v_lounge_id
  FROM public.promotions AS p
  WHERE p.id = p_promotion_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Promotion not found' USING ERRCODE='P0002';
  END IF;

  IF NOT private.can_manage_promotion(v_lounge_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  UPDATE public.promotions
  SET is_active = false,
      archived_at = COALESCE(archived_at, now()),
      archived_by = COALESCE(archived_by, auth.uid())
  WHERE id = p_promotion_id;

  RETURN jsonb_build_object(
    'success', true,
    'promo_id', p_promotion_id,
    'archived', true
  );
END;
$$;


ALTER FUNCTION "public"."delete_promotion"("p_promotion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_user_account"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
    v_user_id uuid := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    DELETE FROM public.notifications WHERE user_id = v_user_id;
    DELETE FROM public.profiles WHERE id = v_user_id;
    DELETE FROM auth.users WHERE id = v_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."delete_user_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_lounges"("p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_city" "text" DEFAULT NULL::"text", "p_search_query" "text" DEFAULT NULL::"text", "p_category_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_sort_type" "text" DEFAULT 'nearest'::"text", "p_is_open_only" boolean DEFAULT false, "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  WITH filtered AS (
    SELECT
      l.*,
      CASE
        WHEN p_lat IS NOT NULL
         AND p_lng IS NOT NULL
         AND l.location_point IS NOT NULL
        THEN public.ST_Distance(
          l.location_point,
          public.ST_SetSRID(
            public.ST_MakePoint(
              p_lng::double precision,
              p_lat::double precision
            ),
            4326
          )::public.geography
        ) / 1000.0
        ELSE NULL
      END AS distance_km,
      (
        SELECT MIN(
          COALESCE(r.hourly_rate_single, r.hourly_rate_multi, r.hourly_rate)
        )
        FROM public.rooms AS r
        WHERE r.lounge_id = l.id
          AND r.is_active IS TRUE
          AND r.status <> 'deleted'
      ) AS min_price_per_hour
    FROM public.lounges AS l
    WHERE l.status = 'active'
      AND l.is_active IS TRUE
      AND (
        p_city IS NULL
        OR btrim(p_city) = ''
        OR lower(l.city) = lower(btrim(p_city))
      )
      AND (
        p_search_query IS NULL
        OR btrim(p_search_query) = ''
        OR l.name ILIKE '%' || btrim(p_search_query) || '%'
        OR l.name_ar ILIKE '%' || btrim(p_search_query) || '%'
        OR l.name_en ILIKE '%' || btrim(p_search_query) || '%'
        OR l.city ILIKE '%' || btrim(p_search_query) || '%'
        OR l.location ILIKE '%' || btrim(p_search_query) || '%'
        OR l.address ILIKE '%' || btrim(p_search_query) || '%'
      )
      AND (
        COALESCE(p_is_open_only, false) IS FALSE
        OR l.is_open IS TRUE
      )
      AND (
        p_category_ids IS NULL
        OR cardinality(p_category_ids) = 0
        OR EXISTS (
          SELECT 1
          FROM public.room_activities AS ra
          JOIN public.rooms AS activity_room
            ON activity_room.id = ra.room_id
          WHERE activity_room.lounge_id = l.id
            AND activity_room.is_active IS TRUE
            AND activity_room.status <> 'deleted'
            AND ra.activity_type_id = ANY(p_category_ids)
        )
        OR EXISTS (
          SELECT 1
          FROM public.lounge_categories AS lc
          WHERE lc.lounge_id = l.id
            AND lc.category_id = ANY(p_category_ids)
        )
      )
  ),
  ranked AS (
    SELECT f.*
    FROM filtered AS f
    ORDER BY
      CASE
        WHEN lower(COALESCE(p_sort_type, 'nearest')) = 'top_rated'
        THEN f.rating
      END DESC NULLS LAST,
      CASE
        WHEN lower(COALESCE(p_sort_type, 'nearest')) <> 'top_rated'
        THEN f.distance_km
      END ASC NULLS LAST,
      f.rating DESC NULLS LAST,
      f.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100)
    OFFSET GREATEST(COALESCE(p_offset, 0), 0)
  )
  SELECT COALESCE(
    jsonb_agg(
      to_jsonb(r)
      || jsonb_build_object(
        'distance_km', r.distance_km,
        'price_per_hour', COALESCE(r.min_price_per_hour, 0),
        'promotions', COALESCE(
          (
            SELECT jsonb_agg(to_jsonb(pr) ORDER BY pr.created_at DESC)
            FROM public.promotions AS pr
            WHERE pr.lounge_id = r.id
              AND pr.is_active IS TRUE
              AND (pr.expires_at IS NULL OR pr.expires_at > now())
          ),
          '[]'::jsonb
        )
      )
    ),
    '[]'::jsonb
  )
  FROM ranked AS r;
$$;


ALTER FUNCTION "public"."discover_lounges"("p_lat" numeric, "p_lng" numeric, "p_city" "text", "p_search_query" "text", "p_category_ids" "uuid"[], "p_sort_type" "text", "p_is_open_only" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispute_match_result"("p_match_id" "uuid", "p_reason" "text") RETURNS "public"."tournament_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_match public.tournament_matches%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NULLIF(btrim(p_reason), '') IS NULL THEN
    RAISE EXCEPTION 'dispute_reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_match
  FROM public.tournament_matches
  WHERE id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'match_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_tournament
  FROM public.tournaments
  WHERE id = v_match.tournament_id;

  IF v_match.status <> 'pending_confirmation' THEN
    RAISE EXCEPTION 'result_not_pending' USING ERRCODE = '55000';
  END IF;

  IF v_match.submitted_by = auth.uid() THEN
    RAISE EXCEPTION 'result_submitter_cannot_dispute_own_submission'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.tournament_participants AS p
    WHERE p.user_id = auth.uid()
      AND p.id IN (v_match.player1_id, v_match.player2_id)
  ) THEN
    RAISE EXCEPTION 'not_match_participant' USING ERRCODE = '42501';
  END IF;

  UPDATE public.tournament_matches
  SET status = 'disputed',
      dispute_reason = btrim(p_reason),
      disputed_by = auth.uid(),
      disputed_at = now(),
      updated_at = now()
  WHERE id = v_match.id
  RETURNING *
  INTO v_match;

  INSERT INTO public.notifications (
    user_id,
    lounge_id,
    title_ar,
    title_en,
    body_ar,
    body_en,
    type,
    metadata
  )
  SELECT DISTINCT
    recipient.user_id,
    v_tournament.lounge_id,
    'نزاع جديد في مباراة',
    'New tournament dispute',
    'يوجد نزاع يحتاج إلى مراجعة.',
    'A tournament dispute requires review.',
    'tournament_dispute',
    jsonb_build_object(
      'tournament_id', v_tournament.id,
      'match_id', v_match.id,
      'reason', btrim(p_reason)
    )
  FROM (
    SELECT ls.user_id
    FROM public.lounge_staff AS ls
    WHERE ls.lounge_id = v_tournament.lounge_id
      AND ls.role IN ('lounge_owner', 'manager')
    UNION
    SELECT p.id
    FROM public.profiles AS p
    WHERE p.lounge_id = v_tournament.lounge_id
      AND p.role IN ('lounge_admin', 'admin', 'owner', 'manager')
  ) AS recipient;

  PERFORM public.tournament_audit(
    v_tournament.id,
    'match_disputed',
    NULL,
    v_match.id,
    NULL,
    to_jsonb(v_match),
    btrim(p_reason)
  );

  RETURN v_match;
END;
$$;


ALTER FUNCTION "public"."dispute_match_result"("p_match_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."draw_tournament_bracket"("p_tournament_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE t public.tournaments%ROWTYPE; ids uuid[]; m uuid; i integer; r integer; total integer; rounds integer; eligible integer; v_p1 uuid; v_p2 uuid;
BEGIN
  SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT(is_super_admin() OR private.is_lounge_manager(t.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF t.status NOT IN('registration_closed','check_in_closed') OR EXISTS(SELECT 1 FROM public.tournament_matches WHERE tournament_id=t.id) THEN RAISE EXCEPTION 'draw_not_allowed'; END IF;
  SELECT array_agg(id ORDER BY random()), count(*) INTO ids,eligible
  FROM public.tournament_participants
  WHERE tournament_id=t.id AND payment_status='paid' AND is_checked_in=true AND registration_status='checked_in';
  IF coalesce(eligible,0)<2 OR eligible>t.bracket_size THEN RAISE EXCEPTION 'eligible_count_invalid'; END IF;
  rounds:=log(2,t.bracket_size)::integer;
  FOR r IN 1..rounds LOOP
    total:=t.bracket_size/(2^r);
    FOR i IN 1..total LOOP
      INSERT INTO public.tournament_matches(tournament_id,round_number,match_order,status)
      VALUES(t.id,r,i,'scheduled') RETURNING id INTO m;
    END LOOP;
  END LOOP;
  UPDATE public.tournament_matches a SET next_match_id=b.id,next_match_slot=CASE WHEN a.match_order%2=1 THEN 1 ELSE 2 END
  FROM public.tournament_matches b
  WHERE a.tournament_id=t.id AND b.tournament_id=t.id AND b.round_number=a.round_number+1 AND b.match_order=((a.match_order+1)/2);
  FOR i IN 1..t.bracket_size/2 LOOP
    v_p1:=ids[(i*2)-1]; v_p2:=ids[i*2];
    UPDATE public.tournament_matches SET player1_id=v_p1,player2_id=v_p2
    WHERE tournament_id=t.id AND round_number=1 AND match_order=i;
  END LOOP;
  PERFORM public.apply_tournament_walkovers(t.id);
  UPDATE public.tournaments SET status='draw_completed',updated_at=now() WHERE id=t.id;
  PERFORM public.tournament_audit(t.id,'bracket_draw_completed',NULL,NULL,NULL,jsonb_build_object('bracket_size',t.bracket_size,'eligible_count',eligible,'participants',ids));
  RETURN (SELECT count(*) FROM public.tournament_matches WHERE tournament_id=t.id);
END;
$$;


ALTER FUNCTION "public"."draw_tournament_bracket"("p_tournament_id" "uuid") OWNER TO "postgres";


