CREATE OR REPLACE FUNCTION "public"."enforce_booking_room_lounge_match"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
begin
  -- Validate that the chosen room belongs to the same lounge as bookings.lounge_id
  if exists (
    select 1
    from public.rooms r
    where r.id = new.room_id
      and r.lounge_id = new.lounge_id
  ) then
    return new;
  end if;

  -- If room doesn't exist, or lounge_id doesn't match, block the write
  raise exception
    'Invalid booking: room_id % does not belong to lounge_id %',
    new.room_id, new.lounge_id
    using errcode = '23514'; -- check_violation
end;
$$;


