CREATE OR REPLACE FUNCTION "public"."enforce_cash_booking_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_authorized boolean := false;
BEGIN
  -- Cash bookings always start as pending and unpaid.
  IF TG_OP = 'INSERT' AND NEW.payment_method = 'cash' THEN
    NEW.status := 'pending'::public.booking_status;
    NEW.payment_status := 'unpaid';
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND (NEW.payment_method = 'cash' OR OLD.payment_method = 'cash')
     AND (
       NEW.payment_status = 'paid'
       OR NEW.status IN ('upcoming'::public.booking_status, 'in_progress'::public.booking_status, 'completed'::public.booking_status)
     )
     AND (
       OLD.payment_status IS DISTINCT FROM NEW.payment_status
       OR OLD.status IS DISTINCT FROM NEW.status
       OR OLD.payment_method IS DISTINCT FROM NEW.payment_method
     ) THEN

    SELECT EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = (SELECT auth.uid())
        AND p.is_active = true
        AND (
          p.role = 'super_admin'
          OR (p.lounge_id = NEW.lounge_id AND p.role IN ('owner', 'manager', 'lounge_admin', 'admin', 'cashier'))
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.lounge_staff ls
      WHERE ls.user_id = (SELECT auth.uid())
        AND ls.lounge_id = NEW.lounge_id
    )
    INTO v_authorized;

    IF NOT v_authorized
       AND current_user NOT IN ('postgres', 'service_role', 'supabase_admin') THEN
      RAISE EXCEPTION 'CASH_BOOKING_APPROVAL_REQUIRED'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_cash_booking_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_moderation_on_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = NEW.user_id AND p.is_banned = true
  ) THEN
    RAISE EXCEPTION 'تم حظر حسابك لمخالفة الشروط';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.lounge_banned_users lbu
    WHERE lbu.lounge_id = NEW.lounge_id
      AND lbu.user_id = NEW.user_id
  ) THEN
    RAISE EXCEPTION 'لا يمكنك الحجز في هذه الصالة بناءً على سياسة الإدارة';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.lounges l
    WHERE l.id = NEW.lounge_id AND l.is_active = false
  ) THEN
    RAISE EXCEPTION 'هذه الصالة موقوفة حاليًا';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_moderation_on_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_payment_financials"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rate numeric := private.platform_commission_rate();
BEGIN
  IF NEW.amount IS NULL OR NEW.amount < 0 THEN
    RAISE EXCEPTION 'Payment amount must be non-negative'
      USING ERRCODE = '22023';
  END IF;

  NEW.commission_rate := v_rate;
  NEW.commission := round(NEW.amount * v_rate, 2);
  NEW.net_to_lounge := NEW.amount - NEW.commission;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_payment_financials"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_request_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  -- Terminal rows are immutable through UPDATE, preventing repeat UPDATE echoes.
  if old.status in ('completed', 'resolved', 'cancelled') then
    return old;
  end if;

  -- Every transition into a terminal state is marked handled and read.
  if new.status in ('completed', 'resolved', 'cancelled') then
    new.is_attended := true;
    new.is_read := true;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_request_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enhanced_tournament_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE v_user uuid; v_lounge uuid; v_type text; v_title_ar text; v_title_en text; v_body_ar text; v_body_en text; v_meta jsonb;
BEGIN
  IF TG_TABLE_NAME='tournament_participants' THEN
    v_user:=NEW.user_id;
    SELECT lounge_id INTO v_lounge FROM public.tournaments WHERE id=NEW.tournament_id;
    IF TG_OP='INSERT' THEN
      v_type:='tournament'; v_title_ar:='تم تسجيلك في البطولة'; v_title_en:='Tournament registration created';
      v_body_ar:='تم تسجيلك بنجاح. يرجى متابعة موعد الدفع.'; v_body_en:='Registration created. Please complete payment before the deadline.';
    ELSIF OLD.registration_status='waitlist' AND NEW.registration_status='pending_payment' THEN
      v_type:='tournament_waitlist_promoted'; v_title_ar:='تم ترقيتك من قائمة الانتظار'; v_title_en:='You were promoted from the waitlist';
      v_body_ar:='تم منحك مقعداً في البطولة. يرجى إتمام الدفع قبل انتهاء المهلة.'; v_body_en:='A tournament seat is now available. Please complete payment before the deadline.';
    ELSIF OLD.payment_status IS DISTINCT FROM NEW.payment_status AND NEW.payment_status='paid' THEN
      v_type:='tournament_payment'; v_title_ar:='تم قبول إثبات الدفع ✅'; v_title_en:='Tournament payment approved ✅';
      v_body_ar:='تم قبول إثبات دفع رسوم البطولة وتأكيد تسجيلك.'; v_body_en:='Your tournament payment proof was approved and your registration is confirmed.';
    ELSIF OLD.payment_status IS DISTINCT FROM NEW.payment_status AND NEW.payment_status='unpaid' AND NEW.payment_rejection_reason IS NOT NULL THEN
      v_type:='tournament_payment'; v_title_ar:='تم رفض إثبات الدفع ❌'; v_title_en:='Tournament payment rejected ❌';
      v_body_ar:='تم رفض إثبات الدفع. السبب: '||NEW.payment_rejection_reason; v_body_en:='Your payment proof was rejected. Reason: '||NEW.payment_rejection_reason;
    ELSE RETURN NEW;
    END IF;
    INSERT INTO public.notifications(user_id,lounge_id,title_ar,title_en,body_ar,body_en,type,metadata)
    VALUES(v_user,v_lounge,v_title_ar,v_title_en,v_body_ar,v_body_en,v_type,
      jsonb_build_object('tournament_id',NEW.tournament_id,'participant_id',NEW.id,'event',v_type));
  ELSIF TG_TABLE_NAME='tournaments' AND TG_OP='UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF NEW.status='cancelled' THEN
      INSERT INTO public.notifications(user_id,lounge_id,title_ar,title_en,body_ar,body_en,type,metadata)
      SELECT p.user_id,NEW.lounge_id,'تم إلغاء البطولة ❌','Tournament cancelled ❌','تم إلغاء البطولة وسيتم متابعة استرداد الرسوم إن وُجدت.','The tournament was cancelled. Any eligible refund will be processed.',
        'tournament_cancelled',jsonb_build_object('tournament_id',NEW.id,'status','cancelled')
      FROM public.tournament_participants p WHERE p.tournament_id=NEW.id AND p.user_id IS NOT NULL AND p.registration_status NOT IN ('cancelled','withdrawn','expired');
    ELSE
      INSERT INTO public.notifications(user_id,lounge_id,title_ar,title_en,body_ar,body_en,type,metadata)
      SELECT p.user_id,NEW.lounge_id,'تحديث حالة البطولة','Tournament status updated','تم تحديث حالة البطولة.','The tournament status was updated.','tournament',jsonb_build_object('tournament_id',NEW.id,'status',NEW.status)
      FROM public.tournament_participants p WHERE p.tournament_id=NEW.id AND p.user_id IS NOT NULL AND p.registration_status IN ('confirmed','checked_in');
    END IF;
  END IF;
  RETURN COALESCE(NEW,OLD);
END;
$$;


ALTER FUNCTION "public"."enhanced_tournament_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_stale_bookings"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE public.bookings
  SET status = 'expired', updated_at = now()
  WHERE status = 'pending' AND expires_at IS NOT NULL AND expires_at <= now();
END;
$$;


