CREATE OR REPLACE FUNCTION "public"."expire_tournament_payments"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE public.tournament_participants
  SET registration_status = 'expired', waitlist_position = NULL, updated_at = now()
  WHERE registration_status = 'pending_payment'
    AND payment_status = 'unpaid'
    AND payment_deadline IS NOT NULL
    AND payment_deadline <= now();
END;
$$;


ALTER FUNCTION "public"."expire_tournament_payments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_active_session"("p_booking_id" "uuid", "p_minutes" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
BEGIN
  IF p_minutes IS NULL OR p_minutes < 1 OR p_minutes > 720 THEN
    RAISE EXCEPTION 'INVALID_EXTENSION_MINUTES' USING ERRCODE = '22023';
  END IF;

  SELECT b.* INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND OR v_booking.status NOT IN ('upcoming'::public.booking_status, 'in_progress'::public.booking_status) THEN
    RAISE EXCEPTION 'BOOKING_NOT_FOUND_OR_NOT_EXTENDABLE' USING ERRCODE = '55000';
  END IF;

  UPDATE public.bookings AS b
  SET extension_status = 'pending',
      requested_extension_minutes = p_minutes,
      updated_at = now()
  WHERE b.id = p_booking_id
    AND COALESCE(b.extension_status, 'none') <> 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EXTENSION_ALREADY_PENDING' USING ERRCODE = '55000';
  END IF;
END;
$$;


ALTER FUNCTION "public"."extend_active_session"("p_booking_id" "uuid", "p_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_active_session"("p_booking_id" "uuid", "p_additional_minutes" integer, "p_additional_cost" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_hourly_rate numeric;
  v_server_cost numeric;
  v_new_duration integer;
  v_new_end timestamp without time zone;
BEGIN
  IF p_booking_id IS NULL OR p_additional_minutes IS NULL
     OR p_additional_minutes < 1 OR p_additional_minutes > 720 THEN
    RAISE EXCEPTION 'INVALID_EXTENSION_PARAMETERS' USING ERRCODE = '22023';
  END IF;

  SELECT b.* INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND OR v_booking.status <> 'in_progress'::public.booking_status THEN
    RAISE EXCEPTION 'ACTIVE_BOOKING_NOT_FOUND' USING ERRCODE = '55000';
  END IF;

  IF current_user NOT IN ('postgres', 'service_role')
     AND (auth.uid() IS NULL OR (auth.uid() IS DISTINCT FROM v_booking.user_id
          AND NOT private.is_lounge_member(v_booking.lounge_id))) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED_FOR_BOOKING' USING ERRCODE = '42501';
  END IF;

  SELECT CASE
           WHEN lower(COALESCE(v_booking.play_mode, '')) = 'single' THEN r.hourly_rate_single
           ELSE r.hourly_rate_multi
         END
  INTO v_hourly_rate
  FROM public.rooms AS r
  WHERE r.id = v_booking.room_id
    AND r.lounge_id = v_booking.lounge_id;

  IF v_hourly_rate IS NULL OR v_hourly_rate < 0 THEN
    RAISE EXCEPTION 'ROOM_RATE_NOT_CONFIGURED' USING ERRCODE = '22023';
  END IF;

  v_new_duration := COALESCE(v_booking.duration_minutes, 60) + p_additional_minutes;
  IF v_new_duration > 1440 THEN
    RAISE EXCEPTION 'INVALID_TOTAL_SESSION_DURATION' USING ERRCODE = '22023';
  END IF;

  v_server_cost := public.calculate_booking_price(v_hourly_rate, p_additional_minutes);
  IF v_server_cost IS NULL OR v_server_cost < 0 THEN
    RAISE EXCEPTION 'SERVER_EXTENSION_PRICE_INVALID' USING ERRCODE = '22023';
  END IF;

  v_new_end := v_booking.date + v_booking.start_time + make_interval(mins => v_new_duration);

  IF EXISTS (
    SELECT 1
    FROM public.bookings AS other_booking
    WHERE other_booking.id <> v_booking.id
      AND other_booking.room_id = v_booking.room_id
      AND other_booking.status IN ('pending'::public.booking_status, 'upcoming'::public.booking_status, 'in_progress'::public.booking_status)
      AND other_booking.booking_period IS NOT NULL
      AND other_booking.booking_period && tsrange(
        (v_booking.date + v_booking.start_time)::timestamp,
        v_new_end,
        '[)'
      )
      AND (other_booking.status <> 'pending'::public.booking_status
           OR other_booking.expires_at IS NULL
           OR other_booking.expires_at > now())
  ) THEN
    RAISE EXCEPTION 'BOOKING_EXTENSION_CONFLICT' USING ERRCODE = '23P01';
  END IF;

  UPDATE public.bookings AS b
  SET duration_minutes = v_new_duration,
      end_time = v_new_end::time,
      end_at = v_new_end::time,
      total_price = COALESCE(b.total_price, 0) + v_server_cost,
      updated_at = now()
  WHERE b.id = v_booking.id;
END;
$$;


ALTER FUNCTION "public"."extend_active_session"("p_booking_id" "uuid", "p_additional_minutes" integer, "p_additional_cost" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_booking_session"("p_booking_id" "uuid", "p_additional_minutes" integer, "p_additional_cost" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_is_operator boolean := false;
  v_hourly_rate numeric;
  v_extension_cost numeric;
  v_new_duration integer;
  v_new_end timestamp without time zone;
  v_new_end_time time without time zone;
  v_new_total numeric;
  v_shift_id uuid;
  v_payment_method text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE = '28000';
  END IF;

  IF p_additional_minutes IS NULL
     OR p_additional_minutes <= 0
     OR p_additional_minutes > 720 THEN
    RAISE EXCEPTION 'INVALID_EXTENSION_MINUTES' USING ERRCODE = '22023';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BOOKING_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.status NOT IN (
    'upcoming'::public.booking_status,
    'in_progress'::public.booking_status
  ) THEN
    RAISE EXCEPTION 'BOOKING_NOT_EXTENDABLE' USING ERRCODE = '55000';
  END IF;

  v_is_operator :=
    public.is_super_admin()
    OR public.has_lounge_permission(v_booking.lounge_id, 'sessions_control');

  IF NOT v_is_operator THEN
    IF v_booking.user_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
    END IF;

    IF COALESCE(v_booking.extension_status, 'none') = 'pending' THEN
      RETURN jsonb_build_object(
        'success', true,
        'status', 'pending',
        'already_pending', true,
        'booking_id', p_booking_id,
        'requested_extension_minutes', v_booking.requested_extension_minutes
      );
    END IF;

    UPDATE public.bookings
    SET extension_status = 'pending',
        requested_extension_minutes = p_additional_minutes,
        updated_at = now()
    WHERE id = p_booking_id;

    RETURN jsonb_build_object(
      'success', true,
      'status', 'pending',
      'already_pending', false,
      'booking_id', p_booking_id,
      'requested_extension_minutes', p_additional_minutes
    );
  END IF;

  SELECT CASE
           WHEN lower(COALESCE(v_booking.play_mode, '')) = 'single'
             THEN r.hourly_rate_single
           ELSE r.hourly_rate_multi
         END
  INTO v_hourly_rate
  FROM public.rooms AS r
  WHERE r.id = v_booking.room_id
    AND r.lounge_id = v_booking.lounge_id;

  IF v_hourly_rate IS NULL OR v_hourly_rate < 0 THEN
    RAISE EXCEPTION 'ROOM_RATE_NOT_CONFIGURED' USING ERRCODE = '22023';
  END IF;

  v_new_duration :=
    COALESCE(v_booking.duration_minutes, 0) + p_additional_minutes;

  IF v_new_duration <= 0 OR v_new_duration > 1440 THEN
    RAISE EXCEPTION 'INVALID_TOTAL_SESSION_DURATION' USING ERRCODE = '22023';
  END IF;

  v_new_end :=
    v_booking.date
    + v_booking.start_time
    + make_interval(mins => v_new_duration);

  v_new_end_time := v_new_end::time;

  IF EXISTS (
    SELECT 1
    FROM public.bookings AS next_booking
    WHERE next_booking.id <> v_booking.id
      AND next_booking.room_id = v_booking.room_id
      AND next_booking.status IN (
        'pending'::public.booking_status,
        'upcoming'::public.booking_status,
        'in_progress'::public.booking_status
      )
      AND next_booking.booking_period IS NOT NULL
      AND next_booking.booking_period && tsrange(
        (v_booking.date + v_booking.start_time)::timestamp,
        v_new_end,
        '[)'
      )
      AND (
        next_booking.status <> 'pending'::public.booking_status
        OR next_booking.expires_at IS NULL
        OR next_booking.expires_at > now()
      )
  ) THEN
    RAISE EXCEPTION 'BOOKING_EXTENSION_CONFLICT' USING ERRCODE = '23P01';
  END IF;

  v_extension_cost :=
    (private.booking_extension_quote(v_booking,p_additional_minutes)->>'extension_cost')::numeric;

  v_new_total :=
    COALESCE(v_booking.total_price, 0) + v_extension_cost;

  IF v_booking.payment_status = 'paid' AND v_extension_cost > 0 THEN
    SELECT s.id
    INTO v_shift_id
    FROM public.shifts AS s
    WHERE s.id = v_booking.shift_id
      AND s.lounge_id = v_booking.lounge_id
      AND s.status = 'open'
    LIMIT 1;

    IF v_shift_id IS NULL THEN
      SELECT s.id
      INTO v_shift_id
      FROM public.shifts AS s
      WHERE s.lounge_id = v_booking.lounge_id
        AND s.status = 'open'
      ORDER BY s.opened_at DESC
      LIMIT 1;
    END IF;

    IF v_shift_id IS NULL THEN
      RAISE EXCEPTION 'OPEN_SHIFT_REQUIRED_FOR_PAID_EXTENSION'
        USING ERRCODE = '55000';
    END IF;

    v_payment_method := COALESCE(v_booking.payment_method, 'cash');

    INSERT INTO public.shift_payments (
      shift_id,
      lounge_id,
      booking_id,
      payment_method,
      category,
      amount,
      paid_at
    )
    VALUES (
      v_shift_id,
      v_booking.lounge_id,
      p_booking_id,
      v_payment_method,
      'gaming_time',
      v_extension_cost,
      now()
    );

    INSERT INTO public.payments (
      booking_id,
      user_id,
      lounge_id,
      amount,
      commission,
      net_to_lounge,
      payment_method,
      status,
      paid_at,
      discount_amount,
      discount_percentage,
      discount_reason,
      discount_approved_by
    )
    VALUES (
      p_booking_id,
      v_booking.user_id,
      v_booking.lounge_id,
      v_new_total,
      round(v_new_total * 0.15, 2),
      v_new_total - round(v_new_total * 0.15, 2),
      v_payment_method,
      'completed',
      now(),
      COALESCE(v_booking.discount_amount, 0),
      COALESCE(v_booking.discount_percentage, 0),
      v_booking.discount_reason,
      v_booking.discount_approved_by
    )
    ON CONFLICT (booking_id)
    DO UPDATE SET
      amount = EXCLUDED.amount,
      commission = EXCLUDED.commission,
      net_to_lounge = EXCLUDED.net_to_lounge,
      payment_method = EXCLUDED.payment_method,
      status = 'completed',
      paid_at = COALESCE(public.payments.paid_at, EXCLUDED.paid_at),
      discount_amount = EXCLUDED.discount_amount,
      discount_percentage = EXCLUDED.discount_percentage,
      discount_reason = EXCLUDED.discount_reason,
      discount_approved_by = EXCLUDED.discount_approved_by;
  END IF;

  UPDATE public.bookings
  SET duration_minutes = v_new_duration,
      end_time = v_new_end_time,
      end_at = v_new_end_time,
      total_price = v_new_total,
      shift_id = COALESCE(v_shift_id, shift_id),
      extension_status = 'approved',
      requested_extension_minutes = NULL,
      updated_at = now()
  WHERE id = p_booking_id;

  IF (SELECT b.total_price FROM public.bookings b WHERE b.id=p_booking_id) IS DISTINCT FROM v_new_total THEN
    RAISE EXCEPTION 'EXTENSION_PRICE_MISMATCH' USING ERRCODE='22023';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'status', 'approved',
    'booking_id', p_booking_id,
    'added_minutes', p_additional_minutes,
    'extension_cost', v_extension_cost,
    'new_duration', v_new_duration,
    'new_end_time', v_new_end_time,
    'new_total', v_new_total,
    'ignored_client_cost', p_additional_cost
  );
END;
$$;


ALTER FUNCTION "public"."extend_booking_session"("p_booking_id" "uuid", "p_additional_minutes" integer, "p_additional_cost" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_payout"("p_payout_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE public.payouts
  SET status = 'failed', failure_reason = p_reason
  WHERE id = p_payout_id AND status IN ('approved','processing');

  IF NOT FOUND THEN RAISE EXCEPTION 'Payout not found or not processing'; END IF;

  UPDATE public.payments
  SET payout_id = NULL
  WHERE payout_id = p_payout_id;

  RETURN jsonb_build_object('success', true, 'payout_id', p_payout_id, 'status', 'failed');
END;
$$;


ALTER FUNCTION "public"."fail_payout"("p_payout_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_lounge_staff_provisioning"("p_actor_id" "uuid", "p_user_id" "uuid", "p_lounge_id" "uuid", "p_role" "text", "p_full_name" "text", "p_phone" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_previous_sub text := current_setting('request.jwt.claim.sub', true);
  v_actor public.profiles%ROWTYPE;
  v_account auth.users%ROWTYPE;
  v_receipt private.staff_provisioning_receipts%ROWTYPE;
  v_super boolean;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF p_actor_id IS NULL OR p_user_id IS NULL OR p_lounge_id IS NULL
    OR p_actor_id = p_user_id OR p_role NOT IN ('manager','cashier','staff')
    OR p_role IS NULL OR nullif(btrim(p_full_name),'') IS NULL THEN
    RAISE EXCEPTION 'INVALID_STAFF_DETAILS' USING ERRCODE = '22023';
  END IF;
  SELECT p.* INTO v_actor FROM public.profiles p JOIN auth.users u ON u.id=p.id
    WHERE p.id=p_actor_id FOR SHARE OF p,u;
  IF NOT FOUND OR v_actor.is_active IS NOT TRUE OR v_actor.is_banned IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'ACCOUNT_NOT_ELIGIBLE' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('request.jwt.claim.sub',p_actor_id::text,true);
  v_super := public.is_super_admin();
  IF v_super IS NOT TRUE AND (v_actor.role NOT IN ('owner','lounge_owner','manager','lounge_admin')
    OR public.has_lounge_permission(p_lounge_id,'staff_manage') IS NOT TRUE) THEN
    RAISE EXCEPTION 'STAFF_MANAGEMENT_DENIED' USING ERRCODE = '42501';
  END IF;
  IF v_super IS NOT TRUE AND v_actor.role IN ('manager','lounge_admin') AND p_role='manager' THEN
    RAISE EXCEPTION 'PEER_MANAGER_CREATION_DENIED' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('request.jwt.claim.sub',coalesce(v_previous_sub,''),true);
  PERFORM 1 FROM public.lounges WHERE id=p_lounge_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'LOUNGE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_account FROM auth.users WHERE id=p_user_id FOR UPDATE;
  IF NOT FOUND OR (v_account.raw_app_meta_data->'staff_provisioning') IS DISTINCT FROM
    jsonb_build_object('actor_id',p_actor_id,'lounge_id',p_lounge_id,'role',p_role) THEN
    RAISE EXCEPTION 'STAFF_PROVISIONING_IDENTITY_MISMATCH' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_receipt FROM private.staff_provisioning_receipts WHERE user_id=p_user_id;
  IF FOUND THEN
    IF (v_receipt.actor_id,v_receipt.lounge_id,v_receipt.role,v_receipt.full_name,v_receipt.phone)
      IS DISTINCT FROM (p_actor_id,p_lounge_id,p_role,btrim(p_full_name),coalesce(p_phone,'')) THEN
      RAISE EXCEPTION 'STAFF_PROVISIONING_REPLAY_MISMATCH' USING ERRCODE='22023';
    END IF;
    RETURN jsonb_build_object('success',true,'user_id',p_user_id,'role',p_role);
  END IF;
  PERFORM 1 FROM public.profiles WHERE id=p_user_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.lounge_staff WHERE user_id=p_user_id)
    OR EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND
      (lounge_id IS NOT NULL OR role NOT IN ('user','customer','cashier','staff') OR is_banned IS DISTINCT FROM false)) THEN
    RAISE EXCEPTION 'STAFF_ACCOUNT_CANNOT_BE_REASSIGNED' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.profiles(id,email,full_name,phone,role,lounge_id,is_active,is_banned,updated_at)
    VALUES(p_user_id,v_account.email,btrim(p_full_name),coalesce(p_phone,''),p_role,p_lounge_id,true,false,now())
    ON CONFLICT(id) DO UPDATE SET email=excluded.email,full_name=excluded.full_name,
      phone=excluded.phone,role=excluded.role,lounge_id=excluded.lounge_id,is_active=true,updated_at=now();
  INSERT INTO public.lounge_staff(lounge_id,user_id,role) VALUES(p_lounge_id,p_user_id,p_role);
  INSERT INTO private.staff_provisioning_receipts(user_id,actor_id,lounge_id,role,full_name,phone)
    VALUES(p_user_id,p_actor_id,p_lounge_id,p_role,btrim(p_full_name),coalesce(p_phone,''));
  RETURN jsonb_build_object('success',true,'user_id',p_user_id,'role',p_role);
END;
$$;


ALTER FUNCTION "public"."finalize_lounge_staff_provisioning"("p_actor_id" "uuid", "p_user_id" "uuid", "p_lounge_id" "uuid", "p_role" "text", "p_full_name" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_owner_lounge_provisioning"("p_actor_id" "uuid", "p_owner_id" "uuid", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_previous_sub text := current_setting('request.jwt.claim.sub', true);
  v_email text;
  v_lounge_id uuid;
  v_existing_actor uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('request.jwt.claim.sub', p_actor_id::text, true);
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Active super administrator required' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('request.jwt.claim.sub', coalesce(v_previous_sub, ''), true);
  IF p_actor_id IS NULL OR p_owner_id IS NULL OR p_actor_id = p_owner_id
     OR nullif(btrim(p_owner_name), '') IS NULL
     OR nullif(btrim(p_lounge_name), '') IS NULL THEN
    RAISE EXCEPTION 'Invalid owner or lounge details' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 918));
  SELECT lounge_id, actor_id INTO v_lounge_id, v_existing_actor
    FROM private.owner_lounge_provisioning WHERE owner_id = p_owner_id;
  IF FOUND THEN
    IF v_existing_actor <> p_actor_id THEN
      RAISE EXCEPTION 'Provisioning actor mismatch' USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object('success', true, 'owner_id', p_owner_id,
      'owner_user_id', p_owner_id, 'lounge_id', v_lounge_id, 'status', 'pending');
  END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = p_owner_id;
  IF v_email IS NULL OR EXISTS (
    SELECT 1 FROM public.lounges WHERE owner_id = p_owner_id
  ) OR EXISTS (
    SELECT 1 FROM public.profiles WHERE id = p_owner_id
      AND (role NOT IN ('customer', 'user') OR lounge_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Account cannot be reassigned' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.profiles(id, email, full_name, phone, role,
    is_active, is_banned, is_setup_completed)
  VALUES(p_owner_id, v_email, btrim(p_owner_name), p_phone, 'owner',
    true, false, false)
  ON CONFLICT (id) DO UPDATE SET full_name = excluded.full_name,
    phone = excluded.phone, role = 'owner', is_active = true,
    is_setup_completed = false, updated_at = now();
  INSERT INTO public.lounges(name, city, location, owner_id, status, is_open, is_active)
  VALUES(btrim(p_lounge_name), p_city, p_address, p_owner_id, 'pending', false, false)
  RETURNING id INTO v_lounge_id;
  UPDATE public.profiles SET lounge_id = v_lounge_id WHERE id = p_owner_id;
  INSERT INTO private.owner_lounge_provisioning(owner_id, actor_id, lounge_id)
  VALUES(p_owner_id, p_actor_id, v_lounge_id);
  RETURN jsonb_build_object('success', true, 'owner_id', p_owner_id,
    'owner_user_id', p_owner_id, 'lounge_id', v_lounge_id, 'status', 'pending');
END;
$$;


ALTER FUNCTION "public"."finalize_owner_lounge_provisioning"("p_actor_id" "uuid", "p_owner_id" "uuid", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text", "p_address" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_owner_lounge_provisioning_v2"("p_actor_id" "uuid", "p_owner_id" "uuid", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_owner_phone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_previous_sub text := current_setting('request.jwt.claim.sub', true);
  v_email text;
  v_lounge_id uuid;
  v_existing_actor uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('request.jwt.claim.sub', p_actor_id::text, true);
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Active super administrator required' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('request.jwt.claim.sub', coalesce(v_previous_sub, ''), true);
  IF p_actor_id IS NULL OR p_owner_id IS NULL OR p_actor_id = p_owner_id
     OR nullif(btrim(p_owner_name), '') IS NULL
     OR nullif(btrim(p_lounge_name), '') IS NULL THEN
    RAISE EXCEPTION 'Invalid owner or lounge details' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 918));
  SELECT lounge_id, actor_id INTO v_lounge_id, v_existing_actor
    FROM private.owner_lounge_provisioning WHERE owner_id = p_owner_id;
  IF FOUND THEN
    IF v_existing_actor <> p_actor_id THEN
      RAISE EXCEPTION 'Provisioning actor mismatch' USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object('success', true, 'owner_id', p_owner_id,
      'owner_user_id', p_owner_id, 'lounge_id', v_lounge_id, 'status', 'pending');
  END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = p_owner_id;
  IF v_email IS NULL OR EXISTS (
    SELECT 1 FROM public.lounges WHERE owner_id = p_owner_id
  ) OR EXISTS (
    SELECT 1 FROM public.profiles WHERE id = p_owner_id
      AND (role NOT IN ('customer', 'user') OR lounge_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Account cannot be reassigned' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.profiles(id, email, full_name, phone, role,
    is_active, is_banned, is_setup_completed)
  VALUES(p_owner_id, v_email, btrim(p_owner_name), NULLIF(btrim(p_owner_phone),''), 'owner',
    true, false, false)
  ON CONFLICT (id) DO UPDATE SET full_name = excluded.full_name,
    phone = excluded.phone, role = 'owner', is_active = true,
    is_setup_completed = false, updated_at = now();
  INSERT INTO public.lounges(name, city, location, address, contact_phone, owner_id, status, is_open, is_active)
  VALUES(btrim(p_lounge_name), p_city, p_address, p_address, NULLIF(btrim(p_phone),''), p_owner_id, 'pending', false, false)
  RETURNING id INTO v_lounge_id;
  UPDATE public.profiles SET lounge_id = v_lounge_id WHERE id = p_owner_id;
  INSERT INTO private.owner_lounge_provisioning(owner_id, actor_id, lounge_id)
  VALUES(p_owner_id, p_actor_id, v_lounge_id);
  RETURN jsonb_build_object('success', true, 'owner_id', p_owner_id,
    'owner_user_id', p_owner_id, 'lounge_id', v_lounge_id, 'status', 'pending');
END;
$$;


ALTER FUNCTION "public"."finalize_owner_lounge_provisioning_v2"("p_actor_id" "uuid", "p_owner_id" "uuid", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text", "p_address" "text", "p_phone" "text", "p_owner_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_auth_disable_task"("p_user_id" "uuid", "p_lease_id" "uuid", "p_success" boolean, "p_error_code" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_task private.auth_disable_tasks%ROWTYPE;
BEGIN
  SELECT * INTO v_task FROM private.auth_disable_tasks t
  WHERE t.user_id=p_user_id AND t.lease_id=p_lease_id AND t.status='running' AND t.leased_until>now() FOR UPDATE;
  IF NOT FOUND OR p_success IS NULL THEN RAISE EXCEPTION 'STALE_AUTH_RECOVERY_LEASE' USING ERRCODE='55000'; END IF;
  IF p_error_code IS NOT NULL AND p_error_code NOT IN ('AUTH_UNAVAILABLE','AUTH_REJECTED') THEN
    RAISE EXCEPTION 'INVALID_AUTH_RECOVERY_ERROR' USING ERRCODE='22023';
  END IF;
  UPDATE private.auth_disable_tasks SET status=CASE WHEN p_success THEN 'completed' WHEN attempts>=5 THEN 'failed' ELSE 'pending' END,
    next_attempt_at=now()+make_interval(secs=>least(3600,30*power(2,attempts-1)::integer)),
    completed_at=CASE WHEN p_success THEN now() ELSE NULL END,
    last_error_code=CASE WHEN p_success THEN NULL ELSE coalesce(p_error_code,'AUTH_UNAVAILABLE') END,
    lease_id=NULL,leased_until=NULL WHERE user_id=p_user_id;
  IF p_success THEN UPDATE public.account_deletion_requests SET auth_disabled_at=coalesce(auth_disabled_at,now()) WHERE user_id=p_user_id; END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."finish_auth_disable_task"("p_user_id" "uuid", "p_lease_id" "uuid", "p_success" boolean, "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_slot_waitlist_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_time time without time zone := COALESCE(NEW.slot_time, '18:00:00'::time);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF NEW.user_id IS NOT NULL AND NEW.user_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Cannot create another customer request' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles AS actor
    WHERE actor.id = v_actor AND actor.is_active IS TRUE AND actor.is_banned IS FALSE) THEN
    RAISE EXCEPTION 'Active account required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.rooms AS resource
    WHERE resource.id = NEW.room_id AND resource.lounge_id = NEW.lounge_id) THEN
    RAISE EXCEPTION 'Room does not belong to the lounge' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(NEW.status, 'waiting') NOT IN ('waiting', 'active') THEN
    RAISE EXCEPTION 'Cannot create a claimed or completed request' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.booking_waitlist (
    user_id, lounge_id, room_id, requested_date, duration_minutes,
    preferred_start_time, start_at, end_at, status
  ) VALUES (
    v_actor, NEW.lounge_id, NEW.room_id, NEW.date, 60,
    v_time, NEW.date + v_time, NEW.date + v_time + interval '60 minutes',
    COALESCE(NEW.status, 'waiting')
  ) RETURNING id INTO NEW.id;
  NEW.user_id := v_actor;
  NEW.slot_time := v_time;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_slot_waitlist_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_booking_waitlist_dates"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  -- 1. Bi-directional sync between start_at/end_at and requested_date/duration_minutes
  IF NEW.start_at IS NOT NULL AND NEW.end_at IS NOT NULL THEN
    IF NEW.end_at <= NEW.start_at THEN
      RAISE EXCEPTION 'end_at must be strictly after start_at' USING ERRCODE = '22023';
    END IF;
    NEW.requested_date := NEW.start_at::date;
    NEW.preferred_start_time := NEW.start_at::time;
    NEW.duration_minutes := GREATEST(15, LEAST(1440, ROUND(EXTRACT(EPOCH FROM (NEW.end_at - NEW.start_at)) / 60)::integer));
  ELSIF NEW.requested_date IS NOT NULL THEN
    NEW.start_at := NEW.requested_date + COALESCE(NEW.preferred_start_time, '00:00:00'::time);
    NEW.duration_minutes := GREATEST(15, LEAST(1440, COALESCE(NEW.duration_minutes, 60)));
    NEW.end_at := NEW.start_at + make_interval(mins => NEW.duration_minutes);
  END IF;

  -- 2. Defaults
  IF NEW.expires_at IS NULL THEN
    NEW.expires_at := now() + interval '14 days';
  END IF;

  IF NEW.intent_id IS NULL THEN
    NEW.intent_id := gen_random_uuid();
  END IF;

  NEW.updated_at := now();

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_booking_waitlist_dates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_room_resource_capabilities"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_primary_act RECORD;
BEGIN
  -- Infer resource_type and capabilities from activity_types if not explicitly set
  IF NEW.resource_type IS NULL OR NEW.resource_type = '' THEN
    SELECT a.* INTO v_primary_act
    FROM public.room_activities ra
    JOIN public.activity_types a ON a.id = ra.activity_type_id
    WHERE ra.room_id = NEW.id
    ORDER BY a.sort_order ASC
    LIMIT 1;

    IF FOUND THEN
      NEW.resource_type := v_primary_act.name;
      IF NEW.requires_screen IS NULL THEN
        NEW.requires_screen := v_primary_act.requires_screen;
      END IF;
      IF NEW.requires_controllers IS NULL THEN
        NEW.requires_controllers := v_primary_act.requires_controllers;
      END IF;
      IF NEW.pricing_model IS NULL THEN
        NEW.pricing_model := v_primary_act.pricing_model;
      END IF;
    ELSE
      NEW.resource_type := 'console';
    END IF;
  END IF;

  -- Table sports (Billiards, Table Tennis, Foosball, Darts) do not require controllers or screens
  IF NEW.resource_type IN ('billiard', 'table_tennis', 'foosball', 'darts', 'board_games') THEN
    IF NEW.requires_screen IS NULL THEN
      NEW.requires_screen := false;
    END IF;
    IF NEW.requires_controllers IS NULL THEN
      NEW.requires_controllers := false;
    END IF;
    IF NEW.controllers_count IS NULL THEN
      NEW.controllers_count := 0;
    END IF;
  END IF;

  IF NEW.resource_attributes IS NULL THEN
    NEW.resource_attributes := '{}'::jsonb;
  END IF;

  IF NEW.min_capacity IS NULL OR NEW.min_capacity < 1 THEN
    NEW.min_capacity := 1;
  END IF;

  IF NEW.max_capacity IS NULL OR NEW.max_capacity < NEW.min_capacity THEN
    NEW.max_capacity := GREATEST(4, NEW.min_capacity);
  END IF;

  NEW.updated_at := now();

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_room_resource_capabilities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_validate_and_clamp_booking_price"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_interval jsonb;
  v_room_subtotal numeric:=0;
  v_extra_controller_rate numeric:=0;
  v_controllers_amount numeric:=0;
  v_addons numeric:=0;
  v_subtotal numeric:=0;
  v_discount numeric:=0;
  v_snap jsonb;
  v_actual_hourly_rate numeric:=0;
BEGIN
  IF current_setting('app.skip_price_clamp',true)='true' THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.is_open_time,false) IS TRUE
     AND NEW.status='in_progress'::public.booking_status THEN
    NEW.duration_minutes:=GREATEST(1,COALESCE(NEW.duration_minutes,1));
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.duration_minutes,0)<=0 OR NEW.duration_minutes>1440 THEN
    RAISE EXCEPTION
      'Invalid booking duration: % minutes. Duration must be between 1 and 1440 minutes.',
      NEW.duration_minutes USING ERRCODE='22023';
  END IF;

  IF NEW.room_id IS NULL THEN
    RAISE EXCEPTION 'Cannot validate booking price: room_id is required.'
      USING ERRCODE='22023';
  END IF;

  -- Extend only the added interval; never reprice time already purchased.
  IF TG_OP='UPDATE' AND NEW.duration_minutes>OLD.duration_minutes
     AND NEW.extension_status='approved'
     AND COALESCE(NEW.is_open_time,false) IS FALSE
     AND ROW(NEW.room_id,NEW.date,NEW.start_time,NEW.play_mode,NEW.extra_controllers)
       IS NOT DISTINCT FROM ROW(OLD.room_id,OLD.date,OLD.start_time,OLD.play_mode,OLD.extra_controllers) THEN
    v_interval:=private.booking_extension_quote(OLD,NEW.duration_minutes-OLD.duration_minutes);
    NEW.room_price:=(v_interval->>'room_price')::numeric;
    NEW.total_price:=(v_interval->>'new_total')::numeric;
    NEW.addons_price:=OLD.addons_price;
    NEW.addons_total:=OLD.addons_total;
    NEW.discount_amount:=OLD.discount_amount;
    NEW.discount_percentage:=OLD.discount_percentage;
    NEW.pricing_snapshot:=jsonb_set(COALESCE(OLD.pricing_snapshot,'{}'::jsonb),'{extensions}',
      COALESCE(OLD.pricing_snapshot->'extensions','[]'::jsonb)||jsonb_build_array(v_interval->'quote'));
    SELECT ARRAY(SELECT DISTINCT unnest(COALESCE(OLD.pricing_rule_ids,'{}'::uuid[]) ||
      ARRAY(SELECT (s->>'rule_id')::uuid FROM jsonb_array_elements(v_interval->'quote'->'segments') s
       WHERE s->>'rule_id' IS NOT NULL))) INTO NEW.pricing_rule_ids;
    RETURN NEW;
  END IF;

  -- Status, payment and canteen updates must preserve the agreed room tariff.
  -- A schedule/mode/controller change deliberately requests a fresh price.
  IF TG_OP = 'UPDATE'
     AND COALESCE(NEW.is_open_time, false) IS FALSE
     AND ROW(NEW.room_id, NEW.date, NEW.start_time, NEW.end_time,
             NEW.duration_minutes, NEW.play_mode, NEW.extra_controllers, NEW.is_open_time)
         IS NOT DISTINCT FROM
         ROW(OLD.room_id, OLD.date, OLD.start_time, OLD.end_time,
             OLD.duration_minutes, OLD.play_mode, OLD.extra_controllers, OLD.is_open_time) THEN
    NEW.room_price := OLD.room_price;
    NEW.pricing_snapshot := OLD.pricing_snapshot;
    NEW.pricing_rule_ids := OLD.pricing_rule_ids;
  ELSIF COALESCE(NEW.is_open_time,false) IS TRUE
     AND NEW.open_time_pricing_snapshot IS NOT NULL
     AND NEW.open_time_pricing_snapshot<>'{}'::jsonb THEN
    v_snap:=NEW.open_time_pricing_snapshot;
    v_actual_hourly_rate:=COALESCE(
      (v_snap->>'effective_hourly_rate')::numeric,
      (v_snap->>'base_hourly_rate')::numeric,
      50
    );
    v_room_subtotal:=round(
      (NEW.duration_minutes/60.0)*v_actual_hourly_rate,
      2
    );
  ELSE
    IF NEW.date IS NULL OR NEW.start_time IS NULL OR NEW.end_time IS NULL THEN
      RAISE EXCEPTION 'Booking date/start/end are required for pricing'
        USING ERRCODE='22023';
    END IF;

    v_interval:=private.price_room_interval(
      NEW.room_id,
      NEW.date,
      NEW.start_time,
      NEW.end_time,
      COALESCE(NEW.play_mode,'single')
    );
    v_room_subtotal:=COALESCE(
      (v_interval->>'room_subtotal')::numeric,0
    );
  END IF;

  IF TG_OP = 'INSERT' OR COALESCE(NEW.is_open_time,false) IS TRUE
     OR ROW(NEW.room_id, NEW.date, NEW.start_time, NEW.end_time,
            NEW.duration_minutes, NEW.play_mode, NEW.extra_controllers, NEW.is_open_time)
        IS DISTINCT FROM
        ROW(OLD.room_id, OLD.date, OLD.start_time, OLD.end_time,
            OLD.duration_minutes, OLD.play_mode, OLD.extra_controllers, OLD.is_open_time) THEN
  SELECT
    GREATEST(0,COALESCE(NEW.extra_controllers,0))
    * COALESCE(r.extra_controller_price,0)
    * (NEW.duration_minutes/60.0)
  INTO v_controllers_amount
  FROM public.rooms AS r
  WHERE r.id=NEW.room_id;

  IF COALESCE(NEW.is_open_time,false) IS FALSE
     OR NEW.status='completed'::public.booking_status THEN
    NEW.room_price:=round(
      v_room_subtotal+COALESCE(v_controllers_amount,0),
      2
    );
  END IF;

  IF v_interval IS NOT NULL THEN
    NEW.pricing_snapshot := v_interval;
    SELECT COALESCE(array_agg(DISTINCT (segment->>'rule_id')::uuid)
      FILTER (WHERE segment->>'rule_id' IS NOT NULL), '{}'::uuid[])
    INTO NEW.pricing_rule_ids
    FROM jsonb_array_elements(v_interval->'segments') segment;
  END IF;
  END IF;

  v_addons:=GREATEST(
    0,COALESCE(NEW.addons_price,NEW.addons_total,0)
  );
  NEW.addons_price:=v_addons;
  NEW.addons_total:=v_addons;

  v_subtotal:=NEW.room_price+v_addons;

  IF COALESCE(NEW.discount_amount,0)>0 THEN
    v_discount:=LEAST(v_subtotal,NEW.discount_amount);
  ELSIF COALESCE(NEW.discount_percentage,0)>0 THEN
    v_discount:=LEAST(
      v_subtotal,
      v_subtotal*(NEW.discount_percentage/100.0)
    );
  ELSE
    v_discount:=0;
  END IF;

  NEW.discount_amount:=v_discount;
  NEW.total_price:=GREATEST(0,v_subtotal-v_discount);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_validate_and_clamp_booking_price"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_unique_referral_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
begin
  if new.referral_code is null then
    new.referral_code := upper(substring(md5(random()::text) from 1 for 8));
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."generate_unique_referral_code"() OWNER TO "postgres";


