CREATE OR REPLACE VIEW "public"."active_lounge_requests" WITH ("security_invoker"='true') AS
 SELECT "co"."id" AS "request_id",
    "co"."lounge_id",
    "co"."booking_id",
    "co"."user_id",
    'canteen_order'::"text" AS "request_type",
    "co"."status",
    "co"."is_attended",
    "co"."is_read",
    "co"."created_at",
    "to_jsonb"("co".*) AS "request_data"
   FROM "public"."canteen_orders" "co"
  WHERE (("co"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"])) AND ("co"."is_attended" IS FALSE))
UNION ALL
 SELECT "sc"."id" AS "request_id",
    "sc"."lounge_id",
    "sc"."booking_id",
    "sc"."user_id",
    'service_call'::"text" AS "request_type",
    "sc"."status",
    "sc"."is_attended",
    "sc"."is_read",
    "sc"."created_at",
    "to_jsonb"("sc".*) AS "request_data"
   FROM "public"."service_calls" "sc"
  WHERE (("sc"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"])) AND ("sc"."is_attended" IS FALSE))
UNION ALL
 SELECT "cr"."id" AS "request_id",
    "cr"."lounge_id",
    "cr"."booking_id",
    "cr"."user_id",
    'client_request'::"text" AS "request_type",
    "cr"."status",
    "cr"."is_attended",
    "cr"."is_read",
    "cr"."created_at",
    "to_jsonb"("cr".*) AS "request_data"
   FROM "public"."client_requests" "cr"
  WHERE (("cr"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"])) AND ("cr"."is_attended" IS FALSE))
UNION ALL
 SELECT "bi"."id" AS "request_id",
    "b"."lounge_id",
    "bi"."booking_id",
    "b"."user_id",
    'booking_item'::"text" AS "request_type",
    "bi"."status",
    "bi"."is_attended",
    "bi"."is_read",
    "bi"."created_at",
    ("to_jsonb"("bi".*) || "jsonb_build_object"('lounge_id', "b"."lounge_id", 'user_id', "b"."user_id")) AS "request_data"
   FROM ("public"."booking_items" "bi"
     JOIN "public"."bookings" "b" ON (("b"."id" = "bi"."booking_id")))
  WHERE (("bi"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"])) AND ("bi"."is_attended" IS FALSE));


ALTER VIEW "public"."active_lounge_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_lounge_requests"("p_lounge_id" "uuid") RETURNS SETOF "public"."active_lounge_requests"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.active_lounge_requests
  where lounge_id = p_lounge_id
  order by created_at desc;
$$;


ALTER FUNCTION "public"."get_active_lounge_requests"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_lounge_requests_page"("p_lounge_id" "uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS TABLE("data" "jsonb", "total_count" bigint, "page" integer, "page_size" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_offset integer;
  v_total bigint := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_lounge_id IS NULL OR p_page IS NULL OR p_page < 1 OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'Invalid lounge or pagination parameters' USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_super_admin() AND NOT private.is_lounge_member(p_lounge_id) THEN
    RAISE EXCEPTION 'Not authorized for this lounge' USING ERRCODE = '42501';
  END IF;

  v_offset := (p_page - 1) * p_page_size;

  WITH combined_requests AS (
    SELECT sc.id
    FROM public.service_calls AS sc
    LEFT JOIN public.bookings AS b ON sc.booking_id = b.id
    WHERE (sc.lounge_id = p_lounge_id OR b.lounge_id = p_lounge_id)
      AND COALESCE(sc.status, 'pending') IN ('pending', 'new', 'in_progress', 'active')
      AND COALESCE(sc.is_attended, false) IS NOT TRUE
      AND COALESCE(sc.call_type, '') <> 'canteen_order'
    UNION ALL
    SELECT co.id
    FROM public.canteen_orders AS co
    LEFT JOIN public.bookings AS b ON co.booking_id = b.id
    WHERE (co.lounge_id = p_lounge_id OR b.lounge_id = p_lounge_id)
      AND COALESCE(co.status, 'pending') IN ('pending', 'new', 'in_progress', 'active')
      AND COALESCE(co.is_attended, false) IS NOT TRUE
  )
  SELECT count(*) INTO v_total FROM combined_requests;

  RETURN QUERY
  WITH combined_requests AS (
    SELECT
      'sc_' || sc.id AS req_id,
      COALESCE(sc.lounge_id, b.lounge_id) AS req_lounge_id,
      sc.booking_id AS req_booking_id,
      'service_call'::text AS req_type,
      COALESCE(sc.call_type, sc.request_type, 'service_call') AS req_request_type,
      COALESCE(sc.note, sc.notes, 'طلب خدمة من العميل') AS req_message,
      COALESCE(sc.note, sc.notes, '') AS req_note,
      COALESCE(sc.status, 'pending') AS req_status,
      sc.created_at AS req_created_at,
      COALESCE(p.full_name, 'Guest') AS req_user_name,
      p.phone AS req_user_phone,
      COALESCE(r.name_ar, r.name_en, r.name, 'Room') AS req_room_name,
      '[]'::jsonb AS req_items
    FROM public.service_calls AS sc
    LEFT JOIN public.bookings AS b ON sc.booking_id = b.id
    LEFT JOIN public.profiles AS p ON COALESCE(sc.user_id, b.user_id) = p.id
    LEFT JOIN public.rooms AS r ON COALESCE(sc.room_id, b.room_id) = r.id
    WHERE (sc.lounge_id = p_lounge_id OR b.lounge_id = p_lounge_id)
      AND COALESCE(sc.status, 'pending') IN ('pending', 'new', 'in_progress', 'active')
      AND COALESCE(sc.is_attended, false) IS NOT TRUE
      AND COALESCE(sc.call_type, '') <> 'canteen_order'

    UNION ALL

    SELECT
      'canteen_' || co.id AS req_id,
      COALESCE(co.lounge_id, b.lounge_id) AS req_lounge_id,
      co.booking_id AS req_booking_id,
      'canteen_order'::text AS req_type,
      'canteen'::text AS req_request_type,
      'طلب كافيتريا (' || COALESCE(co.total_price, 0)::text || ' ج.م)' AS req_message,
      COALESCE(co.note, co.notes, '') AS req_note,
      COALESCE(co.status, 'pending') AS req_status,
      co.created_at AS req_created_at,
      COALESCE(p.full_name, 'Guest') AS req_user_name,
      p.phone AS req_user_phone,
      COALESCE(r.name_ar, r.name_en, r.name, 'Room') AS req_room_name,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'name', coi.item_name,
          'quantity', coi.quantity,
          'price', coi.unit_price,
          'total_price', coi.total_price
        ) ORDER BY coi.created_at)
        FROM public.canteen_order_items AS coi
        WHERE coi.order_id = co.id
      ), '[]'::jsonb) AS req_items
    FROM public.canteen_orders AS co
    LEFT JOIN public.bookings AS b ON co.booking_id = b.id
    LEFT JOIN public.profiles AS p ON COALESCE(co.user_id, b.user_id) = p.id
    LEFT JOIN public.rooms AS r ON b.room_id = r.id
    WHERE (co.lounge_id = p_lounge_id OR b.lounge_id = p_lounge_id)
      AND COALESCE(co.status, 'pending') IN ('pending', 'new', 'in_progress', 'active')
      AND COALESCE(co.is_attended, false) IS NOT TRUE
  )
  SELECT
    jsonb_build_object(
      'id', cr.req_id,
      'lounge_id', cr.req_lounge_id,
      'booking_id', cr.req_booking_id,
      'type', cr.req_type,
      'request_type', cr.req_request_type,
      'message', cr.req_message,
      'note', cr.req_note,
      'status', cr.req_status,
      'created_at', cr.req_created_at,
      'user_name', cr.req_user_name,
      'user_phone', cr.req_user_phone,
      'room_name', cr.req_room_name,
      'items', cr.req_items
    ),
    v_total,
    p_page,
    p_page_size
  FROM combined_requests AS cr
  ORDER BY cr.req_created_at DESC
  LIMIT p_page_size OFFSET v_offset;
END;
$$;


ALTER FUNCTION "public"."get_active_lounge_requests_page"("p_lounge_id" "uuid", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


