CREATE OR REPLACE FUNCTION "public"."get_active_promos"("p_lounge_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."promotions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT p.*
  FROM public.promotions AS p
  INNER JOIN public.lounges AS l ON l.id = p.lounge_id
  WHERE (p_lounge_id IS NULL OR p.lounge_id = p_lounge_id)
    AND l.status = 'active'
    AND p.is_active = true
    AND (p.expires_at IS NULL OR p.expires_at >= NOW())
  ORDER BY p.created_at DESC;
END;
$$;


