CREATE OR REPLACE FUNCTION "public"."get_active_session_details"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
    v_booking_id uuid;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT id INTO v_booking_id
    FROM public.bookings
    WHERE user_id = auth.uid()
      AND status = 'in_progress'::booking_status
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_booking_id IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN public.get_active_session_details(v_booking_id);
END;
$$;


ALTER FUNCTION "public"."get_active_session_details"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_session_details"("p_booking_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
BEGIN

  -- guard:caller_check
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.id = p_booking_id
      AND (b.user_id = auth.uid() OR private.is_lounge_member(b.lounge_id) OR public.is_super_admin())
  ) THEN
    RAISE EXCEPTION 'Not authorized' USING errcode = '42501';
  END IF;

  RETURN (
    SELECT json_build_object(
      'booking', b,
      'lounge', l,
      'room', r,
      'items', COALESCE((
        SELECT json_agg(
          json_build_object(
            'id', bi.id,
            'booking_id', bi.booking_id,
            'product_id', bi.product_id,
            'extra_id', bi.extra_id,
            'name', COALESCE(NULLIF(bi.name, ''), e.name_ar, e.name, 'صنف'),
            'quantity', bi.quantity,
            'unit_price', bi.unit_price,
            'total_price', bi.total_price,
            'status', bi.status,
            'note', bi.note,
            'is_attended', bi.is_attended,
            'created_at', bi.created_at
          ) ORDER BY bi.created_at
        )
        FROM public.booking_items bi
        LEFT JOIN public.extras e ON e.id = COALESCE(bi.extra_id, bi.product_id)
        WHERE bi.booking_id = b.id
      ), '[]'::json),
      'canteen_orders', COALESCE((
        SELECT json_agg(
          json_build_object(
            'id', co.id,
            'status', co.status,
            'total_price', co.total_price,
            'note', co.note,
            'created_at', co.created_at,
            'items', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'extra_id', x.value->>'extra_id',
                  'name', COALESCE(e2.name_ar, e2.name, x.value->>'name', 'صنف'),
                  'quantity', COALESCE((x.value->>'quantity')::integer, 1),
                  'unit_price', COALESCE((x.value->>'price')::numeric, e2.price, 0),
                  'total_price', COALESCE((x.value->>'price')::numeric, e2.price, 0) * COALESCE((x.value->>'quantity')::integer, 1)
                )
              )
              FROM jsonb_array_elements(COALESCE(co.items, '[]'::jsonb)) AS x(value)
              LEFT JOIN public.extras e2 ON e2.id::text = x.value->>'extra_id'
            ), '[]'::jsonb)
          ) ORDER BY co.created_at
        )
        FROM public.canteen_orders co
        WHERE co.booking_id = b.id
      ), '[]'::json)
    )
    FROM public.bookings b
    LEFT JOIN public.lounges l ON l.id = b.lounge_id
    LEFT JOIN public.rooms r ON r.id = b.room_id
    WHERE b.id = p_booking_id
  );
END;
$$;


ALTER FUNCTION "public"."get_active_session_details"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_bookings"() RETURNS TABLE("id" "uuid", "user_id" "uuid", "room_id" "uuid", "lounge_id" "uuid", "date" "date", "start_time" "text", "end_time" "text", "total_price" numeric, "status" "text", "payment_status" "text", "customer_name" "text", "customer_phone" "text", "room_name" "text", "duration_minutes" integer, "created_at" timestamp with time zone)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
  SELECT 
    b.id,
    b.user_id,
    b.room_id,
    b.lounge_id,
    b.date,
    b.start_time::text AS start_time,
    b.end_time::text AS end_time,
    b.total_price,
    b.status::text,
    b.payment_status::text,
    COALESCE(b.user_name, p.full_name, 'Unknown'),
    COALESCE(b.user_phone, p.phone, ''),
    COALESCE(b.room_name, r.name, ''),
    COALESCE(b.duration_minutes, 60),
    b.created_at
  FROM bookings b
  LEFT JOIN profiles p ON b.user_id = p.id
  LEFT JOIN rooms r ON b.room_id = r.id
  ORDER BY b.date DESC, b.start_time DESC;
$$;


ALTER FUNCTION "public"."get_all_bookings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_bookings_admin"("p_lounge_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_payment_status" "text" DEFAULT NULL::"text", "p_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_own_lounge uuid;
  v_target_lounge uuid;
  v_result JSONB;
BEGIN
  SELECT role, lounge_id INTO v_role, v_own_lounge
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_role IS NULL OR (v_role <> 'super_admin' AND v_own_lounge IS NULL) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'super_admin' THEN
    v_target_lounge := p_lounge_id;
  ELSE
    IF p_lounge_id IS NOT NULL AND p_lounge_id <> v_own_lounge THEN
      RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
    END IF;
    v_target_lounge := v_own_lounge;
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', b.id,
      'out_booking_id', b.id,
      'user_id', b.user_id,
      'lounge_id', b.lounge_id,
      'room_id', b.room_id,
      'user_name', COALESCE(b.user_name, p.full_name, 'Walk-in Customer'),
      'customer_name', COALESCE(b.user_name, p.full_name, 'Walk-in Customer'),
      'user_phone', COALESCE(b.user_phone, p.phone),
      'customer_phone', COALESCE(b.user_phone, p.phone),
      'user_email', p.email,
      'customer_email', p.email,
      'room_name', COALESCE(r.name_ar, r.name_en, r.name, 'Room'),
      'out_room_name', COALESCE(r.name_ar, r.name_en, r.name, 'Room'),
      'controllers_count', r.controllers_count,
      'screen_size', r.screen_size,
      'out_booking_date', b.date,
      'date', b.date,
      'out_start_time', b.start_time,
      'start_time', b.start_time,
      'out_end_time', b.end_time,
      'end_time', b.end_time,
      'duration_minutes', b.duration_minutes,
      'status', b.status,
      'out_booking_status', b.status,
      'payment_status', b.payment_status,
      'out_payment_status', b.payment_status,
      'payment_method', b.payment_method,
      'out_payment_method', b.payment_method,
      'total_price', b.total_price,
      'out_total_price', b.total_price,
      'addons_price', b.addons_price,
      'out_addons_price', b.addons_price,
      'voucher_code', b.applied_voucher_code,
      'discount_amount', b.discount_amount,
      'discount_percentage', b.discount_percentage,
      'discount_reason', b.discount_reason,
      'play_mode', b.play_mode,
      'room_price', b.room_price,
      'shift_id', b.shift_id,
      'created_at', b.created_at,
      'checked_in_at', b.checked_in_at,
      'canteen_orders', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'id', co.id,
            'items', co.items,
            'total_price', co.total_price,
            'status', co.status,
            'created_at', co.created_at
          )
        ), '[]'::jsonb)
        FROM public.canteen_orders co
        WHERE co.booking_id = b.id
      ),
      'extras', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'id', bi.id,
            'extra_id', bi.extra_id,
            'name', bi.name,
            'quantity', bi.quantity,
            'unit_price', bi.unit_price,
            'total_price', bi.total_price,
            'status', bi.status
          )
        ), '[]'::jsonb)
        FROM public.booking_items bi
        WHERE bi.booking_id = b.id
      )
    )
  ), '[]'::jsonb) INTO v_result
  FROM (
    SELECT bk.*
    FROM public.bookings bk
    LEFT JOIN public.profiles pr ON bk.user_id = pr.id
    LEFT JOIN public.rooms rm ON bk.room_id = rm.id
    WHERE (v_target_lounge IS NULL OR bk.lounge_id = v_target_lounge)
      AND (p_status IS NULL OR p_status = '' OR bk.status::text = p_status)
      AND (p_payment_status IS NULL OR p_payment_status = '' OR bk.payment_status = p_payment_status)
      AND (p_date IS NULL OR bk.date = p_date)
      AND (
        p_search IS NULL
        OR p_search = ''
        OR bk.id::text ILIKE '%' || p_search || '%'
        OR bk.user_name ILIKE '%' || p_search || '%'
        OR bk.user_phone ILIKE '%' || p_search || '%'
        OR pr.full_name ILIKE '%' || p_search || '%'
        OR pr.phone ILIKE '%' || p_search || '%'
        OR pr.email ILIKE '%' || p_search || '%'
        OR rm.name ILIKE '%' || p_search || '%'
      )
    ORDER BY bk.created_at DESC
    LIMIT p_limit
    OFFSET p_offset
  ) b
  LEFT JOIN public.profiles p ON b.user_id = p.id
  LEFT JOIN public.rooms r ON b.room_id = r.id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_all_bookings_admin"("p_lounge_id" "uuid", "p_status" "text", "p_limit" integer, "p_offset" integer, "p_search" "text", "p_payment_status" "text", "p_date" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."lounges" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid",
    "name" "text" NOT NULL,
    "image_url" "text",
    "images" "text"[],
    "location" "text",
    "city" "text" DEFAULT 'Cairo'::"text",
    "maps_link" "text",
    "rating" numeric DEFAULT 0,
    "total_reviews" integer DEFAULT 0,
    "available_rooms" integer DEFAULT 0,
    "is_open" boolean DEFAULT true,
    "status" "text" DEFAULT 'pending'::"text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "location_point" "public"."geography"(Point,4326),
    "description_ar" "text",
    "description_en" "text",
    "address" "text",
    "contact_phone" "text",
    "opening_time" time without time zone,
    "closing_time" time without time zone,
    "is_active" boolean DEFAULT true,
    "has_discount" boolean DEFAULT false,
    "discount_percentage" integer DEFAULT 0,
    "discount_title_ar" "text",
    "discount_title_en" "text",
    "discount_expires_at" timestamp with time zone,
    "name_ar" "text",
    "name_en" "text",
    "city_id" "uuid",
    "vodafone_cash_number" "text",
    "instapay_account" "text",
    "allow_cash_payment" boolean DEFAULT true NOT NULL,
    "require_prepaid_first_time" boolean DEFAULT true NOT NULL,
    "cash_grace_period_minutes" integer DEFAULT 10 NOT NULL,
    "wallet_number" "text",
    "instapay_handle" "text",
    "suspension_reason" "text",
    "brand_id" "uuid",
    "branch_name" character varying(255),
    "is_main_branch" boolean DEFAULT false NOT NULL,
    "parent_lounge_id" "uuid",
    "allow_open_time_sessions" boolean DEFAULT false NOT NULL,
    "open_time_rounding_minutes" integer DEFAULT 15 NOT NULL,
    "open_time_minimum_minutes" integer DEFAULT 60 NOT NULL,
    "open_time_max_minutes" integer DEFAULT 720 NOT NULL,
    "timezone" "text" DEFAULT 'Africa/Cairo'::"text" NOT NULL,
    "allow_future_bookings" boolean DEFAULT true NOT NULL,
    "allow_request_without_shift" boolean DEFAULT true NOT NULL,
    "future_booking_max_days_advance" integer DEFAULT 14 NOT NULL,
    "unconfirmed_alert_lead_minutes" integer DEFAULT 60 NOT NULL,
    "require_deposit_for_future" boolean DEFAULT false NOT NULL,
    "future_deposit_percentage" integer DEFAULT 20 NOT NULL,
    CONSTRAINT "lounges_cash_grace_period_minutes_check" CHECK ((("cash_grace_period_minutes" >= 0) AND ("cash_grace_period_minutes" <= 1440))),
    CONSTRAINT "lounges_future_booking_limits_check" CHECK (((("future_booking_max_days_advance" >= 1) AND ("future_booking_max_days_advance" <= 90)) AND (("unconfirmed_alert_lead_minutes" >= 15) AND ("unconfirmed_alert_lead_minutes" <= 1440)) AND (("future_deposit_percentage" >= 0) AND ("future_deposit_percentage" <= 100)))),
    CONSTRAINT "lounges_open_time_max_minutes_check" CHECK ((("open_time_max_minutes" >= 60) AND ("open_time_max_minutes" <= 1440))),
    CONSTRAINT "lounges_open_time_minimum_minutes_check" CHECK ((("open_time_minimum_minutes" >= 15) AND ("open_time_minimum_minutes" <= 240))),
    CONSTRAINT "lounges_open_time_policy_order_check" CHECK (("open_time_max_minutes" >= "open_time_minimum_minutes")),
    CONSTRAINT "lounges_open_time_rounding_minutes_check" CHECK (("open_time_rounding_minutes" = ANY (ARRAY[5, 10, 15, 30, 60]))),
    CONSTRAINT "lounges_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'rejected'::"text", 'disabled'::"text", 'deleted'::"text"])))
);


