CREATE OR REPLACE FUNCTION "public"."get_all_payouts"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result json;
BEGIN
