CREATE OR REPLACE FUNCTION "public"."get_booking_cancellation_summary"("p_lounge_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_lounge_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'lounge_id and user_id are required.'
      USING ERRCODE = '22023';
  END IF;

  IF (SELECT auth.uid()) IS NULL
     OR NOT private.is_lounge_member(p_lounge_id) THEN
    RAISE EXCEPTION 'Not authorized to view booking cancellation history for this lounge.'
      USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'after_approval_count', count(*)::integer,
    'last_90_days_count', count(*) FILTER (
      WHERE e.cancelled_at >= statement_timestamp() - interval '90 days'
    )::integer,
    'history', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'event_id', h.id,
          'booking_id', h.booking_id,
          'cancelled_at', h.cancelled_at,
          'cancellation_reason', h.cancellation_reason,
          'booking_date', h.booking_date,
          'start_time', h.start_time,
          'end_time', h.end_time,
          'room_name', h.room_name,
          'cancelled_by', h.cancelled_by
        ) ORDER BY h.cancelled_at DESC
      )
      FROM (
        SELECT e2.id, e2.booking_id, e2.cancelled_at,
               e2.cancellation_reason, e2.booking_date,
               e2.start_time, e2.end_time, e2.room_name, e2.cancelled_by
        FROM private.booking_cancellation_events AS e2
        WHERE e2.lounge_id = p_lounge_id
          AND e2.user_id = p_user_id
          AND e2.was_approved = true
          AND e2.cancellation_source = 'user'
        ORDER BY e2.cancelled_at DESC
        LIMIT 50
      ) AS h
    ), '[]'::jsonb)
  )
  INTO v_result
  FROM private.booking_cancellation_events AS e
  WHERE e.lounge_id = p_lounge_id
    AND e.user_id = p_user_id
    AND e.was_approved = true
    AND e.cancellation_source = 'user';

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_booking_cancellation_summary"("p_lounge_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_booking_payment_destination"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_has_open_shift boolean;
  v_amount_due numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT b.* INTO v_booking FROM public.bookings b WHERE b.id = p_booking_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.user_id IS DISTINCT FROM auth.uid()
     AND NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_booking.lounge_id, 'billing_checkout') THEN
    RAISE EXCEPTION 'Not authorized to view payment details for this booking' USING ERRCODE = '42501';
  END IF;

  SELECT l.* INTO v_lounge FROM public.lounges l WHERE l.id = v_booking.lounge_id;

  SELECT EXISTS (
    SELECT 1 FROM public.shifts s
    WHERE s.lounge_id = v_booking.lounge_id
      AND s.status = 'open'
      AND s.closed_at IS NULL
  ) INTO v_has_open_shift;

  -- Security Gate: Cannot view payment destinations or submit receipts if unconfirmed or no shift
  IF v_booking.confirmation_status = 'pending_confirmation' OR v_has_open_shift IS FALSE THEN
    RETURN jsonb_build_object(
      'can_pay', false,
      'booking_id', p_booking_id,
      'confirmation_status', v_booking.confirmation_status,
      'has_open_shift', v_has_open_shift,
      'reason', 'SHIFT_NOT_OPEN_OR_NOT_CONFIRMED',
      'message_ar', 'لا يمكن تحويل الأموال أو إرسال الإيصال قبل فتح الشيفت وتأكيد الصالة للحجز',
      'message_en', 'Payment destination is withheld until the lounge opens a shift and confirms your booking request.'
    );
  END IF;

  IF v_booking.deposit_required AND NOT v_booking.deposit_paid THEN
    v_amount_due := v_booking.deposit_amount;
  ELSE
    v_amount_due := GREATEST(0, v_booking.total_price);
  END IF;

  RETURN jsonb_build_object(
    'can_pay', true,
    'booking_id', p_booking_id,
    'lounge_id', v_lounge.id,
    'lounge_name', v_lounge.name,
    'confirmation_status', v_booking.confirmation_status,
    'has_open_shift', true,
    'amount_due', v_amount_due,
    'deposit_required', v_booking.deposit_required,
    'instapay_account', v_lounge.instapay_account,
    'instapay_handle', v_lounge.instapay_handle,
    'vodafone_cash_number', v_lounge.vodafone_cash_number,
    'wallet_number', v_lounge.wallet_number
  );
END;
$$;


ALTER FUNCTION "public"."get_booking_payment_destination"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_booking_timeline_for_customer"("p_booking_id" "uuid") RETURNS TABLE("id" "text", "event_code" "text", "title_ar" "text", "title_en" "text", "occurred_at" timestamp with time zone, "payload" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_booking public.bookings%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='42501';
  END IF;
  SELECT b.* INTO v_booking FROM public.bookings b
  WHERE b.id=p_booking_id AND b.user_id=auth.uid();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'BOOKING_NOT_ACCESSIBLE' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
  WITH recorded AS (
    SELECT 'audit:'||a.id::text event_id,a.created_at event_time,
      CASE
        WHEN a.action='insert' THEN 'booking_created'
        WHEN a.new_data->>'status' IS DISTINCT FROM a.old_data->>'status' THEN
          CASE a.new_data->>'status'
            WHEN 'in_progress' THEN 'booking_checked_in'
            WHEN 'completed' THEN 'booking_completed'
            WHEN 'cancelled' THEN 'booking_cancelled'
            WHEN 'upcoming' THEN 'booking_approved' END
        WHEN a.new_data->>'extension_status' IS DISTINCT FROM a.old_data->>'extension_status' THEN
          CASE a.new_data->>'extension_status'
            WHEN 'pending' THEN 'booking_extension_requested'
            WHEN 'approved' THEN 'booking_extension_approved'
            WHEN 'rejected' THEN 'booking_extension_rejected' END
      END code
    FROM public.shift_audit_logs a
    WHERE a.entity_type='booking' AND a.entity_id=p_booking_id
  ), fallback AS (
    SELECT 'booking:'||v_booking.id::text||':'||s.code event_id,s.event_time,s.code
    FROM (VALUES
      ('booking_created',v_booking.created_at),
      ('booking_approved',v_booking.approved_at),
      ('booking_checked_in',v_booking.checked_in_at),
      ('booking_cancelled',v_booking.cancelled_at),
      ('booking_completed',CASE WHEN v_booking.status='completed' THEN v_booking.cashier_closed_at END)
    ) s(code,event_time)
    WHERE s.event_time IS NOT NULL AND NOT EXISTS (SELECT 1 FROM recorded r WHERE r.code=s.code)
  ), events AS (
    SELECT * FROM recorded WHERE code IS NOT NULL
    UNION ALL SELECT * FROM fallback
  )
  SELECT e.event_id,e.code,
    CASE e.code
      WHEN 'booking_created' THEN 'تم إنشاء الحجز'
      WHEN 'booking_approved' THEN 'تم تأكيد الحجز'
      WHEN 'booking_checked_in' THEN 'بدأت الجلسة'
      WHEN 'booking_completed' THEN 'انتهت الجلسة'
      WHEN 'booking_cancelled' THEN 'تم إلغاء الحجز'
      WHEN 'booking_extension_requested' THEN 'طلب تمديد الجلسة'
      WHEN 'booking_extension_approved' THEN 'تمت الموافقة على التمديد'
      WHEN 'booking_extension_rejected' THEN 'تم رفض التمديد' END,
    CASE e.code
      WHEN 'booking_created' THEN 'Booking placed'
      WHEN 'booking_approved' THEN 'Booking confirmed'
      WHEN 'booking_checked_in' THEN 'Session started'
      WHEN 'booking_completed' THEN 'Session completed'
      WHEN 'booking_cancelled' THEN 'Booking cancelled'
      WHEN 'booking_extension_requested' THEN 'Extension requested'
      WHEN 'booking_extension_approved' THEN 'Extension approved'
      WHEN 'booking_extension_rejected' THEN 'Extension rejected' END,
    e.event_time,'{}'::jsonb
  FROM events e ORDER BY e.event_time,e.event_id;
END $$;


ALTER FUNCTION "public"."get_booking_timeline_for_customer"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_canteen_menu"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now timestamp := timezone('Africa/Cairo', now());
  v_dow integer := extract(dow from timezone('Africa/Cairo', now()))::integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.lounges AS l
    WHERE l.id = p_lounge_id
      AND COALESCE(l.is_active,true) IS TRUE
      AND COALESCE(l.status,'active') <> 'deleted'
  ) THEN
    RAISE EXCEPTION 'Lounge not found' USING ERRCODE='P0002';
  END IF;

  SELECT timezone(l.timezone,now()) INTO v_now FROM public.lounges l WHERE l.id = p_lounge_id;
  v_dow := extract(dow FROM v_now)::integer;

  RETURN jsonb_build_object(
    'extras',
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', e.id,
          'lounge_id', e.lounge_id,
          'name', e.name,
          'name_ar', e.name_ar,
          'name_en', e.name_en,
          'price', e.price,
          'category', e.category,
          'icon_key', e.icon_key,
          'image_url', e.image_url,
          'is_available', COALESCE(e.is_available,true)
            AND (
              COALESCE(e.track_stock,false) IS FALSE
              OR COALESCE(e.stock_quantity,0) > 0
            ),
          'stock_quantity', COALESCE(e.stock_quantity,0),
          'track_stock', COALESCE(e.track_stock,false),
          'min_stock_alert', COALESCE(e.min_stock_alert,5)
        )
        ORDER BY e.category, COALESCE(e.name_en,e.name_ar,e.name)
      )
      FROM public.extras AS e
      WHERE e.lounge_id = p_lounge_id
        AND COALESCE(e.is_active,true) IS TRUE
        AND COALESCE(e.is_available,true) IS TRUE
    ), '[]'::jsonb),
    'combos',
    COALESCE((
      SELECT jsonb_agg(combo_payload ORDER BY sort_order, name_ar)
      FROM (
        SELECT
          c.sort_order,
          c.name_ar,
          jsonb_build_object(
            'id', c.id,
            'name_ar', c.name_ar,
            'name_en', c.name_en,
            'description_ar', c.description_ar,
            'description_en', c.description_en,
            'price', c.price,
            'image_url', c.image_url,
            'separate_items_price', COALESCE((
              SELECT sum(e.price * ci.quantity)
              FROM public.canteen_combo_items AS ci
              JOIN public.extras AS e ON e.id = ci.extra_id
              WHERE ci.combo_id = c.id
            ),0),
            'savings', GREATEST(
              0,
              COALESCE((
                SELECT sum(e.price * ci.quantity)
                FROM public.canteen_combo_items AS ci
                JOIN public.extras AS e ON e.id = ci.extra_id
                WHERE ci.combo_id = c.id
              ),0) - c.price
            ),
            'is_available',
              private.canteen_combo_window_available(c,v_now)
              AND EXISTS (SELECT 1 FROM public.canteen_combo_items ci WHERE ci.combo_id = c.id)
              AND (c.valid_from IS NULL OR v_now::date >= c.valid_from)
              AND (c.valid_to IS NULL OR v_now::date <= c.valid_to)
              AND (c.days_of_week IS NULL OR v_dow = ANY(c.days_of_week))
              AND (
                c.available_from IS NULL
                OR c.available_to IS NULL
                OR CASE
                  WHEN c.available_to > c.available_from
                    THEN v_now::time >= c.available_from
                     AND v_now::time < c.available_to
                  ELSE v_now::time >= c.available_from
                    OR v_now::time < c.available_to
                END
              )
              AND NOT EXISTS (
                SELECT 1
                FROM public.canteen_combo_items AS ci
                JOIN public.extras AS e ON e.id = ci.extra_id
                WHERE ci.combo_id = c.id
                  AND (
                    e.lounge_id IS DISTINCT FROM p_lounge_id
                    OR COALESCE(e.is_active,true) IS FALSE
                    OR COALESCE(e.is_available,true) IS FALSE
                    OR (
                      COALESCE(e.track_stock,false) IS TRUE
                      AND COALESCE(e.stock_quantity,0) < ci.quantity
                    )
                  )
              ),
            'items', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'extra_id', e.id,
                  'name_ar', COALESCE(e.name_ar,e.name),
                  'name_en', COALESCE(e.name_en,e.name),
                  'price', e.price,
                  'quantity', ci.quantity
                )
                ORDER BY COALESCE(e.name_en,e.name_ar,e.name)
              )
              FROM public.canteen_combo_items AS ci
              JOIN public.extras AS e ON e.id = ci.extra_id
              WHERE ci.combo_id = c.id
            ), '[]'::jsonb)
          ) AS combo_payload
        FROM public.canteen_combos AS c
        WHERE c.lounge_id = p_lounge_id
          AND COALESCE(c.is_active,true) IS TRUE
          AND (c.valid_from IS NULL OR v_now::date >= c.valid_from)
          AND (c.valid_to IS NULL OR v_now::date <= c.valid_to)
          AND (c.days_of_week IS NULL OR v_dow = ANY(c.days_of_week))
      ) AS q
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_canteen_menu"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cashier_performance"("p_lounge_id" "uuid", "p_start_date" "date" DEFAULT CURRENT_DATE, "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("cashier_id" "uuid", "cashier_name" "text", "shift_count" bigint, "closed_shift_count" bigint, "approved_shift_count" bigint, "total_sales" numeric, "cash_sales" numeric, "digital_sales" numeric, "total_expenses" numeric, "total_difference" numeric, "average_shift_sales" numeric, "open_shift_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
  IF NOT private.can_view_shift_financials(p_lounge_id) THEN RAISE EXCEPTION 'Financial report access denied' USING ERRCODE='42501'; END IF;
  IF auth.uid() IS NULL
     OR (
       COALESCE((SELECT private.current_user_role()), '') <> 'super_admin'
       AND NOT COALESCE((SELECT private.is_lounge_member(p_lounge_id)), false)
     ) THEN
    RAISE EXCEPTION 'Not authorized for this lounge.';
  END IF;

  RETURN QUERY
  SELECT
    COALESCE(s.cashier_id, s.staff_user_id),
    COALESCE(p.full_name, 'Cashier'),
    COUNT(DISTINCT s.id),
    COUNT(DISTINCT s.id) FILTER (WHERE s.status = 'closed'),
    COUNT(DISTINCT s.id) FILTER (WHERE COALESCE(s.is_approved, false)),
    COALESCE(SUM(sp.amount), 0),
    COALESCE(SUM(sp.amount) FILTER (WHERE sp.payment_method = 'cash'), 0),
    COALESCE(SUM(sp.amount) FILTER (WHERE sp.payment_method <> 'cash'), 0),
    COALESCE(SUM(s.total_expenses), 0),
    COALESCE(SUM(s.difference) FILTER (WHERE s.status = 'closed'), 0),
    COALESCE(SUM(sp.amount), 0) / NULLIF(COUNT(DISTINCT s.id), 0),
    COUNT(DISTINCT s.id) FILTER (WHERE s.status = 'open')
  FROM public.shifts s
  LEFT JOIN public.profiles p ON p.id = COALESCE(s.cashier_id, s.staff_user_id)
  LEFT JOIN public.shift_payments sp ON sp.shift_id = s.id
  WHERE s.lounge_id = p_lounge_id
    AND s.opened_at::date BETWEEN p_start_date AND p_end_date
  GROUP BY COALESCE(s.cashier_id, s.staff_user_id), p.full_name;
END;
$$;


ALTER FUNCTION "public"."get_cashier_performance"("p_lounge_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cashier_sync_conflicts"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
 PERFORM private.assert_cashier_conflict_reviewer(p_lounge_id);
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('operation_id',r.operation_id,'sequence',r.sequence,
  'kind',r.request->>'kind','booking_id',r.request->>'booking_id','actor_id',r.actor_id,
  'code',coalesce(latest.result->>'code',r.result->>'code'),'request',r.request,
  'retry_pending',EXISTS(SELECT 1 FROM private.cashier_conflict_reviews a WHERE a.operation_id=r.operation_id
   AND NOT EXISTS(SELECT 1 FROM private.cashier_conflict_outcomes o WHERE o.review_id=a.id))) ORDER BY r.sequence)
 FROM private.cashier_operation_receipts r LEFT JOIN LATERAL
  (SELECT o.result FROM private.cashier_conflict_outcomes o JOIN private.cashier_conflict_reviews a ON a.id=o.review_id
   WHERE a.operation_id=r.operation_id ORDER BY o.created_at DESC LIMIT 1) latest ON true
 WHERE r.lounge_id=p_lounge_id AND r.result->>'status'='conflict'
  AND NOT EXISTS(SELECT 1 FROM private.cashier_conflict_reviews a JOIN private.cashier_conflict_outcomes o ON o.review_id=a.id
   WHERE a.operation_id=r.operation_id AND o.result->>'status'='applied')),'[]'::jsonb);
END; $$;


