CREATE OR REPLACE FUNCTION "public"."get_dashboard_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_total_revenue NUMERIC := 0;
  v_total_bookings INT := 0;
  v_total_lounges INT := 0;
  v_total_users INT := 0;
BEGIN
  -- Strict Authorization: Only Super Admin allowed
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Unauthorized: Global overview requires Super Admin privilege' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(SUM(total_price), 0) INTO v_total_revenue
  FROM public.bookings
  WHERE status != 'cancelled';

  SELECT COUNT(*) INTO v_total_bookings FROM public.bookings;
  SELECT COUNT(*) INTO v_total_lounges FROM public.lounges WHERE status != 'deleted';
  SELECT COUNT(*) INTO v_total_users FROM public.profiles;

  RETURN jsonb_build_object(
    'total_revenue', v_total_revenue,
    'total_bookings', v_total_bookings,
    'total_lounges', v_total_lounges,
    'total_users', v_total_users
  );
END;
$$;


ALTER FUNCTION "public"."get_dashboard_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_discovery_activities"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', activity.id,
        'name_ar', activity.display_name,
        'name_en', activity.display_name,
        'icon_key', activity.icon_key,
        'activity_category', activity.activity_category,
        'rooms_count', activity.rooms_count,
        'lounges_count', activity.lounges_count
      )
      ORDER BY activity.sort_order, activity.display_name, activity.id
    ),
    '[]'::jsonb
  )
  FROM (
    SELECT
      a.id,
      COALESCE(
        NULLIF(btrim(a.label), ''),
        initcap(replace(a.name, '_', ' '))
      ) AS display_name,
      COALESCE(NULLIF(btrim(a.icon_name), ''), 'category') AS icon_key,
      COALESCE(NULLIF(btrim(a.category), ''), 'other') AS activity_category,
      COALESCE(a.sort_order, 9999) AS sort_order,
      count(DISTINCT r.id) AS rooms_count,
      count(DISTINCT r.lounge_id) AS lounges_count
    FROM public.activity_types AS a
    JOIN public.room_activities AS ra
      ON ra.activity_type_id = a.id
    JOIN public.rooms AS r
      ON r.id = ra.room_id
    JOIN public.lounges AS l
      ON l.id = r.lounge_id
    WHERE COALESCE(r.is_active, true) IS TRUE
      AND COALESCE(r.status, 'available') <> 'deleted'
      AND l.status = 'active'
      AND l.is_active IS TRUE
    GROUP BY
      a.id,
      a.label,
      a.name,
      a.icon_name,
      a.category,
      a.sort_order
  ) AS activity;
$$;


ALTER FUNCTION "public"."get_discovery_activities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_home_tournament"() RETURNS TABLE("id" "uuid", "lounge_id" "uuid", "city_id" "uuid", "title_ar" "text", "title_en" "text", "description_ar" "text", "description_en" "text", "game_name" "text", "banner_url" "text", "entry_fee" numeric, "max_participants" integer, "registration_closes_at" timestamp with time zone, "tournament_starts_at" timestamp with time zone, "status" "text", "lounge_name" "text", "city_name_ar" "text", "city_name_en" "text", "participant_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    t.id,
    t.lounge_id,
    t.city_id,
    t.title_ar,
    t.title_en,
    t.description_ar,
    t.description_en,
    t.game_name,
    t.banner_url,
    t.entry_fee,
    t.max_participants,
    t.registration_closes_at,
    t.tournament_starts_at,
    t.status,
    l.name as lounge_name,
    c.name_ar as city_name_ar,
    c.name_en as city_name_en,
    count(tp.id) filter (where tp.registration_status not in ('cancelled', 'withdrawn', 'expired')) as participant_count
  from public.tournaments t
  left join public.lounges l on l.id = t.lounge_id
  left join public.cities c on c.id = t.city_id
  left join public.tournament_participants tp on tp.tournament_id = t.id
  left join public.profiles p on p.id = auth.uid()
  where t.status = 'registration_open'
    and t.registration_opens_at <= now()
    and t.registration_closes_at > now()
    and (
      t.visibility_scope = 'all'
      or (t.visibility_scope = 'city' and t.city_id = p.city_id)
      or (t.visibility_scope = 'radius' and t.city_id = p.city_id)
    )
    and not exists (
      select 1
      from public.tournament_participants mine
      where mine.tournament_id = t.id
        and mine.user_id = auth.uid()
        and mine.registration_status not in ('cancelled', 'withdrawn', 'expired')
    )
  group by t.id, l.name, c.name_ar, c.name_en, p.city_id
  order by
    case when t.city_id = p.city_id then 0 else 1 end,
    t.registration_closes_at asc,
    t.tournament_starts_at asc
  limit 1;
$$;


ALTER FUNCTION "public"."get_home_tournament"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_live_bookings"("p_lounge_id" "uuid") RETURNS SETOF "public"."bookings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_role text;
BEGIN
  -- جلب دور المستخدم المسجل دخوله
  SELECT role INTO v_role 
  FROM public.profiles 
  WHERE id = auth.uid() AND lounge_id = p_lounge_id;

  -- التحقق من الصلاحيات بما فيها lounge_admin
  IF v_role NOT IN ('owner', 'manager', 'lounge_admin', 'admin', 'cashier', 'super_admin') THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = 'P0001';
  END IF;

  RETURN QUERY
  SELECT * FROM public.bookings
  WHERE lounge_id = p_lounge_id
  ORDER BY created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_live_bookings"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_live_bookings_with_items"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Invalid lounge_id parameter';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR EXISTS (
      SELECT 1 FROM public.lounges l
      WHERE l.id = p_lounge_id AND l.owner_id = auth.uid()
    )
    OR public.has_lounge_permission(p_lounge_id, 'bookings.view')
    OR public.has_lounge_permission(p_lounge_id, 'sessions_control')
  ) THEN
    RAISE EXCEPTION 'Unauthorized: You do not have permission to view live bookings for this lounge' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', b.id,
      'out_booking_id', b.id,
      'lounge_id', b.lounge_id,
      'user_id', b.user_id,
      'room_id', b.room_id,
      'start_time', b.start_time,
      'end_time', b.end_time,
      'duration_minutes', b.duration_minutes,
      'total_price', b.total_price,
      'addons_price', b.addons_price,
      'status', b.status,
      'created_at', b.created_at,
      'user_name', COALESCE(b.user_name, p.full_name, 'Walk-in Customer'),
      'user_phone', COALESCE(b.user_phone, p.phone),
      'room_name', COALESCE(r.name_ar, r.name_en, r.name, 'Room'),
      'visit_number', b.visit_num,
      'out_visit_number', b.visit_num,
      'canteen_orders', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'id', co.id,
            'items', co.items,
            'total_price', co.total_price,
            'status', co.status,
            'created_at', co.created_at
          )
        ), '[]'::jsonb)
        FROM public.canteen_orders co
        WHERE co.booking_id = b.id
      )
    )
  ), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      bk.*,
      (
        SELECT 1 + count(DISTINCT previous.created_at)
        FROM public.bookings AS previous
        WHERE previous.lounge_id = bk.lounge_id
          AND previous.created_at < bk.created_at
          AND previous.status IN ('in_progress'::public.booking_status, 'completed'::public.booking_status)
          AND (
            (bk.user_id IS NOT NULL AND previous.user_id = bk.user_id)
            OR (
              bk.user_id IS NULL
              AND previous.user_id IS NULL
              AND NULLIF(btrim(bk.user_phone), '') IS NOT NULL
              AND bk.user_phone NOT IN ('null', 'No Phone')
              AND btrim(previous.user_phone) = btrim(bk.user_phone)
            )
          )
      ) AS visit_num
    FROM public.bookings bk
    WHERE bk.lounge_id = p_lounge_id AND bk.status = 'in_progress'::public.booking_status
    ORDER BY bk.created_at DESC
  ) b
  LEFT JOIN public.profiles p ON b.user_id = p.id
  LEFT JOIN public.rooms r ON b.room_id = r.id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_live_bookings_with_items"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_activities"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_activities jsonb;
BEGIN
  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Lounge ID is required' USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'activity_id', sub.activity_id,
      'name', sub.name,
      'label', sub.label,
      'category', sub.category,
      'icon_name', sub.icon_name,
      'requires_screen', sub.requires_screen,
      'requires_controllers', sub.requires_controllers,
      'pricing_model', sub.pricing_model,
      'rooms_count', sub.rooms_count,
      'available_rooms_count', sub.available_rooms_count,
      'min_hourly_rate', sub.min_rate,
      'max_hourly_rate', sub.max_rate
    )
    ORDER BY sub.sort_order ASC, sub.rooms_count DESC
  )
  INTO v_activities
  FROM (
    SELECT
      a.id AS activity_id,
      a.name,
      a.label,
      COALESCE(a.category, 'console') AS category,
      COALESCE(a.icon_name, 'sports_esports') AS icon_name,
      COALESCE(a.requires_screen, true) AS requires_screen,
      COALESCE(a.requires_controllers, true) AS requires_controllers,
      COALESCE(a.pricing_model, 'per_room_hour') AS pricing_model,
      a.sort_order,
      count(r.id) AS rooms_count,
      count(r.id) FILTER (WHERE r.is_available IS TRUE AND r.status = 'available') AS available_rooms_count,
      ROUND(COALESCE(min(r.hourly_rate_single), 0), 2) AS min_rate,
      ROUND(COALESCE(max(r.hourly_rate_single), 0), 2) AS max_rate
    FROM public.activity_types a
    JOIN public.room_activities ra ON ra.activity_type_id = a.id
    JOIN public.rooms r ON r.id = ra.room_id
    WHERE r.lounge_id = p_lounge_id
      AND COALESCE(r.is_active, true) IS TRUE
      AND COALESCE(r.status, 'available') <> 'deleted'
    GROUP BY a.id, a.name, a.label, a.category, a.icon_name, a.requires_screen,
             a.requires_controllers, a.pricing_model, a.sort_order
  ) AS sub;

  RETURN COALESCE(v_activities, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_lounge_activities"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_booking_capabilities"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lounge public.lounges%ROWTYPE;
  v_has_open_shift boolean;
BEGIN
  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Lounge ID is required' USING ERRCODE = '22023';
  END IF;

  SELECT l.* INTO v_lounge FROM public.lounges l WHERE l.id = p_lounge_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lounge not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.shifts s
    WHERE s.lounge_id = p_lounge_id
      AND s.status = 'open'
      AND s.closed_at IS NULL
  ) INTO v_has_open_shift;

  RETURN jsonb_build_object(
    'lounge_id', p_lounge_id,
    'is_open', COALESCE(v_lounge.is_open, false),
    'has_open_shift', v_has_open_shift,
    'allow_future_bookings', COALESCE(v_lounge.allow_future_bookings, true),
    'allow_request_without_shift', COALESCE(v_lounge.allow_request_without_shift, true),
    'future_booking_max_days_advance', COALESCE(v_lounge.future_booking_max_days_advance, 14),
    'unconfirmed_alert_lead_minutes', COALESCE(v_lounge.unconfirmed_alert_lead_minutes, 60),
    'require_deposit_for_future', COALESCE(v_lounge.require_deposit_for_future, false),
    'future_deposit_percentage', COALESCE(v_lounge.future_deposit_percentage, 20),
    'allow_open_time_sessions', COALESCE(v_lounge.allow_open_time_sessions, false),
    'allow_cash_payment', COALESCE(v_lounge.allow_cash_payment, true)
  );
END;
$$;


ALTER FUNCTION "public"."get_lounge_booking_capabilities"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_booking_rooms"("p_lounge_id" "uuid", "p_activity_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rooms jsonb;
BEGIN
  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Lounge ID is required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.lounges AS l
    WHERE l.id = p_lounge_id
      AND l.status = 'active'
      AND l.is_active IS TRUE
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(
    jsonb_agg(room_payload ORDER BY room_name, room_id),
    '[]'::jsonb
  )
  INTO v_rooms
  FROM (
    SELECT
      r.id AS room_id,
      COALESCE(r.name_en, r.name_ar, r.name, '') AS room_name,
      to_jsonb(r)
      || jsonb_build_object(
        'space_types',
        CASE
          WHEN st.id IS NULL THEN NULL
          ELSE jsonb_build_object(
            'id', st.id,
            'name', st.name,
            'label', st.label
          )
        END,
        'room_activities',
        COALESCE(
          (
            SELECT jsonb_agg(
              jsonb_build_object(
                'activity_type_id', a.id,
                'activity_types', jsonb_build_object(
                  'id', a.id,
                  'name', a.name,
                  'label', a.label,
                  'category', a.category,
                  'icon_name', a.icon_name,
                  'pricing_model', a.pricing_model,
                  'requires_screen', a.requires_screen,
                  'requires_controllers', a.requires_controllers
                )
              )
              ORDER BY COALESCE(a.sort_order, 9999), a.label, a.name
            )
            FROM public.room_activities AS ra
            JOIN public.activity_types AS a
              ON a.id = ra.activity_type_id
            WHERE ra.room_id = r.id
          ),
          '[]'::jsonb
        ),
        'promotions',
        COALESCE(
          (
            SELECT jsonb_agg(to_jsonb(pr) ORDER BY pr.created_at DESC)
            FROM public.promotions AS pr
            WHERE pr.is_active IS TRUE
              AND (pr.expires_at IS NULL OR pr.expires_at > now())
              AND (
                pr.room_id = r.id
                OR (pr.room_id IS NULL AND pr.lounge_id = r.lounge_id)
              )
          ),
          '[]'::jsonb
        )
      ) AS room_payload
    FROM public.rooms AS r
    LEFT JOIN public.space_types AS st
      ON st.id = r.space_type_id
    WHERE r.lounge_id = p_lounge_id
      AND COALESCE(r.is_active, true) IS TRUE
      AND COALESCE(r.status, 'available') NOT IN ('maintenance', 'deleted')
      AND (
        p_activity_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.room_activities AS filter_ra
          WHERE filter_ra.room_id = r.id
            AND filter_ra.activity_type_id = p_activity_id
        )
      )
  ) AS catalog;

  RETURN v_rooms;
END;
$$;


ALTER FUNCTION "public"."get_lounge_booking_rooms"("p_lounge_id" "uuid", "p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_bookings"("p_lounge_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_role text;
  v_own_lounge uuid;
  v_target_lounge uuid;
  v_result json;
BEGIN
  SELECT role, lounge_id INTO v_role, v_own_lounge
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_role IS NULL OR (v_role <> 'super_admin' AND v_own_lounge IS NULL) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_role = 'super_admin' THEN
    v_target_lounge := p_lounge_id;
  ELSE
    IF p_lounge_id IS NOT NULL AND p_lounge_id <> v_own_lounge THEN
      RAISE EXCEPTION 'Not authorized';
    END IF;
    v_target_lounge := v_own_lounge;
  END IF;

  SELECT json_agg(row_to_json(t)) INTO v_result
  FROM (
    SELECT
      b.*,
      json_build_object(
        'id', r.id,
        'name_ar', r.name_ar,
        'name_en', r.name_en,
        'room_type', r.room_type
      ) AS room,
      COALESCE((
        SELECT json_agg(
          json_build_object(
            'id', bi.id,
            'booking_id', bi.booking_id,
            'product_id', bi.product_id,
            'extra_id', bi.extra_id,
            'name', COALESCE(NULLIF(bi.name, ''), e.name_ar, e.name, 'ص�?ف'),
            'quantity', bi.quantity,
            'unit_price', bi.unit_price,
            'total_price', bi.total_price,
            'status', bi.status,
            'note', bi.note,
            'is_attended', bi.is_attended,
            'created_at', bi.created_at
          ) ORDER BY bi.created_at
        )
        FROM public.booking_items bi
        LEFT JOIN public.extras e ON e.id = COALESCE(bi.extra_id, bi.product_id)
        WHERE bi.booking_id = b.id
      ), '[]'::json) AS items,
      COALESCE((
        SELECT json_agg(
          json_build_object(
            'id', co.id,
            'status', co.status,
            'total_price', co.total_price,
            'note', co.note,
            'created_at', co.created_at,
            'items', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'extra_id', x.value->>'extra_id',
                  'name', COALESCE(e2.name_ar, e2.name, x.value->>'name', 'ص�?ف'),
                  'quantity', COALESCE((x.value->>'quantity')::integer, 1),
                  'unit_price', COALESCE((x.value->>'price')::numeric, e2.price, 0),
                  'total_price', COALESCE((x.value->>'price')::numeric, e2.price, 0) * COALESCE((x.value->>'quantity')::integer, 1)
                )
              )
              FROM jsonb_array_elements(COALESCE(co.items, '[]'::jsonb)) AS x(value)
              LEFT JOIN public.extras e2 ON e2.id::text = x.value->>'extra_id'
            ), '[]'::jsonb)
          ) ORDER BY co.created_at
        )
        FROM public.canteen_orders co
        WHERE co.booking_id = b.id
      ), '[]'::json) AS canteen_orders
    FROM public.bookings b
    LEFT JOIN public.rooms r ON r.id = b.room_id
    WHERE (v_target_lounge IS NULL OR b.lounge_id = v_target_lounge)
    ORDER BY b.created_at DESC
  ) t;

  RETURN json_build_object(
    'success', true,
    'data', COALESCE(v_result, '[]'::json)
  );
END;
$$;


ALTER FUNCTION "public"."get_lounge_bookings"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_bookings_page"("p_lounge_id" "uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_page integer := GREATEST(COALESCE(p_page, 1), 1);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 20), 1), 100);
  v_offset integer;
  v_total_count integer;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'p_lounge_id cannot be NULL' USING ERRCODE = '22023';
  END IF;

  PERFORM private.assert_lounge_operator(p_lounge_id, true);

  v_offset := (v_page - 1) * v_page_size;

  SELECT count(*)
  INTO v_total_count
  FROM public.bookings
  WHERE lounge_id = p_lounge_id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'total_count', v_total_count,
        'page', v_page,
        'page_size', v_page_size,
        'data', jsonb_build_object(
          'id', b.id,
          'out_booking_id', b.id,
          'user_id', b.user_id,
          'lounge_id', b.lounge_id,
          'room_id', b.room_id,
          'user_name', COALESCE(b.user_name, p.full_name, 'Walk-in Customer'),
          'user_phone', COALESCE(b.user_phone, p.phone),
          'user_email', COALESCE(b.user_email, p.email),
          'room_name', COALESCE(r.name_ar, r.name_en, r.name, 'Room'),
          'out_room_name', COALESCE(r.name_ar, r.name_en, r.name, 'Room'),
          'controllers_count', r.controllers_count,
          'screen_size', r.screen_size,
          'out_booking_date', b.date,
          'date', b.date,
          'out_start_time', b.start_time,
          'start_time', b.start_time,
          'out_end_time', b.end_time,
          'end_time', b.end_time,
          'duration_minutes', b.duration_minutes,
          'status', b.status,
          'out_booking_status', b.status,
          'payment_status', b.payment_status,
          'out_payment_status', b.payment_status,
          'payment_method', b.payment_method,
          'out_payment_method', b.payment_method,
          'total_price', b.total_price,
          'out_total_price', b.total_price,
          'addons_price', b.addons_price,
          'out_addons_price', b.addons_price,
          'voucher_discount', b.voucher_discount,
          'voucher_code', b.voucher_code,
          'discount_amount', b.discount_amount,
          'discount_percentage', b.discount_percentage,
          'discount_reason', b.discount_reason,
          'play_mode', b.play_mode,
          'room_price', b.room_price,
          'shift_id', b.shift_id,
          'created_at', b.created_at,
          'checked_in_at', b.checked_in_at,
          'out_visit_number', b.visit_num,
          'visit_number', b.visit_num,
          'canteen_orders', (
            SELECT COALESCE(
              jsonb_agg(
                jsonb_build_object(
                  'id', co.id,
                  'items', co.items,
                  'total_price', co.total_price,
                  'status', co.status,
                  'created_at', co.created_at
                )
              ),
              '[]'::jsonb
            )
            FROM public.canteen_orders AS co
            WHERE co.booking_id = b.id
          ),
          'extras', (
            SELECT COALESCE(
              jsonb_agg(
                jsonb_build_object(
                  'id', bi.id,
                  'extra_id', bi.extra_id,
                  'name', bi.name,
                  'quantity', bi.quantity,
                  'unit_price', bi.unit_price,
                  'total_price', bi.total_price,
                  'status', bi.status
                )
              ),
              '[]'::jsonb
            )
            FROM public.booking_items AS bi
            WHERE bi.booking_id = b.id
          )
        )
      )
    ),
    '[]'::jsonb
  )
  INTO v_result
  FROM (
    SELECT
      bk.*,
      DENSE_RANK() OVER (
        PARTITION BY
          CASE
            WHEN bk.user_id IS NOT NULL AND btrim(bk.user_id::text) <> ''
              THEN bk.user_id::text
            WHEN bk.user_phone IS NOT NULL
              AND btrim(bk.user_phone) <> ''
              AND bk.user_phone <> 'null'
              AND bk.user_phone <> 'No Phone'
              THEN btrim(bk.user_phone)
            ELSE bk.id::text
          END
        ORDER BY bk.created_at ASC
      ) AS visit_num
    FROM public.bookings AS bk
    WHERE bk.lounge_id = p_lounge_id
    ORDER BY bk.created_at DESC
    LIMIT v_page_size
    OFFSET v_offset
  ) AS b
  LEFT JOIN public.profiles AS p ON b.user_id = p.id
  LEFT JOIN public.rooms AS r ON b.room_id = r.id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_lounge_bookings_page"("p_lounge_id" "uuid", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


