CREATE OR REPLACE FUNCTION "public"."get_lounge_online_availability"("p_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_now timestamptz:=clock_timestamp();
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.lounges AS lounge
    LEFT JOIN private.cashier_writer_authorities AS writer ON writer.lounge_id=lounge.id
    WHERE lounge.id=p_lounge_id AND lounge.status='active'
      AND lounge.is_active IS TRUE AND lounge.is_open IS TRUE
      AND (
        -- No writer record exists
        writer.lounge_id IS NULL 
        -- Writer was explicitly released
        OR writer.released_at IS NOT NULL
        -- Writer's 24h permit expired
        OR writer.permit_expires_at <= v_now
        -- The cashier who claimed writer authority no longer has an open shift
        OR NOT EXISTS (
          SELECT 1 FROM public.shifts s 
          WHERE s.lounge_id=lounge.id 
            AND (s.cashier_id=writer.actor_id OR s.staff_user_id=writer.actor_id) 
            AND s.status='open' AND s.closed_at IS NULL
        )
        -- Writer is operating in online mode (not local offline mode)
        OR writer.online_requested IS TRUE
        -- Or writer is actively maintaining heartbeat in online mode
        OR (
          writer.released_at IS NULL 
          AND writer.heartbeat_expires_at > v_now
        )
      )
  );
END;
$$;


ALTER FUNCTION "public"."get_lounge_online_availability"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_operating_status"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_lounge public.lounges%ROWTYPE; v_online boolean; v_fault boolean;
BEGIN
 SELECT * INTO v_lounge FROM public.lounges WHERE id=p_lounge_id AND status='active' AND is_active IS TRUE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','unavailable','can_book_online',false,'contact_phone',NULL); END IF;
 v_online:=public.get_lounge_online_availability(p_lounge_id);
 v_fault:=v_lounge.is_open IS TRUE AND NOT v_online
   AND EXISTS(SELECT 1 FROM public.shifts WHERE lounge_id=p_lounge_id AND status='open' AND closed_at IS NULL)
   AND EXISTS(SELECT 1 FROM private.cashier_writer_authorities w
     JOIN public.profiles p ON p.id=w.actor_id JOIN auth.users u ON u.id=p.id
     WHERE w.lounge_id=p_lounge_id AND p.is_active IS TRUE AND p.is_banned IS FALSE
       AND w.released_at IS NULL
       AND w.permit_expires_at > clock_timestamp()
       AND EXISTS(SELECT 1 FROM public.shifts s WHERE s.lounge_id=p_lounge_id AND coalesce(s.cashier_id,s.staff_user_id)=w.actor_id AND s.status='open' AND s.closed_at IS NULL)
       AND w.online_requested IS FALSE);
 RETURN jsonb_build_object('status',CASE WHEN v_online THEN 'open' WHEN v_fault THEN 'technical_issue' ELSE 'closed' END,
   'can_book_online',v_online,'contact_phone',CASE WHEN v_fault THEN nullif(btrim(v_lounge.contact_phone),'') ELSE NULL END);
END; $$;


ALTER FUNCTION "public"."get_lounge_operating_status"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_owner_dashboard_stats"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_today_revenue numeric := 0;
  v_monthly_revenue numeric := 0;
  v_total_rooms integer := 0;
  v_occupied_rooms integer := 0;
  v_occupancy_rate numeric := 0;
  v_active_bookings integer := 0;
  v_open_shifts integer := 0;
  v_low_stock_items integer := 0;
  v_today date := (now() AT TIME ZONE 'Africa/Cairo')::date;
  v_month_start date := date_trunc(
    'month',
    now() AT TIME ZONE 'Africa/Cairo'
  )::date;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Invalid lounge_id parameter' USING ERRCODE = '22023';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR private.can_operate_playspot_lounge(p_lounge_id)
    OR public.is_lounge_member_or_admin(p_lounge_id)
  ) THEN
    RAISE EXCEPTION 'Unauthorized: You do not have access to dashboard stats for this lounge'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(SUM(p.amount), 0)
  INTO v_today_revenue
  FROM public.payments AS p
  WHERE p.lounge_id = p_lounge_id
    AND p.status = 'completed'
    AND (p.paid_at AT TIME ZONE 'Africa/Cairo')::date = v_today;

  SELECT COALESCE(SUM(p.amount), 0)
  INTO v_monthly_revenue
  FROM public.payments AS p
  WHERE p.lounge_id = p_lounge_id
    AND p.status = 'completed'
    AND (p.paid_at AT TIME ZONE 'Africa/Cairo')::date >= v_month_start
    AND (p.paid_at AT TIME ZONE 'Africa/Cairo')::date <= v_today;

  SELECT COUNT(*)
  INTO v_total_rooms
  FROM public.rooms AS r
  WHERE r.lounge_id = p_lounge_id
    AND r.is_active IS TRUE
    AND COALESCE(r.status, 'available') <> 'deleted';

  SELECT COUNT(*)
  INTO v_occupied_rooms
  FROM public.rooms AS r
  WHERE r.lounge_id = p_lounge_id
    AND r.is_active IS TRUE
    AND r.status = 'occupied';

  SELECT COUNT(*)
  INTO v_active_bookings
  FROM public.bookings AS b
  WHERE b.lounge_id = p_lounge_id
    AND b.status = 'in_progress'::public.booking_status;

  SELECT COUNT(*)
  INTO v_open_shifts
  FROM public.shifts AS s
  WHERE s.lounge_id = p_lounge_id
    AND s.status = 'open'
    AND s.closed_at IS NULL;

  SELECT COUNT(*)
  INTO v_low_stock_items
  FROM public.extras AS e
  WHERE e.lounge_id = p_lounge_id
    AND e.is_active IS TRUE
    AND e.track_stock IS TRUE
    AND COALESCE(e.stock_quantity, 0) <= COALESCE(e.min_stock_alert, 0);

  IF v_total_rooms > 0 THEN
    v_occupancy_rate := ROUND(
      (v_occupied_rooms::numeric / v_total_rooms::numeric) * 100,
      1
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'lounge_id', p_lounge_id,
    'today_revenue', v_today_revenue,
    'monthly_revenue', v_monthly_revenue,
    'total_rooms', v_total_rooms,
    'occupied_rooms', v_occupied_rooms,
    'occupancy_rate', v_occupancy_rate,
    'active_bookings', v_active_bookings,
    'open_shifts', v_open_shifts,
    'low_stock_items', v_low_stock_items
  );
END;
$$;


ALTER FUNCTION "public"."get_lounge_owner_dashboard_stats"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_price_range"("p_lounge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_min numeric;
  v_max numeric;
BEGIN
  SELECT
    MIN(COALESCE(r.hourly_rate_single, r.hourly_rate, 0)),
    MAX(GREATEST(COALESCE(r.hourly_rate_multi, 0), COALESCE(r.hourly_rate_single, r.hourly_rate, 0)))
  INTO v_min, v_max
  FROM public.rooms r
  WHERE r.lounge_id = p_lounge_id
    AND COALESCE(r.status, 'available') <> 'deleted'
    AND COALESCE(r.is_active, true) IS TRUE;

  RETURN jsonb_build_object(
    'lounge_id', p_lounge_id,
    'min_price', COALESCE(v_min, 0),
    'max_price', COALESCE(v_max, 0),
    'currency', 'EGP'
  );
END;
$$;


ALTER FUNCTION "public"."get_lounge_price_range"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_review_authors"("p_lounge_id" "uuid") RETURNS TABLE("user_id" "uuid", "full_name" "text", "avatar_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select distinct p.id, p.full_name, p.avatar_url
  from public.lounge_reviews as r
  join public.profiles as p on p.id = r.user_id
  where r.lounge_id = p_lounge_id
    and (select auth.uid()) is not null
    and (
      public.is_super_admin()
      or public.is_lounge_member_or_admin(p_lounge_id)
    );
$$;


