CREATE OR REPLACE FUNCTION "public"."get_lounge_reviews_page"("p_lounge_id" "uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS TABLE("data" "jsonb", "total_count" bigint, "page" integer, "page_size" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with args as (
    select greatest(coalesce(p_page, 1), 1) as page_no,
           least(greatest(coalesce(p_page_size, 20), 1), 100) as size_no
  ), rows as (
    select lr.*, count(*) over () as total_count
    from public.lounge_reviews lr
    where lr.lounge_id = p_lounge_id
    order by lr.created_at desc, lr.id desc
    limit (select size_no from args)
    offset ((select page_no from args) - 1) * (select size_no from args)
  )
  select to_jsonb(rows) - 'total_count',
         rows.total_count,
         (select page_no from args),
         (select size_no from args)
  from rows;
$$;


ALTER FUNCTION "public"."get_lounge_reviews_page"("p_lounge_id" "uuid", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_role_permission_catalog"("p_lounge_id" "uuid", "p_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_role text := private.permission_role(auth.uid(), p_lounge_id);
  v_role text := lower(btrim(COALESCE(p_role, '')));
BEGIN
  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin','owner','manager') THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_role NOT IN ('owner','manager','cashier','staff','super_admin') THEN
    RAISE EXCEPTION 'Unsupported permission role' USING ERRCODE='22023';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'permission_key', a.key,
        'name_ar', a.name_ar,
        'name_en', a.name_en,
        'category', a.category,
        'description_ar', a.description_ar,
        'description_en', a.description_en,
        'is_enabled', private.role_permission_value(v_role, p_lounge_id, a.key)
      )
      ORDER BY a.key
    )
    FROM public.app_permissions AS a
    WHERE private.permission_key_allowed_for_role(v_role, a.key)
  ), '[]'::jsonb);
END;
$$;


