CREATE OR REPLACE FUNCTION "public"."get_lounge_staff"("p_lounge_id" "uuid") RETURNS TABLE("id" "uuid", "email" "text", "full_name" "text", "phone" "text", "role" "text", "lounge_id" "uuid", "is_active" boolean, "created_at" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Authentication and lounge_id are required' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_super_admin() AND NOT public.is_lounge_admin(p_lounge_id) THEN
    RAISE EXCEPTION 'Not authorized for this lounge' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT p.id, p.email::text, COALESCE(p.full_name, 'Staff Member')::text,
         COALESCE(p.phone, '')::text, COALESCE(p.role, 'cashier')::text,
         p.lounge_id, COALESCE(p.is_active, true), COALESCE(p.created_at::text, now()::text)
  FROM public.profiles AS p
  WHERE (p.lounge_id = p_lounge_id OR p.id IN (
      SELECT ls.user_id FROM public.lounge_staff AS ls WHERE ls.lounge_id = p_lounge_id
    ))
    AND p.role NOT IN ('super_admin', 'superadmin')
  ORDER BY p.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_lounge_staff"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lounge_stats"("p_lounge_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_today_rev numeric := 0;
    v_monthly_rev numeric := 0;
    v_active_books integer := 0;
    v_rooms_cnt integer := 0;
    v_occ_cnt integer := 0;
    v_shifts_cnt integer := 0;
    v_extras_cnt integer := 0;
BEGIN

  -- guard:caller_check
  IF auth.uid() IS NULL OR NOT (public.is_super_admin() OR private.is_lounge_member(p_lounge_id)) THEN
    RAISE EXCEPTION 'Not authorized' USING errcode = '42501';
  END IF;

    -- 1. الإيرادات والحجوزات النشطة من جدول bookings
    SELECT 
        COALESCE(SUM(CASE WHEN date >= CURRENT_DATE THEN total_price ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN date >= date_trunc('month', CURRENT_DATE)::date THEN total_price ELSE 0 END), 0),
        COALESCE(COUNT(CASE WHEN status::text IN ('active', 'in_progress', 'upcoming', 'confirmed', 'pending') THEN 1 END), 0)
    INTO v_today_rev, v_monthly_rev, v_active_books
    FROM public.bookings
    WHERE lounge_id = p_lounge_id;

    -- 2. الغرف والإشغال من جدول rooms
    SELECT 
        COUNT(*),
        COUNT(CASE WHEN status IN ('occupied', 'busy') OR is_available = false THEN 1 END)
    INTO v_rooms_cnt, v_occ_cnt
    FROM public.rooms
    WHERE lounge_id = p_lounge_id AND is_active = true;

    -- 3. الشفتات المفتوحة من جدول shifts
    SELECT COUNT(*) INTO v_shifts_cnt
    FROM public.shifts
    WHERE lounge_id = p_lounge_id AND status = 'open';

    -- 4. المنتجات قليلة المخزون من جدول extras
    SELECT COUNT(*) INTO v_extras_cnt
    FROM public.extras
    WHERE lounge_id = p_lounge_id 
      AND track_stock = true 
      AND stock_quantity <= min_stock_alert;

    RETURN json_build_object(
        'success', true,
        'lounge_id', p_lounge_id,
        'today_revenue', v_today_rev,
        'monthly_revenue', v_monthly_rev,
        'total_rooms', v_rooms_cnt,
        'occupied_rooms', v_occ_cnt,
        'occupancy_rate', CASE WHEN v_rooms_cnt > 0 THEN ROUND((v_occ_cnt::numeric / v_rooms_cnt::numeric) * 100, 1) ELSE 0 END,
        'active_bookings', v_active_books,
        'open_shifts', v_shifts_cnt,
        'low_stock_items', v_extras_cnt
    );
END;
$$;


ALTER FUNCTION "public"."get_lounge_stats"("p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_loyalty_dashboard_stats"("p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_level_id" "uuid" DEFAULT NULL::"uuid", "p_referral_status" "text" DEFAULT NULL::"text", "p_user_query" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  WITH user_levels AS (
    SELECT
      p.id,
      p.full_name,
      p.email,
      p.phone,
      COALESCE(p.points, 0) AS points,
      level_row.id AS level_id,
      COALESCE(level_row.name_en, level_row.name_ar, level_row.code, 'Unassigned') AS level_name
    FROM public.profiles AS p
    LEFT JOIN LATERAL (
      SELECT ll.*
      FROM public.loyalty_levels AS ll
      WHERE ll.min_points <= COALESCE(p.points, 0)
      ORDER BY ll.min_points DESC
      LIMIT 1
    ) AS level_row ON true
    WHERE p.role = 'user'
      AND COALESCE(p.is_active, true) IS TRUE
      AND COALESCE(p.is_banned, false) IS FALSE
  ),
  scoped_users AS (
    SELECT ul.*
    FROM user_levels AS ul
    WHERE (p_level_id IS NULL OR ul.level_id = p_level_id)
      AND (
        NULLIF(btrim(p_user_query), '') IS NULL
        OR ul.id::text = btrim(p_user_query)
        OR COALESCE(ul.full_name, '') ILIKE '%' || btrim(p_user_query) || '%'
        OR COALESCE(ul.email, '') ILIKE '%' || btrim(p_user_query) || '%'
        OR COALESCE(ul.phone, '') ILIKE '%' || btrim(p_user_query) || '%'
      )
  ),
  level_counts AS (
    SELECT
      su.level_name,
      count(*)::int AS user_count
    FROM scoped_users AS su
    GROUP BY su.level_name
  ),
  points_stats AS (
    SELECT
      COALESCE(sum(CASE WHEN pt.points > 0 THEN pt.points ELSE 0 END), 0)::int AS total_added_points,
      COALESCE(sum(CASE WHEN pt.type = 'earn_referral' AND pt.points > 0 THEN pt.points ELSE 0 END), 0)::int AS total_referral_points
    FROM public.points_transactions AS pt
    JOIN scoped_users AS su ON su.id = pt.user_id
    WHERE (p_start_date IS NULL OR pt.created_at >= p_start_date)
      AND (
        p_end_date IS NULL
        OR pt.created_at < date_trunc('day', p_end_date) + interval '1 day'
      )
  ),
  referral_stats AS (
    SELECT
      count(*)::int AS total_referrals,
      count(*) FILTER (WHERE r.status = 'completed')::int AS completed_referrals
    FROM public.referrals AS r
    WHERE EXISTS (
        SELECT 1
        FROM scoped_users AS su
        WHERE su.id = r.referrer_id OR su.id = r.referred_id
      )
      AND (p_start_date IS NULL OR r.created_at >= p_start_date)
      AND (
        p_end_date IS NULL
        OR r.created_at < date_trunc('day', p_end_date) + interval '1 day'
      )
      AND (
        NULLIF(btrim(p_referral_status), '') IS NULL
        OR lower(btrim(p_referral_status)) = 'all'
        OR r.status = lower(btrim(p_referral_status))
      )
  ),
  voucher_stats AS (
    SELECT
      count(*)::int AS total_vouchers_issued,
      count(*) FILTER (WHERE uv.status = 'used')::int AS total_vouchers_used,
      count(*) FILTER (
        WHERE uv.status = 'active'
          AND (uv.expires_at IS NULL OR uv.expires_at > now())
      )::int AS total_vouchers_active,
      COALESCE(
        sum(
          CASE
            WHEN uv.status = 'used'
            THEN COALESCE(b.discount_amount, 0)
            ELSE 0
          END
        ),
        0
      )::numeric AS total_discount_value_used
    FROM public.user_vouchers AS uv
    JOIN scoped_users AS su ON su.id = uv.user_id
    LEFT JOIN public.bookings AS b ON b.id = uv.used_booking_id
    WHERE (p_start_date IS NULL OR uv.created_at >= p_start_date)
      AND (
        p_end_date IS NULL
        OR uv.created_at < date_trunc('day', p_end_date) + interval '1 day'
      )
  )
  SELECT jsonb_build_object(
    'total_added_points', ps.total_added_points,
    'user_count_by_level',
      COALESCE(
        (
          SELECT jsonb_object_agg(lc.level_name, lc.user_count ORDER BY lc.level_name)
          FROM level_counts AS lc
        ),
        '{}'::jsonb
      ),
    'total_referrals', rs.total_referrals,
    'completed_referrals', rs.completed_referrals,
    'total_referral_points', ps.total_referral_points,
    'total_vouchers_issued', vs.total_vouchers_issued,
    'total_vouchers_used', vs.total_vouchers_used,
    'total_vouchers_active', vs.total_vouchers_active,
    'total_discount_value_used', vs.total_discount_value_used
  )
  INTO v_result
  FROM points_stats AS ps
  CROSS JOIN referral_stats AS rs
  CROSS JOIN voucher_stats AS vs;

  RETURN COALESCE(
    v_result,
    jsonb_build_object(
      'total_added_points', 0,
      'user_count_by_level', '{}'::jsonb,
      'total_referrals', 0,
      'completed_referrals', 0,
      'total_referral_points', 0,
      'total_vouchers_issued', 0,
      'total_vouchers_used', 0,
      'total_vouchers_active', 0,
      'total_discount_value_used', 0
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_loyalty_dashboard_stats"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_level_id" "uuid", "p_referral_status" "text", "p_user_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_loyalty_referrals"("p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_status" "text" DEFAULT NULL::"text", "p_user_query" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', r.id,
        'referrer_id', r.referrer_id,
        'referred_id', r.referred_id,
        'status', r.status,
        'reward_claimed', r.reward_claimed,
        'created_at', r.created_at,
        'referrer', jsonb_build_object(
          'id', referrer.id,
          'full_name', referrer.full_name,
          'email', referrer.email
        ),
        'referred', jsonb_build_object(
          'id', referred.id,
          'full_name', referred.full_name,
          'email', referred.email
        )
      )
      ORDER BY r.created_at DESC, r.id
    ),
    '[]'::jsonb
  )
  INTO v_result
  FROM public.referrals AS r
  LEFT JOIN public.profiles AS referrer ON referrer.id = r.referrer_id
  LEFT JOIN public.profiles AS referred ON referred.id = r.referred_id
  WHERE (p_start_date IS NULL OR r.created_at >= p_start_date)
    AND (
      p_end_date IS NULL
      OR r.created_at < date_trunc('day', p_end_date) + interval '1 day'
    )
    AND (
      NULLIF(btrim(p_status), '') IS NULL
      OR lower(btrim(p_status)) = 'all'
      OR r.status = lower(btrim(p_status))
    )
    AND (
      NULLIF(btrim(p_user_query), '') IS NULL
      OR r.referrer_id::text = btrim(p_user_query)
      OR r.referred_id::text = btrim(p_user_query)
      OR COALESCE(referrer.full_name, '') ILIKE '%' || btrim(p_user_query) || '%'
      OR COALESCE(referrer.email, '') ILIKE '%' || btrim(p_user_query) || '%'
      OR COALESCE(referrer.phone, '') ILIKE '%' || btrim(p_user_query) || '%'
      OR COALESCE(referred.full_name, '') ILIKE '%' || btrim(p_user_query) || '%'
      OR COALESCE(referred.email, '') ILIKE '%' || btrim(p_user_query) || '%'
      OR COALESCE(referred.phone, '') ILIKE '%' || btrim(p_user_query) || '%'
    );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_loyalty_referrals"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_status" "text", "p_user_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_loyalty_status"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target_user_id uuid := COALESCE(p_user_id, auth.uid());
  v_is_super_admin boolean;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'super_admin'
  ) INTO v_is_super_admin;

  IF v_target_user_id <> auth.uid() AND NOT v_is_super_admin THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT jsonb_build_object(
    'points', COALESCE(p.points, 0),
    'level', COALESCE(l.code, 'bronze'),
    'level_name_ar', COALESCE(l.name_ar, 'برونزي'),
    'level_name_en', COALESCE(l.name_en, 'Bronze'),
    'multiplier', COALESCE(l.multiplier, 1.00),
    'next_level_points', (
      SELECT MIN(ll.min_points)
      FROM public.loyalty_levels ll
      WHERE ll.min_points > COALESCE(p.points, 0)
    )
  ) INTO v_result
  FROM public.profiles p
  LEFT JOIN LATERAL (
    SELECT ll.*
    FROM public.loyalty_levels ll
    WHERE ll.min_points <= COALESCE(p.points, 0)
    ORDER BY ll.min_points DESC
    LIMIT 1
  ) l ON true
  WHERE p.id = v_target_user_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_loyalty_status"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_multi_branch_overview"("p_owner_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_period tsrange;
BEGIN
  IF auth.uid() IS NULL
     OR (
       auth.uid() <> p_owner_id
       AND NOT public._playspot_is_super_admin()
     )
  THEN
    RAISE EXCEPTION 'Not authorized to view this overview'
      USING ERRCODE = '42501';
  END IF;

  IF p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_end_date <= p_start_date
  THEN
    RAISE EXCEPTION 'A valid non-empty date range is required';
  END IF;

  v_start := p_start_date AT TIME ZONE 'UTC';
  v_end := p_end_date AT TIME ZONE 'UTC';
  v_period := tsrange(v_start, v_end, '[)');

  WITH branch_stats AS (
    SELECT
      l.id AS lounge_id,
      l.name AS lounge_name,
      l.branch_name,

      (
        SELECT COALESCE(sum(p.amount), 0)
        FROM public.payments p
        WHERE p.lounge_id = l.id
          AND p.status = 'completed'
          AND p.paid_at >= v_start
          AND p.paid_at < v_end
      )::numeric AS revenue,

      (
        SELECT count(*)
        FROM public.bookings b
        WHERE b.lounge_id = l.id
          AND b.status = 'in_progress'
      )::bigint AS active_sessions_count,

      (
        SELECT count(*)
        FROM public.rooms r
        WHERE r.lounge_id = l.id
      )::bigint AS devices_count,

      (
        SELECT count(*)
        FROM public.rooms r
        WHERE r.lounge_id = l.id
          AND COALESCE(r.is_active, true) = true
      )::bigint AS active_rooms_count,

      (
        SELECT COALESCE(
          sum(
            EXTRACT(
              EPOCH FROM upper(b.booking_period * v_period)
              - lower(b.booking_period * v_period)
            )
          ),
          0
        )
        FROM public.bookings b
        WHERE b.lounge_id = l.id
          AND b.status NOT IN ('cancelled', 'rejected')
          AND b.booking_period && v_period
      )::numeric AS booked_seconds

    FROM public.lounges l
    WHERE l.owner_id = p_owner_id
  )
  SELECT jsonb_build_object(
    'total_revenue',
    COALESCE(sum(bs.revenue), 0),

    'active_sessions_count',
    COALESCE(sum(bs.active_sessions_count), 0),

    'branches',
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'lounge_id', bs.lounge_id,
          'name', bs.lounge_name,
          'branch_name', bs.branch_name,
          'revenue', bs.revenue,
          'active_sessions_count', bs.active_sessions_count,
          'occupancy_percentage',
            CASE
              WHEN bs.active_rooms_count = 0 THEN 0
              ELSE LEAST(
                100::numeric,
                ROUND(
                  (
                    bs.booked_seconds
                    /
                    (
                      bs.active_rooms_count
                      * EXTRACT(EPOCH FROM (v_end - v_start))
                    )
                    * 100
                  )::numeric,
                  2
                )
              )
            END,
          'devices_count', bs.devices_count
        )
        ORDER BY bs.lounge_name
      ),
      '[]'::jsonb
    )
  )
  INTO v_result
  FROM branch_stats bs;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_multi_branch_overview"("p_owner_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_active_tournament"() RETURNS TABLE("participant_id" "uuid", "tournament_id" "uuid", "registration_status" "text", "payment_status" "text", "created_at" timestamp with time zone, "tournament_title_ar" "text", "tournament_title_en" "text", "game_name" "text", "banner_url" "text", "tournament_starts_at" timestamp with time zone, "registration_closes_at" timestamp with time zone, "tournament_status" "text", "lounge_name" "text", "city_name_ar" "text", "city_name_en" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    tp.id as participant_id,
    t.id as tournament_id,
    tp.registration_status,
    tp.payment_status,
    tp.created_at,
    t.title_ar as tournament_title_ar,
    t.title_en as tournament_title_en,
    t.game_name,
    t.banner_url,
    t.tournament_starts_at,
    t.registration_closes_at,
    t.status as tournament_status,
    l.name as lounge_name,
    c.name_ar as city_name_ar,
    c.name_en as city_name_en
  from public.tournament_participants tp
  join public.tournaments t on t.id = tp.tournament_id
  left join public.lounges l on l.id = t.lounge_id
  left join public.cities c on c.id = t.city_id
  where tp.user_id = auth.uid()
    and tp.registration_status not in ('cancelled', 'withdrawn', 'expired')
    and t.status not in ('completed', 'cancelled')
  order by
    case tp.registration_status
      when 'confirmed' then 0
      when 'checked_in' then 1
      when 'waitlist' then 2
      when 'pending_payment' then 3
      when 'eliminated' then 4
      when 'no_show' then 5
      else 6
    end,
    t.tournament_starts_at asc nulls last,
    tp.created_at desc
  limit 1;
$$;


ALTER FUNCTION "public"."get_my_active_tournament"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_bookings"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id uuid := COALESCE(p_user_id, auth.uid());
    v_result json;
BEGIN
    SELECT json_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            b.*,
            json_build_object(
                'id', l.id,
                'name', l.name,
                'image_url', l.image_url,
                'address', l.address,
                'city', l.city
            ) AS lounge,
            json_build_object(
                'id', r.id,
                'name_ar', r.name_ar,
                'name_en', r.name_en,
                'room_type', r.room_type
            ) AS room
        FROM public.bookings b
        LEFT JOIN public.lounges l ON l.id = b.lounge_id
        LEFT JOIN public.rooms r ON r.id = b.room_id
        WHERE b.user_id = v_user_id
        ORDER BY b.created_at DESC
    ) t;

    RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION "public"."get_my_bookings"("p_user_id" "uuid") OWNER TO "postgres";


