CREATE OR REPLACE FUNCTION "public"."get_nearby_lounges"("user_lat" double precision DEFAULT 30.0444, "user_lon" double precision DEFAULT 31.2357, "max_distance" double precision DEFAULT 10000.0) RETURNS TABLE("id" "uuid", "owner_id" "uuid", "name" "text", "description" "text", "image_url" "text", "images" "text"[], "location" "text", "city" "text", "maps_link" "text", "rating" numeric, "total_reviews" integer, "available_rooms" integer, "is_open" boolean, "status" "text", "created_at" timestamp with time zone, "location_point" "public"."geography", "description_ar" "text", "description_en" "text", "address" "text", "latitude" double precision, "longitude" double precision, "contact_phone" "text", "opening_time" time without time zone, "closing_time" time without time zone, "is_active" boolean, "has_discount" boolean, "discount_percentage" numeric, "discount_title_ar" "text", "discount_title_en" "text", "discount_expires_at" timestamp with time zone, "distance_km" double precision)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
  SELECT 
    l.id,
    l.owner_id,
    l.name,
    l.description,
    l.image_url,
    l.images,
    l.location,
    l.city,
    l.maps_link,
    l.rating,
    l.total_reviews,
    l.available_rooms,
    l.is_open,
    l.status,
    l.created_at,
    l.location_point,
    l.description_ar,
    l.description_en,
    l.address,
    l.latitude,
    l.longitude,
    l.contact_phone,
    l.opening_time,
    l.closing_time,
    l.is_active,
    l.has_discount,
    l.discount_percentage,
    l.discount_title_ar,
    l.discount_title_en,
    l.discount_expires_at,
    CASE 
      WHEN l.latitude IS NOT NULL AND l.longitude IS NOT NULL THEN
        (12742 * asin(
          sqrt(
            power(sin((radians(l.latitude - user_lat)) / 2), 2) +
            cos(radians(user_lat)) * cos(radians(l.latitude)) *
            power(sin((radians(l.longitude - user_lon)) / 2), 2)
          )
        ))
      ELSE 999999.0
    END AS distance_km
  FROM lounges l
  ORDER BY distance_km ASC;
$$;


ALTER FUNCTION "public"."get_nearby_lounges"("user_lat" double precision, "user_lon" double precision, "max_distance" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearby_rooms"("user_lat" double precision, "user_lng" double precision, "max_distance_km" double precision DEFAULT 50, "city_name" "text" DEFAULT NULL::"text", "space_type_name" "text" DEFAULT NULL::"text", "activity_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("id" "uuid", "name_ar" "text", "name_en" "text", "photo_url" "text", "images" "text"[], "price_per_hour" numeric, "capacity" integer, "is_available" boolean, "space_type_name_out" "text", "lounge_id" "uuid", "lounge_name" "text", "city" "text", "location" "text", "dist_meters" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    r.id,
    r.name_ar,
    r.name_en,
    r.photo_url,
    r.images,
    COALESCE(r.hourly_rate_single, r.hourly_rate, 0) AS price_per_hour,
    r.max_capacity AS capacity,
    r.is_available,
    st.name AS space_type_name_out,
    l.id AS lounge_id,
    l.name AS lounge_name,
    l.city,
    l.location,
    ST_Distance(
      l.location_point,
      ST_SetSRID(ST_MakePoint(user_lng, user_lat), 4326)::geography
    ) AS dist_meters
  FROM rooms r
  JOIN lounges l ON l.id = r.lounge_id
  LEFT JOIN space_types st ON st.id = r.space_type_id
  WHERE l.location_point IS NOT NULL
    AND r.is_available = true
    AND (city_name IS NULL OR l.city = city_name)
    AND (space_type_name IS NULL OR st.name = space_type_name)
    AND ST_DWithin(
      l.location_point,
      ST_SetSRID(ST_MakePoint(user_lng, user_lat), 4326)::geography,
      max_distance_km * 1000
    )
  ORDER BY l.location_point <-> ST_SetSRID(ST_MakePoint(user_lng, user_lat), 4326)::geography;
$$;


ALTER FUNCTION "public"."get_nearby_rooms"("user_lat" double precision, "user_lng" double precision, "max_distance_km" double precision, "city_name" "text", "space_type_name" "text", "activity_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notifications"("p_lang" "text" DEFAULT 'ar'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "user_id" "uuid", "title" "text", "body" "text", "type" "text", "is_read" boolean, "metadata" "jsonb", "lounge_id" "uuid", "created_at" timestamp without time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    n.id,
    n.user_id,
    CASE WHEN lower(coalesce(p_lang, 'ar')) = 'en' THEN coalesce(n.title_en, n.title_ar, n.title)
         ELSE coalesce(n.title_ar, n.title_en, n.title) END,
    CASE WHEN lower(coalesce(p_lang, 'ar')) = 'en' THEN coalesce(n.body_en, n.body_ar, n.body)
         ELSE coalesce(n.body_ar, n.body_en, n.body) END,
    n.type,
    n.is_read,
    n.metadata,
    n.lounge_id,
    n.created_at
  FROM public.notifications n
  WHERE n.user_id = (SELECT auth.uid())
     OR (
       n.lounge_id IS NOT NULL
       AND (SELECT private.is_lounge_member(n.lounge_id))
     )
  ORDER BY n.created_at DESC, n.id DESC
  LIMIT greatest(1, least(coalesce(p_limit, 20), 100))
  OFFSET greatest(coalesce(p_offset, 0), 0);
$$;


ALTER FUNCTION "public"."get_notifications"("p_lang" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notifications_page"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS TABLE("data" "jsonb", "total_count" bigint, "page" integer, "page_size" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with args as (
    select greatest(coalesce(p_page, 1), 1) as page_no,
           least(greatest(coalesce(p_page_size, 20), 1), 100) as size_no
  ), rows as (
    select n.*, count(*) over () as total_count
    from public.notifications n
    where n.user_id = auth.uid()
    order by n.created_at desc, n.id desc
    limit (select size_no from args)
    offset ((select page_no from args) - 1) * (select size_no from args)
  )
  select to_jsonb(rows) - 'total_count',
         rows.total_count,
         (select page_no from args),
         (select size_no from args)
  from rows;
$$;


ALTER FUNCTION "public"."get_notifications_page"("p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_owner_branches"("p_owner_id" "uuid") RETURNS TABLE("lounge_id" "uuid", "lounge_name" "text", "branch_name" character varying, "is_main_branch" boolean, "city" "text", "is_open" boolean, "status" "text", "is_active" boolean, "total_rooms_count" bigint, "active_sessions_count" bigint, "today_revenue" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL
     OR (
       auth.uid() <> p_owner_id
       AND NOT public._playspot_is_super_admin()
     )
  THEN
    RAISE EXCEPTION 'Not authorized to view these branches'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    l.id,
    l.name,
    l.branch_name,
    l.is_main_branch,
    l.city,
    l.is_open,
    l.status,
    l.is_active,
    (
      SELECT count(*)
      FROM public.rooms r
      WHERE r.lounge_id = l.id
    ),
    (
      SELECT count(*)
      FROM public.bookings b
      WHERE b.lounge_id = l.id
        AND b.status = 'in_progress'
    ),
    COALESCE((
      SELECT sum(p.amount)
      FROM public.payments p
      WHERE p.lounge_id = l.id
        AND p.status = 'completed'
        AND p.paid_at >= timezone('UTC', now())::date::timestamp
        AND p.paid_at < (
          timezone('UTC', now())::date + 1
        )::timestamp
    ), 0)::numeric
  FROM public.lounges l
  WHERE l.owner_id = p_owner_id
  ORDER BY l.is_main_branch DESC, l.created_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_owner_branches"("p_owner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payout_details"("p_payout_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT jsonb_build_object(
    'payout', to_jsonb(po),
    'lounge', jsonb_build_object('id', l.id, 'name', l.name, 'name_ar', l.name_ar, 'name_en', l.name_en),
    'payments', COALESCE((
      SELECT jsonb_agg(to_jsonb(p) ORDER BY p.paid_at, p.id)
      FROM public.payments p
      WHERE p.payout_id = po.id
    ), '[]'::jsonb),
    'reconciliation', jsonb_build_object(
      'payment_count', (SELECT COUNT(*) FROM public.payments p WHERE p.payout_id = po.id),
      'completed_count', (SELECT COUNT(*) FROM public.payments p WHERE p.payout_id = po.id AND p.status = 'completed'),
      'refunded_count', (SELECT COUNT(*) FROM public.payments p WHERE p.payout_id = po.id AND p.status = 'refunded'),
      'calculated_net', COALESCE((SELECT SUM(COALESCE(p.net_to_lounge, p.amount - COALESCE(p.commission, 0))) FROM public.payments p WHERE p.payout_id = po.id AND p.status = 'completed'), 0),
      'difference', po.total_amount - COALESCE((SELECT SUM(COALESCE(p.net_to_lounge, p.amount - COALESCE(p.commission, 0))) FROM public.payments p WHERE p.payout_id = po.id AND p.status = 'completed'), 0)
    )
  ) INTO v_result
  FROM public.payouts po
  JOIN public.lounges l ON l.id = po.lounge_id
  WHERE po.id = p_payout_id;

  IF v_result IS NULL THEN RAISE EXCEPTION 'Payout not found'; END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_payout_details"("p_payout_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_extension_requests"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', 'ext_' || b.id::text,
    'booking_id', b.id,
    'lounge_id', b.lounge_id,
    'room_id', b.room_id,
    'room_name', COALESCE(r.name, 'Room'),
    'user_name', COALESCE(p.full_name, 'Guest'),
    'user_phone', p.phone,
    'requested_minutes', b.requested_extension_minutes,
    'extension_minutes', b.requested_extension_minutes,
    'extension_cost', public.calculate_booking_price(
      CASE WHEN lower(COALESCE(b.play_mode, '')) = 'single'
           THEN r.hourly_rate_single ELSE r.hourly_rate_multi END,
      b.requested_extension_minutes
    ),
    'status', b.extension_status,
    'created_at', b.updated_at
  ) ORDER BY b.updated_at DESC NULLS LAST), '[]'::jsonb)
  INTO v_result
  FROM public.bookings AS b
  LEFT JOIN public.profiles AS p ON p.id = b.user_id
  LEFT JOIN public.rooms AS r ON r.id = b.room_id
  WHERE b.extension_status = 'pending'
    AND COALESCE(b.requested_extension_minutes, 0) > 0
    AND b.status IN ('upcoming'::public.booking_status, 'in_progress'::public.booking_status)
    AND (public.is_super_admin() OR private.is_lounge_member(b.lounge_id));

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_pending_extension_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_kyc_reviews"() RETURNS TABLE("user_id" "uuid", "owner_name" "text", "owner_email" "text", "lounge_name" "text", "id_document_url" "text", "business_document_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'super_admin'
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN QUERY
  SELECT k.user_id, p.full_name, p.email, l.name,
         k.id_document_url, k.business_document_url
  FROM public.kyc_submissions k
  JOIN public.profiles p ON p.id = k.user_id
  JOIN public.lounges l ON l.id = p.lounge_id
  WHERE k.status = 'pending';
END;
$$;


ALTER FUNCTION "public"."get_pending_kyc_reviews"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_payouts"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result json;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT json_agg(p ORDER BY p.created_at DESC)
  INTO v_result
  FROM public.payouts AS p
  WHERE p.status = 'pending'
    AND (
      public.is_super_admin()
      OR private.can_manage_playspot_lounge(p.lounge_id)
    );

  RETURN json_build_object(
    'success', true,
    'data', COALESCE(v_result, '[]'::json)
  );
END;
$$;


ALTER FUNCTION "public"."get_pending_payouts"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_payouts_overview"() RETURNS TABLE("lounge_id" "uuid", "lounge_name" "text", "pending_amount" numeric, "total_transactions" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    p.lounge_id,
    COALESCE(l.name_ar, l.name_en, l.name)::text,
    COALESCE(SUM(p.net_to_lounge), 0),
    COUNT(*)
  FROM public.payments AS p
  JOIN public.lounges AS l ON l.id = p.lounge_id
  WHERE p.status = 'completed'
    AND p.payout_id IS NULL
    AND p.payment_method NOT IN ('cash')
  GROUP BY p.lounge_id, COALESCE(l.name_ar, l.name_en, l.name)
  HAVING COALESCE(SUM(p.net_to_lounge), 0) > 0;
END;
$$;


ALTER FUNCTION "public"."get_pending_payouts_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_points_transactions_page"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS TABLE("data" "jsonb", "total_count" bigint, "page" integer, "page_size" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with args as (
    select greatest(coalesce(p_page, 1), 1) as page_no,
           least(greatest(coalesce(p_page_size, 20), 1), 100) as size_no
  ), rows as (
    select pt.*, count(*) over () as total_count
    from public.points_transactions pt
    where pt.user_id = auth.uid()
    order by pt.created_at desc, pt.id desc
    limit (select size_no from args)
    offset ((select page_no from args) - 1) * (select size_no from args)
  )
  select to_jsonb(rows) - 'total_count',
         rows.total_count,
         (select page_no from args),
         (select size_no from args)
  from rows;
$$;


ALTER FUNCTION "public"."get_points_transactions_page"("p_page" integer, "p_page_size" integer) OWNER TO "postgres";


