CREATE OR REPLACE FUNCTION "public"."get_room_slots_with_prices"("p_room_id" "uuid", "p_date" "date") RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_slots jsonb := '[]'::jsonb;
  v_slot_start time without time zone;
  v_slot_end time without time zone;
  v_cur_min integer;
  v_open_min integer;
  v_close_min integer;
  v_is_available boolean;
  v_quote jsonb;
BEGIN
  SELECT r.* INTO v_room FROM public.rooms r WHERE r.id = p_room_id;
  IF NOT FOUND THEN
    RETURN json_build_array();
  END IF;

  SELECT l.* INTO v_lounge FROM public.lounges l WHERE l.id = v_room.lounge_id;

  v_open_min := (EXTRACT(HOUR FROM COALESCE(v_lounge.opening_time, '10:00:00'::time)) * 60)::integer;
  v_close_min := (EXTRACT(HOUR FROM COALESCE(v_lounge.closing_time, '23:00:00'::time)) * 60)::integer;

  IF v_close_min <= v_open_min THEN
    v_close_min := v_close_min + 1440;
  END IF;

  v_cur_min := v_open_min;

  WHILE v_cur_min + 60 <= v_close_min LOOP
    v_slot_start := ('00:00:00'::time + ((v_cur_min % 1440) || ' minutes')::interval);
    v_slot_end := ('00:00:00'::time + (((v_cur_min + 60) % 1440) || ' minutes')::interval);

    -- Check if slot overlaps with existing booking
    v_is_available := NOT EXISTS (
      SELECT 1 FROM public.bookings b
      WHERE b.room_id = p_room_id
        AND b.date = p_date
        AND b.status IN ('upcoming'::public.booking_status, 'in_progress'::public.booking_status)
        AND (b.start_time, b.end_time) OVERLAPS (v_slot_start, v_slot_end)
    );

    v_quote := public.quote_booking_price(
      p_room_id => p_room_id,
      p_date => p_date,
      p_start => v_slot_start,
      p_end => v_slot_end
    );

    v_slots := v_slots || jsonb_build_object(
      'start_time', to_char(v_slot_start, 'HH24:MI:SS'),
      'end_time', to_char(v_slot_end, 'HH24:MI:SS'),
      'is_available', v_is_available,
      'price', (v_quote->>'final_total')::numeric
    );

    v_cur_min := v_cur_min + 60;
  END LOOP;

  RETURN jsonb_build_array(v_slots);
END;
$$;


ALTER FUNCTION "public"."get_room_slots_with_prices"("p_room_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rooms_by_activity"("p_lounge_id" "uuid", "p_activity_id" "uuid", "p_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rooms jsonb;
  v_eval_date date := COALESCE(p_date, (now() AT TIME ZONE 'Africa/Cairo')::date);
BEGIN
  IF p_lounge_id IS NULL OR p_activity_id IS NULL THEN
    RAISE EXCEPTION 'Lounge ID and Activity ID are required' USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', r.id,
      'lounge_id', r.lounge_id,
      'name', r.name,
      'name_ar', r.name_ar,
      'name_en', r.name_en,
      'resource_type', r.resource_type,
      'resource_attributes', COALESCE(r.resource_attributes, '{}'::jsonb),
      'requires_screen', COALESCE(r.requires_screen, true),
      'requires_controllers', COALESCE(r.requires_controllers, true),
      'controllers_count', COALESCE(r.controllers_count, 0),
      'screen_size', r.screen_size,
      'pricing_model', COALESCE(r.pricing_model, 'per_room_hour'),
      'hourly_rate_single', r.hourly_rate_single,
      'hourly_rate_multi', r.hourly_rate_multi,
      'hourly_rate', r.hourly_rate,
      'extra_controller_price', COALESCE(r.extra_controller_price, 0),
      'min_capacity', COALESCE(r.min_capacity, 1),
      'max_capacity', COALESCE(r.max_capacity, 4),
      'is_available', r.is_available,
      'status', r.status,
      'images', COALESCE(to_jsonb(r.images), '[]'::jsonb),
      'features', COALESCE(to_jsonb(r.features), '[]'::jsonb),
      'space_type_id', r.space_type_id,
      'has_active_bookings_on_date', EXISTS (
        SELECT 1 FROM public.bookings b
        WHERE b.room_id = r.id
          AND b.date = v_eval_date
          AND b.status IN ('pending'::public.booking_status,
                           'upcoming'::public.booking_status,
                           'in_progress'::public.booking_status)
      )
    )
    ORDER BY r.name ASC
  )
  INTO v_rooms
  FROM public.rooms r
  JOIN public.room_activities ra ON ra.room_id = r.id
  WHERE r.lounge_id = p_lounge_id
    AND ra.activity_type_id = p_activity_id
    AND COALESCE(r.is_active, true) IS TRUE
    AND COALESCE(r.status, 'available') <> 'deleted';

  RETURN COALESCE(v_rooms, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_rooms_by_activity"("p_lounge_id" "uuid", "p_activity_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shift_report"("p_lounge_id" "uuid", "p_start_date" "date" DEFAULT CURRENT_DATE, "p_end_date" "date" DEFAULT CURRENT_DATE, "p_cashier_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("shift_id" "uuid", "lounge_id" "uuid", "cashier_id" "uuid", "cashier_name" "text", "opened_at" timestamp with time zone, "closed_at" timestamp with time zone, "status" "text", "is_approved" boolean, "starting_cash" numeric, "total_sales" numeric, "cash_sales" numeric, "digital_sales" numeric, "total_expenses" numeric, "expected_cash" numeric, "actual_cash" numeric, "difference" numeric, "payment_count" bigint, "expense_count" bigint, "linked_booking_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
  IF NOT private.can_view_shift_financials(p_lounge_id) THEN RAISE EXCEPTION 'Financial report access denied' USING ERRCODE='42501'; END IF;
  IF auth.uid() IS NULL
     OR (
       COALESCE((SELECT private.current_user_role()), '') <> 'super_admin'
       AND NOT COALESCE((SELECT private.is_lounge_member(p_lounge_id)), false)
     ) THEN
    RAISE EXCEPTION 'Not authorized for this lounge.';
  END IF;

  RETURN QUERY
  SELECT
    s.id,
    s.lounge_id,
    COALESCE(s.cashier_id, s.staff_user_id),
    COALESCE(p.full_name, 'Cashier'),
    s.opened_at,
    s.closed_at,
    s.status,
    COALESCE(s.is_approved, false),
    COALESCE(s.starting_cash, 0),
    COALESCE(SUM(sp.amount), 0),
    COALESCE(SUM(sp.amount) FILTER (WHERE sp.payment_method = 'cash'), 0),
    COALESCE(SUM(sp.amount) FILTER (WHERE sp.payment_method <> 'cash'), 0),
    COALESCE((SELECT SUM(se.amount) FROM public.shift_expenses se WHERE se.shift_id = s.id), 0),
    COALESCE(s.expected_cash, 0),
    COALESCE(s.actual_cash_counted, 0),
    COALESCE(s.difference, 0),
    COUNT(sp.id),
    (SELECT COUNT(*) FROM public.shift_expenses se WHERE se.shift_id = s.id),
    (SELECT COUNT(*) FROM public.bookings b WHERE b.shift_id = s.id)
  FROM public.shifts s
  LEFT JOIN public.profiles p ON p.id = COALESCE(s.cashier_id, s.staff_user_id)
  LEFT JOIN public.shift_payments sp ON sp.shift_id = s.id
  WHERE s.lounge_id = p_lounge_id
    AND s.opened_at::date BETWEEN p_start_date AND p_end_date
    AND (p_cashier_id IS NULL OR COALESCE(s.cashier_id, s.staff_user_id) = p_cashier_id)
  GROUP BY s.id, p.full_name;
END;
$$;


ALTER FUNCTION "public"."get_shift_report"("p_lounge_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_cashier_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_smart_filtered_lounges"("p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_city" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_has_promotions" boolean DEFAULT NULL::boolean, "p_is_open_only" boolean DEFAULT NULL::boolean, "p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(l)), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      l.id, l.name, l.name_ar, l.name_en, l.image_url, l.rating, l.location, l.city, l.is_open,
      CASE
        WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL AND l.location_point IS NOT NULL THEN
          ROUND((ST_Distance(l.location_point, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography) / 1000.0)::numeric, 2)
        ELSE NULL
      END AS distance_km
    FROM public.lounges l
    WHERE l.status != 'deleted' AND COALESCE(l.is_active, true) = true
      AND (p_city IS NULL OR l.city = p_city)
      AND (p_is_open_only IS NULL OR p_is_open_only = false OR l.is_open = true)
      AND (
        p_search IS NULL OR btrim(p_search) = '' 
        OR l.name ILIKE '%' || btrim(p_search) || '%'
        OR l.name_ar ILIKE '%' || btrim(p_search) || '%'
        OR l.name_en ILIKE '%' || btrim(p_search) || '%'
      )
      AND (
        p_category_id IS NULL 
        OR EXISTS (
          SELECT 1 FROM public.lounge_categories lc 
          WHERE lc.lounge_id = l.id AND lc.category_id = p_category_id
        )
      )
      AND (
        p_has_promotions IS NULL OR p_has_promotions = false
        OR EXISTS (
          SELECT 1 FROM public.promotions pr
          WHERE pr.lounge_id = l.id 
            AND pr.is_active = true 
            AND (pr.expires_at IS NULL OR pr.expires_at > now())
        )
      )
    ORDER BY
      CASE
        WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL AND l.location_point IS NOT NULL THEN
          ST_Distance(l.location_point, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography)
        ELSE 0
      END ASC,
      l.rating DESC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100)
  ) l;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_smart_filtered_lounges"("p_lat" numeric, "p_lng" numeric, "p_city" "text", "p_limit" integer, "p_category_id" "uuid", "p_has_promotions" boolean, "p_is_open_only" boolean, "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_smart_rebook_slots"("p_past_booking_id" "uuid", "p_days_ahead" integer DEFAULT 14) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_past RECORD;
  v_duration_minutes integer := 60;
  v_target_time time without time zone;
  v_target_hour integer;
  v_target_minute integer;
  v_target_total_minutes integer;
  v_preferred_dow integer;
  v_days_ahead integer;
  v_today date := (now() AT TIME ZONE 'Africa/Cairo')::date;
  v_candidate_dates date[] := '{}'::date[];
  v_d date;
  v_i integer;
  v_recommendations jsonb := '[]'::jsonb;
  v_opening time without time zone;
  v_closing time without time zone;
  v_operational_date date;
  v_operational_start timestamp without time zone;
  v_operational_end timestamp without time zone;
  v_cursor timestamp without time zone;
  v_slot_end timestamp without time zone;
  v_slots_for_date text[];
  v_closest_slot text;
  v_min_diff integer;
  v_slot_time time without time zone;
  v_slot_total_minutes integer;
  v_diff integer;
  v_quote jsonb;
  v_closest_start timestamp without time zone;
  v_closest_end timestamp without time zone;
  v_rec_count integer := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  -- 1. Fetch past booking
  SELECT
    b.id,
    b.user_id,
    b.lounge_id,
    b.room_id,
    b.date,
    b.start_time,
    b.end_time,
    b.booking_period,
    b.duration_hours,
    b.open_time_billing_minutes,
    r.name AS room_name,
    r.name_ar AS room_name_ar,
    r.hourly_rate AS room_hourly_rate,
    l.name AS lounge_name,
    l.name_ar AS lounge_name_ar,
    l.opening_time,
    l.closing_time
  INTO v_past
  FROM public.bookings b
  JOIN public.rooms r ON r.id = b.room_id
  JOIN public.lounges l ON l.id = b.lounge_id
  WHERE b.id = p_past_booking_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_past.user_id <> v_user_id
     AND NOT public.is_super_admin()
     AND NOT public.is_lounge_member_or_admin(v_past.lounge_id) THEN
    RAISE EXCEPTION 'Unauthorized to view this booking' USING ERRCODE = '42501';
  END IF;

  -- 2. Determine target duration
  IF v_past.booking_period IS NOT NULL THEN
    v_duration_minutes := ROUND(EXTRACT(EPOCH FROM (upper(v_past.booking_period) - lower(v_past.booking_period))) / 60)::integer;
  ELSIF v_past.duration_hours IS NOT NULL THEN
    v_duration_minutes := ROUND(v_past.duration_hours * 60)::integer;
  ELSIF v_past.open_time_billing_minutes IS NOT NULL THEN
    v_duration_minutes := v_past.open_time_billing_minutes;
  ELSE
    v_duration_minutes := 60;
  END IF;
  v_duration_minutes := GREATEST(15, LEAST(1440, v_duration_minutes));

  -- 3. Determine target time
  v_target_time := COALESCE(
    v_past.start_time,
    CASE WHEN v_past.booking_period IS NOT NULL THEN lower(v_past.booking_period)::time ELSE NULL END,
    '18:00:00'::time
  );
  v_target_hour := EXTRACT(HOUR FROM v_target_time)::integer;
  v_target_minute := EXTRACT(MINUTE FROM v_target_time)::integer;
  v_target_total_minutes := v_target_hour * 60 + v_target_minute;

  -- 4. Determine preferred day-of-week (0 = Sunday, 1 = Monday, ..., 6 = Saturday)
  v_preferred_dow := EXTRACT(DOW FROM COALESCE(
    v_past.date,
    CASE WHEN v_past.booking_period IS NOT NULL THEN lower(v_past.booking_period)::date ELSE NULL END,
    v_today
  ))::integer;

  v_days_ahead := LEAST(GREATEST(COALESCE(p_days_ahead, 14), 1), 30);

  -- 5. Build prioritized candidate dates:
  -- First: Same weekday in next 7-14 days
  FOR v_i IN 1..v_days_ahead LOOP
    v_d := v_today + v_i;
    IF EXTRACT(DOW FROM v_d)::integer = v_preferred_dow THEN
      v_candidate_dates := array_append(v_candidate_dates, v_d);
    END IF;
  END LOOP;

  -- Second: Remaining calendar days in order
  FOR v_i IN 1..v_days_ahead LOOP
    v_d := v_today + v_i;
    IF NOT (v_d = ANY(v_candidate_dates)) THEN
      v_candidate_dates := array_append(v_candidate_dates, v_d);
    END IF;
  END LOOP;

  -- 6. Evaluate each candidate date for available slots
  v_opening := COALESCE(v_past.opening_time, '00:00:00'::time);
  v_closing := COALESCE(v_past.closing_time, '23:59:59'::time);

  FOREACH v_d IN ARRAY v_candidate_dates
  LOOP
    EXIT WHEN v_rec_count >= 5; -- Return up to 5 best recommended dates

    v_operational_date := v_d;
    IF v_closing <= v_opening THEN
      v_operational_start := v_operational_date + v_opening;
      v_operational_end := v_operational_date + interval '1 day' + v_closing;
    ELSE
      v_operational_start := v_operational_date + v_opening;
      v_operational_end := v_operational_date + v_closing;
    END IF;

    v_slots_for_date := '{}'::text[];
    v_cursor := v_operational_start;

    WHILE (v_cursor + make_interval(mins => v_duration_minutes)) <= v_operational_end LOOP
      v_slot_end := v_cursor + make_interval(mins => v_duration_minutes);

      -- Check future lead time (at least 10 minutes from now)
      IF v_cursor >= (now() AT TIME ZONE 'Africa/Cairo') + interval '10 minutes' THEN
        -- Check no conflicting booking
        IF NOT EXISTS (
          SELECT 1 FROM public.bookings b
          WHERE b.room_id = v_past.room_id
            AND b.status IN ('pending'::public.booking_status,
                             'upcoming'::public.booking_status,
                             'in_progress'::public.booking_status)
            AND (b.status <> 'pending'::public.booking_status
                 OR b.expires_at IS NULL OR b.expires_at > now())
            AND b.booking_period && pg_catalog.tsrange(v_cursor, v_slot_end, '[)')
        ) AND NOT EXISTS (
          -- Check no conflicting hold
          SELECT 1 FROM public.booking_holds h
          WHERE h.room_id = v_past.room_id
            AND h.released_at IS NULL
            AND h.expires_at > now()
            AND pg_catalog.tsrange(h.start_at, h.end_at, '[)')
                && pg_catalog.tsrange(v_cursor, v_slot_end, '[)')
        ) THEN
          v_slots_for_date := array_append(v_slots_for_date, to_char(v_cursor::time, 'HH24:MI:SS'));
        END IF;
      END IF;

      v_cursor := v_cursor + interval '30 minutes';
    END LOOP;

    -- If date has available slots, calculate closest slot and price quote
    IF cardinality(v_slots_for_date) > 0 THEN
      v_closest_slot := v_slots_for_date[1];
      v_min_diff := 999999;

      FOREACH v_closest_slot IN ARRAY v_slots_for_date
      LOOP
        v_slot_time := v_closest_slot::time;
        v_slot_total_minutes := (EXTRACT(HOUR FROM v_slot_time)::integer * 60) + EXTRACT(MINUTE FROM v_slot_time)::integer;
        v_diff := abs(v_slot_total_minutes - v_target_total_minutes) % 1440;
        IF v_diff > 720 THEN
          v_diff := 1440 - v_diff;
        END IF;

        IF v_diff < v_min_diff THEN
          v_min_diff := v_diff;
          v_closest_slot := to_char(v_slot_time, 'HH24:MI:SS');
        END IF;
      END LOOP;

      v_closest_start := v_d + v_closest_slot::time;
      v_closest_end := v_closest_start + make_interval(mins => v_duration_minutes);

      -- Authoritative server pricing quote
      BEGIN
        v_quote := public.quote_booking_price(
          v_past.room_id,
          v_closest_start,
          v_closest_end
        );
      EXCEPTION WHEN OTHERS THEN
        v_quote := jsonb_build_object(
          'base_price', ROUND((COALESCE(v_past.room_hourly_rate, 50) * (v_duration_minutes::numeric / 60.0)), 2),
          'final_total', ROUND((COALESCE(v_past.room_hourly_rate, 50) * (v_duration_minutes::numeric / 60.0)), 2),
          'currency', 'EGP'
        );
      END;

      v_recommendations := v_recommendations || jsonb_build_object(
        'date', to_char(v_d, 'YYYY-MM-DD'),
        'day_name', TRIM(to_char(v_d, 'Day')),
        'is_same_weekday', (EXTRACT(DOW FROM v_d)::integer = v_preferred_dow),
        'available_slots', to_jsonb(v_slots_for_date),
        'closest_slot', v_closest_slot,
        'quoted_price', v_quote
      );

      v_rec_count := v_rec_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'past_booking_id', p_past_booking_id,
    'room_id', v_past.room_id,
    'room_name', v_past.room_name,
    'room_name_ar', v_past.room_name_ar,
    'lounge_id', v_past.lounge_id,
    'lounge_name', v_past.lounge_name,
    'lounge_name_ar', v_past.lounge_name_ar,
    'target_time', to_char(v_target_time, 'HH24:MI:SS'),
    'duration_minutes', v_duration_minutes,
    'preferred_weekday', v_preferred_dow,
    'recommendations', v_recommendations
  );
END;
$$;


ALTER FUNCTION "public"."get_smart_rebook_slots"("p_past_booking_id" "uuid", "p_days_ahead" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_staff_permissions"("p_target_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_target uuid := COALESCE(p_target_user_id,auth.uid());
  v_lounge uuid; v_role text; v_actor_role text; v_permissions json;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
  SELECT lounge_id,role INTO v_lounge,v_role FROM public.profiles WHERE id=v_target;
  IF NOT FOUND THEN RAISE EXCEPTION 'Target user not found'; END IF;
  v_actor_role := private.permission_role(auth.uid(),v_lounge);
  IF v_target <> auth.uid() AND (v_actor_role IS NULL OR v_actor_role NOT IN ('super_admin','owner','manager')) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;
  SELECT json_agg(json_build_object(
    'permission_key',a.key,'name_ar',a.name_ar,'name_en',a.name_en,'category',a.category,
    'description_ar',a.description_ar,'description_en',a.description_en,
    'is_enabled',private.user_permission_value(v_target,v_lounge,a.key)) ORDER BY a.key)
    INTO v_permissions FROM public.app_permissions a;
  RETURN json_build_object('success',true,'role',v_role,'lounge_id',v_lounge,
    'permissions',COALESCE(v_permissions,'[]'::json));
END;
$$;


ALTER FUNCTION "public"."get_staff_permissions"("p_target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_lounges_by_revenue"("limit_count" integer DEFAULT 10) RETURNS TABLE("lounge_id" "uuid", "lounge_name" "text", "total_revenue" numeric, "bookings_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.role = 'super_admin'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM public.platform_super_admins psa
    WHERE psa.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN QUERY
  SELECT
    l.id,
    l.name,
    COALESCE(SUM(p.amount), 0)::numeric AS total_revenue,
    COUNT(p.id)::bigint AS bookings_count
  FROM public.lounges l
  LEFT JOIN public.payments p
    ON p.lounge_id = l.id
   AND p.status = 'completed'
  GROUP BY l.id, l.name
  ORDER BY total_revenue DESC
  LIMIT limit_count;
END;
$$;


ALTER FUNCTION "public"."get_top_lounges_by_revenue"("limit_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tournament_audit_logs_page"("p_tournament_id" "uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS TABLE("data" "jsonb", "total_count" bigint, "page" integer, "page_size" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with args as (
    select greatest(coalesce(p_page, 1), 1) as page_no,
           least(greatest(coalesce(p_page_size, 50), 1), 100) as size_no
  ), rows as (
    select tal.*, count(*) over () as total_count
    from public.tournament_audit_logs tal
    where tal.tournament_id = p_tournament_id
    order by tal.created_at desc, tal.id desc
    limit (select size_no from args)
    offset ((select page_no from args) - 1) * (select size_no from args)
  )
  select to_jsonb(rows) - 'total_count',
         rows.total_count,
         (select page_no from args),
         (select size_no from args)
  from rows;
$$;


ALTER FUNCTION "public"."get_tournament_audit_logs_page"("p_tournament_id" "uuid", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tournament_participant_names"("p_tournament_id" "uuid") RETURNS TABLE("participant_id" "uuid", "user_id" "uuid", "user_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lounge_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles AS actor
    WHERE actor.id = auth.uid() AND actor.is_active IS TRUE
      AND actor.is_banned IS NOT TRUE) THEN
    RAISE EXCEPTION 'inactive_account' USING ERRCODE = '42501';
  END IF;
  SELECT t.lounge_id INTO v_lounge_id FROM public.tournaments AS t
  WHERE t.id = p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (
    public.is_super_admin() IS TRUE
    OR private.is_lounge_manager(v_lounge_id) IS TRUE
    OR public.has_lounge_permission(v_lounge_id, 'tournaments_view') IS TRUE
    OR EXISTS (SELECT 1 FROM public.tournament_participants AS own
      WHERE own.tournament_id = p_tournament_id AND own.user_id = auth.uid())
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT participant.id, participant.user_id, NULLIF(btrim(profile.full_name), '')
  FROM public.tournament_participants AS participant
  LEFT JOIN public.profiles AS profile ON profile.id = participant.user_id
  WHERE participant.tournament_id = p_tournament_id
  ORDER BY participant.created_at, participant.id;
END;
$$;


ALTER FUNCTION "public"."get_tournament_participant_names"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_upsell_suggestions"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT private.get_canteen_upsell_suggestions(p_booking_id, false);
$$;


ALTER FUNCTION "public"."get_upsell_suggestions"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_points_balance"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
 v_actor uuid := auth.uid();
 v_target_user_id uuid := COALESCE(p_user_id,auth.uid());
 v_balance integer;
BEGIN
 IF v_actor IS NULL THEN
  RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id
  WHERE p.id=v_actor AND p.is_active IS TRUE AND p.is_banned IS FALSE) THEN
  RAISE EXCEPTION 'Account not eligible' USING ERRCODE='42501';
 END IF;
 IF v_target_user_id IS DISTINCT FROM v_actor AND public.is_super_admin() IS NOT TRUE THEN
  RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
 END IF;
 SELECT COALESCE(SUM(pt.points),0)::integer INTO v_balance
  FROM public.points_transactions pt WHERE pt.user_id=v_target_user_id;
 RETURN v_balance;
END; $$;


ALTER FUNCTION "public"."get_user_points_balance"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_profile"("p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result json;
BEGIN
  IF p_user_id IS NULL THEN
    p_user_id := auth.uid();
  END IF;

  IF p_user_id <> auth.uid()
     AND NOT EXISTS (
       SELECT 1 FROM public.profiles
       WHERE id = auth.uid() AND role = 'super_admin'
     ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT row_to_json(p) INTO result
  FROM public.profiles p
  WHERE p.id = p_user_id;
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_user_profile"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_users_public_info"("user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "full_name" "text", "name" "text", "avatar_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT
    p.id AS user_id,
    p.full_name,
    p.full_name AS name,
    p.avatar_url
  FROM public.profiles AS p
  WHERE p.id = ANY (user_ids);
$$;


ALTER FUNCTION "public"."get_users_public_info"("user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_visible_shifts"("p_lounge_id" "uuid" DEFAULT NULL::"uuid", "p_shift_id" "uuid" DEFAULT NULL::"uuid", "p_active_only" boolean DEFAULT false, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
 IF p_limit IS NULL OR p_limit<1 OR p_limit>200 OR p_offset IS NULL OR p_offset<0 THEN RAISE EXCEPTION 'Invalid pagination' USING ERRCODE='22023'; END IF;
 IF p_lounge_id IS NOT NULL AND NOT public._playspot_has_lounge_access(p_lounge_id) THEN RAISE EXCEPTION 'Lounge access denied' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT private.mask_shift_financials(s.lounge_id,to_jsonb(s) || jsonb_build_object('cashier_name',p.full_name))
 || jsonb_build_object('actual_cash_counted',CASE WHEN s.cashier_id=auth.uid() OR private.can_view_shift_financials(s.lounge_id) THEN s.actual_cash_counted ELSE NULL END)
 FROM public.shifts s LEFT JOIN public.profiles p ON p.id=s.cashier_id
 WHERE public._playspot_has_lounge_access(s.lounge_id)
 AND (p_lounge_id IS NULL OR s.lounge_id=p_lounge_id) AND (p_shift_id IS NULL OR s.id=p_shift_id)
 AND (NOT p_active_only OR (s.status='open' AND s.closed_at IS NULL AND (p_lounge_id IS NOT NULL OR s.cashier_id=auth.uid())))
 ORDER BY s.start_time DESC,s.id LIMIT p_limit OFFSET p_offset;
END; $$;


ALTER FUNCTION "public"."get_visible_shifts"("p_lounge_id" "uuid", "p_shift_id" "uuid", "p_active_only" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_visible_tournaments"("p_latitude" double precision DEFAULT NULL::double precision, "p_longitude" double precision DEFAULT NULL::double precision) RETURNS SETOF "public"."tournaments"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT t.*
  FROM public.tournaments AS t
  JOIN public.lounges AS l ON l.id = t.lounge_id
  LEFT JOIN public.profiles AS p ON p.id = auth.uid()
  WHERE t.status IN (
    'published',
    'registration_open',
    'registration_closed',
    'check_in_open',
    'check_in_closed',
    'draw_completed',
    'in_progress'
  )
  AND (
    t.visibility_scope = 'all'
    OR (
      t.visibility_scope = 'city'
      AND p.city_id IS NOT NULL
      AND t.city_id = p.city_id
    )
    OR (
      t.visibility_scope = 'radius'
      AND p_latitude IS NOT NULL
      AND p_longitude IS NOT NULL
      AND l.location_point IS NOT NULL
      AND ST_DWithin(
        l.location_point,
        ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography,
        t.visibility_radius_km * 1000
      )
    )
  )
  ORDER BY t.tournament_starts_at ASC NULLS LAST, t.created_at DESC;
$$;


ALTER FUNCTION "public"."get_visible_tournaments"("p_latitude" double precision, "p_longitude" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_duplicate_booking_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking_id text;
  v_event text;
  v_status text;
  v_source text;
  v_scheduled_for text;
  v_lock_key text;
BEGIN
  IF NEW.type IS DISTINCT FROM 'booking' OR NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_booking_id := NULLIF(NEW.metadata->>'booking_id', '');
  v_event := NULLIF(NEW.metadata->>'event', '');
  IF v_booking_id IS NULL OR v_event IS NULL THEN
    RETURN NEW;
  END IF;

  v_status := COALESCE(NEW.metadata->>'status', '');
  v_source := COALESCE(NEW.metadata->>'cancellation_source', '');
  v_scheduled_for := COALESCE(NEW.metadata->>'scheduled_for', '');
  v_lock_key :=
    NEW.user_id::text
    || ':booking:'
    || v_booking_id
    || ':'
    || v_event
    || ':'
    || v_status
    || ':'
    || v_source
    || ':'
    || v_scheduled_for;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_lock_key, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM public.notifications AS n
    WHERE n.user_id = NEW.user_id
      AND n.type = 'booking'
      AND n.metadata->>'booking_id' = v_booking_id
      AND COALESCE(n.metadata->>'event', '') = v_event
      AND COALESCE(n.metadata->>'status', '') = v_status
      AND COALESCE(n.metadata->>'cancellation_source', '') = v_source
      AND COALESCE(n.metadata->>'scheduled_for', '') = v_scheduled_for
  ) THEN
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_duplicate_booking_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_duplicate_offer_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_promo_id text;
  v_lock_key text;
BEGIN
  IF NEW.type IS DISTINCT FROM 'offer' OR NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_promo_id := NULLIF(NEW.metadata->>'promo_id', '');
  IF v_promo_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_lock_key :=
    NEW.user_id::text || ':offer:' || v_promo_id;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_lock_key, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM public.notifications AS n
    WHERE n.user_id = NEW.user_id
      AND n.type = 'offer'
      AND n.metadata->>'promo_id' = v_promo_id
  ) THEN
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_duplicate_offer_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_booking_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lounge_name text;
  v_actor_type text;
  v_title_ar text;
  v_title_en text;
  v_body_ar text;
  v_body_en text;
BEGIN
  SELECT COALESCE(l.name_ar, l.name_en, l.name)
  INTO v_lounge_name
  FROM public.lounges AS l
  WHERE l.id = NEW.lounge_id;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.notifications (
      user_id,
      lounge_id,
      title_ar,
      title_en,
      body_ar,
      body_en,
      type,
      is_read,
      metadata,
      created_at
    )
    VALUES (
      NEW.user_id,
      NEW.lounge_id,
      'طلب الحجز وصل!',
      'Booking Request Received!',
      'طلبك في ' || COALESCE(v_lounge_name, 'الصالة') || ' وصل، مستني موافقة الإدارة',
      'Your request at ' || COALESCE(v_lounge_name, 'the lounge') || ' was received, waiting for approval',
      'booking',
      false,
      jsonb_build_object(
        'booking_id', NEW.id,
        'lounge_id', NEW.lounge_id,
        'status', NEW.status::text,
        'event', 'booking_created'
      ),
      now()
    );

  ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF NEW.status = 'upcoming'::public.booking_status THEN
      INSERT INTO public.notifications (
        user_id,
        lounge_id,
        title_ar,
        title_en,
        body_ar,
        body_en,
        type,
        is_read,
        metadata,
        created_at
      )
      VALUES (
        NEW.user_id,
        NEW.lounge_id,
        'تم قبول حجزك! 🎉',
        'Booking Accepted! 🎉',
        'وافق صاحب الصالة على طلب حجزك في ' || COALESCE(v_lounge_name, ''),
        'Your booking at ' || COALESCE(v_lounge_name, '') || ' has been approved.',
        'booking',
        false,
        jsonb_build_object(
          'booking_id', NEW.id,
          'lounge_id', NEW.lounge_id,
          'status', NEW.status::text,
          'event', 'booking_approved'
        ),
        now()
      );

    ELSIF NEW.status IN (
      'cancelled'::public.booking_status,
      'rejected'::public.booking_status
    ) THEN
      v_actor_type := CASE
        WHEN auth.uid() = NEW.user_id THEN 'user'
        WHEN auth.uid() IS NULL THEN 'system'
        ELSE 'admin'
      END;

      IF NEW.status = 'cancelled'::public.booking_status
         AND v_actor_type = 'user' THEN
        v_title_ar := 'تم إلغاء حجزك بنجاح';
        v_title_en := 'Booking Cancelled Successfully';
        v_body_ar := 'تم إلغاء حجزك بنجاح. نأمل أن نراك مرة أخرى.';
        v_body_en := 'Your booking was cancelled successfully. We hope to see you again.';
      ELSIF v_actor_type = 'system' THEN
        v_title_ar := 'تم إلغاء الحجز تلقائيًا';
        v_title_en := 'Booking Cancelled Automatically';
        v_body_ar := 'تم إلغاء حجزك تلقائيًا بسبب انتهاء مهلة الحجز.';
        v_body_en := 'Your booking was cancelled automatically because the booking time limit expired.';
      ELSIF NEW.status = 'rejected'::public.booking_status THEN
        v_title_ar := 'لم تتم الموافقة على حجزك';
        v_title_en := 'Booking Not Approved';
        v_body_ar := 'نأسف، لم تتم الموافقة على حجزك من قبل إدارة الصالة.';
        v_body_en := 'Sorry, your booking was not approved by the lounge management.';
      ELSE
        v_title_ar := 'نأسف، تم إلغاء حجزك';
        v_title_en := 'Booking Cancelled by Management';
        v_body_ar := 'نأسف، تم إلغاء حجزك من قبل إدارة الصالة في ' || COALESCE(v_lounge_name, 'الصالة') || '.';
        v_body_en := 'Sorry, your booking at ' || COALESCE(v_lounge_name, 'the lounge') || ' was cancelled by the lounge management.';
      END IF;

      INSERT INTO public.notifications (
        user_id,
        lounge_id,
        title_ar,
        title_en,
        body_ar,
        body_en,
        type,
        is_read,
        metadata,
        created_at
      )
      VALUES (
        NEW.user_id,
        NEW.lounge_id,
        v_title_ar,
        v_title_en,
        v_body_ar,
        v_body_en,
        'booking',
        false,
        jsonb_build_object(
          'booking_id', NEW.id,
          'lounge_id', NEW.lounge_id,
          'status', NEW.status::text,
          'event', 'booking_status_changed',
          'cancellation_source', v_actor_type
        ),
        now()
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_booking_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_booking_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- التحقق الصارم من تغير الحالة وعدم التكرار
  IF (TG_OP = 'UPDATE' AND (OLD.status::TEXT IS DISTINCT FROM NEW.status::TEXT)) THEN
    
    IF NEW.status::TEXT IN ('completed', 'cancelled', 'rejected', 'declined') THEN
      UPDATE public.rooms 
      SET status = 'available' 
      WHERE id = NEW.room_id 
        AND status <> 'available'; -- شرط يمنع التحديث غير الضروري
        
    ELSIF NEW.status::TEXT IN ('in_progress', 'active', 'occupied') THEN
      UPDATE public.rooms 
      SET status = 'occupied' 
      WHERE id = NEW.room_id 
        AND status <> 'occupied'; -- شرط يمنع التحديث غير الضروري
    END IF;

  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_booking_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_booking_status_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_title_ar text;
  v_title_en text;
  v_body_ar text;
  v_body_en text;
  v_lounge_name_ar text;
  v_lounge_name_en text;
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    SELECT COALESCE(l.name_ar, l.name, 'الصالة'),
           COALESCE(l.name_en, l.name, 'the lounge')
    INTO v_lounge_name_ar, v_lounge_name_en
    FROM public.lounges AS l
    WHERE l.id = NEW.lounge_id;

    IF NEW.status = 'upcoming'::public.booking_status THEN
      v_title_ar := 'تم قبول حجزك! 🎉';
      v_title_en := 'Booking Accepted! 🎉';
      v_body_ar := 'تم قبول حجزك في ' || v_lounge_name_ar || '.';
      v_body_en := 'Your booking at ' || v_lounge_name_en || ' has been accepted.';
    ELSIF NEW.status = 'cancelled'::public.booking_status THEN
      v_title_ar := 'تم إلغاء حجزك ❌';
      v_title_en := 'Booking Cancelled ❌';
      v_body_ar := 'تم إلغاء حجزك في ' || v_lounge_name_ar || '.';
      v_body_en := 'Your booking at ' || v_lounge_name_en || ' was cancelled.';
    ELSIF NEW.status = 'completed'::public.booking_status THEN
      v_title_ar := 'اكتملت الجلسة ⭐';
      v_title_en := 'Session Completed ⭐';
      v_body_ar := 'نتمنى أنك استمتعت بوقتك في ' || v_lounge_name_ar || '.';
      v_body_en := 'We hope you enjoyed your time at ' || v_lounge_name_en || '.';
    ELSE
      RETURN NEW;
    END IF;

    INSERT INTO public.notifications (
      user_id, lounge_id, title_ar, title_en, body_ar, body_en,
      type, is_read, metadata, created_at
    ) VALUES (
      NEW.user_id, NEW.lounge_id, v_title_ar, v_title_en, v_body_ar, v_body_en,
      'booking', false,
      jsonb_build_object('booking_id', NEW.id, 'status', NEW.status::text),
      now()
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_booking_status_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_loyalty_points_on_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_points_earned integer;
BEGIN
  IF NEW.status = 'completed'
     AND (OLD.status IS NULL OR OLD.status <> 'completed')
     AND NEW.user_id IS NOT NULL
     AND NEW.booking_id IS NOT NULL THEN

    IF EXISTS (
      SELECT 1 FROM public.points_transactions
      WHERE user_id = NEW.user_id AND reference_id = NEW.booking_id AND type IN ('earn', 'earn_booking')
    ) THEN
      RETURN NEW;
    END IF;

    v_points_earned := FLOOR(COALESCE(NEW.amount, 0) / 10)::integer;
    IF v_points_earned > 0 THEN
      PERFORM public.award_points(
        NEW.user_id, v_points_earned, 'earn_booking', NEW.booking_id,
        'نقاط من حجز مكتمل', 'booking', NEW.booking_id,
        'booking_completed:' || NEW.booking_id::text,
        jsonb_build_object('booking_id', NEW.booking_id, 'amount', NEW.amount)
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_loyalty_points_on_payment"() OWNER TO "postgres";


