CREATE OR REPLACE FUNCTION "public"."handle_no_show_paid_bookings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now_local timestamp without time zone := pg_catalog.now() AT TIME ZONE 'Africa/Cairo';
  r record;
  v_count integer := 0;
  v_grace_minutes integer;
BEGIN
  FOR r IN
    SELECT b.id, b.room_id,
           COALESCE(l.cash_grace_period_minutes, 15) AS grace_minutes
    FROM public.bookings AS b
    JOIN public.lounges AS l ON l.id = b.lounge_id
    WHERE b.status = 'upcoming'::public.booking_status
      AND b.payment_status = 'paid'
      AND b.checked_in_at IS NULL
      AND b.booking_period IS NOT NULL
      AND lower(b.booking_period) + make_interval(mins => COALESCE(l.cash_grace_period_minutes, 15)) <= v_now_local
    FOR UPDATE OF b SKIP LOCKED
  LOOP
    UPDATE public.bookings AS b
    SET status = 'cancelled'::public.booking_status,
        cancellation_reason = 'NO_SHOW: Paid booking was not checked in within the grace period',
        updated_at = pg_catalog.now()
    WHERE b.id = r.id;

    v_count := v_count + 1;
    IF r.room_id IS NOT NULL THEN
      PERFORM public.sync_room_status(r.room_id);
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."handle_no_show_paid_bookings"() OWNER TO "postgres";


