CREATE OR REPLACE FUNCTION "public"."handle_promo_geo_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lounge_name text;
  v_audience text :=
    lower(COALESCE(NULLIF(btrim(NEW.target_audience), ''), 'all'));
BEGIN
  SELECT COALESCE(l.name_ar, l.name_en, l.name)
  INTO v_lounge_name
  FROM public.lounges AS l
  WHERE l.id = NEW.lounge_id;

  INSERT INTO public.notifications (
    user_id,
    lounge_id,
    title_ar,
    title_en,
    body_ar,
    body_en,
    type,
    is_read,
    metadata
  )
  SELECT
    p.id,
    NEW.lounge_id,
    '🔥 ' || COALESCE(NULLIF(NEW.title_ar, ''), 'عرض جديد!'),
    '🔥 ' || COALESCE(NULLIF(NEW.title_en, ''), 'New Offer!'),
    COALESCE(NULLIF(NEW.tag_ar, ''), 'خصم خاص')
      || ' لدى صالة '
      || COALESCE(v_lounge_name, ''),
    COALESCE(NULLIF(NEW.tag_en, ''), 'Special discount')
      || ' at '
      || COALESCE(v_lounge_name, ''),
    'offer',
    false,
    jsonb_build_object(
      'promo_id', NEW.id,
      'lounge_id', NEW.lounge_id,
      'room_id', NEW.room_id,
      'target_audience', v_audience
    )
  FROM public.profiles AS p
  WHERE p.role = 'user'
    AND COALESCE(p.is_active, true)
    AND (
      v_audience = 'all'
      OR (
        v_audience = 'local'
        AND (
          p.lounge_id = NEW.lounge_id
          OR p.lounge_id IS NULL
        )
      )
    );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_promo_geo_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_stock_on_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- عند إضافة صنف جديد، يتم خصم الكمية من extras
    IF (TG_OP = 'INSERT') THEN
        UPDATE public.extras
        SET stock_quantity = stock_quantity - NEW.quantity
        WHERE id = NEW.product_id AND track_stock = true;
    
    -- عند تعديل الكمية
    ELSIF (TG_OP = 'UPDATE') THEN
        UPDATE public.extras
        SET stock_quantity = stock_quantity - (NEW.quantity - OLD.quantity)
        WHERE id = NEW.product_id AND track_stock = true;

    -- عند حذف الطلب، يتم استرجاع الكمية للمخزون
    ELSIF (TG_OP = 'DELETE') THEN
        UPDATE public.extras
        SET stock_quantity = stock_quantity + OLD.quantity
        WHERE id = OLD.product_id AND track_stock = true;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_stock_on_order"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_lounge_permission"("p_lounge_id" "uuid", "p_permission_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT auth.uid() IS NOT NULL AND private.user_permission_value(auth.uid(),p_lounge_id,p_permission_key);
$$;


