CREATE OR REPLACE FUNCTION "public"."is_admin_of_lounge"("target_lounge_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT CASE
    WHEN auth.uid() IS NULL OR target_lounge_id IS NULL THEN false
    ELSE public.is_super_admin()
      OR EXISTS (
        SELECT 1 FROM public.lounges AS l
        WHERE l.id = target_lounge_id AND l.owner_id = auth.uid()
      )
      OR EXISTS (
        SELECT 1 FROM public.profiles AS p
        WHERE p.id = auth.uid()
          AND p.lounge_id = target_lounge_id
          AND COALESCE(p.is_active, true)
          AND p.role IN ('owner', 'lounge_admin', 'admin', 'manager')
      )
      OR EXISTS (
        SELECT 1
        FROM public.lounge_staff AS ls
        JOIN public.profiles AS p ON p.id = ls.user_id
        WHERE ls.lounge_id = target_lounge_id
          AND ls.user_id = auth.uid()
          AND COALESCE(p.is_active, true)
          AND ls.role IN ('lounge_owner', 'manager')
      )
  END;
$$;


