CREATE OR REPLACE FUNCTION "public"."mark_payout_paid"("p_payout_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  UPDATE public.payouts
  SET status = 'paid', paid_at = now(), paid_by = auth.uid(), notes = COALESCE(p_notes, notes)
  WHERE id = p_payout_id AND status IN ('approved','processing');
  IF NOT FOUND THEN RAISE EXCEPTION 'Payout not found or not ready to be paid'; END IF;
END;
$$;


