CREATE OR REPLACE FUNCTION "public"."normalize_canteen_order_items"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Prices are immutable order snapshots, including discounted offer prices.
  SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(x.value || jsonb_build_object(
    'name',COALESCE(NULLIF(x.value->>'name',''),c.name_ar,e.name_en,e.name_ar,e.name),
    'name_ar',COALESCE(x.value->>'name_ar',c.name_ar,e.name_ar),
    'name_en',COALESCE(x.value->>'name_en',c.name_en,e.name_en),
    'quantity',COALESCE((x.value->>'quantity')::integer,1),
    'price',COALESCE((x.value->>'unit_price')::numeric,(x.value->>'price')::numeric,c.price,e.price,0),
    'unit_price',COALESCE((x.value->>'unit_price')::numeric,(x.value->>'price')::numeric,c.price,e.price,0),
    'total_price',COALESCE((x.value->>'total_price')::numeric,
      COALESCE((x.value->>'unit_price')::numeric,(x.value->>'price')::numeric,c.price,e.price,0)
      * COALESCE((x.value->>'quantity')::integer,1)))) ORDER BY x.ord),'[]'::jsonb)
  INTO NEW.items
  FROM jsonb_array_elements(COALESCE(NEW.items,'[]'::jsonb)) WITH ORDINALITY x(value,ord)
  LEFT JOIN public.extras e ON e.id::text = COALESCE(x.value->>'extra_id',x.value->>'product_id',x.value->>'id')
  LEFT JOIN public.canteen_combos c ON c.id::text = x.value->>'combo_id';
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_canteen_order_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_booking_cancellation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status::text = 'cancelled'
     AND (OLD.status IS NULL OR OLD.status::text <> 'cancelled')
     AND EXISTS (
       SELECT 1
       FROM information_schema.tables
       WHERE table_schema = 'public'
         AND table_name = 'notifications'
     ) THEN
    INSERT INTO public.notifications (
      user_id, lounge_id, title_ar, title_en, body_ar, body_en,
      type, is_read, metadata, created_at
    )
    VALUES (
      NEW.user_id,
      NEW.lounge_id,
      'تم إلغاء الحجز',
      'Booking Cancelled',
      'تم إلغاء حجزك بنجاح.',
      'Your booking was cancelled successfully.',
      'booking',
      false,
      jsonb_build_object('booking_id', NEW.id, 'lounge_id', NEW.lounge_id),
      now()
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_booking_cancellation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_canteen_order_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE v_title_ar text; v_title_en text; v_body_ar text; v_body_en text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status OR NEW.user_id IS NULL THEN RETURN NEW; END IF;
  CASE NEW.status
    WHEN 'preparing','in_progress' THEN
      v_title_ar:='طلبك قيد التحضير 🍔'; v_title_en:='Your order is being prepared 🍔';
      v_body_ar:='بدأت الصالة في تحضير طلب الكانتين.'; v_body_en:='The lounge has started preparing your canteen order.';
    WHEN 'delivered','completed' THEN
      v_title_ar:='تم توصيل طلبك ✅'; v_title_en:='Your order was delivered ✅';
      v_body_ar:='تم توصيل طلب الكانتين إلى غرفتك.'; v_body_en:='Your canteen order was delivered to your room.';
    WHEN 'cancelled' THEN
      v_title_ar:='تم إلغاء طلب الكانتين ❌'; v_title_en:='Canteen order cancelled ❌';
      v_body_ar:='تم إلغاء طلب الكانتين.'; v_body_en:='Your canteen order was cancelled.';
    ELSE RETURN NEW;
  END CASE;
  INSERT INTO public.notifications(user_id,lounge_id,title_ar,title_en,body_ar,body_en,type,is_read,metadata)
  VALUES(NEW.user_id,NEW.lounge_id,v_title_ar,v_title_en,v_body_ar,v_body_en,'canteen',false,
    jsonb_build_object('order_id',NEW.id,'booking_id',NEW.booking_id,'status',NEW.status));
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_canteen_order_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_pending_booking_extension"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_lounge_name_ar text;
  v_lounge_name_en text;
  v_recipient uuid;
BEGIN
  IF NEW.extension_status = 'pending'
     AND OLD.extension_status IS DISTINCT FROM NEW.extension_status THEN
    SELECT
      COALESCE(name_ar, name, 'الصالة'),
      COALESCE(name_en, name, 'the lounge')
    INTO v_lounge_name_ar, v_lounge_name_en
    FROM public.lounges
    WHERE id = NEW.lounge_id;

    FOR v_recipient IN
      SELECT l.owner_id
      FROM public.lounges l
      WHERE l.id = NEW.lounge_id
        AND l.owner_id IS NOT NULL
      UNION
      SELECT ls.user_id
      FROM public.lounge_staff ls
      WHERE ls.lounge_id = NEW.lounge_id
        AND ls.role IN ('lounge_owner', 'manager', 'cashier')
    LOOP
      INSERT INTO public.notifications (
        user_id, lounge_id, title_ar, title_en, body_ar, body_en,
        type, is_read, metadata, created_at
      )
      VALUES (
        v_recipient,
        NEW.lounge_id,
        'طلب تمديد حجز جديد ⏰',
        'New Booking Extension Request ⏰',
        'يوجد طلب تمديد لمدة ' || COALESCE(NEW.requested_extension_minutes, 0) || ' دقيقة في ' || v_lounge_name_ar || ' ويحتاج إلى موافقة.',
        'A ' || COALESCE(NEW.requested_extension_minutes, 0) || '-minute extension request at ' || v_lounge_name_en || ' needs approval.',
        'booking',
        false,
        jsonb_build_object(
          'booking_id', NEW.id,
          'lounge_id', NEW.lounge_id,
          'request_type', 'booking_extension',
          'extension_status', 'pending',
          'extension_minutes', NEW.requested_extension_minutes
        ),
        now()
      );
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_pending_booking_extension"() OWNER TO "postgres";


