        'Your shift was approved. Total sales: '||COALESCE(NEW.total_cash_sales+NEW.total_digital_sales,0)||', difference: '||COALESCE(NEW.difference,0),
        'shift_approved',false,jsonb_build_object('shift_id',NEW.id,'cashier_id',v_recipient,'is_approved',true,
          'starting_cash',NEW.starting_cash,'total_cash_sales',NEW.total_cash_sales,'total_digital_sales',NEW.total_digital_sales,
          'total_expenses',NEW.total_expenses,'expected_cash',NEW.expected_cash,'actual_cash_counted',NEW.actual_cash_counted,'difference',NEW.difference));
    END IF;
