CREATE OR REPLACE FUNCTION "public"."notify_super_admins_on_kyc_submission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  owner_profile public.profiles%rowtype;
  lounge_record public.lounges%rowtype;
  lounge_display_name text;
begin
  if new.user_id is null or new.id_document_url is null
     or (tg_op = 'UPDATE'
         and old.id_document_url is not distinct from new.id_document_url
         and old.business_document_url is not distinct from new.business_document_url) then
    return new;
  end if;

  select p.* into owner_profile from public.profiles p where p.id = new.user_id;
  select l.* into lounge_record from public.lounges l
   where l.owner_id = new.user_id order by l.created_at desc limit 1;
  if lounge_record.id is null then return new; end if;

  lounge_display_name := coalesce(lounge_record.name_ar, lounge_record.name_en, lounge_record.name, '');
  insert into public.notifications
    (user_id, title_ar, title_en, body_ar, body_en, type, metadata, lounge_id)
  select sa.user_id,
    'طلب انضمام صالة جديدة', 'New Lounge Onboarding Request',
    'قامت صالة ' || lounge_display_name || ' برفع مستندات الهوية، وبانتظار المراجعة والاعتماد.',
    lounge_display_name || ' has submitted KYC documents for review.', 'kyc',
    jsonb_build_object(
      'user_id', new.user_id, 'lounge_id', lounge_record.id,
      'lounge_name', lounge_display_name, 'owner_name', owner_profile.full_name,
      'owner_phone', owner_profile.phone, 'request_type', 'kyc_review'
    ), lounge_record.id
  from public.platform_super_admins sa
  where not exists (
    select 1 from public.notifications existing
    where existing.user_id = sa.user_id and existing.type = 'kyc'
      and existing.lounge_id = lounge_record.id
      and existing.metadata ->> 'request_type' = 'kyc_review'
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."notify_super_admins_on_kyc_submission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."onboard_lounge"("p_name" "text", "p_city" "text", "p_lat" double precision, "p_lng" double precision, "p_location" "text", "p_opens_at" "text", "p_closes_at" "text", "p_image_url" "text" DEFAULT NULL::"text", "p_description_ar" "text" DEFAULT NULL::"text", "p_description_en" "text" DEFAULT NULL::"text", "p_images" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_existing_lounge_id uuid;
  v_new_lounge_id uuid;
  v_is_super_admin boolean;
  v_location_point public.geography;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NULLIF(btrim(p_name),'') IS NULL OR ((p_lat IS NULL) <> (p_lng IS NULL)) OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'INVALID_LOUNGE_DRAFT' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM public.profiles WHERE id=v_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OWNER_PROFILE_REQUIRED' USING ERRCODE='42501'; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.platform_super_admins psa
    WHERE psa.user_id = v_user_id
  ) OR EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = v_user_id AND p.role = 'super_admin'
  ) INTO v_is_super_admin;

  SELECT p.lounge_id INTO v_existing_lounge_id
  FROM public.profiles p
  WHERE p.id = v_user_id
    AND p.role IN ('owner', 'lounge_admin')
    AND COALESCE(p.is_setup_completed, false) = false;

  IF v_existing_lounge_id IS NULL
     AND NOT v_is_super_admin
     AND NOT EXISTS (
       SELECT 1 FROM public.profiles p
       WHERE p.id = v_user_id
         AND p.role IN ('owner', 'lounge_admin')
     ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    v_location_point := public.ST_SetSRID(public.ST_MakePoint(p_lng, p_lat), 4326)::public.geography;
  END IF;

  IF v_existing_lounge_id IS NOT NULL THEN
    UPDATE public.lounges
    SET name = COALESCE(p_name, name),
        city = COALESCE(p_city, city),
        location = COALESCE(p_location, location),
        location_point = COALESCE(v_location_point, location_point),
        opening_time = COALESCE(NULLIF(p_opens_at, '')::time, opening_time),
        closing_time = COALESCE(NULLIF(p_closes_at, '')::time, closing_time),
        image_url = COALESCE(p_image_url, image_url),
        images = COALESCE(p_images, images),
        description_ar = COALESCE(p_description_ar, description_ar),
        description_en = COALESCE(p_description_en, description_en),
        status = 'pending',
        is_open = false,
        is_active = false
    WHERE id = v_existing_lounge_id AND owner_id=v_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'LOUNGE_OWNER_REQUIRED' USING ERRCODE='42501'; END IF;

    UPDATE public.profiles
    SET is_setup_completed = false,
        updated_at = now()
    WHERE id = v_user_id;

    RETURN jsonb_build_object(
      'success', true,
      'lounge_id', v_existing_lounge_id,
      'status', 'pending'
    );
  END IF;

  INSERT INTO public.lounges (
    owner_id, name, city, location, location_point, opening_time, closing_time,
    image_url, images, description_ar, description_en,
    is_open, is_active, status
  ) VALUES (
    v_user_id, p_name, p_city, p_location, v_location_point,
    NULLIF(p_opens_at, '')::time,
    NULLIF(p_closes_at, '')::time,
    p_image_url, p_images, p_description_ar, p_description_en,
    false, false, 'pending'
  )
  RETURNING id INTO v_new_lounge_id;

  UPDATE public.profiles
  SET lounge_id = v_new_lounge_id,
      is_setup_completed = false,
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'lounge_id', v_new_lounge_id,
    'status', 'pending'
  );
END;
$$;


ALTER FUNCTION "public"."onboard_lounge"("p_name" "text", "p_city" "text", "p_lat" double precision, "p_lng" double precision, "p_location" "text", "p_opens_at" "text", "p_closes_at" "text", "p_image_url" "text", "p_description_ar" "text", "p_description_en" "text", "p_images" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_lounge_shift"("p_lounge_id" "uuid", "p_starting_cash" numeric DEFAULT 0, "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."shifts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_shift public.shifts%ROWTYPE;
BEGIN
  IF NOT public._playspot_has_lounge_access(p_lounge_id) THEN RAISE EXCEPTION 'Lounge access denied' USING ERRCODE='42501'; END IF;
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required' USING ERRCODE = '28000';
  END IF;

  IF NOT (public.is_super_admin() OR private.can_operate_playspot_lounge(p_lounge_id) OR public.is_lounge_member_or_admin(p_lounge_id)) THEN
    RAISE EXCEPTION 'You are not allowed to open a shift for this lounge' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_shift
  FROM public.shifts
  WHERE lounge_id = p_lounge_id AND status = 'open' AND closed_at IS NULL
  ORDER BY opened_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_populate_record(NULL::public.shifts,private.mask_shift_financials(p_lounge_id,to_jsonb(v_shift)));
  END IF;

  INSERT INTO public.shifts (
    lounge_id,
    staff_user_id,
    cashier_id,
    status,
    starting_cash,
    notes,
    opened_at,
    start_time
  )
  VALUES (
    p_lounge_id,
    auth.uid(),
    auth.uid(),
    'open',
    GREATEST(COALESCE(p_starting_cash, 0), 0),
    p_notes,
    now(),
    now()
  )
  RETURNING * INTO v_shift;

  RETURN jsonb_populate_record(NULL::public.shifts,private.mask_shift_financials(p_lounge_id,to_jsonb(v_shift)));
EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_shift
    FROM public.shifts
    WHERE lounge_id = p_lounge_id AND status = 'open' AND closed_at IS NULL
    ORDER BY opened_at DESC
    LIMIT 1;
    RETURN jsonb_populate_record(NULL::public.shifts,private.mask_shift_financials(p_lounge_id,to_jsonb(v_shift)));
END;
$$;


ALTER FUNCTION "public"."open_lounge_shift"("p_lounge_id" "uuid", "p_starting_cash" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_shift"("p_lounge_id" "uuid", "p_opening_cash" numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_new public.shifts%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF NOT (public.is_super_admin() OR private.can_operate_playspot_lounge(p_lounge_id) OR public.is_lounge_member_or_admin(p_lounge_id)) THEN
    RAISE EXCEPTION 'You are not allowed to open a shift for this lounge' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_new
  FROM public.shifts
  WHERE lounge_id = p_lounge_id AND status = 'open' AND closed_at IS NULL
  ORDER BY opened_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN json_build_object(
      'id', v_new.id,
      'lounge_id', v_new.lounge_id,
      'cashier_id', v_new.cashier_id,
      'starting_cash', v_new.starting_cash,
      'status', v_new.status,
      'opened_at', v_new.opened_at
    );
  END IF;

  INSERT INTO public.shifts (lounge_id, cashier_id, staff_user_id, starting_cash, status, start_time, opened_at)
  VALUES (p_lounge_id, auth.uid(), auth.uid(), COALESCE(p_opening_cash, 0), 'open', now(), now())
  RETURNING * INTO v_new;

  RETURN json_build_object(
    'id', v_new.id,
    'lounge_id', v_new.lounge_id,
    'cashier_id', v_new.cashier_id,
    'starting_cash', v_new.starting_cash,
    'status', v_new.status,
    'opened_at', v_new.opened_at
  );
EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_new
    FROM public.shifts
    WHERE lounge_id = p_lounge_id AND status = 'open' AND closed_at IS NULL
    ORDER BY opened_at DESC
    LIMIT 1;

    RETURN json_build_object(
      'id', v_new.id,
      'lounge_id', v_new.lounge_id,
      'cashier_id', v_new.cashier_id,
      'starting_cash', v_new.starting_cash,
      'status', v_new.status,
      'opened_at', v_new.opened_at
    );
END;
$$;


ALTER FUNCTION "public"."open_shift"("p_lounge_id" "uuid", "p_opening_cash" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_canteen_order"("p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_booking public.bookings%ROWTYPE;
  v_shift_id uuid;
  v_lounge_id uuid;
  v_shift_count integer;
  v_order_id uuid := gen_random_uuid();
  v_parent_id uuid;
  v_note text := NULLIF(btrim(p_note), '');
  v_now timestamp;
  v_item jsonb;
  v_extra_id uuid;
  v_combo_id uuid;
  v_rule_id uuid;
  v_quantity integer;
  v_price numeric;
  v_name text;
  v_extra public.extras%ROWTYPE;
  v_combo public.canteen_combos%ROWTYPE;
  v_component record;
  v_demand record;
  v_suggestion jsonb;
  v_suggestions jsonb := '[]'::jsonb;
  v_total numeric := 0;
  v_lines jsonb := '[]'::jsonb;
  v_demands jsonb := '[]'::jsonb;
  v_shortages jsonb := '[]'::jsonb;
  v_component_count integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'Items must be a JSON array containing 1 to 50 entries' USING ERRCODE = '22023';
  END IF;
  IF length(v_note) > 1000 THEN
    RAISE EXCEPTION 'Order note is too long' USING ERRCODE = '22023';
  END IF;
  IF p_booking_id IS NOT NULL THEN
    SELECT b.* INTO v_booking FROM public.bookings b WHERE b.id = p_booking_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002'; END IF;
    IF v_booking.status NOT IN ('pending','upcoming','in_progress') THEN
      RAISE EXCEPTION 'Canteen orders are not allowed for this booking status' USING ERRCODE = '55000';
    END IF;
    IF v_actor IS DISTINCT FROM v_booking.user_id
       AND NOT private.can_operate_playspot_lounge(v_booking.lounge_id) THEN
      RAISE EXCEPTION 'Not authorized to order for this booking' USING ERRCODE = '42501';
    END IF;
    v_lounge_id := v_booking.lounge_id;
    IF v_actor = v_booking.user_id THEN
      v_suggestions := private.get_canteen_upsell_suggestions(p_booking_id, true);
    END IF;
  ELSE
    SELECT count(*), (array_agg(s.id ORDER BY s.opened_at DESC))[1],
      (array_agg(s.lounge_id ORDER BY s.opened_at DESC))[1]
    INTO v_shift_count, v_shift_id, v_lounge_id
    FROM public.shifts s WHERE s.status = 'open' AND s.cashier_id = v_actor;
    IF v_shift_count <> 1 THEN
      RAISE EXCEPTION 'A single open cashier shift is required for a counter sale' USING ERRCODE = '55000';
    END IF;
  END IF;
  IF v_lounge_id IS NULL THEN RAISE EXCEPTION 'Booking has no lounge' USING ERRCODE = '55000'; END IF;
  SELECT timezone(l.timezone, now()) INTO v_now FROM public.lounges l WHERE l.id = v_lounge_id;

  -- Lock catalogue rows before expanding components. Use the same combo order
  -- as save_canteen_combo, then a global extra-id order for every cart.
  PERFORM c.id FROM public.canteen_combos c
  WHERE c.id IN (SELECT NULLIF(value->>'combo_id','')::uuid FROM jsonb_array_elements(p_items))
  ORDER BY c.id FOR SHARE;
  PERFORM ci.combo_id FROM public.canteen_combo_items ci
  WHERE ci.combo_id IN (SELECT NULLIF(value->>'combo_id','')::uuid FROM jsonb_array_elements(p_items))
  ORDER BY ci.combo_id, ci.extra_id FOR SHARE;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    IF jsonb_typeof(v_item) <> 'object' THEN
      RAISE EXCEPTION 'Each item must be an object' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_extra_id := NULLIF(v_item->>'extra_id','')::uuid;
      v_combo_id := NULLIF(v_item->>'combo_id','')::uuid;
      v_rule_id := NULLIF(v_item->>'upsell_rule_id','')::uuid;
      v_quantity := (v_item->>'quantity')::integer;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'Invalid item identifier or quantity' USING ERRCODE = '22023';
    END;
    IF (v_extra_id IS NULL) = (v_combo_id IS NULL)
       OR v_quantity IS NULL OR v_quantity NOT BETWEEN 1 AND 100
       OR COALESCE(v_item->>'quantity','') !~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'Each item requires exactly one extra_id or combo_id and quantity 1 to 100' USING ERRCODE = '22023';
    END IF;
    v_parent_id := gen_random_uuid();
    IF v_combo_id IS NOT NULL THEN
      SELECT c.* INTO v_combo FROM public.canteen_combos c
      WHERE c.id = v_combo_id AND c.lounge_id = v_lounge_id;
      IF NOT FOUND OR NOT private.canteen_combo_window_available(v_combo, v_now) THEN
        RAISE EXCEPTION 'Combo unavailable' USING ERRCODE = '23514';
      END IF;
      v_price := v_combo.price;
      v_name := COALESCE(v_combo.name_ar,v_combo.name_en);
      v_component_count := 0;
      FOR v_component IN SELECT ci.* FROM public.canteen_combo_items ci WHERE ci.combo_id = v_combo_id LOOP
        v_component_count := v_component_count + 1;
        v_demands := v_demands || jsonb_build_array(jsonb_build_object('id',v_component.extra_id,
          'quantity',v_component.quantity::bigint * v_quantity));
      END LOOP;
      IF v_component_count = 0 THEN RAISE EXCEPTION 'Combo has no components' USING ERRCODE = '23514'; END IF;
    ELSE
      SELECT e.* INTO v_extra FROM public.extras e WHERE e.id = v_extra_id AND e.lounge_id = v_lounge_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Extra unavailable' USING ERRCODE = '23514'; END IF;
      v_price := v_extra.price;
      v_name := COALESCE(v_extra.name_ar,v_extra.name_en,v_extra.name);
      v_demands := v_demands || jsonb_build_array(jsonb_build_object('id',v_extra_id,'quantity',v_quantity));
    END IF;
    IF v_rule_id IS NOT NULL THEN
      SELECT value INTO v_suggestion FROM jsonb_array_elements(v_suggestions)
      WHERE value->>'rule_id' = v_rule_id::text
        AND value->>'target_id' = COALESCE(v_combo_id,v_extra_id)::text
        AND value->>'suggestion_type' = CASE WHEN v_combo_id IS NOT NULL THEN 'combo' ELSE 'extra' END;
      IF NOT FOUND THEN RAISE EXCEPTION 'UPSELL_OFFER_UNAVAILABLE' USING ERRCODE = '23514'; END IF;
      v_price := round(v_price * (1 - (v_suggestion->>'discount_percent')::numeric / 100),2);
    END IF;
    IF v_price IS NULL OR v_price < 0 THEN RAISE EXCEPTION 'Invalid canteen price' USING ERRCODE = '23514'; END IF;
    v_total := v_total + round(v_price * v_quantity,2);
    v_lines := v_lines || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'id',v_parent_id,'extra_id',v_extra_id,'product_id',v_extra_id,'combo_id',v_combo_id,
      'upsell_rule_id',v_rule_id,'is_combo',v_combo_id IS NOT NULL,'name',v_name,
      'name_ar',CASE WHEN v_combo_id IS NOT NULL THEN v_combo.name_ar ELSE v_extra.name_ar END,
      'name_en',CASE WHEN v_combo_id IS NOT NULL THEN v_combo.name_en ELSE v_extra.name_en END,
      'quantity',v_quantity,'price',v_price,'unit_price',v_price,'total_price',round(v_price*v_quantity,2),
      'line_kind',CASE WHEN v_combo_id IS NOT NULL THEN 'combo_parent' ELSE 'item' END)));
  END LOOP;

  -- Aggregate shared components and standalone items before testing stock.
  -- This prevents each line independently accepting the same last units.
  FOR v_demand IN
    SELECT (value->>'id')::uuid id, sum((value->>'quantity')::bigint) quantity
    FROM jsonb_array_elements(v_demands) GROUP BY 1 ORDER BY 1
  LOOP
    SELECT e.* INTO v_extra FROM public.extras e WHERE e.id = v_demand.id FOR UPDATE;
    IF NOT FOUND OR v_extra.lounge_id IS DISTINCT FROM v_lounge_id
       OR v_extra.is_active IS NOT TRUE OR v_extra.is_available IS NOT TRUE THEN
      RAISE EXCEPTION 'Extra or combo component unavailable' USING ERRCODE = '23514';
    END IF;
    IF v_demand.quantity > 2147483647 THEN RAISE EXCEPTION 'Quantity is too large' USING ERRCODE = '22023'; END IF;
    IF v_extra.track_stock IS TRUE AND COALESCE(v_extra.stock_quantity,0) < v_demand.quantity THEN
      v_shortages := v_shortages || jsonb_build_array(jsonb_build_object('id',v_extra.id,
        'name',COALESCE(v_extra.name_ar,v_extra.name_en,v_extra.name),
        'available',COALESCE(v_extra.stock_quantity,0),'requested',v_demand.quantity));
    END IF;
  END LOOP;
  IF jsonb_array_length(v_shortages) > 0 THEN
    RAISE EXCEPTION 'OUT_OF_STOCK' USING ERRCODE = 'P0001',
      DETAIL = jsonb_build_object('unavailable_items',v_shortages)::text;
  END IF;

  -- Standard item prices are re-read under the inventory lock; a changed
  -- catalogue cannot silently produce a different charge from the line price.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_lines) line JOIN public.extras e
    ON e.id = (line->>'extra_id')::uuid LEFT JOIN public.upsell_rules rule ON rule.id = (line->>'upsell_rule_id')::uuid
    WHERE round(e.price * (1 - COALESCE(rule.discount_percent,0)/100),2)
      IS DISTINCT FROM (line->>'unit_price')::numeric) THEN
    RAISE EXCEPTION 'CANTEEN_PRICE_CHANGED' USING ERRCODE = '40001';
  END IF;
  UPDATE public.extras e SET stock_quantity = e.stock_quantity - d.quantity
  FROM (SELECT (value->>'id')::uuid id, sum((value->>'quantity')::integer)::integer quantity
    FROM jsonb_array_elements(v_demands) GROUP BY 1) d
  WHERE e.id = d.id AND e.track_stock IS TRUE;

  INSERT INTO public.canteen_orders(id,booking_id,lounge_id,user_id,shift_id,items,total_price,status,note,notes)
  VALUES(v_order_id,p_booking_id,v_lounge_id,COALESCE(v_booking.user_id,v_actor),v_shift_id,v_lines,v_total,'pending',v_note,v_note);
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_lines) LOOP
    v_parent_id := (v_item->>'id')::uuid;
    v_combo_id := (v_item->>'combo_id')::uuid;
    INSERT INTO public.canteen_order_items(id,order_id,extra_id,combo_id,upsell_rule_id,item_name,quantity,unit_price,total_price,line_kind)
    VALUES(v_parent_id,v_order_id,(v_item->>'extra_id')::uuid,v_combo_id,(v_item->>'upsell_rule_id')::uuid,
      v_item->>'name',(v_item->>'quantity')::integer,(v_item->>'unit_price')::numeric,
      (v_item->>'total_price')::numeric,v_item->>'line_kind');
    IF v_combo_id IS NOT NULL THEN
      INSERT INTO public.canteen_order_items(order_id,extra_id,combo_id,combo_line_id,item_name,quantity,unit_price,total_price,line_kind)
      SELECT v_order_id,ci.extra_id,v_combo_id,v_parent_id,COALESCE(e.name_ar,e.name_en,e.name),
        ci.quantity * (v_item->>'quantity')::integer,0,0,'combo_component'
      FROM public.canteen_combo_items ci JOIN public.extras e ON e.id = ci.extra_id WHERE ci.combo_id = v_combo_id;
    END IF;
    IF p_booking_id IS NOT NULL THEN
      INSERT INTO public.booking_items(booking_id,extra_id,product_id,quantity,unit_price,total_price,price,name,status)
      VALUES(p_booking_id,(v_item->>'extra_id')::uuid,(v_item->>'extra_id')::uuid,
        (v_item->>'quantity')::integer,(v_item->>'unit_price')::numeric,(v_item->>'total_price')::numeric,
        (v_item->>'unit_price')::numeric,v_item->>'name','pending');
    END IF;
  END LOOP;
  IF p_booking_id IS NOT NULL THEN
    UPDATE public.bookings SET addons_price = COALESCE(addons_price,0) + v_total,
      addons_total = COALESCE(addons_price,0) + v_total, updated_at = now() WHERE id = p_booking_id;
    FOR v_rule_id IN SELECT DISTINCT (value->>'upsell_rule_id')::uuid FROM jsonb_array_elements(v_lines)
      WHERE value->>'upsell_rule_id' IS NOT NULL LOOP
      PERFORM public.record_upsell_event(v_rule_id,p_booking_id,'accepted',v_order_id,NULL);
    END LOOP;
  ELSE
    INSERT INTO public.shift_payments(shift_id,lounge_id,payment_method,category,amount,paid_at,canteen_order_id)
    VALUES(v_shift_id,v_lounge_id,'cash','other',v_total,now(),v_order_id);
  END IF;
  RETURN jsonb_build_object('success',true,'order_id',v_order_id,'lounge_id',v_lounge_id,'shift_id',v_shift_id,'total_price',v_total);
END;
$_$;


ALTER FUNCTION "public"."place_canteen_order"("p_booking_id" "uuid", "p_items" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_booking_tournament_room_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  v_conflict record;
begin
  if new.room_id is null
     or new.booking_period is null
     or new.status::text in ('cancelled', 'rejected') then
    return new;
  end if;

  select tm.id, tm.tournament_id, tm.scheduled_at, tm.scheduled_end_at
    into v_conflict
  from public.tournament_matches tm
  where tm.room_id = new.room_id
    and tm.status <> 'cancelled'
    and tm.scheduled_at is not null
    and tm.scheduled_end_at is not null
    and tsrange(
      tm.scheduled_at at time zone 'Africa/Cairo',
      tm.scheduled_end_at at time zone 'Africa/Cairo',
      '[)'
    ) && new.booking_period
  limit 1;

  if found then
    raise exception
      'Room is reserved for a tournament match during this booking period (match_id: %, tournament_id: %)',
      v_conflict.id,
      v_conflict.tournament_id
      using errcode = '23P01';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_booking_tournament_room_overlap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_closed_shift_transaction"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  SELECT status INTO v_status
  FROM public.shifts
  WHERE id = NEW.shift_id;

  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Shift does not exist.';
  END IF;

  IF v_status <> 'open' THEN
    RAISE EXCEPTION 'Transactions can only be added to an open shift.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_closed_shift_transaction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_overlapping_room_bookings"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  overlap_exists boolean;
begin
  -- Only enforce overlap checks for non-cancelled bookings
  if new.status is not null and new.status <> 'cancelled' then
    select exists (
      select 1
      from public.bookings existing
      where existing.room_id = new.room_id
        and existing.id <> new.id
        and (existing.status is null or existing.status <> 'cancelled')
        and (
          existing.start_time < new.end_time
          and existing.end_time > new.start_time
        )
    )
    into overlap_exists;

    if overlap_exists then
      raise exception
        'Overlapping booking for room_id %', new.room_id
        using errcode = '23514'; -- check_violation
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_overlapping_room_bookings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_tournament_booking_room_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  v_conflict record;
  v_match_period tsrange;
begin
  if new.room_id is null
     or new.scheduled_at is null
     or new.scheduled_end_at is null
     or new.status = 'cancelled' then
    return new;
  end if;

  if new.scheduled_end_at <= new.scheduled_at then
    raise exception
      'Tournament match end time must be after start time'
      using errcode = '22007';
  end if;

  v_match_period := tsrange(
    new.scheduled_at at time zone 'Africa/Cairo',
    new.scheduled_end_at at time zone 'Africa/Cairo',
    '[)'
  );

  select b.id, b.status, b.booking_period
    into v_conflict
  from public.bookings b
  where b.room_id = new.room_id
    and b.id is not null
    and b.status::text not in ('cancelled', 'rejected')
    and b.booking_period is not null
    and b.booking_period && v_match_period
  limit 1;

  if found then
    raise exception
      'Room has a regular booking during this tournament match period (booking_id: %)',
      v_conflict.id
      using errcode = '23P01';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_tournament_booking_room_overlap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_booking_waitlist"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_entry public.booking_waitlist%ROWTYPE;
  v_sent integer := 0;
BEGIN
  -- 1. Housekeeping: expire stale waiting requests whose slot time has passed
  UPDATE public.booking_waitlist
  SET status = 'expired', updated_at = now()
  WHERE status IN ('waiting', 'active')
    AND start_at <= (now() AT TIME ZONE 'Africa/Cairo') + interval '10 minutes';

  -- 2. Housekeeping: expire notified entries whose 10-minute claim window elapsed
  UPDATE public.booking_waitlist
  SET status = 'expired', updated_at = now()
  WHERE status = 'notified'
    AND COALESCE(claim_expires_at, notified_at + interval '10 minutes') <= now();

  -- 3. FIFO Dispatch: loop over earliest waiting requests
  FOR v_entry IN
    SELECT w.*
    FROM public.booking_waitlist w
    WHERE w.status IN ('waiting', 'active')
      AND w.start_at > (now() AT TIME ZONE 'Africa/Cairo') + interval '10 minutes'
      AND NOT EXISTS (
        -- Protect fair claim window: skip slot if another user was notified and claim window is active
        SELECT 1 FROM public.booking_waitlist w2
        WHERE w2.room_id = w.room_id
          AND w2.id <> w.id
          AND w2.status = 'notified'
          AND COALESCE(w2.claim_expires_at, w2.notified_at + interval '10 minutes') > now()
          AND pg_catalog.tsrange(w2.start_at, w2.end_at, '[)')
              && pg_catalog.tsrange(w.start_at, w.end_at, '[)')
      )
    ORDER BY w.created_at ASC, w.id ASC
    LIMIT 50
    FOR UPDATE OF w SKIP LOCKED
  LOOP
    -- Advisory lock on room
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_entry.room_id::text, 0)
    );

    -- Verify room & lounge validity
    IF NOT EXISTS (
      SELECT 1 FROM public.rooms r
      JOIN public.lounges l ON l.id = r.lounge_id
      WHERE r.id = v_entry.room_id
        AND r.lounge_id = v_entry.lounge_id
        AND COALESCE(r.is_active, true) IS TRUE
        AND COALESCE(r.status, 'available') <> 'deleted'
        AND COALESCE(l.is_active, true) IS TRUE
    ) THEN
      CONTINUE;
    END IF;

    -- Check for conflicting bookings
    IF EXISTS (
      SELECT 1 FROM public.bookings b
      WHERE b.room_id = v_entry.room_id
        AND b.status IN ('pending'::public.booking_status,
                         'upcoming'::public.booking_status,
                         'in_progress'::public.booking_status)
        AND (b.status <> 'pending'::public.booking_status
             OR b.expires_at IS NULL OR b.expires_at > now())
        AND b.booking_period && pg_catalog.tsrange(v_entry.start_at, v_entry.end_at, '[)')
    ) THEN
      CONTINUE;
    END IF;

    -- Check for conflicting active holds
    IF EXISTS (
      SELECT 1 FROM public.booking_holds h
      WHERE h.room_id = v_entry.room_id
        AND h.released_at IS NULL
        AND h.expires_at > now()
        AND pg_catalog.tsrange(h.start_at, h.end_at, '[)')
            && pg_catalog.tsrange(v_entry.start_at, v_entry.end_at, '[)')
    ) THEN
      CONTINUE;
    END IF;

    -- Intent de-duplication: do not send simultaneous notifications for same intent
    IF v_entry.intent_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.booking_waitlist s
      WHERE s.intent_id = v_entry.intent_id
        AND s.id <> v_entry.id
        AND s.status = 'notified'
        AND COALESCE(s.claim_expires_at, s.notified_at + interval '10 minutes') > now()
    ) THEN
      CONTINUE;
    END IF;

    -- Mark notified with 10-minute claim window
    UPDATE public.booking_waitlist
    SET status = 'notified',
        notified_at = now(),
        claim_expires_at = now() + interval '10 minutes',
        updated_at = now()
    WHERE id = v_entry.id;

    -- Dispatch localized notification
    INSERT INTO public.notifications (
      user_id,
      lounge_id,
      title,
      body,
      title_ar,
      title_en,
      body_ar,
      body_en,
      type,
      is_read,
      metadata,
      created_at
    ) VALUES (
      v_entry.user_id,
      v_entry.lounge_id,
      'الموعد الذي انتظرته أصبح متاحًا!',
      'أمامك 10 دقائق لتأكيد حجزك قبل إتاحة الموعد للآخرين.',
      'الموعد الذي انتظرته أصبح متاحًا!',
      'Your waitlisted slot is now available!',
      'أمامك 10 دقائق لتأكيد حجزك قبل إتاحة الموعد للآخرين.',
      'You have 10 minutes to claim your slot before it opens to others.',
      'booking',
      false,
      jsonb_build_object(
        'event', 'waitlist_available',
        'waitlist_id', v_entry.id,
        'intent_id', v_entry.intent_id,
        'lounge_id', v_entry.lounge_id,
        'room_id', v_entry.room_id,
        'start_at', v_entry.start_at,
        'end_at', v_entry.end_at,
        'claim_expires_at', now() + interval '10 minutes'
      ),
      now()
    );

    v_sent := v_sent + 1;
  END LOOP;

  RETURN v_sent;
END;
$$;


ALTER FUNCTION "public"."process_booking_waitlist"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_tournament_waitlist"("p_tournament_id" "uuid") RETURNS "public"."tournament_participants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
BEGIN
  SELECT * INTO v_t
  FROM public.tournaments
  WHERE id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament_not_found';
  END IF;

  IF NOT (public.is_super_admin() OR private.is_lounge_manager(v_t.lounge_id)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  RETURN private.promote_tournament_waitlist_internal(p_tournament_id);
END;
$$;


ALTER FUNCTION "public"."promote_tournament_waitlist"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_marketing_announcement"("p_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_promo_code" "text" DEFAULT NULL::"text", "p_discount_percentage" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE v_inserted_count integer := 0;
BEGIN
  IF NOT (
    EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin')
    OR EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND lounge_id = p_lounge_id AND role IN ('owner','lounge_admin','admin','manager'))
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  v_inserted_count := public.send_topic_notification(
    'offers_and_promos', p_title_ar, p_title_en, p_body_ar, p_body_en, 'offer',
    jsonb_build_object('lounge_id', p_lounge_id, 'promo_code', p_promo_code, 'discount', p_discount_percentage)
  );

  RETURN jsonb_build_object('success', true, 'notifications_sent', v_inserted_count);
END;
$$;


ALTER FUNCTION "public"."publish_marketing_announcement"("p_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_promo_code" "text", "p_discount_percentage" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_promotion"("p_expires_at" timestamp with time zone, "p_lounge_id" "uuid", "p_room_id" "uuid", "p_tag_ar" "text", "p_tag_en" "text", "p_title_ar" "text", "p_title_en" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_promo_id uuid;
  v_lounge_name text;
BEGIN
  IF NOT (
    EXISTS (
      SELECT 1
      FROM public.profiles
      WHERE id = auth.uid()
        AND role = 'super_admin'
    )
    OR EXISTS (
      SELECT 1
      FROM public.profiles
      WHERE id = auth.uid()
        AND lounge_id = p_lounge_id
        AND role IN ('owner', 'lounge_admin', 'admin', 'manager')
    )
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT name
    INTO v_lounge_name
  FROM public.lounges
  WHERE id = p_lounge_id;

  INSERT INTO public.promotions (
    lounge_id,
    room_id,
    title,
    title_ar,
    title_en,
    tag,
    tag_ar,
    tag_en,
    expires_at,
    is_room_specific,
    is_active
  )
  VALUES (
    p_lounge_id,
    p_room_id,
    COALESCE(p_title_ar, p_title_en),
    p_title_ar,
    p_title_en,
    COALESCE(p_tag_ar, p_tag_en),
    p_tag_ar,
    p_tag_en,
    p_expires_at,
    p_room_id IS NOT NULL,
    true
  )
  RETURNING id INTO v_promo_id;

  INSERT INTO public.notifications (
    user_id,
    lounge_id,
    title_ar,
    title_en,
    body_ar,
    body_en,
    type,
    is_read,
    metadata
  )
  SELECT
    p.id,
    p_lounge_id,
    '🔥 ' || COALESCE(p_title_ar, 'عرض جديد!'),
    '🔥 ' || COALESCE(p_title_en, 'New Offer!'),
    COALESCE(p_tag_ar, 'خصم مميز') || ' في ' || COALESCE(v_lounge_name, 'صالتنا'),
    COALESCE(p_tag_en, 'Special discount') || ' at ' || COALESCE(v_lounge_name, 'our lounge'),
    'offer',
    false,
    jsonb_build_object(
      'promo_id', v_promo_id,
      'lounge_id', p_lounge_id,
      'room_id', p_room_id
    )
  FROM public.profiles AS p
  WHERE p.role = 'user';

  RETURN jsonb_build_object(
    'success', true,
    'promo_id', v_promo_id
  );
END;
$$;


ALTER FUNCTION "public"."publish_promotion"("p_expires_at" timestamp with time zone, "p_lounge_id" "uuid", "p_room_id" "uuid", "p_tag_ar" "text", "p_tag_en" "text", "p_title_ar" "text", "p_title_en" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_promotion"("p_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_tag_ar" "text" DEFAULT NULL::"text", "p_tag_en" "text" DEFAULT NULL::"text", "p_colors" "text"[] DEFAULT ARRAY['#6366F1'::"text", '#A855F7'::"text"], "p_icon_key" "text" DEFAULT 'local_offer'::"text", "p_image_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE v_promo_id uuid; v_lounge_name text;
BEGIN
  IF NOT (
    EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin')
    OR EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND lounge_id = p_lounge_id AND role IN ('owner','lounge_admin','admin','manager'))
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  SELECT name INTO v_lounge_name FROM public.lounges WHERE id = p_lounge_id;
  INSERT INTO public.promotions (lounge_id, title, title_ar, title_en, tag, tag_ar, tag_en, colors, icon_key, image_url, is_active)
  VALUES (p_lounge_id, coalesce(p_title_ar, p_title_en), p_title_ar, p_title_en,
    coalesce(p_tag_ar, p_tag_en), p_tag_ar, p_tag_en, p_colors, p_icon_key, p_image_url, true)
  RETURNING id INTO v_promo_id;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, is_read, metadata)
  SELECT p.id, '🔥 ' || coalesce(p_title_ar, 'عرض جديد!'), '🔥 ' || coalesce(p_title_en, 'New Offer!'),
    coalesce(p_tag_ar, 'خصم مميز') || ' في ' || coalesce(v_lounge_name, 'صالتنا'),
    coalesce(p_tag_en, 'Special discount') || ' at ' || coalesce(v_lounge_name, 'our lounge'),
    'offer', false, jsonb_build_object('promo_id', v_promo_id, 'lounge_id', p_lounge_id)
  FROM public.profiles p WHERE p.role = 'user';

  RETURN jsonb_build_object('success', true, 'promo_id', v_promo_id);
END;
$$;


ALTER FUNCTION "public"."publish_promotion"("p_lounge_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_tag_ar" "text", "p_tag_en" "text", "p_colors" "text"[], "p_icon_key" "text", "p_image_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_tournament"("p_tournament_id" "uuid", "p_open" boolean) RETURNS "public"."tournaments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$ DECLARE v public.tournaments; old jsonb; BEGIN SELECT * INTO v FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE; IF NOT(is_super_admin() OR private.is_lounge_manager(v.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF; old:=to_jsonb(v); UPDATE public.tournaments SET status=CASE WHEN p_open THEN 'registration_open' ELSE 'published' END,updated_at=now() WHERE id=p_tournament_id RETURNING * INTO v; PERFORM public.tournament_audit(v.id,'tournament_status_changed',NULL,NULL,old,to_jsonb(v)); RETURN v; END $$;


