CREATE OR REPLACE FUNCTION "public"."quote_booking_price"("p_room_id" "uuid", "p_date" "date", "p_start" time without time zone, "p_end" time without time zone, "p_play_mode" "text" DEFAULT 'single'::"text", "p_extra_controllers" integer DEFAULT 0, "p_coupon_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
  v_pricing jsonb;
  v_duration_min integer;
  v_base_rate numeric;
  v_effective_rate numeric;
  v_room_subtotal numeric;
  v_controller_rate numeric:=0;
  v_controllers_amount numeric:=0;
  v_promo_type text;
  v_promo_value numeric:=0;
  v_promo_discount numeric:=0;
  v_voucher jsonb;
  v_voucher_discount numeric:=0;
  v_total_before_discount numeric;
  v_final_total numeric;
BEGIN
  SELECT r.* INTO v_room
  FROM public.rooms AS r
  WHERE r.id=p_room_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found' USING ERRCODE='P0002';
  END IF;

  v_pricing:=private.price_room_interval(
    p_room_id,p_date,p_start,p_end,p_play_mode
  );
  v_duration_min:=(v_pricing->>'duration_minutes')::integer;
  v_base_rate:=(v_pricing->>'base_rate')::numeric;
  v_effective_rate:=(v_pricing->>'effective_hourly_rate')::numeric;
  v_room_subtotal:=(v_pricing->>'room_subtotal')::numeric;

  IF COALESCE(p_extra_controllers,0)>0 THEN
    v_controller_rate:=COALESCE(v_room.extra_controller_price,0);
    v_controllers_amount:=round(
      COALESCE(p_extra_controllers,0)
      * v_controller_rate
      * (v_duration_min/60.0),
      2
    );
  END IF;

  SELECT p.discount_type,COALESCE(p.discount_value,0)
  INTO v_promo_type,v_promo_value
  FROM public.promotions AS p
  WHERE p.is_active IS TRUE
    AND p.room_id=p_room_id
    AND COALESCE(p.discount_value,0)>0
    AND (p.expires_at IS NULL OR p.expires_at>now())
  ORDER BY p.created_at DESC,p.id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    SELECT p.discount_type,COALESCE(p.discount_value,0)
    INTO v_promo_type,v_promo_value
    FROM public.promotions AS p
    WHERE p.is_active IS TRUE
      AND p.lounge_id=v_room.lounge_id
      AND p.room_id IS NULL
      AND COALESCE(p.is_room_specific,false) IS FALSE
      AND COALESCE(p.discount_value,0)>0
      AND (p.expires_at IS NULL OR p.expires_at>now())
    ORDER BY p.created_at DESC,p.id DESC
    LIMIT 1;
  END IF;

  IF FOUND AND v_promo_value>0 THEN
    IF lower(COALESCE(v_promo_type,'percentage'))='fixed' THEN
      v_promo_discount:=LEAST(v_room_subtotal,v_promo_value);
    ELSE
      v_promo_discount:=round(
        v_room_subtotal
        * LEAST(GREATEST(v_promo_value,0),100)/100.0,
        2
      );
    END IF;
  END IF;

  IF NULLIF(btrim(COALESCE(p_coupon_code,'')),'') IS NOT NULL THEN
    v_voucher:=public.validate_voucher_by_code(p_coupon_code);
    IF COALESCE((v_voucher->>'valid')::boolean,false) THEN
      IF v_voucher->>'reward_type'='discount_fixed' THEN
        v_voucher_discount:=COALESCE(
          (v_voucher->>'reward_value')::numeric,0
        );
      ELSIF v_voucher->>'reward_type'='free_hour' THEN
        v_voucher_discount:=LEAST(
          GREATEST(0,v_room_subtotal-v_promo_discount),
          v_effective_rate
          * COALESCE((v_voucher->>'reward_value')::numeric,0)
        );
      END IF;
    END IF;
  END IF;

  v_total_before_discount:=v_room_subtotal+v_controllers_amount;
  v_voucher_discount:=LEAST(
    v_voucher_discount,
    GREATEST(0,v_total_before_discount-v_promo_discount)
  );
  v_final_total:=GREATEST(
    0,
    v_total_before_discount-v_promo_discount-v_voucher_discount
  );

  RETURN jsonb_build_object(
    'room_id',p_room_id,
    'lounge_id',v_room.lounge_id,
    'date',p_date,
    'start_time',to_char(p_start,'HH24:MI:SS'),
    'end_time',to_char(p_end,'HH24:MI:SS'),
    'duration_minutes',v_duration_min,
    'play_mode',lower(COALESCE(NULLIF(btrim(p_play_mode),''),'single')),
    'base_rate',v_base_rate,
    'effective_hourly_rate',v_effective_rate,
    'room_subtotal',v_room_subtotal,
    'extra_controllers',COALESCE(p_extra_controllers,0),
    'controller_rate',v_controller_rate,
    'controllers_amount',v_controllers_amount,
    'addons_amount',0,
    'promo_discount_amount',v_promo_discount,
    'voucher_discount_amount',v_voucher_discount,
    'discount_amount',v_promo_discount+v_voucher_discount,
    'subtotal',v_total_before_discount,
    'final_total',round(v_final_total,2),
    'currency','EGP',
    'has_peak_rates',COALESCE((v_pricing->>'has_peak_rates')::boolean,false),
    'segments',COALESCE(v_pricing->'segments','[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."quote_booking_price"("p_room_id" "uuid", "p_date" "date", "p_start" time without time zone, "p_end" time without time zone, "p_play_mode" "text", "p_extra_controllers" integer, "p_coupon_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_my_booking_checkout"("p_hold_token" "uuid", "p_room_requests" "jsonb", "p_extra_items" "jsonb" DEFAULT '[]'::"jsonb", "p_voucher_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM private.require_active_booking_actor();

  RETURN private.build_my_booking_checkout_quote(
    v_user_id,
    p_hold_token,
    p_room_requests,
    p_extra_items,
    p_voucher_code
  );
END;
$$;


ALTER FUNCTION "public"."quote_my_booking_checkout"("p_hold_token" "uuid", "p_room_requests" "jsonb", "p_extra_items" "jsonb", "p_voucher_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_cash_tournament_payment"("p_participant_id" "uuid", "p_amount" numeric, "p_reference_note" "text" DEFAULT NULL::"text") RETURNS "public"."tournament_participants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE
  v_p public.tournament_participants%ROWTYPE;
  v_t public.tournaments%ROWTYPE;
  v_count integer;
BEGIN
  SELECT * INTO v_p FROM public.tournament_participants WHERE id=p_participant_id FOR UPDATE;
  SELECT * INTO v_t FROM public.tournaments WHERE id=v_p.tournament_id FOR UPDATE;

  IF NOT(is_super_admin() OR private.can_operate_playspot_lounge(v_t.lounge_id) OR is_lounge_member_or_admin(v_t.lounge_id)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF v_p.registration_status<>'pending_payment' OR v_p.payment_status<>'unpaid' THEN
    RAISE EXCEPTION 'payment_not_allowed';
  END IF;

  IF p_amount<>v_t.entry_fee THEN
    RAISE EXCEPTION 'amount_mismatch';
  END IF;

  SELECT count(*) INTO v_count FROM public.tournament_participants WHERE tournament_id=v_t.id AND registration_status IN('confirmed','checked_in');
  IF v_count>=v_t.max_participants THEN
    RAISE EXCEPTION 'capacity_reached';
  END IF;

  UPDATE public.tournament_participants
  SET payment_status='paid',registration_status='confirmed',payment_method='cash',approved_by=auth.uid(),approved_at=now(),cash_received_by=auth.uid(),cash_received_at=now(),cash_reference_note=p_reference_note,updated_at=now()
  WHERE id=v_p.id RETURNING * INTO v_p;

  PERFORM public.tournament_audit(v_t.id,'cash_payment_approved',v_p.id,NULL,NULL,to_jsonb(v_p),p_reference_note);
  RETURN v_p;
END
$$;


ALTER FUNCTION "public"."record_cash_tournament_payment"("p_participant_id" "uuid", "p_amount" numeric, "p_reference_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_upsell_event"("p_rule_id" "uuid", "p_booking_id" "uuid", "p_event" "text", "p_canteen_order_id" "uuid" DEFAULT NULL::"uuid", "p_amount" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_rule public.upsell_rules%ROWTYPE;
  v_event text := lower(btrim(COALESCE(p_event,'')));
  v_amount numeric := 0;
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000'; END IF;
  IF v_event NOT IN ('shown','dismissed','accepted','impression','conversion') THEN
    RAISE EXCEPTION 'Unsupported upsell event' USING ERRCODE = '22023';
  END IF;
  SELECT b.* INTO v_booking FROM public.bookings b
    WHERE b.id = p_booking_id AND b.user_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002'; END IF;
  SELECT r.* INTO v_rule FROM public.upsell_rules r
    WHERE r.id = p_rule_id AND r.lounge_id = v_booking.lounge_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Upsell rule not found' USING ERRCODE = 'P0002'; END IF;
  IF v_event IN ('accepted','conversion') THEN
    -- A tap or a supplied amount is not proof of a purchase. Only discounted
    -- lines saved by the order RPC contribute to conversion revenue.
    SELECT sum(coi.total_price) INTO v_amount
    FROM public.canteen_orders co JOIN public.canteen_order_items coi ON coi.order_id = co.id
    WHERE co.id = p_canteen_order_id AND co.booking_id = p_booking_id
      AND co.user_id = auth.uid() AND co.status <> 'cancelled'
      AND coi.upsell_rule_id = p_rule_id AND coi.line_kind IN ('item','combo_parent');
    IF v_amount IS NULL THEN RAISE EXCEPTION 'UPSELL_PURCHASE_REQUIRED' USING ERRCODE = '23514'; END IF;
    SELECT id INTO v_id FROM public.canteen_upsell_events
    WHERE rule_id = p_rule_id AND booking_id = p_booking_id AND canteen_order_id = p_canteen_order_id
      AND event_type IN ('accepted','conversion') ORDER BY created_at LIMIT 1;
    v_event := 'accepted';
  ELSIF v_event = 'dismissed' THEN
    SELECT id INTO v_id FROM public.canteen_upsell_events
    WHERE rule_id = p_rule_id AND booking_id = p_booking_id AND event_type = 'dismissed'
    ORDER BY created_at LIMIT 1;
  ELSE
    IF v_booking.status <> 'in_progress' OR v_rule.is_active IS NOT TRUE THEN
      RAISE EXCEPTION 'UPSELL_OFFER_UNAVAILABLE' USING ERRCODE = '23514';
    END IF;
    IF (SELECT count(*) FROM public.canteen_upsell_events
      WHERE rule_id = p_rule_id AND booking_id = p_booking_id AND event_type IN ('shown','impression'))
      >= v_rule.max_impressions_per_booking THEN
      RETURN jsonb_build_object('success',true,'recorded',false,'event_type','shown');
    END IF;
    v_event := 'shown';
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.canteen_upsell_events(lounge_id,rule_id,booking_id,canteen_order_id,event_type,revenue_generated)
    VALUES(v_booking.lounge_id,p_rule_id,p_booking_id,
      CASE WHEN v_event = 'accepted' THEN p_canteen_order_id ELSE NULL END,v_event,COALESCE(v_amount,0)) RETURNING id INTO v_id;
  END IF;
  RETURN jsonb_build_object('success',true,'event_id',v_id,'event_type',v_event);
END;
$$;


ALTER FUNCTION "public"."record_upsell_event"("p_rule_id" "uuid", "p_booking_id" "uuid", "p_event" "text", "p_canteen_order_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_lounge_staff_provisioning"("p_actor_id" "uuid", "p_email" "text", "p_lounge_id" "uuid", "p_role" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_user_id uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE='42501';
  END IF;
  SELECT id INTO v_user_id FROM auth.users
    WHERE lower(email)=lower(btrim(p_email))
      AND raw_app_meta_data->'staff_provisioning' =
        jsonb_build_object('actor_id',p_actor_id,'lounge_id',p_lounge_id,'role',p_role);
  RETURN v_user_id;
END;
$$;


ALTER FUNCTION "public"."recover_lounge_staff_provisioning"("p_actor_id" "uuid", "p_email" "text", "p_lounge_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redeem_points"("p_user_id" "uuid", "p_redemption_option_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_cost INT;
  v_balance INT;
  v_title TEXT;
  v_reward_type TEXT;
  v_reward_value NUMERIC;
  v_voucher_id UUID;
  v_code TEXT;
  v_is_super_admin BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'super_admin'
  ) INTO v_is_super_admin;

  IF auth.uid() IS NULL OR (auth.uid() <> p_user_id AND NOT v_is_super_admin) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT points_cost, title, reward_type, reward_value
  INTO v_cost, v_title, v_reward_type, v_reward_value
  FROM public.redemption_options
  WHERE id = p_redemption_option_id AND is_active = true;

  IF v_cost IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'المكافأة غير متاحة');
  END IF;

  SELECT points INTO v_balance FROM public.profiles WHERE id = p_user_id FOR UPDATE;

  IF COALESCE(v_balance, 0) < v_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'رصيد النقاط غير كافٍ', 'current_balance', COALESCE(v_balance, 0), 'required', v_cost);
  END IF;

  INSERT INTO public.points_transactions (user_id, points, type, reference_id, description)
  VALUES (p_user_id, -v_cost, 'redeem', p_redemption_option_id, 'صرف: ' || v_title);

  UPDATE public.profiles SET points = points - v_cost WHERE id = p_user_id;

  v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  INSERT INTO public.user_vouchers (user_id, redemption_option_id, code, reward_type, reward_value, expires_at)
  VALUES (p_user_id, p_redemption_option_id, v_code, v_reward_type, v_reward_value, NOW() + INTERVAL '30 days')
  RETURNING id INTO v_voucher_id;

  -- In-App Notification (Type strictly matching CHECK constraint 'loyalty_points')
  INSERT INTO public.notifications (user_id, title, title_ar, title_en, body, body_ar, body_en, type, metadata)
  VALUES (
    p_user_id,
    'Reward Redeemed',
    'تم استبدال النقاط بمكافأة 🎁',
    'Reward Redeemed Successfully',
    'تم استبدال ' || v_cost || ' نقطة وتجهيز كود الخصم الخاص بك: ' || v_code,
    'تم استبدال ' || v_cost || ' نقطة وتجهيز كود الخصم الخاص بك: ' || v_code,
    'Successfully redeemed ' || v_cost || ' points. Voucher code: ' || v_code,
    'loyalty_points',
    jsonb_build_object('voucher_code', v_code, 'voucher_id', v_voucher_id, 'points_cost', v_cost)
  );

  RETURN jsonb_build_object(
    'success', true,
    'new_balance', v_balance - v_cost,
    'voucher_id', v_voucher_id,
    'voucher_code', v_code,
    'expires_in_days', 30
  );
END;
$$;


ALTER FUNCTION "public"."redeem_points"("p_user_id" "uuid", "p_redemption_option_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_cashier_writer"("p_lounge_id" "uuid", "p_device_id" "uuid", "p_online" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_profile public.profiles%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_writer private.cashier_writer_authorities%ROWTYPE;
  v_permit private.cashier_writer_permits%ROWTYPE;
  v_now timestamptz := date_trunc('milliseconds',statement_timestamp());
  v_super_admin boolean;
  v_created boolean;
  v_permissions jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF p_device_id IS NULL OR p_lounge_id IS NULL OR p_online IS NULL THEN
    RAISE EXCEPTION 'INVALID_CASHIER_WRITER_REQUEST' USING ERRCODE='22023';
  END IF;
  PERFORM private.lock_cashier_lounge(p_lounge_id);
  SELECT p.* INTO v_profile FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=v_actor FOR SHARE OF p,u;
  IF NOT FOUND OR v_profile.is_active IS NOT TRUE OR v_profile.is_banned IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'ACCOUNT_NOT_ELIGIBLE' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_lounge FROM public.lounges WHERE id=p_lounge_id FOR SHARE;
  IF NOT FOUND OR v_lounge.status IS DISTINCT FROM 'active' OR v_lounge.is_active IS NOT TRUE THEN
    RAISE EXCEPTION 'LOUNGE_NOT_APPROVED' USING ERRCODE='42501';
  END IF;
  v_super_admin:=public.is_super_admin() IS TRUE;
  IF NOT v_super_admin AND public.has_lounge_permission(p_lounge_id,'sessions_control') IS NOT TRUE THEN
    RAISE EXCEPTION 'CASHIER_WRITER_PERMISSION_DENIED' USING ERRCODE='42501';
  END IF;
  v_permissions:=private.cashier_effective_permissions(p_lounge_id);
  INSERT INTO private.cashier_writer_authorities(lounge_id,actor_id,device_id,issued_at,permit_expires_at,heartbeat_expires_at)
    VALUES(p_lounge_id,v_actor,p_device_id,v_now,v_now+interval '24 hours',v_now)
    ON CONFLICT(lounge_id) DO NOTHING RETURNING * INTO v_writer;
  v_created:=FOUND;
  SELECT * INTO STRICT v_writer FROM private.cashier_writer_authorities WHERE lounge_id=p_lounge_id FOR UPDATE;

  -- Reclaim writer if previously released, OR if the previous permit expired,
  -- OR if the previous actor no longer has an active open shift on this lounge:
  IF v_writer.released_at IS NOT NULL
     OR v_writer.permit_expires_at <= v_now
     OR (v_writer.actor_id <> v_actor AND NOT EXISTS (
       SELECT 1 FROM public.shifts s 
       WHERE s.lounge_id = p_lounge_id 
         AND coalesce(s.cashier_id, s.staff_user_id) = v_writer.actor_id 
         AND s.status = 'open' AND s.closed_at IS NULL
     )) THEN
    IF NOT EXISTS(SELECT 1 FROM private.cashier_bootstrap_claim_context WHERE transaction_id=txid_current()
      AND lounge_id=p_lounge_id AND actor_id=v_actor AND device_id=p_device_id) THEN
      RAISE EXCEPTION 'CASHIER_RECLAIM_REQUIRES_BOOTSTRAP' USING ERRCODE='55000';
    END IF;
    -- Bootstrap of the next shift must have exactly one own open shift.
    IF (SELECT count(*) FROM public.shifts WHERE lounge_id=p_lounge_id
      AND coalesce(cashier_id,staff_user_id)=v_actor AND status='open' AND closed_at IS NULL)<>1 THEN
      RAISE EXCEPTION 'OFFLINE_BOOTSTRAP_REQUIRES_ONE_OWN_SHIFT' USING ERRCODE='55000';
    END IF;
    UPDATE private.cashier_writer_authorities SET actor_id=v_actor,device_id=p_device_id,
      writer_generation=gen_random_uuid(),permit_id=gen_random_uuid(),issued_at=v_now,permit_expires_at=v_now+interval '24 hours',
      heartbeat_expires_at=CASE WHEN p_online THEN v_now+interval '90 seconds' ELSE v_now END,
      online_requested=p_online,released_at=NULL,updated_at=v_now
      WHERE lounge_id=p_lounge_id RETURNING * INTO v_writer;
    v_created:=true;
  END IF;

  IF NOT v_created AND v_writer.online_requested IS DISTINCT FROM p_online
    AND NOT EXISTS(SELECT 1 FROM private.cashier_bootstrap_claim_context
      WHERE transaction_id=txid_current() AND lounge_id=p_lounge_id
        AND actor_id=v_actor AND device_id=p_device_id) THEN
    RAISE EXCEPTION 'CASHIER_MODE_CHANGE_REQUIRES_BOOTSTRAP' USING ERRCODE='55000';
  END IF;

  IF v_writer.actor_id<>v_actor OR v_writer.device_id<>p_device_id THEN
    RAISE EXCEPTION 'CASHIER_WRITER_ALREADY_ASSIGNED' USING ERRCODE='55000';
  END IF;

  v_now:=date_trunc('milliseconds',clock_timestamp());
  IF NOT v_created THEN
    SELECT * INTO v_permit FROM private.cashier_writer_permits WHERE permit_id=v_writer.permit_id FOR SHARE;
    IF NOT FOUND OR (v_permit.lounge_id,v_permit.actor_id,v_permit.device_id,v_permit.issued_at,v_permit.expires_at)
      IS DISTINCT FROM (v_writer.lounge_id,v_writer.actor_id,v_writer.device_id,v_writer.issued_at,v_writer.permit_expires_at) THEN
      RAISE EXCEPTION 'CASHIER_PERMIT_RECORD_MISSING_OR_CHANGED' USING ERRCODE='55000';
    END IF;
  END IF;
  IF v_created OR v_now>=v_permit.expires_at OR v_permissions IS DISTINCT FROM v_permit.permissions THEN
    INSERT INTO private.cashier_writer_permits(permit_id,lounge_id,actor_id,device_id,issued_at,expires_at,permissions)
      VALUES(CASE WHEN v_created THEN v_writer.permit_id ELSE gen_random_uuid() END,
        p_lounge_id,v_actor,p_device_id,v_now,v_now+interval '24 hours',v_permissions) RETURNING * INTO v_permit;
  END IF;
  INSERT INTO private.cashier_permit_generations(permit_id,writer_generation)
    VALUES(v_permit.permit_id,v_writer.writer_generation) ON CONFLICT(permit_id) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM private.cashier_permit_generations WHERE permit_id=v_permit.permit_id
    AND writer_generation=v_writer.writer_generation) THEN
    RAISE EXCEPTION 'CASHIER_PERMIT_GENERATION_MISMATCH' USING ERRCODE='55000';
  END IF;
  UPDATE private.cashier_writer_authorities SET
    permit_id=v_permit.permit_id,issued_at=v_permit.issued_at,permit_expires_at=v_permit.expires_at,
    heartbeat_expires_at=CASE WHEN p_online THEN v_now+interval '90 seconds' ELSE v_now END,
    online_requested=p_online, updated_at=v_now
  WHERE lounge_id=p_lounge_id RETURNING * INTO v_writer;
  RETURN jsonb_build_object(
    'protocol_version',2,'server_time_ms',floor(extract(epoch FROM v_now)*1000)::bigint,'online_requested',p_online,
    'actor_id',v_actor,'lounge_id',p_lounge_id,'device_id',p_device_id,'permit_id',v_writer.permit_id,
    'profile_active',true,'profile_banned',false,'lounge_status',v_lounge.status,'lounge_active',true,
    'offline_enabled',true,'issued_ms',floor(extract(epoch FROM v_writer.issued_at)*1000)::bigint,
    'expires_ms',floor(extract(epoch FROM v_writer.permit_expires_at)*1000)::bigint,
    'heartbeat_expires_at',v_writer.heartbeat_expires_at,
    'last_applied_sequence',v_writer.last_applied_sequence,'timezone',to_jsonb(v_lounge)->>'timezone',
    'permissions',v_permit.permissions
  );
END;
$$;


ALTER FUNCTION "public"."refresh_cashier_writer"("p_lounge_id" "uuid", "p_device_id" "uuid", "p_online" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_for_tournament"("p_tournament_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_p public.tournament_participants;
  v_count integer;
  v_pos integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND OR v_t.status<>'registration_open' OR now()<v_t.registration_opens_at OR now()>=v_t.registration_closes_at THEN RAISE EXCEPTION 'registration_closed'; END IF;
  IF EXISTS(SELECT 1 FROM public.tournament_participants WHERE tournament_id=p_tournament_id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'already_registered'; END IF;
  SELECT count(*) INTO v_count FROM public.tournament_participants WHERE tournament_id=p_tournament_id AND registration_status IN('pending_payment','confirmed','checked_in');
  IF v_count>=v_t.max_participants THEN
    SELECT COALESCE(max(waitlist_position),0)+1 INTO v_pos FROM public.tournament_participants WHERE tournament_id=p_tournament_id AND registration_status='waitlist';
    INSERT INTO public.tournament_participants(tournament_id,user_id,registration_status,waitlist_position) VALUES(p_tournament_id,auth.uid(),'waitlist',v_pos) RETURNING * INTO v_p;
  ELSE
    INSERT INTO public.tournament_participants(tournament_id,user_id,registration_status,payment_status,payment_deadline) VALUES(p_tournament_id,auth.uid(),'pending_payment','unpaid',now()+make_interval(mins=>v_t.payment_deadline_minutes)) RETURNING * INTO v_p;
  END IF;
  PERFORM public.tournament_audit(p_tournament_id,CASE WHEN v_p.registration_status='waitlist' THEN 'waitlist_added' ELSE 'participant_registered' END,v_p.id,NULL,NULL,to_jsonb(v_p));
  RETURN row_to_json(v_p);
END
$$;


ALTER FUNCTION "public"."register_for_tournament"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_ban_request"("p_request_id" "uuid", "p_admin_notes" "text") RETURNS "public"."user_ban_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request public.user_ban_requests;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only super admins can reject ban requests';
  END IF;
  IF p_admin_notes IS NULL OR length(btrim(p_admin_notes)) = 0 THEN
    RAISE EXCEPTION 'Rejection notes are required';
  END IF;

  UPDATE public.user_ban_requests
  SET status = 'rejected', admin_notes = p_admin_notes
  WHERE id = p_request_id
    AND status = 'pending'
  RETURNING * INTO v_request;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pending ban request not found';
  END IF;
  RETURN v_request;
END;
$$;


ALTER FUNCTION "public"."reject_ban_request"("p_request_id" "uuid", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_booking_extension"("p_booking_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE v_booking public.bookings%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING errcode='28000'; END IF;
  SELECT * INTO v_booking FROM public.bookings WHERE id=p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BOOKING_NOT_FOUND' USING errcode='P0002'; END IF;
  PERFORM private.assert_lounge_operator(v_booking.lounge_id,true);
  IF COALESCE(v_booking.extension_status,'none') <> 'pending' THEN RAISE EXCEPTION 'NO_PENDING_EXTENSION_REQUEST' USING errcode='55000'; END IF;
  UPDATE public.bookings SET extension_status='rejected',updated_at=now() WHERE id=p_booking_id;
  INSERT INTO public.notifications(user_id,lounge_id,title_ar,title_en,body_ar,body_en,type,is_read,metadata)
  VALUES(v_booking.user_id,v_booking.lounge_id,'لم تتم الموافقة على تمديد الحجز','Booking Extension Declined',
    COALESCE(p_reason,'لم تتم الموافقة على طلب تمديد الحجز.'),COALESCE(p_reason,'Your booking extension request was declined.'),
    'booking_extension_rejected',false,jsonb_build_object('booking_id',p_booking_id,'reason',p_reason));
  RETURN jsonb_build_object('success',true,'status','rejected','booking_id',p_booking_id);
END;
$$;


ALTER FUNCTION "public"."reject_booking_extension"("p_booking_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_manual_booking"("p_booking_id" "uuid", "p_rejection_reason" "text", "p_action_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_actor uuid := auth.uid();
  v_reason text := NULLIF(btrim(p_rejection_reason), '');
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_action_by IS NOT NULL AND p_action_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Action actor does not match authenticated user'
      USING ERRCODE = '42501';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM private.assert_lounge_operator(v_booking.lounge_id, true);

  IF COALESCE(v_booking.payment_method, '') <> 'manual_transfer' THEN
    RAISE EXCEPTION 'Only manual transfer bookings can be rejected here'
      USING ERRCODE = '55000';
  END IF;

  IF v_booking.payment_status = 'paid' THEN
    RAISE EXCEPTION 'Paid bookings cannot be rejected through manual review'
      USING ERRCODE = '55000';
  END IF;

  IF v_booking.status NOT IN (
    'pending'::public.booking_status,
    'upcoming'::public.booking_status
  ) THEN
    RAISE EXCEPTION 'Booking cannot be rejected in its current status'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.bookings
  SET status = 'rejected'::public.booking_status,
      payment_status = 'unpaid',
      cancellation_reason = COALESCE(v_reason, 'Manual transfer was rejected'),
      cancelled_by = v_actor,
      cancelled_at = now(),
      updated_at = now()
  WHERE id = p_booking_id;

  UPDATE public.rooms AS r
  SET status = 'available',
      is_available = true,
      updated_at = now()
  WHERE r.id = v_booking.room_id
    AND r.status = 'occupied'
    AND NOT EXISTS (
      SELECT 1
      FROM public.bookings AS active_b
      WHERE active_b.room_id = r.id
        AND active_b.id <> p_booking_id
        AND active_b.status = 'in_progress'::public.booking_status
    );

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'status', 'rejected',
    'rejected_by', v_actor,
    'rejection_reason', COALESCE(v_reason, 'Manual transfer was rejected')
  );
END;
$$;


ALTER FUNCTION "public"."reject_manual_booking"("p_booking_id" "uuid", "p_rejection_reason" "text", "p_action_by" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."tournament_payment_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "participant_id" "uuid" NOT NULL,
    "amount" numeric(12,2) NOT NULL,
    "payment_method" "text" NOT NULL,
    "receipt_url" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "submitted_by" "uuid" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "rejection_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "payment_submission_receipt_check" CHECK (((("payment_method" = 'cash'::"text") AND ("receipt_url" IS NULL)) OR (("payment_method" = ANY (ARRAY['instapay'::"text", 'vodafone_cash'::"text"])) AND ("receipt_url" IS NOT NULL)))),
    CONSTRAINT "tournament_payment_submissions_amount_check" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "tournament_payment_submissions_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['instapay'::"text", 'vodafone_cash'::"text", 'cash'::"text"]))),
    CONSTRAINT "tournament_payment_submissions_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."tournament_payment_submissions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_tournament_payment"("p_submission_id" "uuid", "p_reason" "text") RETURNS "public"."tournament_payment_submissions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$ DECLARE v_s public.tournament_payment_submissions%ROWTYPE; v_p public.tournament_participants%ROWTYPE; v_t public.tournaments%ROWTYPE; BEGIN IF p_reason IS NULL OR btrim(p_reason)='' THEN RAISE EXCEPTION 'rejection_reason_required'; END IF; SELECT * INTO v_s FROM public.tournament_payment_submissions WHERE id=p_submission_id FOR UPDATE; SELECT * INTO v_p FROM public.tournament_participants WHERE id=v_s.participant_id FOR UPDATE; SELECT * INTO v_t FROM public.tournaments WHERE id=v_p.tournament_id; IF NOT(is_super_admin() OR private.is_lounge_manager(v_t.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF; IF v_s.status<>'pending' THEN RAISE EXCEPTION 'payment_already_reviewed'; END IF; UPDATE public.tournament_payment_submissions SET status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),rejection_reason=p_reason,updated_at=now() WHERE id=v_s.id RETURNING * INTO v_s; UPDATE public.tournament_participants SET payment_status='unpaid',payment_rejection_reason=p_reason,updated_at=now() WHERE id=v_p.id AND registration_status='pending_payment'; PERFORM public.tournament_audit(v_t.id,'payment_rejected',v_p.id,NULL,NULL,to_jsonb(v_s),p_reason); RETURN v_s; END $$;


ALTER FUNCTION "public"."reject_tournament_payment"("p_submission_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_booking_hold"("p_hold_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  UPDATE public.booking_holds
  SET released_at = COALESCE(released_at, now())
  WHERE hold_token = p_hold_token
    AND user_id = v_user_id
    AND released_at IS NULL;

  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."release_booking_hold"("p_hold_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_cashier_writer"("p_lounge_id" "uuid", "p_device_id" "uuid", "p_permit_id" "uuid", "p_last_applied_sequence" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid();v_writer private.cashier_writer_authorities%ROWTYPE;v_saved private.cashier_writer_release_receipts%ROWTYPE;v_receipt jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF p_lounge_id IS NULL OR p_device_id IS NULL OR p_permit_id IS NULL
    OR p_last_applied_sequence IS NULL OR p_last_applied_sequence<0
    OR p_last_applied_sequence>9007199254740991 THEN
    RAISE EXCEPTION 'INVALID_CASHIER_RELEASE_REQUEST' USING ERRCODE='22023';
  END IF;
  PERFORM private.lock_cashier_lounge(p_lounge_id);
  PERFORM 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id
    WHERE p.id=v_actor AND p.is_active IS TRUE AND p.is_banned IS FALSE FOR SHARE OF p,u;
  IF NOT FOUND OR (public.is_super_admin() IS NOT TRUE
    AND public.has_lounge_permission(p_lounge_id,'sessions_control') IS NOT TRUE) THEN
    RAISE EXCEPTION 'CASHIER_RELEASE_PERMISSION_DENIED' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_saved FROM private.cashier_writer_release_receipts WHERE permit_id=p_permit_id;
  IF FOUND THEN
    IF (v_saved.actor_id,v_saved.lounge_id,v_saved.device_id,v_saved.last_applied_sequence)
      IS DISTINCT FROM (v_actor,p_lounge_id,p_device_id,p_last_applied_sequence) THEN
      RAISE EXCEPTION 'CASHIER_RELEASE_REPLAY_MISMATCH' USING ERRCODE='42501';
    END IF;
    RETURN v_saved.receipt;
  END IF;
  SELECT * INTO v_writer FROM private.cashier_writer_authorities WHERE lounge_id=p_lounge_id FOR UPDATE;
  IF NOT FOUND OR (v_writer.actor_id,v_writer.device_id) IS DISTINCT FROM (v_actor,p_device_id)
    OR NOT EXISTS(SELECT 1 FROM private.cashier_permit_generations g
      JOIN private.cashier_writer_permits p ON p.permit_id=g.permit_id
      WHERE p.permit_id=p_permit_id AND g.writer_generation=v_writer.writer_generation
        AND (p.lounge_id,p.actor_id,p.device_id)=(p_lounge_id,v_actor,p_device_id)) THEN
    RAISE EXCEPTION 'CASHIER_RELEASE_WRITER_MISMATCH' USING ERRCODE='42501';
  END IF;
  IF v_writer.last_applied_sequence<>p_last_applied_sequence THEN
    RAISE EXCEPTION 'CASHIER_RELEASE_SEQUENCE_MISMATCH' USING ERRCODE='55000';
  END IF;
  IF v_writer.released_at IS NULL THEN
    -- Do not lock a shift after the writer: existing close RPCs may already
    -- own it. Read the committed state; a concurrent close can be retried.
    IF EXISTS(SELECT 1 FROM public.shifts WHERE lounge_id=p_lounge_id
      AND coalesce(cashier_id,staff_user_id)=v_actor AND status='open' AND closed_at IS NULL) THEN
      RAISE EXCEPTION 'CASHIER_RELEASE_CLOSE_OWN_SHIFT_FIRST' USING ERRCODE='55000';
    END IF;
    IF EXISTS(SELECT 1 FROM public.bookings WHERE lounge_id=p_lounge_id AND status='in_progress') THEN
      RAISE EXCEPTION 'CASHIER_RELEASE_ACTIVE_SESSION' USING ERRCODE='55000';
    END IF;
    IF EXISTS(SELECT 1 FROM private.cashier_operation_receipts WHERE lounge_id=p_lounge_id
      AND sequence>v_writer.last_applied_sequence AND result->>'status'='conflict') THEN
      RAISE EXCEPTION 'CASHIER_RELEASE_UNRESOLVED_CONFLICT' USING ERRCODE='55000';
    END IF;
    UPDATE private.cashier_writer_authorities SET released_at=clock_timestamp(),online_requested=false,
      heartbeat_expires_at=clock_timestamp(),updated_at=clock_timestamp() WHERE lounge_id=p_lounge_id
      RETURNING * INTO v_writer;
  END IF;
  v_receipt:=jsonb_build_object('protocol_version',2,'released',true,'lounge_id',p_lounge_id,
    'actor_id',v_actor,'device_id',p_device_id,'permit_id',p_permit_id,
    'last_applied_sequence',v_writer.last_applied_sequence,'released_at',v_writer.released_at);
  INSERT INTO private.cashier_writer_release_receipts VALUES(p_permit_id,v_actor,p_lounge_id,p_device_id,
    p_last_applied_sequence,v_receipt);
  RETURN v_receipt;
END; $$;


ALTER FUNCTION "public"."release_cashier_writer"("p_lounge_id" "uuid", "p_device_id" "uuid", "p_permit_id" "uuid", "p_last_applied_sequence" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_lounge_staff_member"("p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_target public.profiles%ROWTYPE;
  v_actor_role text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT p.*
  INTO v_target
  FROM public.profiles AS p
  WHERE p.id = p_target_user_id
  FOR UPDATE;

  IF NOT FOUND OR v_target.lounge_id IS NULL THEN
    RAISE EXCEPTION 'Staff member not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_target.role IN ('owner', 'lounge_owner', 'super_admin', 'superadmin') THEN
    RAISE EXCEPTION 'Owner and super admin accounts are protected'
      USING ERRCODE = '42501';
  END IF;

  v_actor_role := private.permission_role(auth.uid(), v_target.lounge_id);

  IF v_actor_role NOT IN ('super_admin', 'owner', 'manager') THEN
    RAISE EXCEPTION 'Only lounge administrators can manage staff'
      USING ERRCODE = '42501';
  END IF;

  IF v_actor_role IS NULL
     OR (
       v_actor_role <> 'super_admin'
       AND NOT public.has_lounge_permission(
         v_target.lounge_id,
         'staff_manage'
       )
     ) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role = 'manager' AND v_target.role = 'manager' THEN
    RAISE EXCEPTION 'Managers cannot remove peer managers'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.lounge_staff
  WHERE lounge_id = v_target.lounge_id
    AND user_id = p_target_user_id;

  UPDATE public.profiles
  SET lounge_id = NULL,
      role = 'user',
      is_active = false,
      updated_at = now()
  WHERE id = p_target_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_target_user_id,
    'removed_from_lounge', v_target.lounge_id
  );
END;
$$;


ALTER FUNCTION "public"."remove_lounge_staff_member"("p_target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_booking_extension"("p_booking_id" "uuid", "p_requested_minutes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_requested_minutes IS NULL
     OR p_requested_minutes <= 0
     OR p_requested_minutes > 720 THEN
    RAISE EXCEPTION 'Invalid extension minutes' USING ERRCODE = '22023';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
    AND b.user_id = auth.uid()
    AND b.status = 'in_progress'::public.booking_status
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active booking not found for current user'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE(v_booking.extension_status, 'none') = 'pending' THEN
    RAISE EXCEPTION 'Extension request already pending'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.bookings
  SET extension_status = 'pending',
      requested_extension_minutes = p_requested_minutes,
      updated_at = now()
  WHERE id = p_booking_id;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'extension_status', 'pending',
    'requested_extension_minutes', p_requested_minutes
  );
END;
$$;


ALTER FUNCTION "public"."request_booking_extension"("p_booking_id" "uuid", "p_requested_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_staff_assistance"("p_lounge_id" "uuid", "p_room_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_call_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Unauthenticated request';
  END IF;

  INSERT INTO public.service_calls (
    lounge_id,
    room_id,
    user_id,
    notes,
    status,
    created_at
  )
  VALUES (
    p_lounge_id,
    p_room_id,
    auth.uid(),
    p_notes,
    'pending',
    NOW()
  )
  RETURNING id INTO v_call_id;

  RETURN jsonb_build_object('success', true, 'call_id', v_call_id);
END;
$$;


ALTER FUNCTION "public"."request_staff_assistance"("p_lounge_id" "uuid", "p_room_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_staff_assistance_for_booking"("p_booking_id" "uuid", "p_call_type" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_call_id uuid;
  v_call_type text := NULLIF(btrim(p_call_type), '');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF v_call_type IS NULL THEN
    RAISE EXCEPTION 'Call type is required' USING ERRCODE = '22023';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
    AND b.user_id = auth.uid()
    AND b.status = 'in_progress'::public.booking_status
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active booking not found for current user'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.service_calls (
    lounge_id,
    room_id,
    booking_id,
    user_id,
    call_type,
    request_type,
    note,
    notes,
    status,
    is_attended,
    created_at
  )
  VALUES (
    v_booking.lounge_id,
    v_booking.room_id,
    v_booking.id,
    auth.uid(),
    v_call_type,
    v_call_type,
    NULLIF(btrim(p_notes), ''),
    NULLIF(btrim(p_notes), ''),
    'pending',
    false,
    now()
  )
  RETURNING id INTO v_call_id;

  RETURN jsonb_build_object(
    'success', true,
    'call_id', v_call_id,
    'booking_id', v_booking.id,
    'lounge_id', v_booking.lounge_id,
    'room_id', v_booking.room_id,
    'call_type', v_call_type
  );
END;
$$;


ALTER FUNCTION "public"."request_staff_assistance_for_booking"("p_booking_id" "uuid", "p_call_type" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reshare_promotion"("p_promotion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_source public.promotions%ROWTYPE;
  v_new_id uuid;
  v_duration interval;
  v_new_expiry timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  SELECT p.*
  INTO v_source
  FROM public.promotions AS p
  WHERE p.id = p_promotion_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Promotion not found' USING ERRCODE='P0002';
  END IF;

  IF NOT private.can_manage_promotion(v_source.lounge_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_source.expires_at IS NULL THEN
    v_new_expiry := NULL;
  ELSE
    v_duration := v_source.expires_at - v_source.created_at;
    IF v_duration <= interval '0 seconds' THEN
      v_duration := interval '7 days';
    END IF;
    v_new_expiry := now() + v_duration;
  END IF;

  INSERT INTO public.promotions (
    title,
    tag,
    colors,
    icon_key,
    image_url,
    deep_link,
    is_active,
    title_ar,
    title_en,
    tag_ar,
    tag_en,
    lounge_id,
    expires_at,
    is_room_specific,
    room_id,
    target_audience,
    discount_type,
    discount_value,
    reshared_from_id
  )
  VALUES (
    v_source.title,
    v_source.tag,
    v_source.colors,
    v_source.icon_key,
    v_source.image_url,
    v_source.deep_link,
    true,
    v_source.title_ar,
    v_source.title_en,
    v_source.tag_ar,
    v_source.tag_en,
    v_source.lounge_id,
    v_new_expiry,
    v_source.is_room_specific,
    v_source.room_id,
    v_source.target_audience,
    v_source.discount_type,
    v_source.discount_value,
    v_source.id
  )
  RETURNING id INTO v_new_id;

  RETURN jsonb_build_object(
    'success', true,
    'promo_id', v_new_id,
    'reshared_from_id', v_source.id,
    'expires_at', v_new_expiry
  );
END;
$$;


ALTER FUNCTION "public"."reshare_promotion"("p_promotion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_live_request"("p_request_type" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_type text := lower(btrim(COALESCE(p_request_type, '')));
  v_lounge_id uuid;
  v_booking_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'Request id is required' USING ERRCODE = '22023';
  END IF;

  IF v_type IN ('canteen', 'canteen_order') THEN
    SELECT co.lounge_id, co.booking_id
    INTO v_lounge_id, v_booking_id
    FROM public.canteen_orders AS co
    WHERE co.id = p_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Canteen order not found' USING ERRCODE = 'P0002';
    END IF;

    IF NOT public.is_super_admin()
       AND NOT public.has_lounge_permission(v_lounge_id, 'sessions_control') THEN
      RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
    END IF;

    UPDATE public.canteen_orders
    SET status = 'completed',
        is_attended = true,
        is_read = true,
        updated_at = now()
    WHERE id = p_request_id;

  ELSIF v_type IN ('service', 'service_call', 'call_staff') THEN
    SELECT COALESCE(sc.lounge_id, b.lounge_id), sc.booking_id
    INTO v_lounge_id, v_booking_id
    FROM public.service_calls AS sc
    LEFT JOIN public.bookings AS b ON b.id = sc.booking_id
    WHERE sc.id = p_request_id
    FOR UPDATE OF sc;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Service call not found' USING ERRCODE = 'P0002';
    END IF;

    IF NOT public.is_super_admin()
       AND NOT public.has_lounge_permission(v_lounge_id, 'sessions_control') THEN
      RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
    END IF;

    UPDATE public.service_calls
    SET status = 'resolved',
        is_attended = true,
        is_read = true,
        updated_at = now()
    WHERE id = p_request_id;

  ELSIF v_type IN ('request', 'client_request') THEN
    SELECT cr.lounge_id, cr.booking_id
    INTO v_lounge_id, v_booking_id
    FROM public.client_requests AS cr
    WHERE cr.id = p_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Client request not found' USING ERRCODE = 'P0002';
    END IF;

    IF NOT public.is_super_admin()
       AND NOT public.has_lounge_permission(v_lounge_id, 'sessions_control') THEN
      RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
    END IF;

    UPDATE public.client_requests
    SET status = 'resolved',
        is_attended = true,
        is_read = true
    WHERE id = p_request_id;

  ELSE
    RAISE EXCEPTION 'Unsupported request type' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'request_type', v_type,
    'request_id', p_request_id,
    'lounge_id', v_lounge_id,
    'booking_id', v_booking_id
  );
END;
$$;


ALTER FUNCTION "public"."resolve_live_request"("p_request_type" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_payout_review"("p_payout_id" "uuid", "p_resolution" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_lounge_id uuid;
  v_amount numeric;
  v_owner_id uuid;
  v_lounge_name text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_resolution NOT IN ('approve','cancel') THEN RAISE EXCEPTION 'Invalid resolution'; END IF;
  IF NULLIF(trim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'Review reason is required'; END IF;

  IF p_resolution = 'approve' THEN
    UPDATE public.payouts
    SET status = 'pending', notes = concat_ws(E'\n', notes, 'Review resolved: ' || p_reason)
    WHERE id = p_payout_id AND status = 'needs_review';
  ELSE
    UPDATE public.payouts
    SET status = 'cancelled', cancelled_by = auth.uid(), cancelled_at = now(), cancelled_reason = p_reason
    WHERE id = p_payout_id AND status = 'needs_review'
    RETURNING lounge_id, total_amount INTO v_lounge_id, v_amount;

    IF FOUND AND v_lounge_id IS NOT NULL THEN
      SELECT owner_id, COALESCE(name_ar, name_en, name, 'الصالة') INTO v_owner_id, v_lounge_name
      FROM public.lounges WHERE id = v_lounge_id;

      IF v_owner_id IS NOT NULL THEN
        INSERT INTO public.notifications (
          user_id, lounge_id, title_ar, title_en, body_ar, body_en, type, is_read, metadata
        ) VALUES (
          v_owner_id, v_lounge_id,
          'تم رفض/إلغاء طلب سحب الأرباح ⚠️', 'Payout Request Cancelled ⚠️',
          'تم رفض طلب سحب أرباح صالة ' || v_lounge_name || ' بمبلغ ' || v_amount || ' ج.م. السبب: ' || p_reason,
          'Payout request of ' || v_amount || ' EGP for ' || v_lounge_name || ' was rejected. Reason: ' || p_reason,
          'payout', false,
          jsonb_build_object('payout_id', p_payout_id, 'reason', p_reason, 'amount', v_amount)
        );
      END IF;
    END IF;
  END IF;

  IF NOT FOUND THEN RAISE EXCEPTION 'Payout not found or not awaiting review'; END IF;
  RETURN jsonb_build_object('success', true, 'payout_id', p_payout_id, 'status', CASE WHEN p_resolution = 'approve' THEN 'pending' ELSE 'cancelled' END);
END;
$$;


ALTER FUNCTION "public"."resolve_payout_review"("p_payout_id" "uuid", "p_resolution" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_tournament_dispute"("p_match_id" "uuid", "p_winner_id" "uuid", "p_score_player1" integer, "p_score_player2" integer, "p_notes" "text") RETURNS "public"."tournament_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$ DECLARE m public.tournament_matches; t public.tournaments%ROWTYPE; BEGIN SELECT * INTO m FROM public.tournament_matches WHERE id=p_match_id FOR UPDATE; SELECT * INTO t FROM public.tournaments WHERE id=m.tournament_id FOR UPDATE; IF NOT(is_super_admin() OR private.is_lounge_manager(t.lounge_id)) THEN RAISE EXCEPTION 'not_authorized'; END IF; IF p_winner_id NOT IN(m.player1_id,m.player2_id) OR p_notes IS NULL OR btrim(p_notes)='' THEN RAISE EXCEPTION 'invalid_resolution'; END IF; UPDATE public.tournament_matches SET winner_id=p_winner_id,score_player1=p_score_player1,score_player2=p_score_player2,status='completed',resolved_by=auth.uid(),resolved_at=now(),resolution_notes=p_notes,completed_at=now(),updated_at=now() WHERE id=m.id RETURNING * INTO m; IF m.next_match_id IS NOT NULL THEN IF m.next_match_slot=1 THEN UPDATE public.tournament_matches SET player1_id=p_winner_id WHERE id=m.next_match_id AND player1_id IS NULL; ELSE UPDATE public.tournament_matches SET player2_id=p_winner_id WHERE id=m.next_match_id AND player2_id IS NULL; END IF; END IF; PERFORM public.tournament_audit(t.id,'dispute_resolved',p_winner_id,m.id,NULL,to_jsonb(m),p_notes); RETURN m; END $$;


ALTER FUNCTION "public"."resolve_tournament_dispute"("p_match_id" "uuid", "p_winner_id" "uuid", "p_score_player1" integer, "p_score_player2" integer, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_kyc"("p_user_id" "uuid", "p_approve" boolean, "p_notes" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_kyc_updated INT;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Unauthorized: Only Super Admin can review KYC';
  END IF;

  UPDATE public.kyc_submissions
  SET status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
      notes = p_notes,
      updated_at = NOW()
  WHERE user_id = p_user_id;

  GET DIAGNOSTICS v_kyc_updated = ROW_COUNT;
  IF v_kyc_updated = 0 THEN
    RAISE EXCEPTION 'KYC submission not found for user %', p_user_id;
  END IF;

  IF p_approve THEN
    UPDATE public.lounges
    SET status = 'active', is_open = true, is_active = true
    WHERE owner_id = p_user_id;

    UPDATE public.profiles
    SET role = 'owner', is_active = true, is_setup_completed = true, updated_at = NOW()
    WHERE id = p_user_id;
  ELSE
    UPDATE public.lounges
    SET status = 'rejected', is_open = false, is_active = false
    WHERE owner_id = p_user_id;

    UPDATE public.profiles
    SET is_setup_completed = false, updated_at = NOW()
    WHERE id = p_user_id;
  END IF;

  INSERT INTO public.notifications (user_id, title, title_ar, title_en, body, body_ar, body_en, type, metadata)
  VALUES (
    p_user_id,
    CASE WHEN p_approve THEN 'KYC Approved' ELSE 'KYC Rejected' END,
    CASE WHEN p_approve THEN 'تم توثيق الحساب (KYC)' ELSE 'تم رفض توثيق الحساب (KYC)' END,
    CASE WHEN p_approve THEN 'Your KYC verification has been approved' ELSE 'Your KYC verification has been rejected' END,
    CASE WHEN p_approve THEN 'تهانينا! تم اعتماد وتوثيق حسابك بنجاح' ELSE COALESCE('تم رفض طلب التوثيق: ' || p_notes, 'تم رفض طلب التوثيق') END,
    CASE WHEN p_approve THEN 'تهانينا! تم اعتماد وتوثيق حسابك بنجاح' ELSE COALESCE('تم رفض طلب التوثيق: ' || p_notes, 'تم رفض طلب التوثيق') END,
    CASE WHEN p_approve THEN 'Congratulations! Your KYC account verification was approved.' ELSE COALESCE('KYC verification rejected: ' || p_notes, 'KYC verification rejected.') END,
    CASE WHEN p_approve THEN 'kyc_approved' ELSE 'kyc_rejected' END,
    jsonb_build_object('approved', p_approve, 'notes', p_notes)
  );
END;
$$;


ALTER FUNCTION "public"."review_kyc"("p_user_id" "uuid", "p_approve" boolean, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_lounge_request"("p_request_id" "uuid", "p_revision" integer, "p_approve" boolean, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_request private.lounge_review_requests%ROWTYPE; v_lounge_id uuid;
BEGIN
 IF auth.uid() IS NULL OR public.is_super_admin() IS NOT TRUE THEN
  RAISE EXCEPTION 'SUPER_ADMIN_REQUIRED' USING ERRCODE='42501';
 END IF;
 IF p_revision IS NULL OR p_revision<1 OR p_approve IS NULL
  OR (p_approve IS FALSE AND NULLIF(btrim(p_notes),'') IS NULL) THEN
  RAISE EXCEPTION 'INVALID_REVIEW_DECISION' USING ERRCODE='22023';
 END IF;
 SELECT lounge_id INTO v_lounge_id FROM private.lounge_review_requests WHERE id=p_request_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 PERFORM 1 FROM public.lounges WHERE id=v_lounge_id FOR UPDATE;
 SELECT * INTO v_request FROM private.lounge_review_requests WHERE id=p_request_id FOR UPDATE;
 IF v_request.revision<>p_revision THEN RAISE EXCEPTION 'REVIEW_REVISION_CONFLICT' USING ERRCODE='55000'; END IF;
 IF v_request.status<>'pending' THEN
  IF v_request.reviewer_id=auth.uid() AND v_request.status=(CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END)
   AND v_request.notes IS NOT DISTINCT FROM NULLIF(btrim(p_notes),'') THEN
   RETURN jsonb_build_object('success',true,'request_id',v_request.id,'status',v_request.status,'idempotent',true);
  END IF;
  RAISE EXCEPTION 'REVIEW_ALREADY_DECIDED' USING ERRCODE='55000';
 END IF;
 IF (SELECT owner_id FROM public.lounges WHERE id=v_lounge_id) IS DISTINCT FROM v_request.owner_id THEN
  RAISE EXCEPTION 'LOUNGE_OWNER_CHANGED' USING ERRCODE='55000';
 END IF;
 IF v_request.snapshot IS DISTINCT FROM jsonb_build_object(
  'lounge',(SELECT to_jsonb(l)-ARRAY['status','is_active','is_open','updated_at'] FROM public.lounges l WHERE id=v_lounge_id),
  'rooms',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.rooms r WHERE lounge_id=v_lounge_id),
  'extras',(SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]'::jsonb) FROM public.extras e WHERE lounge_id=v_lounge_id)) THEN
  RAISE EXCEPTION 'REVIEW_DATA_CHANGED' USING ERRCODE='55000';
 END IF;
 UPDATE private.lounge_review_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
  reviewer_id=auth.uid(),notes=NULLIF(btrim(p_notes),''),reviewed_at=now() WHERE id=p_request_id;
 UPDATE public.lounges SET status=CASE WHEN p_approve THEN 'active' ELSE 'rejected' END,
  is_active=p_approve,is_open=false WHERE id=v_lounge_id;
 UPDATE public.profiles SET is_active=CASE WHEN p_approve THEN true ELSE is_active END,
  is_setup_completed=p_approve,updated_at=now()
  WHERE id=v_request.owner_id AND lounge_id=v_lounge_id;
 INSERT INTO public.notifications(user_id,title,title_ar,title_en,body,body_ar,body_en,type,metadata)
 VALUES(v_request.owner_id,
  CASE WHEN p_approve THEN 'KYC Approved' ELSE 'KYC Rejected' END,
  CASE WHEN p_approve THEN 'تم قبول بيانات الصالة' ELSE 'تحتاج بيانات الصالة إلى تعديل' END,
  CASE WHEN p_approve THEN 'Lounge review approved' ELSE 'Lounge review rejected' END,
  COALESCE(NULLIF(btrim(p_notes),''),'Lounge review completed'),
  CASE WHEN p_approve THEN 'تم قبول البيانات. فتح الصالة للحجوزات يتطلب شيفتًا واتصالًا متاحًا.' ELSE btrim(p_notes) END,
  CASE WHEN p_approve THEN 'Data approved. Online booking requires an open shift and available connectivity.' ELSE btrim(p_notes) END,
  CASE WHEN p_approve THEN 'kyc_approved' ELSE 'kyc_rejected' END,
  jsonb_build_object('lounge_id',v_lounge_id,'request_id',p_request_id,'revision',p_revision,'approved',p_approve));
 RETURN jsonb_build_object('success',true,'request_id',p_request_id,'status',CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,'idempotent',false);
END;
$$;


ALTER FUNCTION "public"."review_lounge_request"("p_request_id" "uuid", "p_revision" integer, "p_approve" boolean, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_tournament_payment_for_participant"("p_participant_id" "uuid", "p_approved" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_participant public.tournament_participants%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
  v_submission public.tournament_payment_submissions%ROWTYPE;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT *
  INTO v_participant
  FROM public.tournament_participants
  WHERE id = p_participant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'participant_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_tournament
  FROM public.tournaments
  WHERE id = v_participant.tournament_id;

  IF NOT (
    public.is_super_admin()
    OR private.is_lounge_manager(v_tournament.lounge_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_submission
  FROM public.tournament_payment_submissions
  WHERE participant_id = p_participant_id
    AND status = 'pending'
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pending_payment_submission_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  IF p_approved THEN
    v_result := to_jsonb(
      public.approve_tournament_payment(
        v_submission.id,
        NULLIF(btrim(p_reason), '')
      )
    );
  ELSE
    IF NULLIF(btrim(p_reason), '') IS NULL THEN
      RAISE EXCEPTION 'rejection_reason_required'
        USING ERRCODE = '22023';
    END IF;

    PERFORM public.reject_tournament_payment(
      v_submission.id,
      btrim(p_reason)
    );

    SELECT to_jsonb(tp)
    INTO v_result
    FROM public.tournament_participants AS tp
    WHERE tp.id = p_participant_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'participant', v_result,
    'approved', p_approved
  );
END;
$$;


ALTER FUNCTION "public"."review_tournament_payment_for_participant"("p_participant_id" "uuid", "p_approved" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_canteen_combo"("p_combo" "jsonb", "p_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid;
  v_lounge_id uuid;
  v_item jsonb;
  v_extra_id uuid;
  v_quantity integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  BEGIN
    v_id := NULLIF(p_combo->>'id','')::uuid;
    v_lounge_id := NULLIF(p_combo->>'lounge_id','')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Invalid combo identifier' USING ERRCODE='22023';
  END;

  IF v_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Lounge is required' USING ERRCODE='22023';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR public.has_lounge_permission(v_lounge_id,'menu_manage_items')
  ) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF COALESCE((p_combo->>'price')::numeric,-1) < 0 THEN
    RAISE EXCEPTION 'Invalid combo price' USING ERRCODE='22023';
  END IF;

  IF NULLIF(btrim(COALESCE(p_combo->>'name_ar','')),'') IS NULL THEN
    RAISE EXCEPTION 'Arabic combo name is required' USING ERRCODE='22023';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'Combo items must be an array' USING ERRCODE='22023';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.canteen_combos (
      lounge_id,name_ar,name_en,description_ar,description_en,image_url,
      price,days_of_week,available_from,available_to,valid_from,valid_to,
      is_active,sort_order
    )
    VALUES (
      v_lounge_id,
      btrim(p_combo->>'name_ar'),
      NULLIF(btrim(COALESCE(p_combo->>'name_en','')),''),
      NULLIF(btrim(COALESCE(p_combo->>'description_ar','')),''),
      NULLIF(btrim(COALESCE(p_combo->>'description_en','')),''),
      NULLIF(btrim(COALESCE(p_combo->>'image_url','')),''),
      (p_combo->>'price')::numeric,
      CASE
        WHEN p_combo ? 'days_of_week'
          AND jsonb_typeof(p_combo->'days_of_week') = 'array'
        THEN ARRAY(
          SELECT jsonb_array_elements_text(p_combo->'days_of_week')::integer
        )
        ELSE NULL
      END,
      NULLIF(p_combo->>'available_from','')::time,
      NULLIF(p_combo->>'available_to','')::time,
      NULLIF(p_combo->>'valid_from','')::date,
      NULLIF(p_combo->>'valid_to','')::date,
      COALESCE((p_combo->>'is_active')::boolean,true),
      COALESCE((p_combo->>'sort_order')::integer,0)
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.canteen_combos AS c
    SET
      name_ar=btrim(p_combo->>'name_ar'),
      name_en=NULLIF(btrim(COALESCE(p_combo->>'name_en','')),''),
      description_ar=NULLIF(btrim(COALESCE(p_combo->>'description_ar','')),''),
      description_en=NULLIF(btrim(COALESCE(p_combo->>'description_en','')),''),
      image_url=NULLIF(btrim(COALESCE(p_combo->>'image_url','')),''),
      price=(p_combo->>'price')::numeric,
      days_of_week=CASE
        WHEN p_combo ? 'days_of_week'
          AND jsonb_typeof(p_combo->'days_of_week') = 'array'
        THEN ARRAY(
          SELECT jsonb_array_elements_text(p_combo->'days_of_week')::integer
        )
        ELSE NULL
      END,
      available_from=NULLIF(p_combo->>'available_from','')::time,
      available_to=NULLIF(p_combo->>'available_to','')::time,
      valid_from=NULLIF(p_combo->>'valid_from','')::date,
      valid_to=NULLIF(p_combo->>'valid_to','')::date,
      is_active=COALESCE((p_combo->>'is_active')::boolean,true),
      sort_order=COALESCE((p_combo->>'sort_order')::integer,0),
      updated_at=now()
    WHERE c.id=v_id
      AND c.lounge_id=v_lounge_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Combo not found' USING ERRCODE='P0002';
    END IF;
  END IF;

  DELETE FROM public.canteen_combo_items WHERE combo_id=v_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    BEGIN
      v_extra_id := NULLIF(v_item->>'extra_id','')::uuid;
      v_quantity := COALESCE((v_item->>'quantity')::integer,1);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Invalid combo item' USING ERRCODE='22023';
    END;

    IF v_extra_id IS NULL OR v_quantity NOT BETWEEN 1 AND 100 THEN
      RAISE EXCEPTION 'Invalid combo item' USING ERRCODE='22023';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.extras AS e
      WHERE e.id=v_extra_id
        AND e.lounge_id=v_lounge_id
        AND COALESCE(e.is_active,true) IS TRUE
    ) THEN
      RAISE EXCEPTION 'Combo item does not belong to lounge'
        USING ERRCODE='23514';
    END IF;

    INSERT INTO public.canteen_combo_items(combo_id,extra_id,quantity)
    VALUES(v_id,v_extra_id,v_quantity);
  END LOOP;

  RETURN (
    SELECT to_jsonb(c)
      || jsonb_build_object(
        'items', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'extra_id',e.id,
              'name_ar',COALESCE(e.name_ar,e.name),
              'name_en',COALESCE(e.name_en,e.name),
              'price',e.price,
              'quantity',ci.quantity
            )
          )
          FROM public.canteen_combo_items AS ci
          JOIN public.extras AS e ON e.id=ci.extra_id
          WHERE ci.combo_id=c.id
        ),'[]'::jsonb)
      )
    FROM public.canteen_combos AS c
    WHERE c.id=v_id
  );
END;
$$;


ALTER FUNCTION "public"."save_canteen_combo"("p_combo" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_lounge_extra"("p_extra" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid;
  v_lounge_id uuid;
  v_existing public.extras%ROWTYPE;
  v_name_ar text;
  v_name_en text;
  v_name text;
  v_category text;
  v_price numeric;
  v_cost_price numeric;
  v_stock integer;
  v_min_stock integer;
  v_track_stock boolean;
  v_available boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF p_extra IS NULL OR jsonb_typeof(p_extra) <> 'object' THEN
    RAISE EXCEPTION 'EXTRA_PAYLOAD_REQUIRED' USING ERRCODE='22023';
  END IF;

  BEGIN
    v_id := NULLIF(p_extra->>'id','')::uuid;
    v_lounge_id := NULLIF(p_extra->>'lounge_id','')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'INVALID_EXTRA_ID' USING ERRCODE='22023';
  END;

  IF v_lounge_id IS NULL THEN
    RAISE EXCEPTION 'LOUNGE_ID_REQUIRED' USING ERRCODE='22023';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR public.has_lounge_permission(v_lounge_id, 'menu_manage_items')
  ) THEN
    RAISE EXCEPTION 'MENU_MANAGE_ITEMS_PERMISSION_REQUIRED' USING ERRCODE='42501';
  END IF;

  IF v_id IS NOT NULL THEN
    SELECT e.* INTO v_existing
    FROM public.extras AS e
    WHERE e.id=v_id
    FOR UPDATE;

    IF FOUND AND v_existing.lounge_id IS DISTINCT FROM v_lounge_id THEN
      RAISE EXCEPTION 'CROSS_LOUNGE_EXTRA' USING ERRCODE='42501';
    END IF;
  END IF;

  v_name_ar := NULLIF(btrim(COALESCE(p_extra->>'name_ar','')),'');
  v_name_en := NULLIF(btrim(COALESCE(p_extra->>'name_en','')),'');
  v_name := COALESCE(
    v_name_en,
    v_name_ar,
    NULLIF(btrim(COALESCE(p_extra->>'name','')),'')
  );
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'EXTRA_NAME_REQUIRED' USING ERRCODE='22023';
  END IF;

  BEGIN
    v_price := COALESCE(NULLIF(p_extra->>'price','')::numeric,0);
    v_cost_price := NULLIF(p_extra->>'cost_price','')::numeric;
    v_stock := COALESCE(NULLIF(p_extra->>'stock_quantity','')::integer,0);
    v_min_stock := COALESCE(NULLIF(p_extra->>'min_stock_alert','')::integer,5);
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'INVALID_EXTRA_NUMERIC_VALUE' USING ERRCODE='22023';
  END;

  IF v_price < 0 OR (v_cost_price IS NOT NULL AND v_cost_price < 0)
     OR v_stock < 0 OR v_min_stock < 0 THEN
    RAISE EXCEPTION 'INVALID_EXTRA_NUMERIC_VALUE' USING ERRCODE='22023';
  END IF;

  v_category := lower(btrim(COALESCE(NULLIF(p_extra->>'category',''),'other')));
  v_track_stock := COALESCE((p_extra->>'track_stock')::boolean,false);
  v_available := COALESCE((p_extra->>'is_available')::boolean,true);

  IF v_id IS NULL THEN
    v_id := gen_random_uuid();
  END IF;

  INSERT INTO public.extras(
    id,lounge_id,name,name_ar,name_en,price,cost_price,category,
    icon_key,image_url,is_available,is_active,stock_quantity,
    track_stock,min_stock_alert
  )
  VALUES(
    v_id,v_lounge_id,v_name,v_name_ar,v_name_en,v_price,v_cost_price,v_category,
    NULLIF(btrim(COALESCE(p_extra->>'icon_key','')),''),
    NULLIF(btrim(COALESCE(p_extra->>'image_url','')),''),
    v_available,true,v_stock,v_track_stock,v_min_stock
  )
  ON CONFLICT(id) DO UPDATE SET
    name=EXCLUDED.name,
    name_ar=EXCLUDED.name_ar,
    name_en=EXCLUDED.name_en,
    price=EXCLUDED.price,
    cost_price=EXCLUDED.cost_price,
    category=EXCLUDED.category,
    icon_key=EXCLUDED.icon_key,
    image_url=EXCLUDED.image_url,
    is_available=EXCLUDED.is_available,
    stock_quantity=EXCLUDED.stock_quantity,
    track_stock=EXCLUDED.track_stock,
    min_stock_alert=EXCLUDED.min_stock_alert
  WHERE public.extras.lounge_id=EXCLUDED.lounge_id;

  RETURN (
    SELECT to_jsonb(e)
    FROM public.extras e
    WHERE e.id=v_id
  );
END;
$$;


ALTER FUNCTION "public"."save_lounge_extra"("p_extra" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_lounge_room"("p_room_id" "uuid", "p_lounge_id" "uuid", "p_name" "text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_single_price" numeric DEFAULT 0, "p_multi_price" numeric DEFAULT 0, "p_extra_controller_price" numeric DEFAULT 0, "p_activity_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_max_capacity" integer DEFAULT 4, "p_open_time_enabled" boolean DEFAULT true, "p_resource_type" "text" DEFAULT 'console'::"text", "p_resource_attributes" "jsonb" DEFAULT '{}'::"jsonb", "p_requires_screen" boolean DEFAULT NULL::boolean, "p_requires_controllers" boolean DEFAULT NULL::boolean, "p_pricing_model" "text" DEFAULT 'per_room_hour'::"text", "p_min_capacity" integer DEFAULT 1, "p_controllers_count" integer DEFAULT NULL::integer, "p_screen_size" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room_id uuid;
  v_activity_id uuid;
  v_existing_lounge_id uuid;
  v_req_screen boolean;
  v_req_controllers boolean;
  v_norm_controllers integer;
  v_norm_screen text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'Lounge ID is required' USING ERRCODE = '22023';
  END IF;

  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Room name is required' USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(p_lounge_id, 'rooms_manage') THEN
    RAISE EXCEPTION 'Not authorized to manage rooms in this lounge' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(p_single_price, 0) < 0 OR COALESCE(p_multi_price, 0) < 0 OR COALESCE(p_extra_controller_price, 0) < 0 THEN
    RAISE EXCEPTION 'Prices must be non-negative' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_min_capacity, 1) < 1 THEN
    RAISE EXCEPTION 'Min capacity must be at least 1' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_max_capacity, 1) < COALESCE(p_min_capacity, 1) THEN
    RAISE EXCEPTION 'Max capacity must be greater than or equal to min capacity' USING ERRCODE = '22023';
  END IF;

  -- Validate room does not belong to another lounge if updating
  IF p_room_id IS NOT NULL THEN
    SELECT r.lounge_id
    INTO v_existing_lounge_id
    FROM public.rooms AS r
    WHERE r.id = p_room_id;

    IF FOUND AND v_existing_lounge_id IS DISTINCT FROM p_lounge_id THEN
      RAISE EXCEPTION 'Cannot modify room belonging to another lounge' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Capability normalization for table games (Billiards, Table Tennis, etc.)
  IF p_resource_type IN ('billiard', 'table_tennis', 'foosball', 'darts', 'board_games') THEN
    v_req_screen := COALESCE(p_requires_screen, false);
    v_req_controllers := COALESCE(p_requires_controllers, false);
    v_norm_controllers := COALESCE(p_controllers_count, 0);
    v_norm_screen := COALESCE(p_screen_size, NULL);
  ELSE
    v_req_screen := COALESCE(p_requires_screen, true);
    v_req_controllers := COALESCE(p_requires_controllers, true);
    v_norm_controllers := COALESCE(p_controllers_count, 2);
    v_norm_screen := COALESCE(p_screen_size, '43"');
  END IF;

  -- Atomic Upsert of room
  INSERT INTO public.rooms (
    id,
    lounge_id,
    name,
    name_ar,
    name_en,
    hourly_rate_single,
    hourly_rate_multi,
    extra_controller_price,
    min_capacity,
    max_capacity,
    is_available,
    status,
    resource_type,
    resource_attributes,
    requires_screen,
    requires_controllers,
    pricing_model,
    controllers_count,
    screen_size,
    open_time_enabled,
    space_type_id,
    updated_at
  ) VALUES (
    COALESCE(p_room_id, gen_random_uuid()),
    p_lounge_id,
    p_name,
    p_name,
    p_name,
    p_single_price,
    p_multi_price,
    p_extra_controller_price,
    p_min_capacity,
    p_max_capacity,
    true,
    'available',
    COALESCE(p_resource_type, 'console'),
    COALESCE(p_resource_attributes, '{}'::jsonb),
    v_req_screen,
    v_req_controllers,
    COALESCE(p_pricing_model, 'per_room_hour'),
    v_norm_controllers,
    v_norm_screen,
    COALESCE(p_open_time_enabled, true),
    p_category_id,
    now()
  )
  ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    name_ar = EXCLUDED.name_ar,
    name_en = EXCLUDED.name_en,
    hourly_rate_single = EXCLUDED.hourly_rate_single,
    hourly_rate_multi = EXCLUDED.hourly_rate_multi,
    extra_controller_price = EXCLUDED.extra_controller_price,
    min_capacity = EXCLUDED.min_capacity,
    max_capacity = EXCLUDED.max_capacity,
    resource_type = EXCLUDED.resource_type,
    resource_attributes = EXCLUDED.resource_attributes,
    requires_screen = EXCLUDED.requires_screen,
    requires_controllers = EXCLUDED.requires_controllers,
    pricing_model = EXCLUDED.pricing_model,
    controllers_count = EXCLUDED.controllers_count,
    screen_size = EXCLUDED.screen_size,
    open_time_enabled = EXCLUDED.open_time_enabled,
    space_type_id = COALESCE(EXCLUDED.space_type_id, public.rooms.space_type_id),
    updated_at = now()
  RETURNING id INTO v_room_id;

  -- Synchronize activities atomically
  DELETE FROM public.room_activities
  WHERE room_id = v_room_id;

  IF p_activity_ids IS NOT NULL AND cardinality(p_activity_ids) > 0 THEN
    FOREACH v_activity_id IN ARRAY p_activity_ids
    LOOP
      IF EXISTS (SELECT 1 FROM public.activity_types WHERE id = v_activity_id) THEN
        INSERT INTO public.room_activities (room_id, activity_type_id)
        VALUES (v_room_id, v_activity_id)
        ON CONFLICT DO NOTHING;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'room_id', v_room_id,
    'lounge_id', p_lounge_id,
    'name', p_name,
    'resource_type', COALESCE(p_resource_type, 'console'),
    'pricing_model', COALESCE(p_pricing_model, 'per_room_hour'),
    'min_capacity', p_min_capacity,
    'max_capacity', p_max_capacity,
    'requires_screen', v_req_screen,
    'requires_controllers', v_req_controllers,
    'controllers_count', v_norm_controllers,
    'screen_size', v_norm_screen,
    'activities_count', COALESCE(cardinality(p_activity_ids), 0)
  );
END;
$$;


ALTER FUNCTION "public"."save_lounge_room"("p_room_id" "uuid", "p_lounge_id" "uuid", "p_name" "text", "p_category_id" "uuid", "p_single_price" numeric, "p_multi_price" numeric, "p_extra_controller_price" numeric, "p_activity_ids" "uuid"[], "p_max_capacity" integer, "p_open_time_enabled" boolean, "p_resource_type" "text", "p_resource_attributes" "jsonb", "p_requires_screen" boolean, "p_requires_controllers" boolean, "p_pricing_model" "text", "p_min_capacity" integer, "p_controllers_count" integer, "p_screen_size" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_lounge_room_v2"("p_room" "jsonb", "p_activity_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room_id uuid;
  v_lounge_id uuid;
  v_existing public.rooms%ROWTYPE;
  v_status text;
  v_activity_id uuid;
  v_name text;
  v_requires_screen boolean;
  v_requires_controllers boolean;
  v_controllers_count integer;
  v_screen_size text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000';
  END IF;
  IF p_room IS NULL OR jsonb_typeof(p_room) <> 'object' THEN
    RAISE EXCEPTION 'ROOM_PAYLOAD_REQUIRED' USING ERRCODE='22023';
  END IF;

  v_lounge_id := NULLIF(p_room->>'lounge_id','')::uuid;
  v_room_id := COALESCE(NULLIF(p_room->>'id','')::uuid, gen_random_uuid());
  IF v_lounge_id IS NULL THEN
    RAISE EXCEPTION 'LOUNGE_ID_REQUIRED' USING ERRCODE='22023';
  END IF;
  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_lounge_id,'rooms_manage') THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_existing
  FROM public.rooms
  WHERE id=v_room_id
  FOR UPDATE;

  IF FOUND AND v_existing.lounge_id IS DISTINCT FROM v_lounge_id THEN
    RAISE EXCEPTION 'ROOM_LOUNGE_MISMATCH' USING ERRCODE='42501';
  END IF;

  v_name := COALESCE(
    NULLIF(btrim(p_room->>'name_en'),''),
    NULLIF(btrim(p_room->>'name_ar'),''),
    NULLIF(btrim(p_room->>'name'),'')
  );
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'ROOM_NAME_REQUIRED' USING ERRCODE='22023';
  END IF;

  IF COALESCE((p_room->>'hourly_rate_single')::numeric,0) < 0
     OR COALESCE((p_room->>'hourly_rate_multi')::numeric,0) < 0
     OR COALESCE((p_room->>'extra_controller_price')::numeric,0) < 0 THEN
    RAISE EXCEPTION 'ROOM_PRICE_INVALID' USING ERRCODE='22023';
  END IF;

  IF COALESCE((p_room->>'max_capacity')::integer,1) < 1 THEN
    RAISE EXCEPTION 'ROOM_CAPACITY_INVALID' USING ERRCODE='22023';
  END IF;

  v_status := lower(COALESCE(NULLIF(btrim(p_room->>'status'),''), 'available'));
  IF v_status NOT IN ('available','occupied','maintenance') THEN
    RAISE EXCEPTION 'ROOM_STATUS_INVALID' USING ERRCODE='22023';
  END IF;

  IF FOUND AND v_status IS DISTINCT FROM v_existing.status THEN
    IF v_status='maintenance' THEN
      IF NOT public.is_super_admin()
         AND NOT public.has_lounge_permission(v_lounge_id,'rooms_manage') THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE='42501';
      END IF;
    ELSE
      IF NOT public.is_super_admin()
         AND NOT public.has_lounge_permission(v_lounge_id,'sessions_control') THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE='42501';
      END IF;
    END IF;
  END IF;

  v_requires_screen := COALESCE((p_room->>'requires_screen')::boolean,true);
  v_requires_controllers := COALESCE((p_room->>'requires_controllers')::boolean,true);
  v_controllers_count := CASE
    WHEN v_requires_controllers THEN GREATEST(COALESCE((p_room->>'controllers_count')::integer,0),0)
    ELSE 0
  END;
  v_screen_size := CASE
    WHEN v_requires_screen THEN NULLIF(btrim(p_room->>'screen_size'),'')
    ELSE NULL
  END;

  INSERT INTO public.rooms(
    id,lounge_id,name,name_ar,name_en,description_ar,description_en,
    space_type_id,max_capacity,hourly_rate_single,hourly_rate_multi,
    extra_controller_price,is_available,images,features_ar,features_en,
    controllers_count,screen_size,resource_type,requires_screen,
    requires_controllers,pricing_model,status,is_active,
    open_time_enabled,open_time_pricing_mode,open_time_custom_hourly_rate,
    open_time_price_multiplier,open_time_minimum_minutes,
    open_time_rounding_minutes,open_time_max_minutes,
    open_time_buffer_before_booking_minutes,updated_at
  )
  VALUES(
    v_room_id,v_lounge_id,v_name,
    NULLIF(p_room->>'name_ar',''),NULLIF(p_room->>'name_en',''),
    NULLIF(p_room->>'description_ar',''),NULLIF(p_room->>'description_en',''),
    NULLIF(p_room->>'space_type_id','')::uuid,
    COALESCE((p_room->>'max_capacity')::integer,4),
    COALESCE((p_room->>'hourly_rate_single')::numeric,0),
    COALESCE((p_room->>'hourly_rate_multi')::numeric,0),
    CASE WHEN v_requires_controllers
      THEN COALESCE((p_room->>'extra_controller_price')::numeric,0)
      ELSE 0 END,
    v_status='available',
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_room->'images','[]'::jsonb))),ARRAY[]::text[]),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_room->'features_ar','[]'::jsonb))),ARRAY[]::text[]),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_room->'features_en','[]'::jsonb))),ARRAY[]::text[]),
    v_controllers_count,v_screen_size,
    COALESCE(NULLIF(p_room->>'resource_type',''),'console'),
    v_requires_screen,v_requires_controllers,
    COALESCE(NULLIF(p_room->>'pricing_model',''),'per_room_hour'),
    v_status,true,
    COALESCE((p_room->>'open_time_enabled')::boolean,true),
    COALESCE(NULLIF(p_room->>'open_time_pricing_mode',''),'same_hourly'),
    NULLIF(p_room->>'open_time_custom_hourly_rate','')::numeric,
    COALESCE(NULLIF(p_room->>'open_time_price_multiplier','')::numeric,1),
    COALESCE(NULLIF(p_room->>'open_time_minimum_minutes','')::integer,30),
    COALESCE(NULLIF(p_room->>'open_time_rounding_minutes','')::integer,15),
    NULLIF(p_room->>'open_time_max_minutes','')::integer,
    COALESCE(NULLIF(p_room->>'open_time_buffer_before_booking_minutes','')::integer,15),
    now()
  )
  ON CONFLICT(id) DO UPDATE SET
    name=EXCLUDED.name,
    name_ar=EXCLUDED.name_ar,
    name_en=EXCLUDED.name_en,
    description_ar=EXCLUDED.description_ar,
    description_en=EXCLUDED.description_en,
    space_type_id=EXCLUDED.space_type_id,
    max_capacity=EXCLUDED.max_capacity,
    hourly_rate_single=EXCLUDED.hourly_rate_single,
    hourly_rate_multi=EXCLUDED.hourly_rate_multi,
    extra_controller_price=EXCLUDED.extra_controller_price,
    is_available=EXCLUDED.is_available,
    images=EXCLUDED.images,
    features_ar=EXCLUDED.features_ar,
    features_en=EXCLUDED.features_en,
    controllers_count=EXCLUDED.controllers_count,
    screen_size=EXCLUDED.screen_size,
    resource_type=EXCLUDED.resource_type,
    requires_screen=EXCLUDED.requires_screen,
    requires_controllers=EXCLUDED.requires_controllers,
    pricing_model=EXCLUDED.pricing_model,
    status=EXCLUDED.status,
    open_time_enabled=EXCLUDED.open_time_enabled,
    open_time_pricing_mode=EXCLUDED.open_time_pricing_mode,
    open_time_custom_hourly_rate=EXCLUDED.open_time_custom_hourly_rate,
    open_time_price_multiplier=EXCLUDED.open_time_price_multiplier,
    open_time_minimum_minutes=EXCLUDED.open_time_minimum_minutes,
    open_time_rounding_minutes=EXCLUDED.open_time_rounding_minutes,
    open_time_max_minutes=EXCLUDED.open_time_max_minutes,
    open_time_buffer_before_booking_minutes=EXCLUDED.open_time_buffer_before_booking_minutes,
    updated_at=now();

  DELETE FROM public.room_activities WHERE room_id=v_room_id;
  FOREACH v_activity_id IN ARRAY COALESCE(p_activity_ids,ARRAY[]::uuid[])
  LOOP
    IF NOT EXISTS(SELECT 1 FROM public.activity_types WHERE id=v_activity_id) THEN
      RAISE EXCEPTION 'ACTIVITY_NOT_FOUND' USING ERRCODE='22023';
    END IF;
    INSERT INTO public.room_activities(room_id,activity_type_id)
    VALUES(v_room_id,v_activity_id)
    ON CONFLICT DO NOTHING;
  END LOOP;

  RETURN jsonb_build_object(
    'success',true,
    'room_id',v_room_id,
    'lounge_id',v_lounge_id,
    'activities_count',COALESCE(cardinality(p_activity_ids),0)
  );
END;
$$;


ALTER FUNCTION "public"."save_lounge_room_v2"("p_room" "jsonb", "p_activity_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_redemption_option_admin"("p_option_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_description_ar" "text", "p_description_en" "text", "p_points_cost" integer, "p_reward_type" "text", "p_reward_value" numeric, "p_is_active" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid;
  v_type text := lower(btrim(COALESCE(p_reward_type,'')));
  v_title text;
  v_description text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'SUPER_ADMIN_REQUIRED' USING ERRCODE='42501';
  END IF;

  IF p_points_cost IS NULL OR p_points_cost <= 0 THEN
    RAISE EXCEPTION 'INVALID_POINTS_COST' USING ERRCODE='22023';
  END IF;

  IF v_type NOT IN ('discount_fixed','free_hour') THEN
    RAISE EXCEPTION 'INVALID_REWARD_TYPE' USING ERRCODE='22023';
  END IF;

  IF v_type = 'discount_fixed'
     AND (p_reward_value IS NULL OR p_reward_value <= 0) THEN
    RAISE EXCEPTION 'INVALID_REWARD_VALUE' USING ERRCODE='22023';
  END IF;

  IF v_type = 'free_hour'
     AND p_reward_value IS NOT NULL
     AND p_reward_value <= 0 THEN
    RAISE EXCEPTION 'INVALID_REWARD_VALUE' USING ERRCODE='22023';
  END IF;

  IF NULLIF(btrim(COALESCE(p_title_ar,'')),'') IS NULL
     OR NULLIF(btrim(COALESCE(p_title_en,'')),'') IS NULL THEN
    RAISE EXCEPTION 'BILINGUAL_TITLE_REQUIRED' USING ERRCODE='22023';
  END IF;

  v_title := COALESCE(
    NULLIF(btrim(p_title_en),''),
    NULLIF(btrim(p_title_ar),''),
    'Redemption Option'
  );
  v_description := COALESCE(
    NULLIF(btrim(COALESCE(p_description_en,'')),''),
    NULLIF(btrim(COALESCE(p_description_ar,'')),'')
  );

  IF p_option_id IS NULL THEN
    INSERT INTO public.redemption_options (
      title,
      description,
      points_cost,
      reward_type,
      reward_value,
      is_active,
      title_ar,
      title_en,
      description_ar,
      description_en
    )
    VALUES (
      v_title,
      v_description,
      p_points_cost,
      v_type,
      CASE
        WHEN v_type='free_hour' THEN COALESCE(p_reward_value,1)
        ELSE p_reward_value
      END,
      COALESCE(p_is_active,true),
      btrim(p_title_ar),
      btrim(p_title_en),
      NULLIF(btrim(COALESCE(p_description_ar,'')),''),
      NULLIF(btrim(COALESCE(p_description_en,'')),'')
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.redemption_options
    SET title = v_title,
        description = v_description,
        points_cost = p_points_cost,
        reward_type = v_type,
        reward_value = CASE
          WHEN v_type='free_hour' THEN COALESCE(p_reward_value,1)
          ELSE p_reward_value
        END,
        is_active = COALESCE(p_is_active,true),
        title_ar = btrim(p_title_ar),
        title_en = btrim(p_title_en),
        description_ar = NULLIF(btrim(COALESCE(p_description_ar,'')),''),
        description_en = NULLIF(btrim(COALESCE(p_description_en,'')),'')
    WHERE id = p_option_id
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'REDEMPTION_OPTION_NOT_FOUND' USING ERRCODE='P0002';
    END IF;
  END IF;

  RETURN (
    SELECT to_jsonb(r)
    FROM public.redemption_options AS r
    WHERE r.id = v_id
  );
END;
$$;


ALTER FUNCTION "public"."save_redemption_option_admin"("p_option_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_description_ar" "text", "p_description_en" "text", "p_points_cost" integer, "p_reward_type" "text", "p_reward_value" numeric, "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_tournament_prizes"("p_tournament_id" "uuid", "p_prizes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tournament public.tournaments%ROWTYPE;
  v_prize jsonb;
  v_reward jsonb;
  v_prize_id uuid;
  v_placement integer;
  v_reward_type text;
  v_amount numeric;
  v_points integer;
  v_saved integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  SELECT t.*
  INTO v_tournament
  FROM public.tournaments AS t
  WHERE t.id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament_not_found' USING ERRCODE='P0002';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR private.can_operate_playspot_lounge(v_tournament.lounge_id)
    OR public.is_lounge_member_or_admin(v_tournament.lounge_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;

  IF v_tournament.status IN ('in_progress','completed','cancelled') THEN
    RAISE EXCEPTION 'tournament_prizes_locked' USING ERRCODE='55000';
  END IF;

  IF p_prizes IS NULL OR jsonb_typeof(p_prizes) <> 'array' THEN
    RAISE EXCEPTION 'prizes_must_be_array' USING ERRCODE='22023';
  END IF;

  IF jsonb_array_length(p_prizes) > 64 THEN
    RAISE EXCEPTION 'too_many_prize_placements' USING ERRCODE='22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (
      SELECT (x->>'placement')::integer AS placement
      FROM jsonb_array_elements(p_prizes) AS x
    ) AS placements
    GROUP BY placement
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'duplicate_prize_placement' USING ERRCODE='23505';
  END IF;

  DELETE FROM public.tournament_prizes
  WHERE tournament_id = p_tournament_id;

  FOR v_prize IN SELECT value FROM jsonb_array_elements(p_prizes)
  LOOP
    BEGIN
      v_placement := (v_prize->>'placement')::integer;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid_prize_placement' USING ERRCODE='22023';
    END;

    IF v_placement < 1 THEN
      RAISE EXCEPTION 'invalid_prize_placement' USING ERRCODE='22023';
    END IF;

    v_points := 0;

    IF COALESCE(v_prize->'rewards','[]'::jsonb) IS NOT NULL
       AND jsonb_typeof(COALESCE(v_prize->'rewards','[]'::jsonb)) <> 'array' THEN
      RAISE EXCEPTION 'prize_rewards_must_be_array' USING ERRCODE='22023';
    END IF;

    FOR v_reward IN
      SELECT value
      FROM jsonb_array_elements(COALESCE(v_prize->'rewards','[]'::jsonb))
    LOOP
      v_reward_type := lower(btrim(COALESCE(
        v_reward->>'reward_type',
        v_reward->>'type',
        ''
      )));

      IF v_reward_type NOT IN ('trophy','cash','points','voucher','custom') THEN
        RAISE EXCEPTION 'invalid_prize_reward_type' USING ERRCODE='22023';
      END IF;

      BEGIN
        v_amount := NULLIF(
          COALESCE(v_reward->>'amount', v_reward->>'value', ''),
          ''
        )::numeric;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'invalid_prize_reward_amount' USING ERRCODE='22023';
      END;

      IF v_reward_type IN ('cash','points')
         AND (v_amount IS NULL OR v_amount < 0) THEN
        RAISE EXCEPTION 'prize_reward_amount_required' USING ERRCODE='22023';
      END IF;

      IF v_reward_type = 'cash'
         AND NULLIF(btrim(COALESCE(v_reward->>'currency','')),'') IS NULL THEN
        RAISE EXCEPTION 'cash_reward_currency_required' USING ERRCODE='22023';
      END IF;

      IF v_reward_type = 'points' THEN
        v_points := v_points + floor(v_amount)::integer;
      END IF;
    END LOOP;

    INSERT INTO public.tournament_prizes (
      tournament_id,
      placement,
      points,
      bonus,
      metadata
    )
    VALUES (
      p_tournament_id,
      v_placement,
      v_points,
      0,
      COALESCE(v_prize->'metadata','{}'::jsonb)
    )
    RETURNING id INTO v_prize_id;

    FOR v_reward IN
      SELECT value
      FROM jsonb_array_elements(COALESCE(v_prize->'rewards','[]'::jsonb))
    LOOP
      v_reward_type := lower(btrim(COALESCE(
        v_reward->>'reward_type',
        v_reward->>'type',
        ''
      )));

      BEGIN
        v_amount := NULLIF(
          COALESCE(v_reward->>'amount', v_reward->>'value', ''),
          ''
        )::numeric;
      EXCEPTION WHEN OTHERS THEN
        v_amount := NULL;
      END;

      INSERT INTO public.tournament_prize_rewards (
        prize_id,
        reward_type,
        title_ar,
        title_en,
        description_ar,
        description_en,
        amount,
        currency,
        metadata,
        is_delivered
      )
      VALUES (
        v_prize_id,
        v_reward_type,
        NULLIF(btrim(COALESCE(v_reward->>'title_ar','')),''),
        NULLIF(btrim(COALESCE(v_reward->>'title_en','')),''),
        NULLIF(btrim(COALESCE(v_reward->>'description_ar','')),''),
        NULLIF(btrim(COALESCE(v_reward->>'description_en','')),''),
        v_amount,
        NULLIF(btrim(COALESCE(v_reward->>'currency','')),''),
        COALESCE(v_reward->'metadata','{}'::jsonb),
        false
      );
    END LOOP;

    v_saved := v_saved + 1;
  END LOOP;

  PERFORM public.tournament_audit(
    p_tournament_id,
    'tournament_prizes_saved',
    NULL,
    NULL,
    NULL,
    jsonb_build_object('placements', v_saved)
  );

  RETURN jsonb_build_object(
    'success', true,
    'tournament_id', p_tournament_id,
    'placements_saved', v_saved
  );
END;
$$;


ALTER FUNCTION "public"."save_tournament_prizes"("p_tournament_id" "uuid", "p_prizes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_broadcast_notification"("p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_inserted integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF NULLIF(btrim(COALESCE(p_title_ar,'')),'') IS NULL
     OR NULLIF(btrim(COALESCE(p_title_en,'')),'') IS NULL
     OR NULLIF(btrim(COALESCE(p_body_ar,'')),'') IS NULL
     OR NULLIF(btrim(COALESCE(p_body_en,'')),'') IS NULL THEN
    RAISE EXCEPTION 'BILINGUAL_NOTIFICATION_REQUIRED' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.notifications (
    user_id,
    title_ar,
    title_en,
    body_ar,
    body_en,
    type,
    is_read,
    metadata
  )
  SELECT
    p.id,
    p_title_ar,
    p_title_en,
    p_body_ar,
    p_body_en,
    COALESCE(NULLIF(btrim(p_type),''),'system'),
    false,
    COALESCE(p_metadata,'{}'::jsonb)
  FROM public.profiles AS p
  WHERE COALESCE(p.is_active,true) IS TRUE
    AND COALESCE(p.is_banned,false) IS FALSE
    AND p.role = 'user';

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'recipient_count', v_inserted
  );
END;
$$;


ALTER FUNCTION "public"."send_broadcast_notification"("p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_topic_notification"("p_topic_key" "text", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text" DEFAULT 'info'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  WITH inserted_rows AS (
    INSERT INTO public.notifications (
      user_id,
      title_ar,
      title_en,
      body_ar,
      body_en,
      type,
      is_read,
      metadata
    )
    SELECT
      p.id,
      p_title_ar,
      p_title_en,
      p_body_ar,
      p_body_en,
      p_type,
      false,
      jsonb_build_object('topic', p_topic_key) || COALESCE(p_metadata, '{}'::jsonb)
    FROM public.profiles AS p
    WHERE p.is_active = true
    RETURNING id
  )
  SELECT count(*) INTO v_count
  FROM inserted_rows;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."send_topic_notification"("p_topic_key" "text", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_user_notification"("p_user_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_notification_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'Target user is required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.profiles AS p WHERE p.id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Target user not found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.notifications (
    user_id,
    title_ar,
    title_en,
    body_ar,
    body_en,
    type,
    is_read,
    metadata
  )
  VALUES (
    p_user_id,
    p_title_ar,
    p_title_en,
    p_body_ar,
    p_body_en,
    p_type,
    false,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_notification_id;

  RETURN v_notification_id;
END;
$$;


ALTER FUNCTION "public"."send_user_notification"("p_user_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_body_ar" "text", "p_body_en" "text", "p_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


