CREATE OR REPLACE FUNCTION "public"."set_booking_first_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_completed_count integer;
BEGIN
  IF NEW.user_id IS NULL THEN
    IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id
      WHERE p.id=auth.uid() AND p.is_active IS TRUE AND p.is_banned IS FALSE)
      OR NOT EXISTS(SELECT 1 FROM public.lounges WHERE id=NEW.lounge_id AND is_active IS TRUE AND status='active')
      OR (public.is_super_admin() IS NOT TRUE AND public.has_lounge_permission(NEW.lounge_id,'bookings.manage') IS NOT TRUE) THEN
      RAISE EXCEPTION 'WALK_IN_BOOKING_PERMISSION_DENIED' USING ERRCODE='42501';
    END IF;
    NEW.is_first_booking:=false;RETURN NEW;
  END IF;
  SELECT coalesce(completed_bookings_count,0) INTO v_completed_count FROM public.profiles WHERE id=NEW.user_id FOR UPDATE;
  NEW.is_first_booking:=(coalesce(v_completed_count,0)=0);
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."set_booking_first_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lounge_extra_availability"("p_extra_id" "uuid", "p_is_available" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_extra public.extras%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  SELECT e.* INTO v_extra
  FROM public.extras e
  WHERE e.id=p_extra_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EXTRA_NOT_FOUND' USING ERRCODE='P0002';
  END IF;

  IF NOT (
    public.is_super_admin()
    OR public.has_lounge_permission(v_extra.lounge_id, 'menu_toggle_availability')
  ) THEN
    RAISE EXCEPTION 'MENU_TOGGLE_PERMISSION_REQUIRED' USING ERRCODE='42501';
  END IF;

  UPDATE public.extras
  SET is_available=p_is_available
  WHERE id=p_extra_id;

  RETURN jsonb_build_object(
    'success',true,
    'extra_id',p_extra_id,
    'is_available',p_is_available
  );
END;
$$;


ALTER FUNCTION "public"."set_lounge_extra_availability"("p_extra_id" "uuid", "p_is_available" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lounge_staff_active"("p_target_user_id" "uuid", "p_is_active" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_target public.profiles%ROWTYPE;
  v_actor_role text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT p.*
  INTO v_target
  FROM public.profiles AS p
  WHERE p.id = p_target_user_id
  FOR UPDATE;

  IF NOT FOUND OR v_target.lounge_id IS NULL THEN
    RAISE EXCEPTION 'Staff member not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_target.role IN ('owner', 'lounge_owner', 'super_admin', 'superadmin') THEN
    RAISE EXCEPTION 'Owner and super admin accounts are protected'
      USING ERRCODE = '42501';
  END IF;

  v_actor_role := private.permission_role(auth.uid(), v_target.lounge_id);

  IF v_actor_role NOT IN ('super_admin', 'owner', 'manager') THEN
    RAISE EXCEPTION 'Only lounge administrators can manage staff'
      USING ERRCODE = '42501';
  END IF;

  IF v_actor_role IS NULL
     OR (
       v_actor_role <> 'super_admin'
       AND NOT public.has_lounge_permission(
         v_target.lounge_id,
         'staff_manage'
       )
     ) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role = 'manager' AND v_target.role = 'manager' THEN
    RAISE EXCEPTION 'Managers cannot modify peer managers'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.profiles
  SET is_active = COALESCE(p_is_active, false),
      updated_at = now()
  WHERE id = p_target_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_target_user_id,
    'is_active', COALESCE(p_is_active, false)
  );
END;
$$;


ALTER FUNCTION "public"."set_lounge_staff_active"("p_target_user_id" "uuid", "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_operational_status"("p_room_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_status text:=lower(btrim(COALESCE(p_status,'')));v_lounge_id uuid;v_required_permission text;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
 IF NOT EXISTS(SELECT FROM public.profiles p WHERE p.id=auth.uid() AND COALESCE(p.is_active,true) AND NOT COALESCE(p.is_banned,false)) THEN
  RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE='42501';
 END IF;
 IF p_room_id IS NULL THEN RAISE EXCEPTION 'ROOM_ID_REQUIRED' USING ERRCODE='22023'; END IF;
 IF v_status NOT IN ('available','occupied','maintenance') THEN RAISE EXCEPTION 'INVALID_ROOM_STATUS' USING ERRCODE='22023'; END IF;
 SELECT r.lounge_id INTO v_lounge_id FROM public.rooms r WHERE r.id=p_room_id AND r.status<>'deleted' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ROOM_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 v_required_permission:=CASE WHEN v_status='maintenance' THEN 'rooms_manage' ELSE 'sessions_control' END;
 IF NOT public.is_super_admin() AND NOT public.has_lounge_permission(v_lounge_id,v_required_permission) THEN
  RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE='42501';
 END IF;
 UPDATE public.rooms SET status=v_status,is_available=(v_status='available'),updated_at=now() WHERE id=p_room_id;
 RETURN jsonb_build_object('success',true,'room_id',p_room_id,'lounge_id',v_lounge_id,'status',v_status,'is_available',(v_status='available'));
END $$;


ALTER FUNCTION "public"."set_room_operational_status"("p_room_id" "uuid", "p_status" "text") OWNER TO "postgres";


