CREATE OR REPLACE FUNCTION "public"."start_booking_session"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_shift_id uuid;
  v_now timestamptz := now();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_booking.lounge_id, 'sessions_control') THEN
    RAISE EXCEPTION 'Not authorized for session control in this lounge' USING ERRCODE = '42501';
  END IF;

  -- Idempotency: if already running, return success
  IF v_booking.status = 'in_progress'::public.booking_status THEN
    RETURN jsonb_build_object(
      'success', true,
      'booking_id', p_booking_id,
      'status', 'in_progress',
      'idempotent', true
    );
  END IF;

  IF v_booking.status NOT IN ('upcoming'::public.booking_status, 'pending'::public.booking_status) THEN
    RAISE EXCEPTION 'Booking is not startable from current status: %', v_booking.status
      USING ERRCODE = '55000';
  END IF;

  -- Require active shift for the lounge
  SELECT s.id
  INTO v_shift_id
  FROM public.shifts AS s
  WHERE s.lounge_id = v_booking.lounge_id
    AND s.status = 'open'
    AND s.closed_at IS NULL
  ORDER BY s.opened_at DESC
  LIMIT 1
  FOR SHARE;

  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'NO_OPEN_SHIFT';
  END IF;

  -- Security check: Non-open-time bookings require full payment before starting
  IF COALESCE(v_booking.payment_status, 'unpaid') <> 'paid'
     AND COALESCE(v_booking.is_open_time, false) IS FALSE THEN
    RAISE EXCEPTION 'PAYMENT_REQUIRED_BEFORE_SESSION_START' USING ERRCODE = '55000';
  END IF;

  UPDATE public.bookings AS b
  SET status = 'in_progress'::public.booking_status,
      checked_in_at = COALESCE(b.checked_in_at, v_now),
      actual_start_time = COALESCE(b.actual_start_time, v_now),
      shift_id = COALESCE(b.shift_id, v_shift_id),
      updated_at = v_now
  WHERE b.id = p_booking_id;

  IF v_booking.room_id IS NOT NULL THEN
    UPDATE public.rooms AS r
    SET status = 'occupied',
        is_available = false,
        updated_at = v_now
    WHERE r.id = v_booking.room_id
      AND r.status NOT IN ('maintenance', 'deleted');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'status', 'in_progress',
    'shift_id', v_shift_id
  );
END;
$$;


ALTER FUNCTION "public"."start_booking_session"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_open_time_booking_session"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_shift_id uuid;
  v_now timestamptz := now();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE = '28000';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BOOKING_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_booking.lounge_id, 'sessions_control') THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  SELECT l.*
  INTO v_lounge
  FROM public.lounges AS l
  WHERE l.id = v_booking.lounge_id
  FOR SHARE;

  IF NOT FOUND OR COALESCE(v_lounge.allow_open_time_sessions, false) IS FALSE THEN
    RAISE EXCEPTION 'OPEN_TIME_DISABLED_FOR_LOUNGE' USING ERRCODE = '55000';
  END IF;

  -- Require open shift
  SELECT s.id
  INTO v_shift_id
  FROM public.shifts AS s
  WHERE s.lounge_id = v_booking.lounge_id
    AND s.status = 'open'
    AND s.closed_at IS NULL
  ORDER BY s.opened_at DESC
  LIMIT 1
  FOR SHARE;

  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'NO_OPEN_SHIFT';
  END IF;

  IF v_booking.status = 'in_progress'::public.booking_status THEN
    RETURN jsonb_build_object(
      'success', true,
      'booking_id', p_booking_id,
      'status', 'in_progress',
      'is_open_time', true,
      'idempotent', true
    );
  END IF;

  IF v_booking.status NOT IN ('upcoming'::public.booking_status, 'pending'::public.booking_status) THEN
    RAISE EXCEPTION 'BOOKING_NOT_STARTABLE' USING ERRCODE = '55000';
  END IF;

  -- Open Time walk-in sessions explicitly do NOT require prior payment
  UPDATE public.bookings AS b
  SET status = 'in_progress'::public.booking_status,
      is_open_time = true,
      checked_in_at = COALESCE(b.checked_in_at, v_now),
      actual_start_time = COALESCE(b.actual_start_time, v_now),
      open_time_started_at = COALESCE(b.open_time_started_at, v_now),
      shift_id = COALESCE(b.shift_id, v_shift_id),
      updated_at = v_now
  WHERE b.id = p_booking_id;

  IF v_booking.room_id IS NOT NULL THEN
    UPDATE public.rooms AS r
    SET status = 'occupied',
        is_available = false,
        updated_at = v_now
    WHERE r.id = v_booking.room_id
      AND r.status NOT IN ('maintenance', 'deleted');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'status', 'in_progress',
    'is_open_time', true,
    'shift_id', v_shift_id
  );
END;
$$;


ALTER FUNCTION "public"."start_open_time_booking_session"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_open_time_session"("p_room_id" "uuid", "p_customer_name" "text" DEFAULT NULL::"text", "p_customer_phone" "text" DEFAULT NULL::"text", "p_play_mode" "text" DEFAULT 'single'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
  v_lounge public.lounges%ROWTYPE;
  v_shift_id uuid;
  v_booking_id uuid;
  v_started_at timestamptz := now();
  v_tz text := 'Africa/Cairo';
  v_local_now timestamp without time zone;
  v_next_booking_start timestamp without time zone;
  v_must_end_by timestamp without time zone;
  v_play_mode text := lower(COALESCE(NULLIF(btrim(p_play_mode), ''), 'single'));
  v_base_rate numeric;
  v_effective_rate numeric;
  v_snapshot jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF v_play_mode NOT IN ('single', 'multi') THEN
    RAISE EXCEPTION 'Invalid play mode: %', p_play_mode USING ERRCODE = '22023';
  END IF;

  SELECT r.*
  INTO v_room
  FROM public.rooms AS r
  WHERE r.id = p_room_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT l.*
  INTO v_lounge
  FROM public.lounges AS l
  WHERE l.id = v_room.lounge_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lounge not found' USING ERRCODE = 'P0002';
  END IF;

  v_tz := COALESCE(NULLIF(btrim(v_lounge.timezone), ''), 'Africa/Cairo');
  v_local_now := v_started_at AT TIME ZONE v_tz;

  -- Permission check
  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(v_room.lounge_id, 'sessions_control') THEN
    RAISE EXCEPTION 'Not authorized for session control in this lounge' USING ERRCODE = '42501';
  END IF;

  -- Policy checks
  IF COALESCE(v_lounge.allow_open_time_sessions, false) IS FALSE THEN
    RAISE EXCEPTION 'Open time sessions are disabled for this lounge' USING ERRCODE = '55000';
  END IF;

  IF COALESCE(v_room.open_time_enabled, true) IS FALSE THEN
    RAISE EXCEPTION 'Open time sessions are disabled for this room' USING ERRCODE = '55000';
  END IF;

  IF COALESCE(v_room.status, 'available') = 'maintenance'
     OR COALESCE(v_room.is_available, true) IS FALSE THEN
    RAISE EXCEPTION 'Room is not available' USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.bookings AS b
    WHERE b.room_id = p_room_id AND b.status = 'in_progress'::public.booking_status
  ) THEN
    RAISE EXCEPTION 'Room already has an active session' USING ERRCODE = '55000';
  END IF;

  -- Require open shift of this lounge
  SELECT s.id
  INTO v_shift_id
  FROM public.shifts AS s
  WHERE s.lounge_id = v_room.lounge_id
    AND s.status = 'open'
    AND s.closed_at IS NULL
  ORDER BY s.opened_at DESC
  LIMIT 1
  FOR SHARE;

  IF v_shift_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'NO_OPEN_SHIFT';
  END IF;

  -- Protection of upcoming bookings & must_end_by calculation
  SELECT min(b.date::date + b.start_time::time)
  INTO v_next_booking_start
  FROM public.bookings AS b
  WHERE b.room_id = p_room_id
    AND b.status IN ('pending'::public.booking_status, 'upcoming'::public.booking_status)
    AND (b.date::date + b.start_time::time) > v_local_now;

  IF v_next_booking_start IS NOT NULL THEN
    v_must_end_by := v_next_booking_start - make_interval(mins => COALESCE(v_room.open_time_buffer_before_booking_minutes, 15));
    IF v_must_end_by <= v_local_now THEN
      RAISE EXCEPTION 'Next booking is too soon to start an open time session' USING ERRCODE = '55000';
    END IF;
  END IF;

  -- Rate determination
  v_base_rate := CASE
    WHEN v_play_mode = 'multi' AND COALESCE(v_room.hourly_rate_multi, 0) > 0 THEN v_room.hourly_rate_multi
    ELSE COALESCE(v_room.hourly_rate_single, v_room.hourly_rate, 50)
  END;

  IF COALESCE(v_base_rate, 0) <= 0 THEN
    RAISE EXCEPTION 'Room has no valid hourly rate configured' USING ERRCODE = '23514';
  END IF;

  v_effective_rate := CASE v_room.open_time_pricing_mode
    WHEN 'custom_hourly' THEN COALESCE(v_room.open_time_custom_hourly_rate, v_base_rate)
    WHEN 'hourly_plus_percentage' THEN ROUND(v_base_rate * COALESCE(v_room.open_time_price_multiplier, 1.0), 2)
    ELSE v_base_rate
  END;

  -- Build price & policy snapshot
  v_snapshot := jsonb_build_object(
    'pricing_mode', COALESCE(v_room.open_time_pricing_mode, 'same_hourly'),
    'base_hourly_rate', v_base_rate,
    'effective_hourly_rate', v_effective_rate,
    'custom_hourly_rate', v_room.open_time_custom_hourly_rate,
    'price_multiplier', v_room.open_time_price_multiplier,
    'minimum_minutes', COALESCE(v_room.open_time_minimum_minutes, v_lounge.open_time_minimum_minutes, 30),
    'rounding_minutes', COALESCE(v_room.open_time_rounding_minutes, v_lounge.open_time_rounding_minutes, 15),
    'max_minutes', COALESCE(v_room.open_time_max_minutes, v_lounge.open_time_max_minutes, 720),
    'buffer_before_booking_minutes', COALESCE(v_room.open_time_buffer_before_booking_minutes, 15),
    'must_end_by', v_must_end_by
  );

  -- Insert Open Time booking (payment_status = 'unpaid', no fake collection!)
  INSERT INTO public.bookings (
    lounge_id,
    room_id,
    room_name,
    user_name,
    user_phone,
    date,
    start_time,
    end_time,
    duration_minutes,
    status,
    payment_status,
    payment_method,
    shift_id,
    play_mode,
    room_price,
    total_price,
    is_open_time,
    open_time_started_at,
    checked_in_at,
    actual_start_time,
    open_time_pricing_snapshot,
    created_at,
    updated_at
  ) VALUES (
    v_room.lounge_id,
    v_room.id,
    COALESCE(NULLIF(v_room.name_ar, ''), NULLIF(v_room.name_en, ''), v_room.name),
    COALESCE(NULLIF(btrim(p_customer_name), ''), 'Walk-in customer'),
    NULLIF(btrim(p_customer_phone), ''),
    v_local_now::date,
    to_char(v_local_now, 'HH24:MI:SS')::time,
    to_char(v_local_now, 'HH24:MI:SS')::time,
    1,
    'in_progress'::public.booking_status,
    'unpaid',
    'cash',
    v_shift_id,
    v_play_mode,
    0,
    0,
    true,
    v_started_at,
    v_started_at,
    v_started_at,
    v_snapshot,
    now(),
    now()
  )
  RETURNING id INTO v_booking_id;

  -- Occupy room
  UPDATE public.rooms
  SET status = 'occupied',
      is_available = false,
      updated_at = now()
  WHERE id = v_room.id;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', v_booking_id,
    'room_id', v_room.id,
    'lounge_id', v_room.lounge_id,
    'started_at', v_started_at,
    'must_end_by', v_must_end_by,
    'status', 'in_progress',
    'is_open_time', true,
    'shift_id', v_shift_id
  );
END;
$$;


ALTER FUNCTION "public"."start_open_time_session"("p_room_id" "uuid", "p_customer_name" "text", "p_customer_phone" "text", "p_play_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_payout_processing"("p_payout_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'super_admin' AND is_active) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  UPDATE public.payouts
  SET status = 'processing', processing_started_by = auth.uid(), processing_started_at = now()
  WHERE id = p_payout_id AND status = 'approved';
  IF NOT FOUND THEN RAISE EXCEPTION 'Payout not found or not approved'; END IF;
  RETURN jsonb_build_object('success', true, 'payout_id', p_payout_id, 'status', 'processing');
END;
$$;


ALTER FUNCTION "public"."start_payout_processing"("p_payout_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_tournament_match"("p_match_id" "uuid", "p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."tournament_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_match public.tournament_matches%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT *
  INTO v_match
  FROM public.tournament_matches
  WHERE id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'match_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_tournament
  FROM public.tournaments
  WHERE id = v_match.tournament_id;

  IF NOT (
    public.is_super_admin()
    OR private.is_lounge_manager(v_tournament.lounge_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF v_match.status <> 'scheduled'
     OR v_match.player1_id IS NULL
     OR v_match.player2_id IS NULL THEN
    RAISE EXCEPTION 'match_not_ready' USING ERRCODE = '55000';
  END IF;

  IF p_room_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.rooms AS r
    WHERE r.id = p_room_id
      AND r.lounge_id = v_tournament.lounge_id
      AND r.is_active IS TRUE
      AND r.status <> 'deleted'
  ) THEN
    RAISE EXCEPTION 'invalid_tournament_room' USING ERRCODE = '22023';
  END IF;

  UPDATE public.tournament_matches
  SET room_id = COALESCE(p_room_id, room_id),
      status = 'in_progress',
      started_at = COALESCE(started_at, now()),
      updated_at = now()
  WHERE id = v_match.id
  RETURNING *
  INTO v_match;

  PERFORM public.tournament_audit(
    v_tournament.id,
    'match_started',
    NULL,
    v_match.id,
    NULL,
    to_jsonb(v_match)
  );

  RETURN v_match;
END;
$$;


ALTER FUNCTION "public"."start_tournament_match"("p_match_id" "uuid", "p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_kyc_documents"("p_id_document_url" "text", "p_business_document_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_user_prefix text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  v_user_prefix := v_user_id::text || '/';

  IF p_id_document_url IS NULL OR btrim(p_id_document_url) = '' THEN
    RAISE EXCEPTION 'ID document reference is required'
      USING ERRCODE = '22023';
  END IF;

  IF NOT (
    btrim(p_id_document_url) LIKE v_user_prefix || '%'
    OR btrim(p_id_document_url) LIKE '%/kyc-documents/' || v_user_prefix || '%'
  ) THEN
    RAISE EXCEPTION 'ID document reference does not belong to caller'
      USING ERRCODE = '42501';
  END IF;

  IF p_business_document_url IS NOT NULL
     AND btrim(p_business_document_url) <> ''
     AND NOT (
       btrim(p_business_document_url) LIKE v_user_prefix || '%'
       OR btrim(p_business_document_url) LIKE '%/kyc-documents/' || v_user_prefix || '%'
     ) THEN
    RAISE EXCEPTION 'Business document reference does not belong to caller'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.kyc_submissions (
    user_id,
    id_document_url,
    business_document_url,
    status
  )
  VALUES (
    v_user_id,
    btrim(p_id_document_url),
    nullif(btrim(p_business_document_url), ''),
    'pending'
  )
  ON CONFLICT (user_id)
  DO UPDATE SET
    id_document_url = EXCLUDED.id_document_url,
    business_document_url = EXCLUDED.business_document_url,
    status = 'pending',
    updated_at = now();
END;
$$;


ALTER FUNCTION "public"."submit_kyc_documents"("p_id_document_url" "text", "p_business_document_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_lounge_review"("p_lounge_id" "uuid", "p_rating" numeric, "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_review_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Unauthenticated request';
  END IF;

  INSERT INTO public.lounge_reviews (
    lounge_id,
    user_id,
    rating,
    comment,
    created_at
  )
  VALUES (
    p_lounge_id,
    auth.uid(),
    p_rating,
    p_comment,
    NOW()
  )
  RETURNING id INTO v_review_id;

  -- Update average lounge rating
  UPDATE public.lounges
  SET rating = (SELECT ROUND(AVG(rating)::numeric, 1) FROM public.lounge_reviews WHERE lounge_id = p_lounge_id),
      total_reviews = (SELECT COUNT(*) FROM public.lounge_reviews WHERE lounge_id = p_lounge_id)
  WHERE id = p_lounge_id;

  RETURN jsonb_build_object('success', true, 'review_id', v_review_id);
END;
$$;


ALTER FUNCTION "public"."submit_lounge_review"("p_lounge_id" "uuid", "p_rating" numeric, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_lounge_review"("p_lounge_id" "uuid", "p_id_document_path" "text", "p_business_document_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
 v_lounge public.lounges%ROWTYPE;
 v_snapshot jsonb;
 v_request private.lounge_review_requests%ROWTYPE;
 v_revision integer;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
 SELECT * INTO v_lounge FROM public.lounges WHERE id=p_lounge_id FOR UPDATE;
 IF NOT FOUND OR v_lounge.owner_id IS DISTINCT FROM auth.uid() THEN
  RAISE EXCEPTION 'LOUNGE_OWNER_REQUIRED' USING ERRCODE='42501';
 END IF;
 IF v_lounge.status NOT IN ('pending','rejected') THEN
  RAISE EXCEPTION 'LOUNGE_REVIEW_STATE_CONFLICT' USING ERRCODE='55000';
 END IF;
 IF NULLIF(btrim(v_lounge.name),'') IS NULL OR NULLIF(btrim(v_lounge.city),'') IS NULL
  OR NULLIF(btrim(v_lounge.address),'') IS NULL OR NULLIF(btrim(v_lounge.contact_phone),'') IS NULL
  OR v_lounge.opening_time IS NULL OR v_lounge.closing_time IS NULL
  OR v_lounge.location_point IS NULL
  OR (NULLIF(btrim(v_lounge.vodafone_cash_number),'') IS NULL
      AND NULLIF(btrim(v_lounge.instapay_account),'') IS NULL) THEN
  RAISE EXCEPTION 'LOUNGE_PROFILE_INCOMPLETE' USING ERRCODE='22023';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.rooms WHERE lounge_id=p_lounge_id AND is_active IS TRUE) THEN
  RAISE EXCEPTION 'LOUNGE_RESOURCES_REQUIRED' USING ERRCODE='22023';
 END IF;
 IF p_id_document_path IS NULL OR split_part(p_id_document_path,'/',1)<>auth.uid()::text
  OR p_id_document_path LIKE '%..%' OR p_id_document_path LIKE '%://%'
  OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='kyc-documents' AND name=p_id_document_path) THEN
  RAISE EXCEPTION 'INVALID_ID_DOCUMENT' USING ERRCODE='22023';
 END IF;
 IF p_business_document_path IS NOT NULL AND (
  split_part(p_business_document_path,'/',1)<>auth.uid()::text
  OR p_business_document_path LIKE '%..%' OR p_business_document_path LIKE '%://%'
  OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='kyc-documents' AND name=p_business_document_path)) THEN
  RAISE EXCEPTION 'INVALID_BUSINESS_DOCUMENT' USING ERRCODE='22023';
 END IF;
 v_snapshot:=jsonb_build_object('lounge',to_jsonb(v_lounge)-ARRAY['status','is_active','is_open','updated_at'],
  'rooms',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.rooms r WHERE lounge_id=p_lounge_id),
  'extras',(SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]'::jsonb) FROM public.extras e WHERE lounge_id=p_lounge_id));
 SELECT * INTO v_request FROM private.lounge_review_requests WHERE lounge_id=p_lounge_id AND status='pending';
 IF FOUND THEN
  IF v_request.snapshot=v_snapshot AND v_request.id_document_path=p_id_document_path
   AND v_request.business_document_path IS NOT DISTINCT FROM p_business_document_path THEN
   RETURN jsonb_build_object('success',true,'request_id',v_request.id,'revision',v_request.revision,'status','pending','idempotent',true);
  END IF;
  RAISE EXCEPTION 'PENDING_REVIEW_IMMUTABLE' USING ERRCODE='55000';
 END IF;
 SELECT COALESCE(max(revision),0)+1 INTO v_revision FROM private.lounge_review_requests WHERE lounge_id=p_lounge_id;
 UPDATE public.lounges SET status='pending',is_active=false,is_open=false WHERE id=p_lounge_id;
 INSERT INTO private.lounge_review_requests(lounge_id,owner_id,revision,snapshot,id_document_path,business_document_path)
 VALUES(p_lounge_id,auth.uid(),v_revision,v_snapshot,p_id_document_path,p_business_document_path) RETURNING * INTO v_request;
 UPDATE public.profiles SET is_setup_completed=true,updated_at=now()
  WHERE id=auth.uid() AND lounge_id=p_lounge_id;
 RETURN jsonb_build_object('success',true,'request_id',v_request.id,'revision',v_revision,'status','pending','idempotent',false);
END;
$$;


ALTER FUNCTION "public"."submit_lounge_review"("p_lounge_id" "uuid", "p_id_document_path" "text", "p_business_document_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_lounge_review"("p_lounge_id" "uuid", "p_booking_id" "uuid", "p_rating" numeric, "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_review_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'Rating must be between 1 and 5'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.bookings AS b
    WHERE b.id = p_booking_id
      AND b.user_id = auth.uid()
      AND b.lounge_id = p_lounge_id
      AND b.status = 'completed'::public.booking_status
  ) THEN
    RAISE EXCEPTION 'Completed booking not found for current user'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.lounge_reviews (
    lounge_id,
    booking_id,
    user_id,
    rating,
    comment,
    created_at
  )
  VALUES (
    p_lounge_id,
    p_booking_id,
    auth.uid(),
    p_rating,
    NULLIF(btrim(p_comment), ''),
    now()
  )
  ON CONFLICT (user_id, booking_id)
  DO UPDATE SET
    rating = EXCLUDED.rating,
    comment = EXCLUDED.comment
  RETURNING id INTO v_review_id;

  RETURN jsonb_build_object(
    'success', true,
    'review_id', v_review_id,
    'booking_id', p_booking_id,
    'lounge_id', p_lounge_id
  );
END;
$$;


ALTER FUNCTION "public"."submit_lounge_review"("p_lounge_id" "uuid", "p_booking_id" "uuid", "p_rating" numeric, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_match_result"("p_match_id" "uuid", "p_score_player1" integer, "p_score_player2" integer, "p_proof_image_url" "text") RETURNS "public"."tournament_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  m public.tournament_matches;
  t public.tournaments%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_score_player1 IS NULL OR p_score_player2 IS NULL
     OR p_score_player1 < 0 OR p_score_player2 < 0
     OR p_score_player1 = p_score_player2 THEN
    RAISE EXCEPTION 'invalid_result';
  END IF;

  SELECT * INTO m
  FROM public.tournament_matches
  WHERE id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'match_not_found';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.tournament_participants p
    WHERE p.user_id = auth.uid()
      AND p.id IN (m.player1_id, m.player2_id)
  ) THEN
    RAISE EXCEPTION 'not_match_participant';
  END IF;

  IF m.status NOT IN ('scheduled', 'in_progress') THEN
    RAISE EXCEPTION 'result_already_pending_or_closed';
  END IF;

  SELECT * INTO t
  FROM public.tournaments
  WHERE id = m.tournament_id;

  UPDATE public.tournament_matches
  SET score_player1 = p_score_player1,
      score_player2 = p_score_player2,
      proof_image_url = p_proof_image_url,
      submitted_by = auth.uid(),
      result_submitted_at = now(),
      confirmation_deadline = now() + interval '5 minutes',
      status = 'pending_confirmation',
      updated_at = now()
  WHERE id = m.id
  RETURNING * INTO m;

  PERFORM public.tournament_audit(
    t.id,
    'match_result_submitted',
    NULL,
    m.id,
    NULL,
    to_jsonb(m)
  );

  RETURN m;
END;
$$;


ALTER FUNCTION "public"."submit_match_result"("p_match_id" "uuid", "p_score_player1" integer, "p_score_player2" integer, "p_proof_image_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_tournament_payment"("p_participant_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_receipt_url" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_p public.tournament_participants%ROWTYPE;
  v_t public.tournaments%ROWTYPE;
  v_s public.tournament_payment_submissions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_participant_id IS NULL THEN
    RAISE EXCEPTION 'Participant ID is required' USING ERRCODE = '22023';
  END IF;

  SELECT p.*
  INTO v_p
  FROM public.tournament_participants AS p
  WHERE p.id = p_participant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Participant registration not found' USING ERRCODE = 'P0002';
  END IF;

  -- Explicit caller ownership check
  IF v_p.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Not authorized: You can only submit payment for your own participation'
      USING ERRCODE = '42501';
  END IF;

  SELECT t.*
  INTO v_t
  FROM public.tournaments AS t
  WHERE t.id = v_p.tournament_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_p.registration_status <> 'pending_payment'
     OR COALESCE(v_p.payment_status, 'unpaid') <> 'unpaid' THEN
    RAISE EXCEPTION 'Payment is not allowed in the current registration state' USING ERRCODE = '55000';
  END IF;

  IF v_p.payment_deadline IS NOT NULL AND v_p.payment_deadline < now() THEN
    RAISE EXCEPTION 'Payment deadline has expired' USING ERRCODE = '55000';
  END IF;

  IF p_payment_method NOT IN ('instapay', 'vodafone_cash') THEN
    RAISE EXCEPTION 'Invalid payment method: only instapay and vodafone_cash are accepted'
      USING ERRCODE = '22023';
  END IF;

  IF p_receipt_url IS NULL OR btrim(p_receipt_url) = '' THEN
    RAISE EXCEPTION 'Payment receipt URL is required' USING ERRCODE = '22023';
  END IF;

  IF p_amount IS NULL OR p_amount <> v_t.entry_fee THEN
    RAISE EXCEPTION 'Payment amount mismatch: expected entry fee of %', v_t.entry_fee
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tournament_payment_submissions (
    participant_id, amount, payment_method, receipt_url, submitted_by
  ) VALUES (
    p_participant_id, p_amount, p_payment_method, p_receipt_url, auth.uid()
  )
  RETURNING * INTO v_s;

  UPDATE public.tournament_participants
  SET payment_status = 'pending',
      payment_method = p_payment_method,
      receipt_url = p_receipt_url,
      updated_at = now()
  WHERE id = p_participant_id
  RETURNING * INTO v_p;

  PERFORM public.tournament_audit(
    v_t.id,
    'payment_submitted',
    p_participant_id,
    NULL,
    NULL,
    to_jsonb(v_s)
  );

  RETURN row_to_json(v_p);
END;
$$;


ALTER FUNCTION "public"."submit_tournament_payment"("p_participant_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_receipt_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_tournament_payment"("p_participant_id" "uuid", "p_tournament_id" "uuid", "p_user_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_receipt_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
        DECLARE
            v_curr_status TEXT;
            v_result JSONB;
        BEGIN
            -- Atomic row lock on participant row to prevent TOCTOU race conditions
            SELECT status INTO v_curr_status
            FROM public.tournament_participants
            WHERE id = p_participant_id
            FOR UPDATE;

            IF v_curr_status IN ('payment_submitted', 'paid', 'confirmed') THEN
                RETURN jsonb_build_object(
                    'success', true,
                    'already_submitted', true,
                    'message', 'Payment receipt already submitted and under review.'
                );
            END IF;

            -- Update status atomically
            UPDATE public.tournament_participants
            SET status = 'payment_submitted',
                payment_method = p_payment_method,
                receipt_url = p_receipt_url,
                updated_at = NOW()
            WHERE id = p_participant_id;

            RETURN jsonb_build_object(
                'success', true,
                'already_submitted', false,
                'participant_id', p_participant_id
            );
        END;
        $$;


ALTER FUNCTION "public"."submit_tournament_payment"("p_participant_id" "uuid", "p_tournament_id" "uuid", "p_user_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_receipt_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."super_admin_create_lounge_with_owner"("p_owner_email" "text", "p_owner_password" "text", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text" DEFAULT 'Cairo'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.role = 'super_admin'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM public.platform_super_admins psa
    WHERE psa.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN public.create_lounge_with_owner(
    p_owner_email => p_owner_email,
    p_owner_password => p_owner_password,
    p_owner_name => p_owner_name,
    p_lounge_name => p_lounge_name,
    p_city => p_city
  );
END;
$$;


ALTER FUNCTION "public"."super_admin_create_lounge_with_owner"("p_owner_email" "text", "p_owner_password" "text", "p_owner_name" "text", "p_lounge_name" "text", "p_city" "text") OWNER TO "postgres";


