CREATE OR REPLACE FUNCTION "public"."suspend_lounge"("p_lounge_id" "uuid", "p_reason" "text") RETURNS "public"."lounges"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lounge public.lounges;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only super admins can suspend lounges';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'Suspension reason is required';
  END IF;

  UPDATE public.lounges
  SET is_active = false,
      suspension_reason = p_reason
  WHERE id = p_lounge_id
  RETURNING * INTO v_lounge;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lounge not found';
  END IF;
  RETURN v_lounge;
END;
$$;


ALTER FUNCTION "public"."suspend_lounge"("p_lounge_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_booking_room"("p_booking_id" "uuid", "p_new_room_id" "uuid", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_segment public.booking_time_segments%ROWTYPE;
  v_new_room public.rooms%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_elapsed_seconds numeric;
  v_elapsed_minutes numeric;
  v_segment_price numeric;
  v_new_rate numeric;
BEGIN
  IF auth.uid() IS NULL OR p_actor_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Actor must be the authenticated user' USING ERRCODE = '42501';
  END IF;
  SELECT b.* INTO v_booking FROM public.bookings b WHERE b.id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT private.can_manage_playspot_lounge(v_booking.lounge_id) THEN
    RAISE EXCEPTION 'Not authorized to swap rooms for this lounge' USING ERRCODE = '42501';
  END IF;
  IF v_booking.status <> 'in_progress' OR v_booking.room_id IS NULL THEN
    RAISE EXCEPTION 'Only an in-progress booking with a current room can be swapped' USING ERRCODE = '55000';
  END IF;
  IF p_new_room_id = v_booking.room_id THEN RAISE EXCEPTION 'Target room is already assigned'; END IF;
  SELECT r.* INTO v_new_room FROM public.rooms r
  WHERE r.id = p_new_room_id AND r.lounge_id = v_booking.lounge_id
    AND r.is_active IS TRUE AND r.is_available IS TRUE AND r.status = 'available'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Target room is not available in this lounge' USING ERRCODE = '55000'; END IF;
  SELECT s.* INTO v_segment FROM public.booking_time_segments s
  WHERE s.booking_id = p_booking_id AND s.ended_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No active time segment exists; seed a verified session start before swapping' USING ERRCODE = '55000'; END IF;
  IF v_segment.room_id IS DISTINCT FROM v_booking.room_id THEN RAISE EXCEPTION 'Active segment room does not match booking room' USING ERRCODE = '55000'; END IF;
  v_elapsed_seconds := GREATEST(0, EXTRACT(EPOCH FROM (v_now - v_segment.started_at)));
  v_elapsed_minutes := v_elapsed_seconds / 60;
  v_segment_price := ROUND(v_segment.hourly_rate * v_elapsed_seconds / 3600, 2);
  UPDATE public.booking_time_segments SET ended_at = v_now, total_price = v_segment_price WHERE id = v_segment.id;
  v_new_rate := CASE WHEN v_booking.play_mode = 'multi' THEN COALESCE(v_new_room.hourly_rate_multi, 0)
                     ELSE COALESCE(v_new_room.hourly_rate_single, v_new_room.hourly_rate, 0) END;
  INSERT INTO public.booking_time_segments (booking_id, room_id, started_at, hourly_rate)
  VALUES (p_booking_id, p_new_room_id, v_now, v_new_rate);
  UPDATE public.bookings SET room_id = p_new_room_id,
    room_name = COALESCE(v_new_room.name_ar, v_new_room.name_en, v_new_room.name), updated_at = v_now
  WHERE id = p_booking_id;
  RETURN jsonb_build_object('success', true, 'old_room_id', v_segment.room_id,
    'new_room_id', p_new_room_id, 'elapsed_minutes', v_elapsed_minutes,
    'closed_segment_price', v_segment_price, 'new_hourly_rate', v_new_rate);
END;
$$;


ALTER FUNCTION "public"."swap_booking_room"("p_booking_id" "uuid", "p_new_room_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_booking_period_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_start_ts timestamp;
    v_end_ts timestamp;
BEGIN
    IF NEW.start_at IS NOT NULL AND NEW.end_at IS NOT NULL THEN
        v_start_ts := NEW.start_at;
        v_end_ts := NEW.end_at;
    ELSIF NEW.date IS NOT NULL AND NEW.start_time IS NOT NULL AND NEW.end_time IS NOT NULL THEN
        v_start_ts := (NEW.date + NEW.start_time)::timestamp;
        IF COALESCE(NEW.duration_minutes, 0) > 0 THEN
            v_end_ts := v_start_ts + (NEW.duration_minutes || ' minutes')::interval;
        ELSIF NEW.end_time <= NEW.start_time THEN
            v_end_ts := (NEW.date + NEW.end_time + interval '1 day')::timestamp;
        ELSE
            v_end_ts := (NEW.date + NEW.end_time)::timestamp;
        END IF;
    END IF;

    IF v_start_ts IS NOT NULL AND v_end_ts IS NOT NULL AND v_start_ts < v_end_ts THEN
        NEW.booking_period := tsrange(v_start_ts, v_end_ts, '[)');
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_booking_period_trigger"() OWNER TO "postgres";


