    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare target_id uuid := coalesce(new.lounge_id, old.lounge_id);
begin
  update public.lounges set
    total_reviews = (select count(*) from public.reviews where lounge_id = target_id),
    rating = (select coalesce(round(avg(rating)::numeric, 2), 0) from public.reviews where lounge_id = target_id)
  where id = target_id;
