CREATE OR REPLACE FUNCTION "public"."sync_room_status"("p_room_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_now_local timestamp without time zone := pg_catalog.now() AT TIME ZONE 'Africa/Cairo';
  v_room_status text;
  v_has_active boolean := false;
  v_has_soon_booking boolean := false;
BEGIN
  SELECT r.status INTO v_room_status
  FROM public.rooms AS r
  WHERE r.id = p_room_id;

  IF NOT FOUND OR v_room_status IN ('deleted', 'maintenance') THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.bookings AS b
    WHERE b.room_id = p_room_id
      AND b.status = 'in_progress'::public.booking_status
      AND b.booking_period IS NOT NULL
      AND b.booking_period @> v_now_local
  ) INTO v_has_active;

  SELECT EXISTS (
    SELECT 1
    FROM public.bookings AS b
    WHERE b.room_id = p_room_id
      AND b.status IN ('pending'::public.booking_status, 'upcoming'::public.booking_status, 'in_progress'::public.booking_status)
      AND b.booking_period IS NOT NULL
      AND upper(b.booking_period) > v_now_local
      AND lower(b.booking_period) <= v_now_local + interval '30 minutes'
      AND (b.status <> 'pending'::public.booking_status OR b.expires_at IS NULL OR b.expires_at > pg_catalog.now())
  ) INTO v_has_soon_booking;

  UPDATE public.rooms AS r
  SET status = CASE
        WHEN v_has_active THEN 'occupied'
        WHEN r.status = 'occupied' THEN 'available'
        ELSE r.status
      END,
      is_available = NOT (v_has_active OR v_has_soon_booking),
      updated_at = pg_catalog.now()
  WHERE r.id = p_room_id
    AND r.status NOT IN ('deleted', 'maintenance');
END;
$$;


ALTER FUNCTION "public"."sync_room_status"("p_room_id" "uuid") OWNER TO "postgres";


