CREATE OR REPLACE FUNCTION "public"."tournament_event_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_title_ar text;
  v_title_en text;
  v_body_ar text;
  v_body_en text;
  v_type text;
  v_meta jsonb;
  v_user uuid;
  v_winner_user uuid;
  v_lounge uuid;
  v_next public.tournament_matches;
  v_tournament_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'tournament_participants' THEN
    v_user := COALESCE(NEW.user_id, OLD.user_id);
    SELECT lounge_id INTO v_lounge FROM public.tournaments WHERE id = COALESCE(NEW.tournament_id, OLD.tournament_id);

    IF TG_OP = 'INSERT' THEN
      v_type := 'tournament';
      v_title_ar := 'تم تسجيلك في البطولة';
      v_title_en := 'Tournament registration created';
      v_body_ar := 'تم تسجيلك بنجاح. يرجى متابعة موعد الدفع.';
      v_body_en := 'Registration created. Please complete payment before the deadline.';
    ELSIF TG_OP = 'UPDATE' AND OLD.registration_status = 'waitlist' AND NEW.registration_status = 'pending_payment' THEN
      v_type := 'tournament_waitlist_promoted';
      v_title_ar := 'تم ترقيتك من قائمة الانتظار';
      v_title_en := 'You were promoted from the waitlist';
      v_body_ar := 'تم منحك مقعداً في البطولة. يرجى إتمام الدفع قبل انتهاء المهلة.';
      v_body_en := 'A tournament seat is now available. Please complete payment before the deadline.';
      v_meta := jsonb_build_object('tournament_id', NEW.tournament_id, 'participant_id', NEW.id, 'payment_deadline', NEW.payment_deadline, 'event', 'waitlist_promoted');
    ELSIF NEW.payment_status IS DISTINCT FROM OLD.payment_status OR NEW.registration_status IS DISTINCT FROM OLD.registration_status THEN
      v_type := 'tournament_payment';
      v_title_ar := 'تحديث تسجيل البطولة';
      v_title_en := 'Tournament registration updated';
      v_body_ar := 'تم تحديث حالة التسجيل أو الدفع.';
      v_body_en := 'Your tournament registration or payment status was updated.';
    ELSE
      RETURN COALESCE(NEW, OLD);
    END IF;

    INSERT INTO public.notifications(user_id, lounge_id, title_ar, title_en, body_ar, body_en, type, metadata)
    VALUES (v_user, v_lounge, v_title_ar, v_title_en, v_body_ar, v_body_en, v_type,
      COALESCE(v_meta, jsonb_build_object('tournament_id', COALESCE(NEW.tournament_id, OLD.tournament_id), 'participant_id', COALESCE(NEW.id, OLD.id), 'event', TG_OP)));

  ELSIF TG_TABLE_NAME = 'tournament_matches' THEN
    IF TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
      v_tournament_id := COALESCE(NEW.tournament_id, OLD.tournament_id);

      IF NEW.status = 'completed' AND NEW.winner_id IS NOT NULL THEN
        SELECT p.user_id INTO v_winner_user FROM public.tournament_participants p WHERE p.id = NEW.winner_id;
        SELECT * INTO v_next FROM public.tournament_matches WHERE id = NEW.next_match_id;
      END IF;

      FOR v_user IN
        SELECT DISTINCT p.user_id
        FROM public.tournament_participants p
        WHERE p.id IN (COALESCE(NEW.player1_id, OLD.player1_id), COALESCE(NEW.player2_id, OLD.player2_id))
          AND p.user_id IS NOT NULL
      LOOP
        IF NOT (NEW.status = 'completed' AND v_user = v_winner_user) THEN
          INSERT INTO public.notifications(user_id, lounge_id, title_ar, title_en, body_ar, body_en, type, metadata)
          SELECT v_user, t.lounge_id, 'تحديث في مباراة البطولة', 'Tournament match updated', 'تم تحديث حالة مباراتك.', 'Your tournament match was updated.', 'tournament_match',
            jsonb_build_object('tournament_id', t.id, 'match_id', COALESCE(NEW.id, OLD.id), 'status', COALESCE(NEW.status, OLD.status))
          FROM public.tournaments t WHERE t.id = v_tournament_id;
        END IF;
      END LOOP;

      IF NEW.status = 'completed' AND NEW.winner_id IS NOT NULL AND v_winner_user IS NOT NULL THEN
        INSERT INTO public.notifications(user_id, lounge_id, title_ar, title_en, body_ar, body_en, type, metadata)
        SELECT
          v_winner_user,
          t.lounge_id,
          'مبروك! لقد فزت بالمباراة',
          'Congratulations! You won the match',
          format(
            'فزت بنتيجة %s - %s. مباراتك القادمة %s.',
            NEW.score_player1,
            NEW.score_player2,
            CASE WHEN v_next.id IS NULL OR v_next.scheduled_at IS NULL
              THEN 'سيتم تحديد موعدها لاحقاً'
              ELSE 'يوم ' || to_char(v_next.scheduled_at AT TIME ZONE 'Africa/Cairo', 'DD/MM/YYYY الساعة HH24:MI')
            END
          ),
          format(
            'You won %s - %s. Your next match is %s.',
            NEW.score_player1,
            NEW.score_player2,
            CASE WHEN v_next.id IS NULL OR v_next.scheduled_at IS NULL
              THEN 'to be scheduled later'
              ELSE to_char(v_next.scheduled_at AT TIME ZONE 'Africa/Cairo', 'DD/MM/YYYY at HH24:MI')
            END
          ),
          'tournament_match',
          jsonb_build_object(
            'event', 'match_won',
            'tournament_id', v_tournament_id,
            'match_id', NEW.id,
            'winner_id', NEW.winner_id,
            'score_player1', NEW.score_player1,
            'score_player2', NEW.score_player2,
            'next_match_id', v_next.id,
            'next_match_scheduled_at', v_next.scheduled_at
          )
        FROM public.tournaments t
        WHERE t.id = v_tournament_id;
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'tournaments' AND TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.notifications(user_id, lounge_id, title_ar, title_en, body_ar, body_en, type, metadata)
    SELECT DISTINCT p.user_id, NEW.lounge_id, 'تحديث حالة البطولة', 'Tournament status updated', 'تم تحديث حالة البطولة.', 'The tournament status was updated.', 'tournament', jsonb_build_object('tournament_id', NEW.id, 'status', NEW.status)
    FROM public.tournament_participants p
    WHERE p.tournament_id = NEW.id AND p.user_id IS NOT NULL AND p.registration_status IN ('confirmed', 'checked_in');
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."tournament_event_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_award_points_on_booking_complete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_completed_count integer;
BEGIN
  -- Keep the trigger function safe if it is reused without the trigger predicate.
  IF NEW.status IS DISTINCT FROM 'completed'::public.booking_status
     OR COALESCE(NEW.payment_status, 'unpaid') <> 'paid' THEN
    RETURN NEW;
  END IF;

  PERFORM public.award_points_for_booking(NEW.id);

  IF NEW.user_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_completed_count
    FROM public.bookings AS b
    WHERE b.user_id = NEW.user_id
      AND b.status = 'completed'::public.booking_status
      AND COALESCE(b.payment_status, 'unpaid') = 'paid';

    IF v_completed_count = 1 THEN
      PERFORM public.advance_loyalty_mission(NEW.user_id, 'first_booking', 1);
    END IF;

    PERFORM public.advance_loyalty_mission(
      NEW.user_id,
      'two_completed_bookings',
      1
    );

    IF NEW.start_time >= TIME '10:00'
       AND NEW.start_time < TIME '16:00' THEN
      PERFORM public.advance_loyalty_mission(
        NEW.user_id,
        'off_peak_booking',
        1
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_award_points_on_booking_complete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_award_points_on_review"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_valid boolean;
  v_award jsonb;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.bookings AS b
    WHERE b.id = NEW.booking_id
      AND b.user_id = NEW.user_id
      AND b.status = 'completed'::public.booking_status
  )
  INTO v_valid;

  IF NOT v_valid THEN
    RETURN NEW;
  END IF;

  v_award := public.award_points(
    p_user_id => NEW.user_id,
    p_points => 15,
    p_type => 'earn_review',
    p_reference_id => NEW.id,
    p_description => 'نقاط من تقييم صالة',
    p_source_type => 'lounge_review',
    p_source_id => NEW.id,
    p_idempotency_key => 'review:' || NEW.user_id::text || ':' || NEW.id::text,
    p_metadata => jsonb_build_object(
      'review_id', NEW.id,
      'booking_id', NEW.booking_id,
      'lounge_id', NEW.lounge_id
    )
  );

  IF COALESCE((v_award->>'applied')::boolean, false) IS TRUE THEN
    PERFORM public.advance_loyalty_mission(
      NEW.user_id,
      'write_review',
      1
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_award_points_on_review"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_broadcast_booking_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  v_customer_name text;
  v_room_name text;
  v_payload booking_broadcast_payload;
begin
  select full_name into v_customer_name from profiles where id = new.user_id;
  select name_ar into v_room_name from rooms where id = new.room_id;

  v_payload := row(new.id, new.status, new.date, new.start_time, new.end_time, new.total_price, v_customer_name, v_room_name);

  perform realtime.broadcast_changes(
    'lounge_bookings_' || new.lounge_id::text,
    tg_op,
    tg_op,
    tg_table_name,
    tg_table_schema,
    v_payload,
    v_payload
  );

  return new;
end;
$$;


