CREATE OR REPLACE FUNCTION "public"."trg_notify_on_booking_decision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_lounge_name text;
begin
  -- بس لما الحالة فعلياً تتغير من pending لحاجة تانية
  if old.status = 'pending' and new.status = 'upcoming' then
    select name into v_lounge_name from lounges where id = new.lounge_id;

    insert into notifications (user_id, title_ar, title_en, body_ar, body_en, type, is_read, metadata)
    values (
      new.user_id,
      'تم قبول حجزك!', 'Booking Approved!',
      'صاحب ' || coalesce(v_lounge_name, 'الصالة') || ' وافق على حجزك',
      coalesce(v_lounge_name, 'The lounge') || ' owner approved your booking',
      'booking', false,
      jsonb_build_object('booking_id', new.id)
    );

    update payments set status = 'pending' where booking_id = new.id and status = 'waiting_approval';

  elsif old.status = 'pending' and new.status = 'cancelled' then
    select name into v_lounge_name from lounges where id = new.lounge_id;

    insert into notifications (user_id, title_ar, title_en, body_ar, body_en, type, is_read, metadata)
    values (
      new.user_id,
      'للأسف، حجزك اتلغى', 'Booking Declined',
      'صاحب ' || coalesce(v_lounge_name, 'الصالة') || ' مش قادر يستقبل حجزك في الميعاد ده',
      coalesce(v_lounge_name, 'The lounge') || ' owner could not accommodate your booking at this time',
      'booking', false,
      jsonb_build_object('booking_id', new.id)
    );

    update payments set status = 'cancelled' where booking_id = new.id and status = 'waiting_approval';
  end if;

  return new;
end;
$$;


