CREATE OR REPLACE FUNCTION "public"."update_booking_status_admin"("p_booking_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_status public.booking_status;
  v_now_local timestamp without time zone :=
    now() AT TIME ZONE 'Africa/Cairo';
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT b.*
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = p_booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM private.assert_lounge_operator(v_booking.lounge_id, true);

  BEGIN
    v_status := p_status::public.booking_status;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Invalid booking status' USING ERRCODE = '22023';
  END;

  IF v_status IN (
       'in_progress'::public.booking_status,
       'completed'::public.booking_status
     )
     AND COALESCE(v_booking.payment_status, 'unpaid') <> 'paid' THEN
    RAISE EXCEPTION 'PAYMENT_REQUIRED_FOR_ACTIVE_OR_COMPLETED_BOOKING'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.bookings
  SET status = v_status,
      updated_at = now()
  WHERE id = p_booking_id;

  IF v_status = 'in_progress'::public.booking_status
     OR (
       v_status = 'upcoming'::public.booking_status
       AND v_booking.booking_period IS NOT NULL
       AND v_booking.booking_period @> v_now_local
     ) THEN
    UPDATE public.rooms
    SET status = 'occupied',
        is_available = false,
        updated_at = now()
    WHERE id = v_booking.room_id
      AND status NOT IN ('maintenance', 'deleted');
  ELSIF v_status IN (
    'upcoming'::public.booking_status,
    'completed'::public.booking_status,
    'cancelled'::public.booking_status,
    'rejected'::public.booking_status
  ) THEN
    UPDATE public.rooms AS r
    SET status = 'available',
        is_available = true,
        updated_at = now()
    WHERE r.id = v_booking.room_id
      AND r.status = 'occupied'
      AND NOT EXISTS (
        SELECT 1
        FROM public.bookings AS active_b
        WHERE active_b.room_id = r.id
          AND active_b.id <> p_booking_id
          AND active_b.status IN (
            'upcoming'::public.booking_status,
            'in_progress'::public.booking_status,
            'pending'::public.booking_status
          )
          AND active_b.booking_period IS NOT NULL
          AND active_b.booking_period @> v_now_local
      );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', p_booking_id,
    'status', v_status::text
  );
END;
$$;


ALTER FUNCTION "public"."update_booking_status_admin"("p_booking_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_lounge_average_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  affected_lounge_id uuid;
BEGIN
  FOR affected_lounge_id IN
    SELECT DISTINCT lounge_id
    FROM (VALUES
      (CASE WHEN TG_OP = 'DELETE' THEN OLD.lounge_id ELSE NEW.lounge_id END),
      (CASE WHEN TG_OP = 'UPDATE' THEN OLD.lounge_id ELSE NULL::uuid END)
    ) AS affected(lounge_id)
    WHERE lounge_id IS NOT NULL
    ORDER BY lounge_id
  LOOP
    -- Serialize concurrent review changes before reading their aggregate.
    PERFORM 1 FROM public.lounges WHERE id = affected_lounge_id FOR UPDATE;
    UPDATE public.lounges AS lounge
    SET total_reviews = review_summary.review_count,
        rating = review_summary.average_rating
    FROM (
      SELECT count(*)::integer AS review_count,
             coalesce(avg(rating), 0) AS average_rating
      FROM public.lounge_reviews
      WHERE lounge_id = affected_lounge_id
    ) AS review_summary
    WHERE lounge.id = affected_lounge_id;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."update_lounge_average_rating"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_lounge_open_time_policy"("p_lounge_id" "uuid", "p_enabled" boolean, "p_rounding_minutes" integer DEFAULT 15, "p_minimum_minutes" integer DEFAULT 60, "p_max_minutes" integer DEFAULT 720) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rounding integer := COALESCE(p_rounding_minutes, 15);
  v_minimum integer := COALESCE(p_minimum_minutes, 60);
  v_maximum integer := COALESCE(p_max_minutes, 720);
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE = '28000';
  END IF;

  IF p_lounge_id IS NULL THEN
    RAISE EXCEPTION 'LOUNGE_ID_REQUIRED' USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT public.has_lounge_permission(p_lounge_id, 'lounges_manage_settings') THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  IF v_rounding NOT IN (5, 10, 15, 30, 60)
     OR v_minimum < 15
     OR v_minimum > 240
     OR v_maximum < 60
     OR v_maximum > 1440
     OR v_maximum < v_minimum THEN
    RAISE EXCEPTION 'INVALID_OPEN_TIME_POLICY' USING ERRCODE = '22023';
  END IF;

  UPDATE public.lounges
  SET allow_open_time_sessions = COALESCE(p_enabled, false),
      open_time_rounding_minutes = v_rounding,
      open_time_minimum_minutes = v_minimum,
      open_time_max_minutes = v_maximum,
      updated_at = now()
  WHERE id = p_lounge_id
    AND COALESCE(status, 'approved') NOT IN ('deleted', 'rejected', 'suspended')
  RETURNING id
  INTO p_lounge_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'LOUNGE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'lounge_id', p_lounge_id,
    'allow_open_time_sessions', COALESCE(p_enabled, false),
    'open_time_rounding_minutes', v_rounding,
    'open_time_minimum_minutes', v_minimum,
    'open_time_max_minutes', v_maximum
  );
END;
$$;


ALTER FUNCTION "public"."update_lounge_open_time_policy"("p_lounge_id" "uuid", "p_enabled" boolean, "p_rounding_minutes" integer, "p_minimum_minutes" integer, "p_max_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_lounge_staff_member"("p_target_user_id" "uuid", "p_full_name" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_role" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_target public.profiles%ROWTYPE;
  v_actor_role text;
  v_new_role text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT p.*
  INTO v_target
  FROM public.profiles AS p
  WHERE p.id = p_target_user_id
  FOR UPDATE;

  IF NOT FOUND OR v_target.lounge_id IS NULL THEN
    RAISE EXCEPTION 'Staff member not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_target.role IN ('owner', 'lounge_owner', 'super_admin', 'superadmin') THEN
    RAISE EXCEPTION 'Owner and super admin accounts are protected'
      USING ERRCODE = '42501';
  END IF;

  v_actor_role := private.permission_role(auth.uid(), v_target.lounge_id);

  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role NOT IN ('super_admin', 'owner', 'manager') THEN
    RAISE EXCEPTION 'Only lounge administrators can manage staff'
      USING ERRCODE = '42501';
  END IF;

  IF v_actor_role <> 'super_admin'
     AND NOT public.has_lounge_permission(
       v_target.lounge_id,
       'staff_manage'
     ) THEN
    RAISE EXCEPTION 'Missing staff_manage permission'
      USING ERRCODE = '42501';
  END IF;

  IF v_actor_role = 'manager'
     AND v_target.role = 'manager' THEN
    RAISE EXCEPTION 'Managers cannot modify peer managers'
      USING ERRCODE = '42501';
  END IF;

  IF p_role IS NOT NULL THEN
    v_new_role := CASE lower(btrim(p_role))
      WHEN 'manager' THEN 'manager'
      WHEN 'admin' THEN 'manager'
      WHEN 'lounge_admin' THEN 'manager'
      WHEN 'cashier' THEN 'cashier'
      WHEN 'staff' THEN 'staff'
      ELSE NULL
    END;

    IF v_new_role IS NULL THEN
      RAISE EXCEPTION 'Unsupported staff role'
        USING ERRCODE = '22023';
    END IF;

    IF v_actor_role = 'manager' AND v_new_role = 'manager' THEN
      RAISE EXCEPTION 'Managers cannot promote staff to manager'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    v_new_role := v_target.role;
  END IF;

  UPDATE public.profiles
  SET full_name = COALESCE(NULLIF(btrim(p_full_name), ''), full_name),
      phone = COALESCE(NULLIF(btrim(p_phone), ''), phone),
      role = v_new_role,
      updated_at = now()
  WHERE id = p_target_user_id;

  UPDATE public.lounge_staff
  SET role = v_new_role
  WHERE lounge_id = v_target.lounge_id
    AND user_id = p_target_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_target_user_id,
    'lounge_id', v_target.lounge_id,
    'role', v_new_role
  );
END;
$$;


ALTER FUNCTION "public"."update_lounge_staff_member"("p_target_user_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_notification_preference"("p_preference_key" "text", "p_value" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated_preferences JSONB;
BEGIN
  UPDATE public.profiles
  SET notification_preferences = jsonb_set(
    COALESCE(notification_preferences, '{}'::jsonb),
    ARRAY[p_preference_key],
    to_jsonb(p_value)
  )
  WHERE id = auth.uid()
  RETURNING notification_preferences INTO v_updated_preferences;

  RETURN v_updated_preferences;
END;
$$;


ALTER FUNCTION "public"."update_notification_preference"("p_preference_key" "text", "p_value" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_promotion"("p_promotion_id" "uuid", "p_room_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_tag_ar" "text", "p_tag_en" "text", "p_discount_type" "text", "p_discount_value" numeric, "p_expires_at" timestamp with time zone, "p_colors" "text"[], "p_icon_key" "text", "p_image_url" "text" DEFAULT NULL::"text", "p_deep_link" "text" DEFAULT NULL::"text", "p_target_audience" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lounge_id uuid;
  v_type text := lower(btrim(COALESCE(p_discount_type, 'percentage')));
  v_value numeric := COALESCE(p_discount_value, 0);
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  SELECT lounge_id
  INTO v_lounge_id
  FROM public.promotions
  WHERE id = p_promotion_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Promotion not found' USING ERRCODE='P0002';
  END IF;

  IF NOT private.can_manage_promotion(v_lounge_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_type NOT IN ('percentage','fixed') THEN
    RAISE EXCEPTION 'Unsupported discount type' USING ERRCODE='22023';
  END IF;

  IF v_value < 0 OR (v_type='percentage' AND v_value > 100) THEN
    RAISE EXCEPTION 'Invalid discount value' USING ERRCODE='22023';
  END IF;

  IF p_room_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.rooms r
    WHERE r.id = p_room_id
      AND r.lounge_id = v_lounge_id
  ) THEN
    RAISE EXCEPTION 'Room does not belong to lounge' USING ERRCODE='22023';
  END IF;

  IF p_colors IS NULL OR array_length(p_colors,1) < 2 THEN
    RAISE EXCEPTION 'At least two colors are required' USING ERRCODE='22023';
  END IF;

  UPDATE public.promotions
  SET
    room_id = p_room_id,
    title = COALESCE(NULLIF(btrim(p_title_ar),''), NULLIF(btrim(p_title_en),''), 'Offer'),
    title_ar = p_title_ar,
    title_en = p_title_en,
    tag = COALESCE(NULLIF(btrim(p_tag_ar),''), NULLIF(btrim(p_tag_en),'')),
    tag_ar = p_tag_ar,
    tag_en = p_tag_en,
    colors = p_colors,
    icon_key = COALESCE(NULLIF(btrim(p_icon_key),''),'local_offer'),
    image_url = p_image_url,
    deep_link = p_deep_link,
    expires_at = p_expires_at,
    is_room_specific = p_room_id IS NOT NULL,
    target_audience = COALESCE(NULLIF(btrim(p_target_audience),''),'all'),
    discount_type = v_type,
    discount_value = v_value
  WHERE id = p_promotion_id;

  RETURN jsonb_build_object(
    'success', true,
    'promo_id', p_promotion_id,
    'discount_type', v_type,
    'discount_value', v_value
  );
END;
$$;


ALTER FUNCTION "public"."update_promotion"("p_promotion_id" "uuid", "p_room_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_tag_ar" "text", "p_tag_en" "text", "p_discount_type" "text", "p_discount_value" numeric, "p_expires_at" timestamp with time zone, "p_colors" "text"[], "p_icon_key" "text", "p_image_url" "text", "p_deep_link" "text", "p_target_audience" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_role_permission"("p_role" "text", "p_permission_key" "text", "p_is_enabled" boolean, "p_lounge_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_role text := lower(btrim(p_role));
  v_permission_key text := btrim(p_permission_key);
  v_actor_role text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';
  END IF;

  IF v_role NOT IN ('owner','manager','cashier','staff','super_admin') THEN
    RAISE EXCEPTION 'Unsupported permission role' USING ERRCODE='22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.app_permissions AS a WHERE a.key = v_permission_key
  ) THEN
    RAISE EXCEPTION 'Unknown permission key' USING ERRCODE='22023';
  END IF;

  IF p_is_enabled
     AND NOT private.permission_key_allowed_for_role(v_role, v_permission_key) THEN
    RAISE EXCEPTION 'Permission cannot be delegated to this role'
      USING ERRCODE='42501';
  END IF;

  IF p_lounge_id IS NULL THEN
    IF NOT public.is_super_admin() THEN
      RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
    END IF;

    UPDATE public.role_permissions
    SET is_enabled = p_is_enabled,
        updated_at = now()
    WHERE role = v_role
      AND permission_key = v_permission_key;

    RETURN jsonb_build_object(
      'success', true,
      'scope', 'global',
      'role', v_role,
      'permission_key', v_permission_key,
      'is_enabled', p_is_enabled
    );
  END IF;

  v_actor_role := private.permission_role(auth.uid(), p_lounge_id);

  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin','owner','manager') THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;

  IF v_actor_role <> 'super_admin'
     AND NOT public.has_lounge_permission(p_lounge_id, 'staff_manage') THEN
    RAISE EXCEPTION 'Missing staff_manage permission' USING ERRCODE='42501';
  END IF;

  IF v_role = 'super_admin' THEN
    RAISE EXCEPTION 'Super admin permissions are global-only'
      USING ERRCODE='42501';
  END IF;

  IF v_role = 'owner' AND v_actor_role <> 'super_admin' THEN
    RAISE EXCEPTION 'Only a super admin can change owner permissions'
      USING ERRCODE='42501';
  END IF;

  IF v_actor_role = 'manager'
     AND v_role NOT IN ('cashier','staff') THEN
    RAISE EXCEPTION 'Managers can only edit cashier or staff permissions'
      USING ERRCODE='42501';
  END IF;

  INSERT INTO public.lounge_role_permissions (
    lounge_id, role, permission_key, is_enabled, updated_at
  )
  VALUES (
    p_lounge_id, v_role, v_permission_key, p_is_enabled, now()
  )
  ON CONFLICT (lounge_id, role, permission_key)
  DO UPDATE
  SET is_enabled = EXCLUDED.is_enabled,
      updated_at = now();

  RETURN jsonb_build_object(
    'success', true,
    'scope', 'lounge',
    'lounge_id', p_lounge_id,
    'role', v_role,
    'permission_key', v_permission_key,
    'is_enabled', p_is_enabled
  );
END;
$$;


ALTER FUNCTION "public"."update_role_permission"("p_role" "text", "p_permission_key" "text", "p_is_enabled" boolean, "p_lounge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tournament"("p_tournament_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_description_ar" "text", "p_description_en" "text", "p_game_name" "text", "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone) RETURNS "public"."tournaments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
DECLARE v public.tournaments;
BEGIN
  SELECT * INTO v FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'tournament_not_found'; END IF;

  IF NOT (is_super_admin() OR private.can_operate_playspot_lounge(v.lounge_id) OR is_lounge_member_or_admin(v.lounge_id)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF v.status NOT IN ('draft','published','registration_open') THEN RAISE EXCEPTION 'tournament_not_editable'; END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_participants WHERE tournament_id = v.id) THEN RAISE EXCEPTION 'tournament_has_participants'; END IF;
  IF p_max_participants < 2 OR p_max_participants > v.bracket_size THEN RAISE EXCEPTION 'invalid_capacity'; END IF;
  IF p_registration_closes_at <= p_registration_opens_at THEN RAISE EXCEPTION 'invalid_registration_window'; END IF;
  IF p_check_in_closes_at <= p_check_in_opens_at THEN RAISE EXCEPTION 'invalid_checkin_window'; END IF;

  UPDATE public.tournaments
  SET title_ar=p_title_ar,title_en=p_title_en,description_ar=p_description_ar,description_en=p_description_en,
      game_name=p_game_name,max_participants=p_max_participants,entry_fee=p_entry_fee,
      registration_opens_at=p_registration_opens_at,registration_closes_at=p_registration_closes_at,
      payment_deadline_minutes=p_payment_deadline_minutes,check_in_opens_at=p_check_in_opens_at,
      check_in_closes_at=p_check_in_closes_at,tournament_starts_at=p_tournament_starts_at,updated_at=now()
  WHERE id=v.id RETURNING * INTO v;

  PERFORM public.tournament_audit(v.id,'tournament_updated',NULL,NULL,NULL,to_jsonb(v));
  RETURN v;
END;
$$;


ALTER FUNCTION "public"."update_tournament"("p_tournament_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_description_ar" "text", "p_description_en" "text", "p_game_name" "text", "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tournament_with_visibility"("p_tournament_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_description_ar" "text", "p_description_en" "text", "p_game_name" "text", "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone, "p_visibility_scope" "text" DEFAULT 'all'::"text", "p_visibility_radius_km" numeric DEFAULT NULL::numeric) RETURNS "public"."tournaments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v public.tournaments;
BEGIN
  IF p_visibility_scope NOT IN ('all', 'city', 'radius') THEN
    RAISE EXCEPTION 'invalid_visibility_scope';
  END IF;

  IF p_visibility_scope = 'radius'
     AND (p_visibility_radius_km IS NULL OR p_visibility_radius_km < 1 OR p_visibility_radius_km > 500) THEN
    RAISE EXCEPTION 'invalid_visibility_radius';
  END IF;

  IF p_visibility_scope <> 'radius' AND p_visibility_radius_km IS NOT NULL THEN
    RAISE EXCEPTION 'radius_only_for_radius_scope';
  END IF;

  v := public.update_tournament(
    p_tournament_id, p_title_ar, p_title_en, p_description_ar,
    p_description_en, p_game_name, p_max_participants, p_entry_fee,
    p_registration_opens_at, p_registration_closes_at,
    p_payment_deadline_minutes, p_check_in_opens_at,
    p_check_in_closes_at, p_tournament_starts_at
  );

  UPDATE public.tournaments
  SET visibility_scope = p_visibility_scope,
      visibility_radius_km = p_visibility_radius_km,
      updated_at = now()
  WHERE id = v.id
  RETURNING * INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION "public"."update_tournament_with_visibility"("p_tournament_id" "uuid", "p_title_ar" "text", "p_title_en" "text", "p_description_ar" "text", "p_description_en" "text", "p_game_name" "text", "p_max_participants" integer, "p_entry_fee" numeric, "p_registration_opens_at" timestamp with time zone, "p_registration_closes_at" timestamp with time zone, "p_payment_deadline_minutes" integer, "p_check_in_opens_at" timestamp with time zone, "p_check_in_closes_at" timestamp with time zone, "p_tournament_starts_at" timestamp with time zone, "p_visibility_scope" "text", "p_visibility_radius_km" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_points"("p_user_id" "uuid", "p_points_change" integer, "p_reason" "text" DEFAULT 'تعديل إداري للنقاط'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_old_points integer;
  v_new_points integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'super_admin'
  ) AND NOT (SELECT current_user = 'postgres') THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_points_change = 0 THEN
    RETURN;
  END IF;

  SELECT COALESCE(points, 0) INTO v_old_points
  FROM public.profiles
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User profile not found' USING ERRCODE = 'P0002';
  END IF;

  v_new_points := GREATEST(0, v_old_points + p_points_change);

  UPDATE public.profiles
  SET points = v_new_points
  WHERE id = p_user_id;

  INSERT INTO public.points_transactions (
    user_id, points, type, reference_id, description, created_at
  ) VALUES (
    p_user_id,
    p_points_change,
    CASE WHEN p_points_change > 0 THEN 'admin_grant' ELSE 'admin_deduct' END,
    auth.uid(),
    COALESCE(p_reason, 'تعديل إداري للنقاط'),
    now()
  );
END;
$$;


ALTER FUNCTION "public"."update_user_points"("p_user_id" "uuid", "p_points_change" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_booking_payment_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_allow_cash boolean;
  v_require_first_prepaid boolean;
BEGIN
  SELECT allow_cash_payment, require_prepaid_first_time
    INTO v_allow_cash, v_require_first_prepaid
  FROM public.lounges
  WHERE id = NEW.lounge_id;

  IF NEW.payment_method = 'cash' AND COALESCE(v_allow_cash, false) = false THEN
    RAISE EXCEPTION 'Cash payment is disabled for this lounge';
  END IF;

  IF NEW.payment_method = 'cash'
     AND COALESCE(v_require_first_prepaid, true)
     AND NEW.is_first_booking THEN
    RAISE EXCEPTION 'First booking must use manual_transfer payment';
  END IF;

  IF NEW.payment_method = 'manual_transfer'
     AND NULLIF(btrim(NEW.sender_wallet_phone), '') IS NULL THEN
    RAISE EXCEPTION 'sender_wallet_phone is required for manual_transfer';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_booking_payment_policy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_resource_booking_constraints"("p_room_id" "uuid", "p_players_count" integer, "p_extra_attributes" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
BEGIN
  IF p_room_id IS NULL THEN
    RAISE EXCEPTION 'Room ID is required' USING ERRCODE = '22023';
  END IF;

  SELECT r.* INTO v_room
  FROM public.rooms r
  WHERE r.id = p_room_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error_code', 'ROOM_NOT_FOUND',
      'message', 'Room not found'
    );
  END IF;

  IF p_players_count IS NOT NULL THEN
    IF p_players_count < COALESCE(v_room.min_capacity, 1) THEN
      RETURN jsonb_build_object(
        'valid', false,
        'error_code', 'CAPACITY_UNDERFLOW',
        'message', 'Player count is below minimum required capacity (' || COALESCE(v_room.min_capacity, 1) || ')'
      );
    END IF;

    IF p_players_count > COALESCE(v_room.max_capacity, 4) THEN
      RETURN jsonb_build_object(
        'valid', false,
        'error_code', 'CAPACITY_EXCEEDED',
        'message', 'Player count exceeds maximum room capacity (' || COALESCE(v_room.max_capacity, 4) || ')'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'room_id', v_room.id,
    'resource_type', v_room.resource_type,
    'pricing_model', v_room.pricing_model,
    'min_capacity', v_room.min_capacity,
    'max_capacity', v_room.max_capacity,
    'requires_screen', v_room.requires_screen,
    'requires_controllers', v_room.requires_controllers
  );
END;
$$;


ALTER FUNCTION "public"."validate_resource_booking_constraints"("p_room_id" "uuid", "p_players_count" integer, "p_extra_attributes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_tournament_payment_setup"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  has_payment_method boolean;
BEGIN
  IF NEW.entry_fee > 0
     AND NEW.status IN ('published', 'registration_open') THEN
    SELECT (
      NULLIF(btrim(l.vodafone_cash_number), '') IS NOT NULL
      OR NULLIF(btrim(l.instapay_account), '') IS NOT NULL
    )
    INTO has_payment_method
    FROM public.lounges l
    WHERE l.id = NEW.lounge_id;

    IF COALESCE(has_payment_method, false) = false THEN
      RAISE EXCEPTION
        'Paid tournaments require at least one lounge payment method: Vodafone Cash or InstaPay';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_tournament_payment_setup"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_voucher"("p_voucher_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_voucher user_vouchers;
begin
  select * into v_voucher from user_vouchers where id = p_voucher_id and user_id = auth.uid();
  if v_voucher is null then
    return jsonb_build_object('valid', false, 'error', 'الكوبون غير موجود');
  elsif v_voucher.status = 'used' then
    return jsonb_build_object('valid', false, 'error', 'الكوبون ده اتستخدم قبل كده');
  elsif v_voucher.expires_at < now() then
    return jsonb_build_object('valid', false, 'error', 'الكوبون منتهي الصلاحية');
  end if;
  return jsonb_build_object('valid', true, 'reward_type', v_voucher.reward_type, 'reward_value', v_voucher.reward_value);
end;
$$;


ALTER FUNCTION "public"."validate_voucher"("p_voucher_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_voucher_by_code"("p_code" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_voucher public.user_vouchers%ROWTYPE;
  v_is_staff boolean := false;
  v_target_user uuid;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Unauthenticated user');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = v_actor
      AND (
        role IN ('super_admin', 'lounge_owner', 'lounge_manager', 'cashier')
        OR lounge_id IS NOT NULL
      )
  ) INTO v_is_staff;

  IF v_is_staff THEN
    v_target_user := p_user_id; -- Staff can validate any customer's voucher (or specific customer if passed)
  ELSE
    v_target_user := v_actor; -- Regular user can only validate their own vouchers
  END IF;

  SELECT * INTO v_voucher
  FROM public.user_vouchers
  WHERE UPPER(TRIM(code)) = UPPER(TRIM(p_code))
    AND (v_target_user IS NULL OR user_id = v_target_user)
    AND status = 'active'
    AND (expires_at IS NULL OR expires_at > NOW())
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Voucher is invalid, expired, or already used');
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'voucher_id', v_voucher.id,
    'code', v_voucher.code,
    'reward_type', v_voucher.reward_type,
    'reward_value', v_voucher.reward_value,
    'min_spend', 0,
    'user_id', v_voucher.user_id
  );
END;
$$;


ALTER FUNCTION "public"."validate_voucher_by_code"("p_code" "text", "p_user_id" "uuid") OWNER TO "postgres";


