CREATE OR REPLACE FUNCTION "public"."withdraw_from_tournament"("p_tournament_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_p public.tournament_participants%ROWTYPE;
  v_old_waitlist_position integer;
  v_was_seat_holder boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'tournament_not_found'; END IF;
  IF v_t.status IN ('draw_completed', 'in_progress', 'completed', 'cancelled') THEN RAISE EXCEPTION 'withdrawal_closed_after_draw'; END IF;
  SELECT * INTO v_p FROM public.tournament_participants WHERE tournament_id = p_tournament_id AND user_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'participant_not_found'; END IF;
  IF v_p.registration_status IN ('withdrawn', 'cancelled', 'expired', 'eliminated', 'no_show') THEN RAISE EXCEPTION 'participant_not_withdrawable'; END IF;
  v_was_seat_holder := v_p.registration_status IN ('pending_payment', 'confirmed', 'checked_in');
  v_old_waitlist_position := v_p.waitlist_position;
  UPDATE public.tournament_participants SET registration_status = 'withdrawn', payment_deadline = NULL, waitlist_position = NULL, updated_at = now() WHERE id = v_p.id RETURNING * INTO v_p;
  IF v_old_waitlist_position IS NOT NULL THEN
    UPDATE public.tournament_participants SET waitlist_position = waitlist_position - 1, updated_at = now() WHERE tournament_id = p_tournament_id AND registration_status = 'waitlist' AND waitlist_position > v_old_waitlist_position;
  END IF;
  PERFORM public.tournament_audit(p_tournament_id, 'participant_withdrawn', v_p.id, NULL, NULL, to_jsonb(v_p), 'Participant withdrew before the tournament draw');
  IF v_was_seat_holder THEN PERFORM private.promote_tournament_waitlist_internal(p_tournament_id); END IF;
  RETURN row_to_json(v_p);
END;
$$;


ALTER FUNCTION "public"."withdraw_from_tournament"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw_tournament_participant"("p_participant_id" "uuid", "p_reason" "text" DEFAULT 'Admin withdrawal'::"text") RETURNS "public"."tournament_participants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_participant public.tournament_participants%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
  v_old_waitlist_position integer;
  v_was_seat_holder boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT *
  INTO v_participant
  FROM public.tournament_participants
  WHERE id = p_participant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'participant_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_tournament
  FROM public.tournaments
  WHERE id = v_participant.tournament_id
  FOR UPDATE;

  IF NOT (
    public.is_super_admin()
    OR private.is_lounge_manager(v_tournament.lounge_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF v_tournament.status IN (
    'draw_completed',
    'in_progress',
    'completed',
    'cancelled'
  ) THEN
    RAISE EXCEPTION 'withdrawal_closed_after_draw'
      USING ERRCODE = '55000';
  END IF;

  IF v_participant.registration_status IN (
    'withdrawn',
    'cancelled',
    'expired',
    'eliminated',
    'no_show'
  ) THEN
    RAISE EXCEPTION 'participant_not_withdrawable'
      USING ERRCODE = '55000';
  END IF;

  v_was_seat_holder := v_participant.registration_status IN (
    'pending_payment',
    'confirmed',
    'checked_in'
  );
  v_old_waitlist_position := v_participant.waitlist_position;

  IF v_participant.payment_status = 'paid' THEN
    INSERT INTO public.tournament_refunds (
      tournament_id,
      participant_id,
      user_id,
      amount,
      reason
    )
    VALUES (
      v_tournament.id,
      v_participant.id,
      v_participant.user_id,
      v_tournament.entry_fee,
      COALESCE(NULLIF(btrim(p_reason), ''), 'Admin withdrawal')
    )
    ON CONFLICT DO NOTHING;
  END IF;

  UPDATE public.tournament_participants
  SET registration_status = 'withdrawn',
      payment_status = CASE
        WHEN payment_status = 'paid' THEN 'refund_pending'
        ELSE payment_status
      END,
      payment_deadline = NULL,
      waitlist_position = NULL,
      updated_at = now()
  WHERE id = v_participant.id
  RETURNING *
  INTO v_participant;

  IF v_old_waitlist_position IS NOT NULL THEN
    UPDATE public.tournament_participants
    SET waitlist_position = waitlist_position - 1,
        updated_at = now()
    WHERE tournament_id = v_tournament.id
      AND registration_status = 'waitlist'
      AND waitlist_position > v_old_waitlist_position;
  END IF;

  IF v_was_seat_holder THEN
    PERFORM private.promote_tournament_waitlist_internal(v_tournament.id);
  END IF;

  PERFORM public.tournament_audit(
    v_tournament.id,
    'participant_withdrawn_by_admin',
    v_participant.id,
    NULL,
    NULL,
    to_jsonb(v_participant),
    COALESCE(NULLIF(btrim(p_reason), ''), 'Admin withdrawal')
  );

  RETURN v_participant;
END;
$$;


ALTER FUNCTION "public"."withdraw_tournament_participant"("p_participant_id" "uuid", "p_reason" "text") OWNER TO "postgres";


