    "priority" integer DEFAULT 100 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "upsell_rules_discount_percent_check" CHECK ((("discount_percent" IS NULL) OR (("discount_percent" >= (0)::numeric) AND ("discount_percent" <= (100)::numeric)))),
    CONSTRAINT "upsell_rules_max_impressions_per_booking_check" CHECK ((("max_impressions_per_booking" >= 1) AND ("max_impressions_per_booking" <= 20))),
    CONSTRAINT "upsell_rules_single_target" CHECK (((("suggest_extra_id" IS NOT NULL) AND ("suggest_combo_id" IS NULL)) OR (("suggest_extra_id" IS NULL) AND ("suggest_combo_id" IS NOT NULL)))),
    CONSTRAINT "upsell_rules_trigger_type_check" CHECK (("trigger_type" = ANY (ARRAY['session_minutes_elapsed'::"text", 'cart_contains_category'::"text", 'session_start'::"text", 'time_of_day'::"text"])))
