    CONSTRAINT "payments_amount_non_negative" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "payments_commission_rate_valid" CHECK ((("commission_rate" >= (0)::numeric) AND ("commission_rate" <= (1)::numeric))),
    CONSTRAINT "payments_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['cash'::"text", 'manual_transfer'::"text", 'card'::"text", 'vodafone_cash'::"text", 'fawry'::"text", 'instapay'::"text", 'app_wallet'::"text"]))),
    CONSTRAINT "payments_status_check" CHECK (("status" = ANY (ARRAY['completed'::"text", 'refunded'::"text", 'pending'::"text", 'waiting_approval'::"text", 'cancelled'::"text"])))
);


