CREATE POLICY "tournament_matches_write_policy" ON "public"."tournament_matches" TO "authenticated" USING (("public"."is_super_admin"() OR (EXISTS ( SELECT 1
   FROM "public"."tournaments" "t"
  WHERE (("t"."id" = "tournament_matches"."tournament_id") AND "public"."is_lounge_admin"("t"."lounge_id")))))) WITH CHECK (("public"."is_super_admin"() OR (EXISTS ( SELECT 1
   FROM "public"."tournaments" "t"
  WHERE (("t"."id" = "tournament_matches"."tournament_id") AND "public"."is_lounge_admin"("t"."lounge_id"))))));



