ALTER TABLE "public"."tournament_prize_rewards" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "tournament_prize_rewards_manage_creator" ON "public"."tournament_prize_rewards" USING ((EXISTS ( SELECT 1
   FROM ("public"."tournament_prizes" "tp"
     JOIN "public"."tournaments" "t" ON (("t"."id" = "tp"."tournament_id")))
  WHERE (("tp"."id" = "tournament_prize_rewards"."prize_id") AND ("t"."created_by" = ( SELECT "auth"."uid"() AS "uid")))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM ("public"."tournament_prizes" "tp"
     JOIN "public"."tournaments" "t" ON (("t"."id" = "tp"."tournament_id")))
  WHERE (("tp"."id" = "tournament_prize_rewards"."prize_id") AND ("t"."created_by" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "tournament_prize_rewards_select_authenticated" ON "public"."tournament_prize_rewards" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."tournament_prizes" "tp"
     JOIN "public"."tournaments" "t" ON (("t"."id" = "tp"."tournament_id")))
  WHERE (("tp"."id" = "tournament_prize_rewards"."prize_id") AND ("t"."status" <> ALL (ARRAY['draft'::"text", 'cancelled'::"text"]))))));



