ALTER TABLE "public"."upsell_rules" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "upsell_rules_delete" ON "public"."upsell_rules" FOR DELETE TO "authenticated" USING (("public"."is_super_admin"() OR "public"."has_lounge_permission"("lounge_id", 'menu_manage_items'::"text")));



CREATE POLICY "upsell_rules_insert" ON "public"."upsell_rules" FOR INSERT TO "authenticated" WITH CHECK ((("public"."is_super_admin"() OR "public"."has_lounge_permission"("lounge_id", 'menu_manage_items'::"text")) AND (("suggest_extra_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."extras" "extra_scope"
  WHERE (("extra_scope"."id" = "upsell_rules"."suggest_extra_id") AND ("extra_scope"."lounge_id" = "upsell_rules"."lounge_id"))))) AND (("suggest_combo_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."canteen_combos" "combo_scope"
  WHERE (("combo_scope"."id" = "upsell_rules"."suggest_combo_id") AND ("combo_scope"."lounge_id" = "upsell_rules"."lounge_id")))))));



CREATE POLICY "upsell_rules_read" ON "public"."upsell_rules" FOR SELECT TO "authenticated" USING ("public"."_playspot_has_lounge_access"("lounge_id"));



CREATE POLICY "upsell_rules_update" ON "public"."upsell_rules" FOR UPDATE TO "authenticated" USING (("public"."is_super_admin"() OR "public"."has_lounge_permission"("lounge_id", 'menu_manage_items'::"text"))) WITH CHECK ((("public"."is_super_admin"() OR "public"."has_lounge_permission"("lounge_id", 'menu_manage_items'::"text")) AND (("suggest_extra_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."extras" "extra_scope"
  WHERE (("extra_scope"."id" = "upsell_rules"."suggest_extra_id") AND ("extra_scope"."lounge_id" = "upsell_rules"."lounge_id"))))) AND (("suggest_combo_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."canteen_combos" "combo_scope"
  WHERE (("combo_scope"."id" = "upsell_rules"."suggest_combo_id") AND ("combo_scope"."lounge_id" = "upsell_rules"."lounge_id")))))));



