CREATE POLICY "user_ban_requests_insert_owner_or_manager" ON "public"."user_ban_requests" FOR INSERT TO "authenticated" WITH CHECK ((("private"."permission_role"(( SELECT "auth"."uid"() AS "uid"), "lounge_id") = ANY (ARRAY['owner'::"text", 'manager'::"text"])) AND ("user_id" <> ( SELECT "auth"."uid"() AS "uid")) AND (("booking_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."bookings" "b"
  WHERE (("b"."id" = "user_ban_requests"."booking_id") AND ("b"."lounge_id" = "user_ban_requests"."lounge_id") AND ("b"."user_id" = "user_ban_requests"."user_id")))))));



CREATE POLICY "user_ban_requests_select_owner_or_admin" ON "public"."user_ban_requests" FOR SELECT USING (((EXISTS ( SELECT 1
   FROM "public"."platform_super_admins" "sa"
  WHERE ("sa"."user_id" = ( SELECT "auth"."uid"() AS "uid")))) OR (EXISTS ( SELECT 1
   FROM "public"."lounge_staff" "ls"
  WHERE (("ls"."lounge_id" = "user_ban_requests"."lounge_id") AND ("ls"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("ls"."role" = ANY (ARRAY['lounge_owner'::"text", 'manager'::"text"])))))));



CREATE POLICY "user_ban_requests_update_admin" ON "public"."user_ban_requests" FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM "public"."platform_super_admins" "sa"
  WHERE ("sa"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."platform_super_admins" "sa"
  WHERE ("sa"."user_id" = ( SELECT "auth"."uid"() AS "uid")))));



